(12163, 'Lattafa THARWAH Silver EDP Hombre', NULL, 28800, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b386f-392d-70a9-ac69-86238a4a2898.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b386f-392f-717b-8033-7c320749e2b9.png?storeId=1681', 'Hombre', 1, 0, NULL, NULL),
(12164, 'Lattafa ATHEERI EDP 100ml  Mujer', NULL, 30500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b3869-cb1e-773f-8683-f751ee86811c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b3869-cb36-7760-95f5-f808693ae309.jpeg?storeId=1681', 'Mujer', 1, 0, NULL, NULL),
(12165, 'Set Versace Eros Parfum 3pzas', NULL, 59500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b3862-2267-77e4-80f9-0844fa253064.png?storeId=1681', 'Sets Hombre', 1, 0, NULL, NULL),
(12166, 'Korbaj Emir EDP 100ml Unisex', NULL, 57000, 0, 'Korbaj', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b33c2-55d3-74a9-94cd-f5d5042deb24.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b33c2-5407-71aa-b768-e158308bdc14.png?storeId=1681', 'Hombre|Mujer', 1, 0, NULL, NULL),
(12167, 'Jennifer López Still EDP 100ml Mujer', '<p><strong>Notas de salida (inicio):</strong></p><ul><li>Té Earl Grey (nota distintiva, limpia y ligeramente verde)</li><li>Mandarina (citrus vibrante</li><li>Pimienta blanca</li><li>Arroz</li><li>Manzana</li></ul><p>Aporta frescura, luminosidad y un ligero contraste especiado al principio.</p><p><strong>Notas de corazón (corazón floral):</strong></p><ul><li>Jazmín</li><li>Fresia</li><li>Madreselva</li><li>Flor de azahar del naranjo</li><li>Rosa</li><li>Lirio de los valles (muguete)</li></ul><p> Bouquet floral suave y femenino, clásico y elegante. </p><p><strong>Notas de fondo (secado):</strong></p><ul><li><strong>Sándalo</strong> (calidez amaderada)</li><li><strong>Ámbar</strong> (fondo envolvente y sensual)</li><li><strong>Almizcle</strong> (suavidad y proyección cercana)</li><li><strong>Iris</strong></li><li><strong>Toque de pimienta</strong></li></ul><p> Aporta profundidad, sensualidad y elegancia duradera</p><p><br></p>', 29800, 0, 'Jennifer López', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b2e0f-69cb-7029-925e-255a00f86f00.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b2e0f-69a9-71d9-ad81-539c0dfa4c7f.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Jennifer López Still</strong> es una fragancia <strong>femenina floral elegante y sofisticada</strong>, lanzada en 2003 y creada por el perfumista <strong>Michel Girard</strong>. Su estilo olfativo equilibra notas frescas y florales con un fondo cálido y sensual, evocando una feminidad madura, segura y refinada.</p>', NULL),
(12168, 'Body Mist Victoria´s Secret ROMANCE', NULL, 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b2cc0-1f91-75df-8478-8d37853ff37c.jpeg?storeId=1681', 'Mujer', 1, 0, NULL, NULL),
(12169, 'Adidas Arena Edition Champions League 100ml EDT Hombre', '<p><strong>Salida:</strong> cítricos refrescantes (mandarina/limón), toques verdes</p><p><strong>Corazón:</strong> especias suaves y acordes aromáticos</p><p><strong>Fondo:</strong> maderas claras, almizcle limpio</p>', 8500, 2, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b24a6-7d9e-7511-9212-e90bb341cb6f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b24a6-7ddd-7125-b8c6-7fecd44bc8b9.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia <strong>fresca y energética</strong>, pensada para el uso diario y para quienes buscan un aroma deportivo sin complicaciones. Transmite sensación de limpieza, dinamismo y ligereza. Ideal para climas cálidos, actividades diurnas o después del ejercicio. </p>', NULL),
(12170, 'Al Haramain Aqua Dubai 75ml EDP Unisex', NULL, 39500, 0, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b2401-cd99-7590-83fd-31613780be67.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b2401-ce47-75bd-9b05-4bb9852f0e21.png?storeId=1681', 'Hombre', 1, 0, NULL, NULL),
(12171, 'Paco Rabanne Olympea EDP 80ml Mujer', NULL, 62000, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b23f7-d850-727e-b65d-89dd074561e9.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b23f7-d8c8-755c-a93e-49061c8cbf58.png?storeId=1681', 'Mujer', 1, 0, NULL, NULL),
(12172, 'Armaf Odyssey Revolution 100ml EDP Men', '<p><strong>Salida (top):</strong> grosella negra, naranja sanguina, piña y salvia — una apertura afrutada, chispeante y ligeramente herbal. </p><p><strong>Corazón (medio):</strong> praliné, vainilla, ciruela y cardamomo — dulce, especiado y cremoso, con un toque gourmand. </p><p><strong>Fondo (base):</strong> haba tonka y pachulí — aporta calidez, profundidad y una estela terrosa-amaderada.</p>', 29500, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15ba-1610-765d-bc95-f8620fa72280.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15ba-1530-7149-ae41-22711042790e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><em>Armaf Odyssey Revolution</em> es una fragancia masculina moderna y envolvente con un perfil aromático-frutal que mezcla frescura jugosa con matices cálidos y gourmand. Se percibe vibrante y multifacética: empieza con un golpe frutal intenso, pasa a un corazón especiado-dulce y acaba con una base cálida y profunda que deja una estela memorable.</p>', NULL),
(12173, 'Lattafa Rave Now Women EDP 100ml Mujer', '<p><strong>Salida (top):</strong> frutos rojos (fresa, frambuesa, cereza) y naranja — jugosa y fresca. </p><p><strong>Corazón (medio):</strong> malvavisco / marshmallow, lirio de los valles (muguete) y jazmín — dulce floral suave y delicado. </p><p><strong>Fondo (base):</strong> vainilla, almizcle y musgo — cálido, sensual y duradero.</p>', 20000, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15b3-c00c-7653-9f43-03f45cdfff59.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15b3-c56c-7208-ae4e-8e757f8174e7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15b3-c72b-75db-95ef-ac8ceb504973.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Lattafa Rave Now Women</em> es una fragancia femenina moderna y vibrante con un perfil dulce-frutal y floral, pensada para la mujer que quiere un aroma alegre, fresco y elegante. Tiene una mezcla de frutas jugosas, dulzura cremosa y un toque cálido al final, lo que la hace versátil para el día a día o para momentos especiales. </p>', NULL),
(12174, 'Bharara Viking Kashmir 100ml EDP Unisex', '<p><strong>Salida:</strong> cardamomo y notas especiadas con un toque fresco y brillante. </p><p><strong>Corazón:</strong> flores como jazmín, lirio del valle, iris/lirio y violeta, aportando un perfil floral elegante y algo empolvado. </p><p><strong>Fondo:</strong> ámbar seco, sándalo, almizcle, nagarmotha (hierba ciperácea) y vainilla, ofreciendo una base cálida, amaderada y sensual con buena duración.</p>', 46500, 1, 'Bharara', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b1590-2904-73da-8ee0-ba4b5f9864de.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b1590-2dbc-7026-819d-0364184451c5.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Fragancia unisex sofisticada y envolvente que mezcla elementos aromáticos, especiados, florales y amaderados para crear un aroma con carácter y profundidad. Su perfil puede evocar un aire elegante, moderno y ligeramente místico, ideal si buscas una fragancia que destaque sin ser demasiado dulce o juvenil.</p>', NULL),
(12175, 'Lattafa Jassor EDP 100ml Hombre', '<p><strong>Salida (top):</strong> bergamota, cardamomo y manzana — fresco, afrutado y especiado al inicio. </p><p><strong>Corazón (medio):</strong> lavanda, geranio y tabaco — agrega un toque floral con matices aromáticos y un giro robusto. </p><p><strong>Fondo (base):</strong> cuero, haba tonka, vetiver y pachulí — aporta profundidad cálida, terrosa y amaderada que perdura.</p>', 27000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b1056-3fab-737d-a4ae-0e540e5bdd90.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b1056-43a4-7031-998d-f8f87b5c541a.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Lattafa Jasoor</em> es una fragancia aromática especiada con toques orientales, diseñada para transmitir energía, carácter y sofisticación. Es muy popular entre los hombres por su mezcla equilibrada de frescura, especias y una base cálida y profunda — ideal si te gustan perfumes versátiles que evolucionan desde notas brillantes hasta un acabado más rico y elegante.</p>', NULL),
(12176, 'Tubbees Berry Explosion EDP 50ml Unisex', '<p><strong>Salida (top):</strong> fresa, frambuesa, grosella negra — con toques de lichi y pomelo. </p><p><strong>Corazón (medio):</strong> esencia de arándano tipo jarabe (blueberry syrup), rosa, violeta.</p><p><strong>Fondo (base):</strong> vainilla, almizcle, algodón de azúcar y sándalo — un acabado cálido, suavemente dulce y algo cremoso.</p>', 11800, 1, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c2b-85b7-7580-9e6c-6d22abf2b82e.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Fragancia unisex frutal-floral con perfil vibrante y juvenil. Su carácter es jugoso, dulce y alegre; parece pensada para quienes les gusta un aroma frutal-afrutado-dulce, fresco al inicio pero con un fondo cálido y cremoso.</p>', NULL),
(12177, 'Tubbees Candy Apple EDP 50ml Unisex', '<p><strong>Salida (top):</strong> manzana verde, algodón de azúcar, ciruela / fruta roja (también puede aparecer per a veces).</p><p><strong>Corazón (medio):</strong> azúcar con canela, frutos rojos, flor blanca / notas florales-afrutadas. </p><p><strong>Fondo (base):</strong> almizcle, musgo / notas ambaradas, caramelo.</p>', 11800, 0, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c27-1428-75bf-8519-a13d8d3eb25a.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Es una fragancia unisex con perfil frutal-gourmand, divertida y juvenil — pensada para evocar ese dulce recuerdo de feria, cuando muerdes una manzana acaramelada. Mezcla frescura frutal con dulzura cálida, resultando alegre, seductora y algo juguetona.</p>', NULL),
(12178, 'Tubbees Golden Praline Bliss EDP 50ml Unisex', '<p><strong>Salida (top):</strong> azúcar moreno, praliné, mantequilla, mandarina, nuez/frutos secos </p><p><strong>Corazón (medio):</strong> mora (blackberry), crema / vainilla cremosa</p><p><strong>Fondo (base):</strong> tonka, vainilla, matices polvorientos / “powdery” — suavidad aterciopelada y cálida</p>', 11800, 0, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c23-2181-77ae-9720-718410388c99.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c23-213b-751d-b72c-2cb6af297e91.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>ragancia unisex de perfil gourmand — rica, cálida y reconfortante. Evoca la sensación de un postre dulce y cremoso: praliné dorado, azúcar moreno, vainilla y frutos secos mezclados en una atmósfera cálida, elegante y adictiva.</p>', NULL),
(12179, 'Tubbees Lemon A Licious EDP 50ml Unisex', '<p><strong>Salida (top):</strong> ralladura de limón, mandarina, naranja, avellana (y toques de bergamota/lima en algunas listas).</p><p><strong>Corazón (medio):</strong> sorbete de lima, jazmín, flor de azahar, tuberosa (y en algunas versiones un toque de flor blanca/orange blossom). <strong>Fondo (base):</strong> vainilla, sándalo, notas polvorientas (almizcle suave / polvo), lo que le da un cierre cálido y cremoso-acogedor.</p>', 11800, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c1e-e9d1-7089-b375-18f11d684d78.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Fragancia unisex cítrico-gourmand que combina frescura brillante con un toque cremoso-dulce. Al inicio entrega una explosión chispeante de cítricos, luego evoluciona hacia un corazón floral-oriental suave, cerrando con una base cálida, dulce y envolvente — ideal si buscas algo alegre, luminoso y con un final reconfortante.</p>', NULL),
(12180, 'Tubbees Passion Fruit Mojito EDP 50ml Unisex', '<p><strong>Salida (top):</strong> maracuyá, piña, frutas tropicales, grosella negra / fruta-blossom. </p><p><strong>Corazón (medio):</strong> flor de azahar (orange blossom), jazmín, mango, frambuesa. </p><p><strong>Fondo (base):</strong> almizcle, notas azucaradas / “sugary”, sándalo.</p>', 11800, 0, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c1a-d068-7418-ab37-4ae9f7a824eb.png?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Esta fragancia es un perfume unisex frutal-dulce con aire tropical. Combina la viveza de frutas exóticas con un toque “coctel” fresco, evocando una mezcla alegre, veraniega y vibrante: ideal para quienes buscan un aroma ligero, veraniego y entretenido.</p>', NULL),
(12181, 'Tubbees Tres Leches EDP 50ml Unisex', '<p><strong>Salida (top):</strong> leche, almendra, coco. </p><p><strong>Corazón (medio):</strong> jazmín, vainilla, haba tonka. </p><p><strong>Fondo (base):</strong> ámbar, almizcle, sándalo.</p>', 11800, 1, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c16-c339-751b-932e-990c4f5c299d.png?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Fragancia unisex de la firma Tubbees con perfil gourmand, inspirada en el tradicional postre latino “tres leches”. Es un aroma cremoso, reconfortante y dulce — evoca la sensación de un pastel bañado en leche con vainilla y caramelo, ideal para quienes disfrutan aromas cálidos, acogedores y “comestibles”.</p>', NULL),
(12182, 'Tubbees Sweet Mango Melody EDP 50ml Unisex', '<p><strong>Salida:</strong> mango maduro, bergamota, pomelo / toronja (y en algunas versiones, toque de cítricos extra) </p><p><strong>Corazón:</strong> pudín de mango cremoso, cachemira, violeta, flor blanca </p><p><strong>Fondo:</strong> caramelo, almizcle suave, pachulí, durazno (o notas frutales suaves)</p>', 11800, 1, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c13-074a-749d-8dd2-076af0217d5f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c13-07c5-704c-884e-4f7c31387bd9.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Fragancia unisex, tropical-gourmand, centrada en la dulzura jugosa del mango maduro. Es luminosa, alegre y exótica: recuerda a un mango cremoso, dulce y afrutado, con matices cálidos y reconfortantes, ideal para quienes gustan de aromas frutales-dulces con un toque sofisticado. </p>', NULL),
(12183, 'Tubbees Tira Miss You EDP 50ml Unisex', '<p><strong>Salida:</strong> almendra dulce, leche, café </p><p><strong>Corazón:</strong> ámbar, regaliz, flor blanca </p><p><strong>Fondo:</strong> caramelo, almizcle, nuez, vainilla</p>', 11800, 1, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c0f-3266-70ee-85ad-ba3138d99644.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p> Es una fragancia unisex del tipo gourmand, inspirada en el postre italiano tiramisú. Evoca esa sensación de postre cremoso, café caliente y dulzura reconfortante, ideal para quien disfruta aromas cálidos, suaves y adictivos.</p>', NULL),
(12184, 'Valentino Donna Born In Roma Intense 100ml EDP Mujer', '<p><strong>Salida (“top notes”)</strong>: Vainilla Bourbon y Ámbar — cálida, dulce, envolvente.</p><p><strong>Corazón (“middle notes”)</strong>: Jazmín (flor blanca, elegante y luminosa).</p><p><strong>Fondo (“base notes”)</strong>: Benjuí — añade profundidad resinosa, balsámica y algo de calidez persistente.</p>', 79000, 0, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019afa73-5575-77bc-a25a-b4be188b89bd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019afa73-57f2-7318-9106-8cafbd001d02.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>ámbar-floral</strong> con un carácter sensual, sofisticado y seductor. Su apertura es dulce y cremosa por la vainilla, con un toque cálido gracias al ámbar. Luego se transforma en un corazón floral elegante, gracias al jazmín, que le da feminidad y refinamiento. Finalmente, el benjuí en la base aporta una sensación cálida, resinosa y duradera. En conjunto, transmite una <strong>sensación cálida, elegante y magnética</strong> — ideal para quien quiere dejar una impresión duradera, con un aura de sofisticación y seducción.</p>', NULL),
(12185, 'Set Victoria Velvet Petals 75ml Body Mist & Crema', '<p>Notas de salida: Almendra azucarada, fruta estrella.</p><p>Notas de corazón: Leche de coco, flor de loto azul, flor de albaricoquero.</p><p>Notas de fondo: Sándalo, almizcles, vainilla de Madagascar</p>', 15800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aef5e-d982-723a-aae3-2471bae471d0.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Velvet Petals posee una fragancia floral dulce y cremosa que combina notas de almendra azucarada, flor de loto y vainilla de Madagascar. Es ideal para quienes buscan una fragancia femenina, cálida y reconfortante.</p>', NULL),
(12186, 'Set Victoria Secret Pure Seduction 75ml Body Mist & Crema', '<p>Salida: melón dulce y aloe vera, aportando una frescura inicial.</p><p>Corazón: ciruela roja madura, añadiendo un toque afrutado y jugoso.</p><p>Fondo: fresia y manzanilla, brindando una base floral suave y reconfortante.</p>', 15800, 1, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aef5d-9651-76d9-8731-ae7cc7ddbbdf.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Pure Seduction es una fragancia dulce y afrutada que combina notas jugosas con un toque floral suave. Su aroma evoca una sensación de frescura y feminidad, ideal para quienes buscan una fragancia ligera y encantadora para el uso diario.</p>', NULL),
(12187, 'Set Victoria Secret Love Spell 75ml Body Mist & Crema', '<p>Salida: durazno, manzana roja y flor de cerezo/cherry blossom </p><p>Corazón: lirio de los valles, jazmín blanco y lilac</p><p>Fondo: tamarindo, almizcle suave y maderas claras</p>', 15800, 1, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aef5c-90a6-762a-897c-30557f13b7db.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Love Spell  afrutado-floral vibrante y refrescante, ideal para uso diario. Su fragancia combina la dulzura jugosa del durazno y la cereza con un toque limpio y floral, evocando juventud, alegría y nostalgia.</p>', NULL),
(12188, 'Cristiano Ronaldo ORIGINS EDT 100ml Hombre', NULL, 25500, 0, 'Cristiano Ronaldo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aea0e-c4b7-733c-b7f7-a0bdb303b80e.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aea0e-c4e9-766d-890b-90ca31aeb365.png?storeId=1681', 'Hombre', 1, 0, NULL, NULL),
(12189, 'Set Gucci Flora Georgeous Jasmine EDP  50ml + 10ml', '<p><strong>Salida:</strong> mandarina, bergamota, flor de magnolia</p><p><strong>Corazón:</strong> jazmín sambac, jazmín grandiflorum, rosa suave</p><p><strong>Fondo:</strong> sándalo cremoso, benjuí dulce, pachulí ligero</p>', 53500, 0, 'Gucci', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aae59-b2c5-7239-b00b-0d70a3d15694.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p><strong>Gucci Flora Gorgeous Jasmine</strong> es una fragancia luminosa, delicada y profundamente femenina que celebra la suavidad del jazmín en su versión más moderna y radiante. Se siente como un rayo de sol filtrándose entre flores blancas recién abiertas: dulce, aterciopelada y con un aura positiva que eleva el ánimo al instante. Su apertura es fresca y chispeante, mientras que el corazón de jazmín aporta una elegancia cremosa y envolvente. El fondo cálido y ligeramente amaderado sostiene la fragancia con una sensualidad suave y reconfortante. Es perfecta para quienes aman los aromas florales limpios, brillantes y con un toque juvenil.</p>', NULL),
(12190, 'Marc Jacobs Daisy 100ml EDT Mujer', '<p><strong>Salida</strong>: hojas de violeta, toronja sanguina, fresa. </p><p><strong>Corazón</strong>: gardenia, violeta, jazmín. </p><p><strong>Fondo</strong>: almizcle blanco, maderas blancas, vainilla</p>', 54500, 1, 'Marc Jacobs', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aadaa-c61e-7069-a25e-b2e79e920500.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aadaa-c2d9-74b9-86f1-57c41f90f426.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia que captura la esencia de la juventud eterna: fresca, radiante y naturalmente encantadora. Desde el primer spray, te envuelve una chispa luminosa de notas frutales y verdes que evocan un día soleado lleno de libertad. Su corazón floral —suave, femenino y delicado— florece como un ramo recién cortado, mientras que el fondo cálido y limpio le da una sensación de pureza y serenidad que acompaña durante horas. Es un perfume que transmite alegría inocente, ligereza y un encanto despreocupado, perfecto para quienes aman lo delicado y la elegancia sutil.</p>', NULL),
(12191, 'Davidoff Cool Water 200ml EDT Hombre', '<p>Agua de mar , menta, lavanda, romero, cilantro y notas verdes  frescura oceánica herbal. </p><p>Melodía central </p><p>Sándalo, geranio, jazmín y neroli  bouquet floral-maderado limpio. </p><p>Ritmo final </p><p>Musgo de roble, almizcle, tabaco, cedro y ámbar gris  base masculina ligera y duradera.</p>', 32500, 1, 'David Off', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aad7d-5bd7-71da-b00b-1df2d4b09514.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aad7d-5eba-747f-9ff6-98c2e2c22573.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia acuática aromática clásica lanzada en 1988, considerada un referente de frescura marina. Refleja vitalidad, energía y limpieza masculina, ideal para uso diario y climas cálidos.</p>', NULL),
(12192, 'Giorgio Armani Acqua Di Gio Parfum 100ml Hombre', '<p>Salida: Bergamota, mandarina verde y acordes marinos </p><p>Corazón: Geranio, salvia esclarea y romero </p><p>Fondo: Incienso, pachulí, vetiver y maderas cálidas</p>', 72000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aad0d-2513-7738-ad41-3e01fc78f6a8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aad0d-257f-75b8-b20a-314b01b88e32.png?storeId=1681', 'Hombre', 1, 0, '<p>Acqua di Giò Parfum fue relanzada en 2023 como una versión moderna de la emblemática Acqua di Giò Profumo (2015), con una fórmula refinada que acentúa la frescura marina y añade profundidad gracias al incienso. Es una fragancia masculina fino-olímpica, elegante y sofisticada, que equilibra lo limpio con lo amaderado.</p>', NULL),
(12193, 'Armaf Odyssey Bahamas 100ml EDP Men', '<p><strong>Salida:</strong> algas, melón cantalupo, manzana Granny Smith, pera, ciruela y sal.</p><p><strong>Corazón:</strong> notas acuáticas, nenúfar (lirio de agua), incienso y musgo de roble.</p><p><strong>Fondo:</strong> ámbar, cedro, azúcar y almizcle.</p>', 29500, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa83f-672c-7628-9115-e08d92176bc7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa83f-6fc2-762d-9f5d-cfd4fa217d5e.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa83f-7746-76ca-8f0e-f6bd3bf80be9.png?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia acuática-aromática de aire veraniego y tropical, que transmite la sensación de una brisa marina fresca y dulce con frutas jugosas, para luego asentarse en un fondo cálido y amaderado.</p>', NULL),
(12194, 'Calvin Klein Eternty Aqua 100ml EDT Hombre', '<p><strong>Salida (top):</strong> pepino, cítricos, hojas verdes y loto. </p><p><strong>Corazón (media):</strong> lavanda, ciruela (mirabelle), pimienta de Sichuan, cedro de Virginia.</p><p><strong>Fondo (base):</strong> madera de gaiac, sándalo, pachulí y almizcle.</p>', 26000, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa835-9b7a-7657-9083-e957f6b9dcbd.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa835-99b3-73a7-8e96-bfa84f7a5000.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina fresca y acuática, que evoca la sensación de una brisa marina ligera con un toque verde y cítrico, equilibrado por un fondo amaderado moderno y sofisticado.</p>', NULL),
(12195, 'Bharara Niche Femme 100ml EDP Mujer', '<p><strong>Salida:</strong> frutas.</p><p><strong>Corazón:</strong> incienso, rosa turca.</p><p><strong>Fondo:</strong> sándalo, vainilla.</p>', 42500, 1, 'Bharara', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa781-8e5d-71ba-9491-f49bb943c9b9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa781-8eb9-7189-a4e3-cf5bcc01c30d.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia femenina elegante y moderna, con una apertura frutal brillante que evoluciona hacia un corazón ligeramente místico de incienso y rosa turca, para terminar en un fondo cálido y cremoso de sándalo y vainilla.</p>', NULL),
(12196, 'Giorgio Armani Code 75ml EDT Hombre', '<p><strong>Salida:</strong> limón, bergamota.</p><p><strong>Corazón:</strong> estrella de anís, flor de olivo, madera de guayaco.</p><p><strong>Fondo:</strong> cuero, haba tonka, tabaco.</p>', 46000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa771-80c7-705d-90fc-0f46d7bacb57.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa771-8108-711a-bb9d-b7386d45e161.png?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia seductora y refinada para hombre, que combina notas cítricas frescas con un corazón aromático especiado y un fondo profundo y elegante. Evoca una masculinidad moderna, sofisticada y con un toque de misterio.</p>', NULL),
(12197, 'Set Burberry Goddess  EDP 100ml +10ml  Mujer', '<p><strong>Salida (top):</strong> Infusión de vainilla brillante y lavanda luminosa </p><p><strong>Corazón (media):</strong> Vainilla “caviar” </p><p><strong>Fondo (base):</strong> Absoluto de vainilla más oscuro y cremoso</p><p><strong>Toques de contraste:</strong> Cacao terroso y raíz de jengibre aportan profundidad y balance aromático</p>', 65500, 0, 'Burberry', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a9f4c-0057-755e-ad7b-6ecaa2fd4e38.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a9f4c-023a-735e-96f4-cce309de40d5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a9f4c-0156-761d-917b-eb5c4ba59d65.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Una fragancia contemporánea, cálida y sofisticada que celebra el poder interior femenino. Es un “gourmand aromático” donde la vainilla es la nota central, pero con matices aromáticos y especiados que la hacen elegante y profunda.</p>', NULL),
(12198, 'Tubbees Dreamy Treats EDP 50ml Unisex', '<p><strong>Salida:</strong> lirio de los valles, melocotón, coco, sándalo</p><p><strong>Corazón:</strong> arroz, flores blancas, caramelo</p><p><strong>Fondo:</strong> leche, almizcle, sándalo, haba tonka</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8ab0-756d-71ca-9b03-7a71f9e01124.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8ab0-7d86-729f-ad5b-179e34224566.png?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Una fragancia acogedora y cremosa que evoca un postre suave y reconfortante con un toque floral y goloso.</p>', NULL),
(12199, 'Tubbees Berry Blast EDP 50ml Unisex', '<p><strong>Salida:</strong> grosella negra (blackcurrant), bergamota, fresia</p><p><strong>Corazón:</strong> pachulí, jazmín, rosa</p><p><strong>Fondo:</strong> almizcle, vainilla, azúcar</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aae-8f77-749e-940d-a3e8dc022c3a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aae-9942-72bb-a0d6-fc6d8c3f8dce.png?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Una fragancia enérgica y divertida que explota con frutos rojos vibrantes, se suaviza con flores elegantes y se posa en una base cálida y acogedora.</p>', NULL),
(12200, 'Tubbees Cotton Candy EDP 50ml Unisex', '<p>Salida: leche de coco</p><p>Corazón: algodón de azúcar, caramelo </p><p>Fondo: vainilla, almizcle</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aac-a9d0-73bc-9cf0-5e1dd85b5876.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aac-b2cd-70d3-94eb-cdf0a7076bde.png?storeId=1681', 'Niños|Mujer', 1, 0, '<p>Una fragancia dulce y nostálgica que recuerda a un día de feria: algodón de azúcar cremoso, cálido y reconfortante.</p>', NULL),
(12201, 'Tubbees Pink Sugar EDP 50ml Unisex', '<p><strong>Salida:</strong> lirio de los valles, sándalo, coco, melocotón </p><p><strong>Corazón:</strong> caramelo, arroz, flores blancas </p><p><strong>Fondo:</strong> leche, almizcle, haba tonka, sándalo</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aaa-0740-763d-8b0d-5984385c8374.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aaa-03e0-7571-b9fb-4ef3a7be0943.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Fragancia dulce, juguetona y reconfortante con un toque gourmand muy acogedor, evocando caramelo cremoso y dulces.</p>', NULL),
(12202, 'Tubbees Cherry Luxe EDP 50ml Unisex', '<p><strong>Salida:</strong> heliotropo, cereza, frutos rojos </p><p><strong>Corazón:</strong> tonka, jazmín, sándalo </p><p><strong>Fondo:</strong> almizcle, vainilla, ámbar gris</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aa7-1f23-714f-a32f-591cc383d8d9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aa7-1ea7-721b-9003-308bcf2b4477.jpeg?storeId=1681', 'Mujer|Niños', 1, 0, '<p>Una fragancia dulce y sofisticada que combina la jugosidad de la cereza con matices florales y una base cremosa, ideal tanto para mujer como para hombre y niñ@s.</p>', NULL),
(12203, 'Tubbees Candy Pop EDP 50ml Unisex', '<p><strong>Salida:</strong> algodón de azúcar, frambuesa</p><p><strong>Corazón:</strong> chicle, vainilla cremosa</p><p><strong>Fondo:</strong> caramelo suave, almizcle dulce</p>', 10500, 2, 'Tubbees', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aa4-b6e8-7040-9953-8fa21fa7d831.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8aa4-c77c-72c0-b96a-55ef56e588e9.png?storeId=1681', 'Niños|Mujer', 1, 0, '<p>Un aroma dulce y juguetón inspirado en las golosinas, con un toque juvenil y adictivo perfecto para quienes aman los perfumes gourmand.</p>', NULL),
(12204, 'Perry Ellis 360 Black 200ML EDT Hombre', '<p>Jengibre picante</p><p>Cardamomo cálido</p><p>Bergamota fresca</p>', 29500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a852d-542c-7678-8e4b-59cd3ae9fa79.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia intensa, especiada y seductoramente elegante. <strong>360 Black</strong> combina el misterio del tabaco con la calidez del ámbar y la sensualidad de la gamuza, envolviendo a quien la lleva en un aura de sofisticación nocturna.</p><p>Ideal para hombres que buscan dejar huella con una estela sobria, varonil y magnética.</p>', NULL),
(12205, 'Set Issey Miyake Pour Homme 125ml EDT + Shower Gel + After Shave', '<p><strong>Salida</strong>: Yuzu, limón, bergamota, mandarina, ciprés, cilantro, estragón, salvia, verbena, calone (acorde marino) </p><p><strong>Corazón:</strong> Loto azul, nuez moscada, lirio de los valles, azafrán, canela de Ceylán, geranio bourbon, reseda </p><p><strong>Fondo:</strong> Vetiver de Tahití, almizcle, cedro, sándalo, tabaco, ámbar</p>', 40500, 1, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7f60-c4fa-705e-b107-cccc65b10dcc.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7f60-c515-740d-875c-7eb15db26774.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Lanzada en 1994 y creada por Jacques Cavallier, esta fragancia masculina es un clásico acuático‑amaderado que evoca pureza, frescura y naturaleza. Combina cítricos chispeantes con especias suaves y un fondo amaderado, perfecta para hombres que buscan un aroma limpio y versátil para el día a día.</p>', NULL),
(12206, 'Xerjoff Naxos EDP 100ml Unisex', '<p><strong>Salida:</strong> bergamota, limón, lavanda.</p><p><strong>Corazón:</strong> miel, canela, jazmín Sambac, cashmerán.</p><p><strong>Fondo:</strong> hoja de tabaco, haba de tonka, vainilla</p>', 152000, 0, 'Xerjoff', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7bfd-72a0-751d-bc54-f5826f004972.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7bfd-73d6-73eb-8f37-2055c57ba0dd.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7bfd-71f5-738c-a473-b523156a8ba5.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia unisex de carácter lujoso y refinado que combina frescura cítrica, dulzura gourmand y profundidad especiada-amaderada. Evoca el sol del Mediterráneo, miel cálida, tabaco refinado y un toque de elegancia italiana.</p>', NULL),
(12207, 'Hugo Boss Bottled Night 100ml EDT Hombre', '<p><strong>Notas de salida:</strong> lavanda y hojas de abedul.</p><p><strong>Notas de corazón:</strong> violeta, jazmín y cardamomo.</p><p><strong>Notas de fondo: </strong>maderas (como Louro Amarelo y sándalo) y almizcle.</p><p><br></p><p>Perfil olfativo: amaderado-aromático, limpio pero con carácter nocturno.</p>', 42500, 0, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7b52-7ff8-75bf-8c66-162ab83598ca.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7b52-80b8-71f9-bf04-eeb17877869d.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia masculina que evoca la noche: elegante, refinada y algo misteriosa. Comienza con una frescura aromática de lavanda que se mezcla con la hoja de abedul, evoluciona hacia un corazón floral-violeta y finaliza con maderas cálidas y almizcle que le dan presencia sobria. Ideal para la tarde o noche, para un hombre que quiere proyectar sofisticación sin estridencias.</p>', NULL),
(12208, 'Lacoste L.12.12 Blanco 100ml EDP Hombre', '<p>Notas de salida: lima “finger lime” (cí­trico punzante) y cardamomo especiado.</p><p>Notas de corazón: eucalipto y lavandín/vegetales verdes. </p><p>Notas de fondo: cedro, pino, vetiver y gamuza (suede) que aportan una base amaderada-terrosa.</p>', 43500, 0, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6b93-5b7e-7708-8fbb-8ed35645da81.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6b93-5b8b-711a-a353-154624e34da5.png?storeId=1681', 'Hombre', 1, 0, '<p>Esta versión EDP de L.12.12 Blanc está inspirada en la icónica camisa polo blanca de Lacoste, y busca transmitir una masculinidad fresca, deportiva pero refinada. Abre con un impacto cítrico-especiado que despierta los sentidos, luego transita hacia verdes herbáceos, y finalmente se asienta en una base amaderada más seria. El resultado es una fragancia limpia, moderna y versátil para el hombre que quiere algo desenfadado pero con estilo.</p>', NULL),
(12209, 'Antonio Banderas Blue Seduction 200ml EDT Hombre', '<p><strong>Salida</strong>: cítrica y afrutada con melón, bergamota, menta y grosella negra, que transmiten frescura y vitalidad desde el primer moment</p><p><strong>Corazón</strong>: mezcla aquática con agua de mar, manzana verde, capuchino, cardamomo y nuez moscada, que aportan un giro moderno y distintivo </p><p><strong>Fondo</strong>: base suave y masculina de ámbar y madera, con una sutil estela cálida</p>', 22000, 0, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a61be-64bd-74cc-810b-7fa8c80732cf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a61be-65cc-745b-99bd-63e17450d56e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Antonio Banderas Blue Seduction</strong> (2007) es una fragancia acuática y frutal que ofrece una experiencia refrescante, tonalidad veraniega y carácter juvenil. Su frescura y precio la convierten en una opción ideal para usar a diario sin pretensiones, especialmente en climas cálidos.</p>', NULL),
(12210, 'Jo Milano Roll It 1 PARFUM 100ml Hombre', '<p><strong>Salida:</strong> limón, bayas rosadas (pink berries), jengibre y mango.</p><p><strong>Corazón:</strong> azul de cumarina (blue coumarin), jazmín y maderas secas. </p><p><strong>Fondo:</strong> oud, almizcle y ámbar.</p>', 55000, 2, 'Jo Milano', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a61ae-8dcf-7088-a130-189b7e385b31.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a61ae-8a11-7688-92d8-2f3b5871d6e3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a61ae-8a0b-72ca-a650-bc1d3620ce4b.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Esta fragancia abre con un impacto luminoso gracias al limón y mango, aportando frescura y un toque tropical. Luego evoluciona hacia maderas y flores que le dan un carácter más sereno y refinado. Finalmente se asienta en una base profunda y cálida: el oud, almizcle y ámbar le dan persistencia y elegancia. Buena para usar tanto de día como de noche, y bastante versátil para diferentes ambientes gracias a su mezcla de frescura + calidez. Por su carácter frutal-especiado al inicio, funciona bien en primavera/verano; por su base rica puede también adaptarse a temporadas más templadas.</p>', NULL),
(12211, 'Ariana Grande Thank You Next 2.0 EDP 100ml Mujer', '<p>Salida: jugo de manzana, fresa silvestre, granada. </p><p>Corazón: orquídea blanca, jazmín. </p><p>Fondo: malvavisco (marshmallow), almizcle, sándalo.</p>', 44500, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5828-e4c9-7404-b57c-d963e82b5e1c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5828-e996-77ad-81a9-38cef43dd247.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5828-e5c7-7318-9eeb-95f1800b3b38.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Thank U, Next 2.0 es una fragancia frutal-dulce y femenina, pensada para un público joven que busca un aroma alegre, juguetón y fácil de llevar. La apertura es vibrante gracias a la combinación de manzana dulce, fresa y granada, lo que genera una sensación divertida y moderna. Luego el corazón floral aporta un toque de elegancia suave, y finalmente la base de malvavisco, almizcle y sándalo le da calidez y un perfil algo gourmand sin llegar a lo pesado. </p><p>Se destaca que esta versión (2.0) evita algunas notas que a ciertos usuarios incomodaban en la versión original.</p>', NULL),
(12212, 'Dolce&Gabbana The One EDP 100ml Hombre', '<p>Es una fragancia amaderada-especiada para hombre que busca combinar sofisticación y presencia. Comienza con una apertura fresca y herbácea gracias al pomelo, cilantro y albahaca; luego evoluciona hacia un corazón cálido y especiado con jengibre, cardamomo y flor de azahar; por último se asienta en una base masculina de tabaco, cedro y ámbar. Según la marca, ofrece “masculinidad auténtica, magnética e intensa”. Este perfil la hace especialmente apta para salidas nocturnas, citas, estaciones frías o ambientes donde quieres dejar una impresión elegante y con carácter.</p>', 49000, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57fb-09e1-760d-a43b-2a4407f1c41d.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57fb-0a18-72e1-bce7-03a03fd6e1b3.png?storeId=1681', 'Hombre', 1, 0, '<p>Notas de salida: pomelo (grapefruit), cilantro, albahaca.</p><p>Notas de corazón: cardamomo, jengibre, flor de azahar de naranjo (orange blossom). </p><p>Notas de fondo: ámbar, tabaco, cedro.</p>', NULL),
(12213, 'Orientica Exclusive Azure Fantasy 80ml Extrait De Parfum Unisex', '<p>Salida: bergamota, jengibre, menta y nuez moscada.</p><p>Corazón: jazmín, lirio de los valles (muguete) y geranio.</p><p>Fondo: ámbar gris (ambergris), almizcle y madera de guayaco (guaiac wood).</p>', 59000, 2, 'Orientica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57ec-f83d-765e-b89a-2f5bf3a09fbe.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57ec-fb42-71ca-8c6d-30828c88ce88.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Exclusive Azure Fantasy es una fragancia unisex que busca evocar frescura ágil, elegancia y profundidad. La apertura es vibrante y chispeante gracias a la bergamota, menta y jengibre; luego se suaviza hacia un corazón floral y refinado con jazmín y geranio; finalmente se asienta en una base cálida, amaderada y almizclada que brinda carácter. Se sugiere como ideal para climas cálidos o estaciones como primavera-verano, aunque su fondo la hace algo más versátil.</p>', NULL),
(12214, 'Dolce&Gabbana Intenso EDP 125ml Hombre', '<p>Notas de salida: albahaca, lavanda, geranio, caléndula y acordes acuáticos.</p><p>Notas de corazón: tabaco, heno (hay), salvia esclarea, ciprés y un acorde llamado “moepel” (derivado de flores/hojas de un árbol africano). Notas de fondo: sándalo, almizcle, ámbar, labdanum, ciprés.</p>', 40500, 2, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57dc-789a-750c-9bff-526ab928b9b9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57dc-7a68-76e1-a119-d68d9cc5577e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Intenso EDP es una fragancia <strong>amaderada-aromática</strong> creada para el hombre moderno que busca elegancia y carácter. Comienza con una apertura verde-herbal fresca (lavanda + albahaca + notas acuáticas), pasa a un corazón con tabaco y heno que le dan profundidad y masculinidad, y concluye con una base cálida y sofisticada de maderas, ámbar y almizcle. La inclusión del acorde “moepel” le brinda un sello distintivo.</p>', NULL),
(12215, 'Azzaro Chrome EDT 100ml Hombre', '<p>Salida: romero, piña, neroli, bergamota, limón.</p><p>Corazón: ciclamen (violeta persa), cilantro, jazmín, musgo de roble.</p><p>Fondo: sándalo, haba tonka, almizcle, cedro, palo de rosa de Brasil, cardamomo.</p>', 32500, 2, 'Azzaro', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57d6-3a2e-7164-9fc8-4bac3ce327aa.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57d6-3c03-730f-ae58-b31e96c22448.png?storeId=1681', 'Hombre', 1, 0, '<p>Chrome EDT es una fragancia masculina con un perfil <strong>cítrico-aromático</strong> que evoca frescura y vitalidad, ideal para climas templados o cálidos. La apertura es brillante gracias al limón, bergamota y piña, luego se traslada a un corazón floral-verde más suave, y la base amaderada y almizclada aporta seriedad y masculinidad.</p><p>Es una opción versátil para uso diario, oficina o salidas informales.</p>', NULL),
(12216, 'Set Lattafa Art Of Universe 4pzas Hombre', '<p>Salida: bergamota, mandarina, jengibre, menta.</p><p>Corazón: flor de azahar (orange blossom), pera.</p><p>Fondo: cedro, ámbar, almizcle</p>', 38000, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a56d8-7a81-737f-bbd2-2f567eb0447c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a56d8-7c22-75ce-87a8-bb76b1b375ba.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Art of Universe es una fragancia que combina frescura cítrica y aromática en su apertura con un corazón frutal-floral suave para finalmente asentarse en una base cálida, amaderada y almizclada. La apertura es luminosa y vibrante gracias a cítricos + menta/jengibre, luego la pera y la flor de azahar aportan dulzor ligero y elegancia, y la base de cedro, ámbar y almizcle da ese remate sofisticado y algo cálido.</p>', NULL),
(12217, 'Rasasi Hawas Malibu EDP 100ML Hombre', '<p>Salida: piña, naranja, pomelo (grapefruit).</p><p>Corazón: iris (orris), lavanda, ámbar. </p><p>Fondo: haba tonka, almizcle (musk), pachulí, cashmerán (cashmeran).</p>', 33500, 2, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5648-14f3-74ff-880b-5ff40b1390b1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5648-181d-727a-bc04-2661f36b07ee.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5648-176e-722f-8e97-1aa6fa779cee.png?storeId=1681', 'Hombre', 1, 0, '<p>Hawas Malibu es una fragancia unisex con espíritu tropical-aromático que busca evocar una tarde soleada junto al mar: la apertura es brillante y jugosa gracias a frutas tropicales (especialmente la piña) combinadas con cítricos. Luego evoluciona hacia un corazón más suave y refinado con iris y lavanda sobre ámbar, antes de asentarse en una base cálida, musgosa-amaderada con tonka y pachulí. Este perfil la hace ideal para climas cálidos, días de verano o uso casual, cuando quieres un aroma fresco pero con carácter y buen estilo. Su aroma está inspirado en *Le Beau Le Parfum*</p>', NULL),
(12218, 'Rasasi Hawas Tropical EDP 100ML Hombre', '<p>Salida: agua de coco, hoja de higuera, jengibre.</p><p>Corazón: coco, higo, menta. </p><p>Fondo: sándalo, haba tonka, almizcle.</p>', 32500, 0, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5641-f153-766e-988c-180439d0a7ea.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5641-f3c9-701d-8ae9-d033b24f9d78.png?storeId=1681', 'Hombre', 1, 0, '<p>Hawas Tropical es una fragancia masculina lanzada en 2025 que evoca una escapada tropical: frescura verde-acuática, marcada por el coco y el higo en apertura, arropada luego por una base cálida y amaderada. Ideal para climas cálidos, días soleados o momentos informales, transmite un aire libre, veraniego y relajado con cierto carácter.</p>', NULL),
(12219, 'Giorgio Armani Acqua Di Gioia EDP 100ml', '<p>Salida: limón de Amalfi (“Limone Primo Fiore”) y hojas de menta fresca.</p><p>Corazón: jazmín «agua» (water jasmine) y notas acuáticas/florales suaves. </p><p>Fondo: cedro (Virginia cedar), azúcar moreno (brown sugar) y ládano (labdanum) que aportan calidez y un remate amaderado-resinoso.</p>', 57000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a562e-ed85-708f-9a6c-cc68369ccacf.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a562e-ed99-763c-8da5-0bc659e7e84b.png?storeId=1681', 'Mujer', 1, 0, '<p>Esta fragancia transmite una frescura luminosa y serena, inspirada en la naturaleza mediterránea. Comienza con cítricos brillantes y menta que evocan brisa marina, evoluciona hacia flores ligeras y agua atmosférica, y concluye con una base cálida de madera y dulzor sutil. Ideal para la primavera y el verano, es femenina, elegante y a la vez ligera.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12220, 'Giorgio Armani My Way  90ml EDP Mujer', '<p>Notas de salida: flor de azahar de naranjo, bergamota.</p><p>Notas de corazón: jazmín de la India, tuberosa. </p><p>Notas de fondo: vainilla de Madagascar, almizcle blanco, cedro de Virginia.</p>', 62500, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5628-1da1-7656-8791-6b4663866ad2.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5628-1f35-75d9-89e3-738c445472fa.png?storeId=1681', 'Mujer', 1, 0, '<p>Un “bouquet” floral blanco luminoso, construido para una mujer moderna, curiosa y auténtica, que busca vivir experiencias significativas. La apertura es fresca gracias a la bergamota y flor de azahar, el corazón aporta un carácter más floral profundo con jazmín y tuberosa, y la base añade calidez elegante con vainilla, almizcle y madera de cedro. El resultado: femenino, refinado, y relativamente versátil para el día o la tarde.</p>', NULL),
(12221, 'Carolina Herrera 212 VIP Black ELIXIR 100ml Hombre', '<p>Salida: lavanda negra, pomelo (toronja) efervescente, bayas de enebro.</p><p>Corazón: regaliz negro, flor de azahar, azafrán.</p><p>Fondo: vainilla negra, madera de roble, vetiver.</p>', 58800, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5302-0fd2-7086-ae66-858aaa93536a.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5302-1075-7388-90e8-fb7f88a3b84b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5302-116b-701f-bcea-99e7c85700f9.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia intensa y seductora, desarrollada para la noche o eventos especiales. Combina la frescura aromática de la lavanda negra con toques cítricos iniciales, para luego transitar hacia un corazón dulce-especiado (regaliz negro y azafrán) y rematar con una base cálida y adictiva de vainilla negra y madera. El efecto general es moderno, sofisticado y con carácter.</p>', NULL),
(12222, 'Guess Girl EDT 100ml EDT', '<p><strong>Notas de salida (top):</strong> frambuesa, melón y bergamota.</p><p><strong>Notas de corazón (medio):</strong> orquídea, azucena (lily) y acacia negra (robinia/black locust).</p><p><strong>Notas de fondo (base):</strong> vainilla de Madagascar y sándalo australiano.</p>', 21500, 1, 'Guess', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a23e5-5cc8-7076-a51e-fecfdec10cfc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a23e5-5c93-71bb-8e03-e27281737169.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia para mujer de carácter juvenil y juguetón, perteneciente a la familia olfativa floral-frutal. Fue lanzada en 2013, con creación del perfumista Laurent Le Guernec. La concentración es Eau de Toilette (EDT), lo que sugiere una presencia fresca pero moderada. </p><p>Ideal para el día a día, momentos casuales, o para uso diario en primavera/verano gracias a su frescura frutal.</p>', NULL),
(12223, 'Paco Rabanne Invictus Parfum 100ml Hombre', '<ul><li><strong>Salida:</strong> pomelo, pimienta negra</li><li><strong>Corazón:</strong> lavanda, geranio</li><li><strong>Fondo:</strong> ámbar, madera de guayaco, benjuí</li></ul><p>Una mezcla envolvente que deja una estela magnética y duradera.</p>', 65000, 2, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e95f-6c61-71fb-b7b6-d3199a979208.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e95f-6ba1-72ea-9ce5-ff9fa7bcf331.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia intensa y poderosa que representa la victoria y la masculinidad en su máxima expresión. Invictus Parfum combina frescura vibrante con notas cálidas y sensuales, ideal para hombres seguros de sí mismos y determinados.</p>', NULL),
(12224, 'Joop Pour Homme EDT 125ml Hombre', '<p>Notas de salida: Flor de azahar del naranjo, mandarina, bergamota y limón de Amalfi.</p><p>Notas de corazón: Jazmín, heliotropo, lirio de los valles, cardamomo y canela.</p><p>Notas de fondo: Sándalo, haba tonka, pachulí y vainilla</p>', 22500, 2, 'Joop', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e8bb-6cb2-70de-b791-41413eca2a48.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e8bb-6cc4-71f8-8608-643965ac05ff.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Joop! Homme Eau de Toilette es una fragancia masculina clásica lanzada en 1989, reconocida por su aroma oriental fougère distintivo. Su composición única ha generado opiniones divididas entre los usuarios, pero sigue siendo una opción popular para quienes buscan una fragancia intensa y duradera.</p>', NULL),
(12225, 'Kids Peppa Pig EDT 100ml', '<p><strong>Salida (cabeza)</strong>Frutales suaves (manzana, fresa, naranja dulce), notas cítricas ligeras como mandarina o limón suave. </p><p><strong>Corazón (media)</strong>Flores muy suaves como jazmín, rosa ligera, tal vez flores blancas, o una nota cremosita/amielada ligera. </p><p><strong>Fondo (base)</strong>Almizcle blanco, vainilla ligera, pachulí suave quizá, para dar cuerpo sin ser pesado; un toque dulce que se quede confortable.</p>', 7500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e3c4-a781-718a-b75b-5b414a5178e2.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Aroma <strong>dulce y delicado</strong>, pensada para niñ@s pequeños, o uso familiar. Proyección y duración probablemente <strong>moderadas</strong>, lo típico de un EDT infantil: durará algunas horas, suficiente para uso diario, sin ser muy intenso. Ideal para uso después del baño, antes de dormir, para salir con ropa casual.</p>', NULL),
(12226, 'Kids Minnie Mouse EDT 100ml', '<p>Salida (cabeza)Cítricos (mandarina, naranja, limón), notas verdes, acordes frutales.</p><p>Corazón (nota media)Flores suaves como jazmín, violeta, ylang‑ylang, lirios, quizá flores blancas.</p><p>Fondo (nota base)Vainilla, almizcle (musk), madera suave (sándalo), ámbar. </p>', 7500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e3bf-c693-738f-a074-fd149a7ceb14.png?storeId=1681', 'Niños', 1, 0, '<p>Público objetivo: niñas / niñas jóvenes. Es una fragancia infantil, dulce, juguetona y suave.</p>', NULL),
(12227, 'Kids Mickey Mouse 100ml EDT Niño', '<p>Salida (Notas de cabeza)Bergamota, notas verdes, limón / lima</p><p>Corazón (Notas medias)Flor de azahar del naranjo, flores blancas, jazmín</p><p>Fondo (Notas base)Almizcle, ámbar, vainilla</p>', 7500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e3bc-06ba-76db-8fc9-0cb750c87be6.png?storeId=1681', 'Niños', 1, 0, '<p>Es una fragancia infantil, pensada para niños (niño) de uso diario. Presentación de <strong>100 ml</strong>. Se la describe como “fresca”, “suave” y “agradable”, ideal para acompañar actividades diarias sin resultar invasiva.</p>', NULL),
(12228, 'Set Al Haramain Collection Amber Oud 4 x 60ml', '<h3><strong>Amber Oud Gold Edition</strong></h3><ul><li><strong>Salida:</strong> bergamota, notas verdes</li><li><strong>Corazón:</strong> melón, piña, notas dulces (gourmand), ámbar</li><li><strong>Fondo:</strong> vainilla, almizcle, maderas</li></ul><h3><strong>Amber Oud Carbon Edition</strong></h3><ul><li><strong>Salida:</strong> bergamota, lavanda, romero</li><li><strong>Corazón:</strong> geranio, salvia, notas marina</li><li><strong>Fondo:</strong> vetiver, cedro, ámbar, musgo</li></ul><h3><strong>Amber Oud Tobacco Edition</strong></h3><ul><li><strong>Salida:</strong> canela, jengibre, tabaco, pimienta negra</li><li><strong>Corazón:</strong> clavo, vainilla, cacao, tonka, incienso</li><li><strong>Fondo:</strong> madera, frutos secos, ámbar, tabaco seco</li></ul><h3><strong>Amber Oud Bleu Edition</strong></h3><ul><li><strong>Salida:</strong> pomelo (grapefruit), limón, menta, pimienta rosa</li><li><strong>Corazón:</strong> jengibre, vetiver, jazmín</li><li><strong>Fondo:</strong> incienso de olíbano, sándalo, cedro, pachulí</li></ul>', 105500, 1, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4d7-4fec-732f-9431-603e7dac456c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4d7-5149-7510-bb85-ae4c55385721.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4d7-502f-713e-8a44-b3a51502df26.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4d7-5131-703b-8247-8deeb3740c83.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Es una línea unisex con varias versiones/flankers del aroma <em>Amber Oud</em> original, cada una con un carácter distinto: algunas más dulces, otras más amaderadas, otras más frescas. </p>', NULL),
(12229, 'Set Moschino Toy 2 3pzas Mujer', '<p>Salida: manzana, mandarina, magnolia </p><p>Corazón: grosella blanca, peonía, jazmín </p><p>Fondo: almizcle, amberwood (ambramadera), sándalo</p>', 48000, 0, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4c8-dcfa-748d-ba37-688cd2d10d52.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Moschino Toy 2 (2018) es una fragancia femenina que equilibra lo frutal, floral y almizclado. Creada por Alberto Morillas y Fabrice Pellegrin, es fresca y versátil, perfecta para el día a día en ambientes cálidos.</p>', NULL),
(12230, 'Set Jean Paul Gaultier Scandal EDT', '<p>Notas de salida: Mandarina, Esclarea</p><p>Notas de corazón: Caramelo, Haba Tonka</p><p>Nota de fondo: Vetiver</p>', 60500, 0, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4be-8594-71b8-9d3a-d4974554e13d.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Jean Paul Gaultier Scandal Pour Homme Eau de Toilette es una fragancia masculina lanzada en 2021, destacada por su perfil dulce y amaderado. Esta fragancia ha sido bien recibida por su rendimiento y originalidad. <strong>Set Incluye perfume 100ml + 20ml</strong></p>', NULL),
(12231, 'Set Perry Ellis 360 Red EDT 3pzas Hombre', '<p>Bergamota italiana: fresca y ligeramente amarga, aporta una apertura cítrica y vibrante.</p><p>Limón verde: ácido y refrescante, con un toque energizante.</p><p>Mandarina: dulce y jugosa, con una sensación de suavidad.</p><p>Naranja: cítrica y dulce, con una nota alegre.</p><p>Canela roja: especiada y cálida, con un toque picante</p>', 28800, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4a7-e071-74cd-8906-72c1aae123ac.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Una fragancia masculina que combina la frescura de los cítricos con la calidez de las especias y la profundidad de las maderas, creando una estela envolvente y energética. Ideal para hombres que buscan un aroma distintivo y sofisticado. <strong>Incluye perfume 100ml, mini y gel de ducha.</strong></p>', NULL),
(12232, 'Set Perry Ellis 360 Purple EDP 3pzas Mujer', '<p>Durazno (melocotón): jugoso y dulce, aporta una apertura afrutada y cálida.</p><p>Zarzamora (frambuesa negra): añade un toque ligeramente ácido y profundo.</p><p>Flor de manzano: fresca y ligera, con un matiz floral delicado.</p>', 28800, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4a5-80de-776f-9f1d-518e35580482.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Una fragancia femenina que fusiona la frescura de las frutas con la sofisticación de las flores blancas y un toque amaderado, creando una estela envolvente y elegante. Ideal para mujeres modernas que buscan un aroma distintivo y encantador. <strong>Incluye perfume 100ml, mini y gel de ducha.</strong></p>', NULL),
(12233, 'Set Perry Ellis 360 EDT 3pzas Mujer', '<p><strong>Estilo </strong>Olfativo Floral cítrico almizclado</p><p><strong>Apertura </strong>Citrus especiado (paprika + mandarina)</p><p><strong>Corazón </strong>Floral blanco (azahar y orquídea)</p><p><strong>Base </strong>Vainilla, ámbar, almizcle blanco </p><p>Destacado por su suavidad y versatilidad económica.</p>', 30500, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d4a3-0c52-71ed-b6c6-a7d82afd1c3b.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Perry Ellis 360° White es una fragancia floral almizclada con toques cálidos y dulces. Combina una apertura cítrica especiada (mandarina con paprika) con un corazón floral blanco refinado, terminando en una base suave y reconfortante gracias a la vainilla, el ámbar y el almizcle blanco. Está diseñada para el uso diario y se considera versátil para climas templados o frescos. <strong>Incluye perfume 100ml, mini y gel de ducha.</strong></p>', NULL),
(12234, 'Mancera Red Tobacco EDP 120ml Unisex', '<p><strong>Salida (Notas de cabeza):</strong> canela, azafrán, incienso, nuez moscada, manzana verde, durazno blanco y oud nepalí</p><p><strong>Corazón (Notas medias):</strong> jazmín y pachulí</p><p><strong>Fondo (Notas de base):</strong> tabaco preciado, ámbar, maderas (sándalo, guayaco), vetiver, vainilla y almizcle blanco</p>', 65000, 2, 'Mancera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d49b-3d44-7797-9e1e-50695ef550df.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d49b-3a2f-72cc-9436-cd2b754d683b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d49b-3ee3-77f3-af71-1c779d693781.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Red Tobacco es una fragancia cálida, especiada y oriental-fumada. Abre con una explosión de especias y frutas, evoluciona hacia un núcleo ahumado, y termina en un fondo dulce, amaderado y tabacalero. Es intensa, duradera y bastante proyectiva.</p>', NULL),
(12235, 'Mancera Cedrat Boise EDP 120ml Unisex', '<p><strong>Salida:</strong> limón, grosella negra, especias</p><p><strong>Corazón:</strong> frutas, hojas de pachulí, jazmín</p><p><strong>Fondo:</strong> cedro, cuero, sándalo, vainilla, almizcle</p>', 61000, 2, 'Mancera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d494-677e-72fc-a139-01ab367a87b0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d494-645e-71f8-960a-5c80017c8f29.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia fresca y vibrante con salida cítrica intensa, corazón afrutado y fondo amaderado y almizclado. Ideal para todo el año, especialmente primavera y verano.</p>', NULL),
(12236, 'Montblanc Legend Blue EDP 100ml Hombre', '<ul><li><strong>Notas de salida:</strong> Lavanda, menta verde</li><li><strong>Notas de corazón:</strong> Madera de cedro, sándalo</li><li><strong>Notas de fondo:</strong> Ambroxan, musgo</li></ul>', 42500, 0, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d48f-5797-710c-a6bf-39a9c1aa3d98.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d48f-546b-76ff-abfe-a1edaf909882.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Montblanc Legend Blue</strong> es una fragancia aromática amaderada que combina frescura y sofisticación. Ideal para el hombre moderno y elegante, ofrece una estela limpia y masculina, perfecta para el uso diario y ocasiones especiales. </p>', NULL),
(12237, 'Ariana Grande Mood Vainilla EDP 100ml Mujer', '<ul><li><strong>Notas de salida:</strong> Fresia, Ciruela, Almizcle</li><li><strong>Notas de corazón:</strong> Iris, Praliné</li><li><strong>Notas de fondo:</strong> Vainilla, Cacao</li></ul>', 39000, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d486-ee01-7318-b66d-23b0be99be29.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d486-ee9e-7088-b7c4-d308d8667f05.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d486-ef2e-7068-846b-ee910515f97b.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Mod Vanilla</strong> es una fragancia dulce y envolvente que combina la calidez de la vainilla con toques florales y afrutados. Ideal para quienes buscan un perfume suave y reconfortante, perfecto para el uso diario o para ocasiones especiales. Su duración es moderada, ofreciendo una estela sutil pero persistente.</p>', NULL),
(12238, 'Ariana Grande Mood Blush EDP 100ml Mujer', '<p><strong>Notas de salida:</strong> Bergamota italiana, fruta de la pasión, pimienta rosa, frambuesa</p><p><strong>Notas de corazón:</strong> Rosa, magnolia, pera</p><p><strong>Notas de fondo:</strong> Almizcle, ambroxan, Dreamwood™, sándalo</p>', 38000, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d483-bf55-714d-8801-8d8f943d8f61.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d483-bdf3-7361-8e23-0850f22b1d26.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d483-bf87-73b5-a946-5cd6517b42a8.png?storeId=1681', 'Mujer', 1, 0, '<p>Ariana Grande Mod Blush es una fragancia fresca, floral y afrutada con un toque moderno y delicado. Ideal para el día a día, combina notas cítricas y frutales con un fondo suave y almizclado, perfecta para quienes buscan una esencia ligera y femenina.</p>', NULL),
(12239, 'Giorgio Armani Acqua Di Gio Profondo Parfum 100ml Hombre', '<p><strong>Notas de salida:</strong> Bergamota, pimienta negra, y un toque de limón</p><p><em>(aportan frescura y un inicio vibrante y especiado)</em></p><p><br></p><p><strong>Notas de corazón:</strong> Jazmín, lavanda y pachulí</p><p><em>(añaden un carácter floral elegante y un poco terroso)</em></p><p><br></p><p><strong>Notas de fondo:</strong> Ámbar, almizcle y vainilla</p><p><em>(ofrecen calidez, sensualidad y una base duradera)</em></p>', 72000, 1, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d47c-c6b6-7082-9f91-ccb825ab3734.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d47c-c384-74dc-b4f8-0bbc372b330c.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Profondo Parfum es una fragancia que destaca por su aroma intenso y envolvente, ideal para quienes buscan una experiencia olfativa profunda y sofisticada. Desde la primera aplicación, se perciben notas cálidas y misteriosas que capturan la atención sin ser abrumadoras. Es una fragancia versátil para la noche o para ocasiones especiales, que transmite confianza y sensualidad. Su duración es notable, y el sillage (la estela que deja) es moderado a intenso, perfecto para quienes quieren dejar una impresión duradera.</p>', NULL),
(12240, 'Jo Milano Game Of Spades FULL-HOUSE Parfum 100ml Unisex', '<ul><li><strong>Salida / Top:</strong> Bergamota calabresa, naranja siciliana y citron.</li><li><strong>Corazón / Medio:</strong> Neroli de Túnez, jengibre nigeriano y canela de Ceilán.</li><li><strong>Base / Fondo:</strong> Ambroxan, té negro chino, olíbano y madera de guayaco.</li></ul><p><br></p><p>Esta composición inicia con una explosión cítrica fresca, seguida de un corazón especiado y floral, y culmina en una base cálida, amaderada y ligeramente ahumada</p>', 51000, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d46f-94a3-7016-8d34-fcd0c4a155ba.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d46f-984c-77de-9734-7824b953ad86.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><strong>Jo Milano Game of Spades Full-House Parfum</strong> es una fragancia unisex de la colección <em>Luxury</em> de Jo Milano, lanzada en 2024. Se inspira en <em>Louis Vuitton Imagination</em>, ofreciendo una interpretación más accesible en términos de precio.</p>', NULL),
(12241, 'Jo Milano Game Of Spades BONUS Parfum 100ml Unisex', '<p><strong>Salida / Top:</strong> limón, naranja, citron, menta, grosella negra, coriandro (cilantro) </p><p><strong>Corazón / Medio:</strong> rosa de mayo, albaricoque, albahaca, semillas de zanahoria </p><p><strong>Base / Fondo:</strong> ambrette, higo, dátiles</p>', 51000, 2, 'Jo Milano', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d46c-49a7-7182-af6c-875c8d6b73f7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d46c-4752-7246-873b-10cf70e54f53.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>“Game of Spades Bonus” es una fragancia unisex que combina notas frutales, cítricas y herbales, con una base cálida, dulce y ligeramente seca por los dátiles y el higo. Tiene frescura inicial por los cítricos y la menta, un corazón frutal‑floral con carácter, y una base reconfortante que le da profundidad. Destaca por ser alegre, llamativa, con buen contraste entre lo fresco y lo cálido, ideal para quienes buscan algo versátil pero con presencia.</p>', NULL),
(12242, 'Jo Milano Game Of Spades WILCARD Parfum 100ml Unisex', '<p><strong>Salida / Top:</strong> bergamota, flores, coriandro (coriander)</p><p><strong>Corazón / Medio:</strong> manzana, ambroxan, vainilla </p><p><strong>Fondo / Base:</strong> tonka bean, ámbar gris, notas amaderadas</p>', 51000, 1, 'Jo Milano', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d467-9034-77ce-9bd3-63049acac9be.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d467-909f-73d4-917c-23f8bb7bbd0b.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Es una fragancia <strong>unisex</strong> floral‑amaderada‑almizclada con toques frutales y gourmand, bastante moderna. La concentración es <em>Parfum</em>, lo que le da mayor duración e intensidad que muchas EDT/EDP comunes. Su apertura tiene frescura cítrica y floral, luego evoluciona a una mezcla dulce/frutada con la manzana y la vainilla, y más tarde se asienta en un fondo cálido, amaderado y dulce por la tonka y el ámbar gris.</p>', NULL),
(12243, 'Orientica Oud Zafron EDP 80ml Unisex', '<p><strong>Salida / Top:</strong> notas orientales, vainilla </p><p><strong>Corazón / Medio:</strong> azafrán, pachulí </p><p><strong>Fondo / Base:</strong> oud, madera de guayaco (gaiac wood), almizcle</p>', 51000, 0, 'Orientica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d42b-fc80-721d-858d-223b96654513.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d42b-f83c-7368-a10b-765a48a9502d.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Esta fragancia es de la familia <strong>oriental‑amaderada especiada</strong>, lanzada en 2021. Es un perfume unisex que combina dulzura (de la vainilla) con riqueza especiada (azafrán) y profundidad amaderada (oud + madera de gaiac), lo que da una sensación de lujo, sofisticación, y mucha presencia. Se adapta bien tanto para ocasiones nocturnas como para momentos especiales, y suele tener buena fijación y proyección.</p>', NULL),
(12244, 'Armaf Club De Nuit Lion Heart 105ml EDP Hombre', '<p><strong>Salida / Top notes:</strong> Lavanda, Menta </p><p><strong>Corazón / Notas medias:</strong> Vainilla, Benjuí </p><p><strong>Fondo / Notas base:</strong> Haba tonka, Miel, Tabaco</p>', 33500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d425-1aed-734e-8b3d-862ab6450843.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d425-1c34-75bf-8772-6aadb38b2afd.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Armaf Club De Nuit Lionheart Man EDP</strong> es una fragancia masculina de carácter <strong>oriental-fougère</strong>, intensa y envolvente, ideal para climas frescos o salidas nocturnas. Abre con un toque fresco y aromático de <strong>lavanda y menta</strong>, que evoluciona hacia un corazón cálido de <strong>vainilla y benjuí</strong>, finalizando con una base dulce y profunda de <strong>haba tonka, miel y tabaco</strong>. Tiene <strong>buena duración y proyección</strong>, dejando un rastro seductor, moderno y masculino con personalidad marcada.</p>', NULL),
(12245, 'Parfums De Marly Delina 75ml EDP Mujer', '<p><strong>Salida / Notas de cabeza:</strong></p><ul><li>Ruibarbo</li><li>Lichi (Lychee) </li><li>Bergamota </li><li>Nuez moscada (Nutmeg) </li></ul><p><strong>Corazón / Notas medias:</strong></p><ul><li>Rosa Damascena (Rosa Damascena) </li><li>Peonía (Peony) </li><li>Musgo blanco / Almizcle blanco (White Musk)</li><li>Petalia (una nota floral) </li><li>Vainilla (Vanilla) </li></ul><p><strong>Fondo / Notas base:</strong></p><ul><li>Cashmeran </li><li>Cedro (Cedarwood) </li><li>Vetiver </li><li>Incienso (Incense)</li></ul>', 165000, 0, 'Mujer', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d41c-422a-70cf-b037-2d59248683bd.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d41c-423c-735c-8d74-8ea0995972be.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>frutal‑floral dulce</strong>, con mucha elegancia. Tiene un toque moderno pero refinado. La rosa Damascena aporta la flor clásica, mientras que lichi, ruibarbo y bergamota ofrecen frescura y parte jugosa/frutada al inicio. La vainilla, el musk y el cashmeran le dan suavidad, calidez y buen agarre en la piel. </p>', NULL),
(12246, 'Animale 75ml EDP Mujer', '<p><strong>Salida (Top) </strong></p><p>• Cilantro </p><p>• Notas verdes </p><p>• Jacinto </p><p>• Neroli </p><p>• Bergamota </p><p>• Palo de rosa de Brasil</p><p><strong>Corazón (Medio)</strong>• Miel </p><p>• Clavel </p><p>• Raíz de lirio (orris) </p><p>• Jazmín </p><p>• Ylang‑ylang </p><p>• Lirio de los valles (muguete) </p><p>• Rosa</p><p><strong>Fondo (Base)</strong>• Musgo de roble (oakmoss) </p><p>• Civet (algalia) </p><p>• Pachulí </p><p>• Vetiver </p><p>• Almizcle </p><p>• Coco</p>', 29800, 0, 'Animale', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d416-24c2-77e2-b93f-d166d3aabf92.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d416-2b43-71db-b997-1c549465566f.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Animale</em> es una fragancia clásica para mujer, lanzada en <strong>1987</strong>. Pertenece a la familia olfativa <strong>Chipre floral</strong>. Eso significa que combina notas florales con un fondo terroso/musgoso, algo de almizcle, y componentes con carácter verde / animalico que aportan profundidad. Es intensa, con buena persistencia y estela (“sillage”) — muchos usuarios comentan que dura bastante bien. </p>', NULL),
(12247, 'Azzaro Wanted EDP 100ml Hombre', '<p><strong>Salida / Cabeza:</strong> bayas de enebro (<em>juniper berries</em>) </p><p><strong>Corazón / Medio:</strong> salvia (<em>sage</em>) </p><p><strong>Fondo / Base:</strong> vetiver</p>', 48000, 2, 'Azzaro', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d411-575a-77e1-a873-f5f81a081483.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d411-57e7-706e-b548-dbb50b96d0ec.png?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia que mezcla frescura herbal / aromática con base seca de vetiver, resultando elegante, relativamente masculina, con carácter pero sin ser demasiado agresiva. Hay un toque ligeramente dulce/herbal que la suaviza.</p>', NULL),
(12248, 'Versace Bright Crystal Parfum 90ml Mujer', '<p><strong>Salida / Top</strong>Yuzu, Granada (Pomegranate), Frutos rojos (“Red Fruits”), Acorde helado (<em>ice accord</em>) </p><p><strong>Corazón / Medio</strong>Peonía, Magnolia, Flor de Loto (Lotus), Helvetolide (un almizcle sintético floral/frutal) </p><p><strong>Base / Fondo</strong>Acajou (madera caoba), Ámbar vegetal, Almizcle, Ambrox / Ambrox Super / Norlimbanol (moléculas base ambaradas y amaderadas modernas) </p>', 56000, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d409-f456-734b-a8d3-8842c70e5ed6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d409-f808-72eb-886d-ce741167edf9.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Bright Crystal Parfum</strong> es una versión lanzada en <strong>2024</strong> que toma el ADN del Bright Crystal clásico (2006) pero lo hace más profundo, más brillante, con toques más modernos y una presencia un poco más marcada. Está pensada para quienes les gusta la fragancia floral‑frutada ligera, femenina y elegante, pero con más riqueza, mejor duración y un acabado más sofisticado que solo un EDT. El frasco mantiene la estética cristalina de la línea Bright Crystal, con un líquido rosado claro, tapa facetada tipo cristal, líneas limpias y presencia muy “versace‑femenina”.</p>', NULL),
(12249, 'Hugo Boss XX EDT 100ml Mujer', '<p><strong>Salida / Top:</strong> lichi, grosella negra, mandarina.</p><p><strong>Corazón / Medio:</strong> jazmín, arroz basmati, rosa.</p><p><strong>Base / Fondo:</strong> almizcle, sándalo, ámbar.</p>', 28000, 1, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d406-20fd-76fa-950c-3dd1f832ccec.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d406-1f4f-705f-a34e-232a7995ea0c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d406-1d97-761f-be18-40e1beeeb4ee.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Moderno, femenino, algo juguetón por las notas frutales, pero con elegancia gracias al jazmín/rosa/almizcle. No es extremadamente pesado, puede usarse para el día o noche dependiendo de cuánto lo apliques.</p>', NULL),
(12250, 'Antonio Banderas Queen Of Seduction 80ml EDT Mujer', '<p><strong>Salida / Notas de cabeza:</strong> acorde acuoso, pomelo (grapefruit), frambuesa </p><p><strong>Corazón / Medio:</strong> peonía, jazmín, iris, pimienta rosa (pink pepper) </p><p><strong>Fondo / Notas base:</strong> gamuza (suede), cedro, ámbar</p>', 18000, 1, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3fb-7587-751f-9370-e845c227f35a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3fb-7515-745f-9eb4-c7a4370f17ac.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3fb-7905-74a6-9985-df71260372b2.png?storeId=1681', 'Mujer', 1, 0, '<p>Aroma fresco, veraniego, ligero. Ideal para uso diario, ambiente cálido, primavera / verano. No es una fragancia muy densa; se siente limpia, femenina, con vida. No es demasiado dulce ni pesada; el punto dulce lo da la frambuesa junto con el pomelo, pero no domina todo. Las notas florales le aportan delicadeza.</p>', NULL),
(12251, 'Jean Paul Gaultier Le Male Elixir Absolu 125ml Hombre', '<p><strong>Salida / Top:</strong> ciruela (<em>plum</em>), canela (<em>cinnamon</em>), cardamomo (<em>cardamom</em>), bergamota.</p><p><strong>Corazón / Medio:</strong> lavanda (<em>lavender</em>), davana, artemisia.</p><p><strong>Base / Fondo:</strong> haba tonka (<em>tonka bean</em>), benjuí (<em>benzoin</em>), almizcle de ambrette (<em>ambrette musk</em>), pachulí, ládano (<em>labdanum</em>)</p>', 69500, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3f7-50e6-7721-8509-b329062da824.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3f7-54a4-7415-b869-b66160ca6617.png?storeId=1681', 'Hombre', 1, 0, '<p>Las primeras impresiones suelen ser bastante frutales (la ciruela se nota) con especias cálidas (canela, cardamomo), y una lavanda que aporta frescura herbal. Luego evoluciona hacia una base más cálida, dulce y envolvente gracias a la haba tonka, benjuí y ládano. Se comenta que tiene <strong>muy buena duración</strong> y estela: proyecta bien al inicio y deja huella bastante tiempo. No es una fragancia ligera: el perfil dulce + especiado + frutal la hace más adecuada para clima templado o frío, o para uso nocturno / salidas cuando se quiera destacar.</p>', NULL),
(12252, 'Jean Paul Gaultier Le Male EDT 125ml Hombre', '<p><strong>Salida / Top notes</strong>: Lavanda, menta, bergamota, cardamomo, artemisia. </p><p><strong>Corazón / Medio</strong>: Canela, flor de azahar (orange blossom), alcaravea (caraway).</p><p><strong>Fondo / Base notes</strong>: Vainilla, haba tonka, ámbar, sándalo, cedro.</p>', 59500, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3f2-943b-73c9-ad62-09c6c08f32ca.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3f2-9335-762b-a3c3-8d4f11422db5.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Es muy reconocible por el contraste entre la frescura inicial (menta + lavanda) y un fondo cálido, dulce y algo cremoso gracias a la vainilla y la haba tonka. A lo largo de las horas, las notas especiadas y amaderadas (cedro, sándalo, ámbar) cobran más protagonismo. Su estilo lo hace ideal para quien busca un perfume que combine lo llamativo y lo clásico, con buena recepción: muchos lo consideran de los perfumes masculinos que más cumplidos generan.</p>', NULL),
(12253, 'Jean Paul Gaultier Scandal Le Parfum 100ml Hombre', '<p><strong>Salida / Top</strong>Geranio</p><p><strong>Corazón / Medio</strong>Haba tonka</p><p><strong>Fondo / Base</strong>Sándalo, Vetiver</p>', 62000, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3df-d792-70de-9d04-631864252059.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3df-db61-73f6-a1af-c5a822a7d371.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3df-d8aa-74b5-9bb6-9db22b902dfe.png?storeId=1681', 'Hombre', 1, 0, '<p>Lanzamiento: <strong>2022</strong>. Familia olfativa: Amaderada ‑ Gourmand / Ámbar amaderado. Perfil: es una fragancia intensa, con carácter dulce, cálido, con notas especiadas y cremosas, ideal para noches o climas templados‑fríos.</p>', NULL),
(12254, 'Versace Eros 100ml EDP Mujer', '<p><strong>Salida / Top notes:</strong> limón siciliano, bergamota de Calabria, granada.</p><p><strong>Corazón / Notas medias:</strong> flor de limón, jazmín sambac, jazmín común, peonía.</p><p><strong>Fondo / Base notes:</strong> almizcle, ambroxan, notas amaderadas, sándalo</p>', 45000, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3d6-b952-7434-a3f6-a237bd42d31f.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3d6-b7eb-74bd-bb57-90ca137700d8.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>floral‑amaderada‑almizclada</strong>, con un toque cítrico brillante al inicio que luego evoluciona hacia notas florales suaves y una base más cálida, cremosa y sensual. Fue lanzada en <strong>2014</strong>. Diseñadores involucrados: Alberto Morillas, Olivier Cresp y Nathalie Lorson.</p>', NULL),
(12255, 'Set Perry Ellis Sky EDT', '<p><strong>Salida (top notes):</strong></p><ul><li>Lima (limón verde) </li><li>Bergamota </li><li>Lavanda </li><li>Menta</li></ul><p><br></p><p><strong>Corazón (notas medias):</strong></p><ul><li>Notas acuáticas (“watery notes”)</li><li>Hoja de violeta</li><li>Pamplewood (una nota amaderada con matiz cítrico/floral) </li><li>Ládenum (labdanum) </li></ul><p><br></p><p><strong>Fondo (notas base):</strong></p><ul><li>Cedro de Virginia</li><li>Ambroxan</li><li>Pachulí </li><li>Sándalo</li></ul>', 30500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3d0-b967-7260-89bd-74a60650a60f.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Sky es una fragancia fresca, moderna y versátil para hombre, lanzada en <strong>2022</strong>. Pertenece a la familia <strong>cítrico-aquática-amaderada</strong> — combina notas luminosas y refrescantes con bases cálidas y maderadas. Es adecuada tanto para uso diurno como nocturno, especialmente en climas cálidos, o para cuando quieres algo que sea fresco pero con cuerpo.</p>', NULL),
(12256, 'Valentino Uomo Born In Roma Extradose Parfum 100ml Hombre', '<p><strong>Salida / Cabeza</strong>Notas especiadas (“Spicy Notes”), Bergamota, Mandarina</p><p><strong>Corazón / Medio</strong>Lavandín salvaje (“Wild Lavender” / “Lavandin” / lavanda aromática), notas saladas</p><p><strong>Fondo / Base</strong>Notas amaderadas (Woody notes), Vetiver, madera guaiac (Guaiac Wood)</p>', 72000, 0, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d192-3c76-7642-a131-911496b732f0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d192-3ca6-71ca-8c53-932469cee4b7.png?storeId=1681', 'Hombre', 1, 0, '<p>Lanzado en <strong>2025</strong>, esta versión posee un aroma más intenso que las versiones anteriores de la línea Born in Roma Uomo; busca dar una impresión más seductora, con madera, especias y lavanda.</p>', NULL),
(12257, 'Armaf Odyssey Eau Montagne 100ml EDP Unisex', '<p><strong>Salida / Top </strong>Almendra, lactonas cremosas, especias suaves.</p><p><strong>Corazón / Medio </strong>Flores blancas.</p><p><strong>Fondo / Base </strong>Vainilla, cacao, madera de sándalo, almizcle.</p>', 29500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d18d-c5fe-70c4-ad65-4a7635bba7eb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d18d-c691-702b-a49c-4295e4a6d329.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Tiene un carácter cálido, reconfortante, bastante gourmand por la almendra, vainilla y cacao. Pero también tiene elegancia gracias al sándalo y las flores blancas. </p><p>Climas recomendados: más para días frescos, invierno o noches frías, ya que su dulzura y calidez pueden sentirse pesadas en calor extremo. Uso ideal: para salir, cenas, eventos especiales, o cuando quieres algo dulce, acogedor y con presencia, pero que no sea agresivo.</p>', NULL),
(12258, 'Versace Eros Najim Parfum 100ml Hombre', '<p><strong>Salida / Top</strong>Mandarina amarilla de Italia, Salvia Esclarea, Azafrán, Cardamomo</p><p><strong>Corazón / Medio</strong>Oud, Cedro, Caramelo</p><p><strong>Base / Fondo</strong>Incienso (incense), Pachulí, Vetiver, Haba Tonka</p>', 52000, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d188-af71-72ff-87b5-9f571c97cef0.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d188-b0e9-748f-8e8b-dd2b71c51d77.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Es una edición de la línea <em>Eros</em> de Versace, con un perfil más cálido, especiado y oriental‑ambarado, con influencias notables del gusto del Medio Oriente. Se presenta como un Parfum; es más concentrado, denso, con mejor duración y presencia que muchas versiones EDT o EDP de la línea Eros.</p>', NULL),
(12259, 'Paco Rabanne Fame The Couture Edition EDP 80ml Mujer', '<p><strong>Salida / Top</strong>Incienso cremoso (<em>Creamy Incense</em>), Bergamota de Italia, Agua de Coco</p><p><strong>Corazón / Medio</strong>Iris, Jazmín Sambac, Wolfwood </p><p><strong>Fondo / Base</strong>Bálsamo de vainilla (<em>Vanilla Balm</em>), Sándalo australiano, Almizcle (Musk)</p>', 68800, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d17e-5107-7339-9163-0ca9ff5036d6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d17e-550e-727d-8ff6-fbe02069136b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d17e-4ec1-713d-b960-c9faabdb6c35.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><em>Fame The Couture Edition</em> es una edición limitada lanzada en <strong>2025</strong> por Paco Rabanne dentro de la línea <em>Fame</em>. Se inspira en la moda, lo chic y lo audaz: el frasco viene vestido con un abrigo de peluche y detalles dorados, recreando un aire de glamour y estilo vanguardista. Aromáticamente es una fragancia floral‑ámbar, dulce pero con elementos cremosos y toques sofisticados como incienso y polvo de iris, lo que le da elegancia y presencia. </p>', NULL),
(12260, 'Paris Corner Marshmellow Blush EDP 100ml Mujer', '<p><strong>Salida / Top:</strong> Strawberry (fresa), Raspberry (frambuesa), Lemon (limón) </p><p><strong>Corazón / Medio:</strong> Ambroxan, Orange Blossom (azahar), Whipped Cream (nata montada / crema batida)</p><p><strong>Fondo / Base:</strong> Musk (almizcle), Marshmallow (malvavisco / nube de azúcar), Vanilla (vainilla)</p>', 32500, 2, 'Paris Corner', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d178-1dea-7199-b076-c15e330db0bf.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d178-21cb-731a-b3f8-beef90fc85e8.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d178-1fef-724d-ba72-aa52fb6c445a.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>gourmand‑frutal</strong> dulce, juguetona, con carácter reconfortante. La sensación al usarla es como un batido de fresa cremoso, con malvavisco suave, vainilla y notas de crema, con un toque de almizcle que le da algo de “pegamento” al aroma para que dure más. Se le menciona que tiene similitudes con <em>Kayali Yum Boujee Marshmallow</em>, lo cual sugiere que apunta al mismo estilo dulce‑cremoso que ese perfume popular.</p>', NULL),
(12261, 'Messi EDP 100ml Hombre', '<p><strong>Salida / Cabeza </strong>Cardamomo fresco, hoja de manzana, ciprés silvestre</p><p><strong>Corazón / Medio </strong>Cuero, lavanda, raíz de lirio (iris) </p><p><strong>Base / Fondo </strong>Vainilla (vainilla bean), pachulí, cedro de Virginia</p>', 32500, 2, 'Messi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d167-d9c4-742c-9459-3fa5b7ff921a.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d167-da17-77e7-8ae1-59212ad75997.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Messi EDP</em> es una fragancia masculina lanzada en 2024, con la idea de capturar la personalidad de Lionel Messi: elegancia, humildad, carisma y presencia. Se define dentro de la familia <strong>amaderado‑aromática / fougère ambarada</strong>, con una apertura fresca y especiada, corazón elegante con matices de cuero y raíz de lirio, y una base cálida que incluye vainilla, madera de cedro y pachulí. </p><p>Tiene buena versatilidad: puede usarse tanto para el día como para la noche, funciona bien en climas templados a frescos, y su perfil lo hace apropiado para situaciones casuales y también más formales si buscas algo que imponga discretamente. </p>', NULL),
(12262, 'Zimaya Fatima Velvet Love Extrait De Parfum 100ml Mujer', '<p><strong>Salida (Top):</strong> violeta, bergamota, pera </p><p><strong>Corazón (Heart):</strong> rosa, lavanda, agarwood (oud) </p><p><strong>Fondo (Base):</strong> oud, vainilla</p>', 25500, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d161-0dcc-7189-9a37-34c9f13e288c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d161-1118-727b-ba00-c6c4de700b52.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>femenina, </strong>se clasifica dentro de la familia <strong>floral‑amaderada</strong> (o floriental con base de madera / oud) Versión Extrait de Parfum en muchos casos, lo que sugiere una concentración mayor que un EDP estándar, lo que puede aportar mejor duración y proyección. Dulzura moderada a alta, debido a la vainilla y notas frutales. Perfil sofisticado, ideal para ocasiones especiales o para quienes buscan un perfume con presencia.</p>', NULL),
(12263, 'Set Afnan 9am Dive 3pzas', '<p>Familia olfativa: Aromática - Acuática - Cítrica</p><p><br></p><p>Notas de salida: Menta, limón, pimienta rosa, mandarina</p><p>Notas de corazón: Lavanda, canela, jengibre, notas marinas</p><p>Notas de fondo: Ámbar, pachulí, madera de gaiac, cedro</p><p><br></p><p>Esta fragancia ofrece una apertura refrescante y chispeante, seguida por un corazón especiado y limpio, y culmina en una base cálida y amaderada que le da profundidad sin perder su frescura.</p>', 34000, 1, 'Afnan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d153-c94c-77d0-aa93-32c8e1c414e5.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Afnan 9AM Dive es una fragancia masculina vibrante y acuática, ideal para el verano. Su aroma fresco y energizante combina notas cítricas y marinas con un fondo amaderado y ligeramente especiado. Es una fragancia que evoca la sensación de una inmersión matutina en aguas cristalinas, perfecta para hombres que buscan una esencia limpia, dinámica y duradera. </p><p>Este set incluye perfume 100ml + Gel de ducha y desodorante.</p>', NULL),
(12264, 'Set Afnan 9pm 3pzas', '<p>Notas de salida: Manzana, canela, lavanda silvestre y bergamota.</p><p>Notas de corazón: Flor de azahar del naranjo y lirio de los valles (muguete).</p><p>Notas de fondo: Vainilla, haba tonka, ámbar y pachulí.</p><p>Esta combinación crea una fragancia cálida, dulce y ligeramente especiada, con una base cremosa y envolvente.</p><p><strong> Características generales</strong></p><p>Familia olfativa: Ámbar Vainilla.</p><p>Estilo: Dulce, cálido y envolvente.</p><p>Uso recomendado: Ideal para ocasiones nocturnas y eventos especiales.</p>', 34000, 0, 'Afnan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d14f-674f-774a-b9eb-a2ad1c254bf3.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Afnan 9PM Eau de Parfum es una fragancia masculina lanzada en 2020 por la marca emiratí Afnan. Perteneciente a la familia olfativa Ámbar Vainilla, se caracteriza por su aroma dulce, cálido y envolvente, ideal para ocasiones nocturnas y eventos especiales. Este set incluye perfume 100ml + Gel de ducha y desodorante.</p>', NULL),
(12265, 'Dior Sauvage Parfum 100ml Hombre', '<p><strong>Salida / Top</strong>Bergamota, Mandarina, Elemi</p><p><strong>Corazón / Medio</strong>Sándalo (de Sri Lanka)</p><p><strong>Fondo / Base</strong>Olibanum (incienso/resina), Haba tonka, Vainilla</p>', 86000, 0, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d149-a18a-77ff-b84d-e554a13ac685.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d149-9f43-749e-9fef-eebda5b43e53.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Sauvage Parfum</em> fue lanzado en <strong>2019</strong> como una versión más concentrada, cálida y profunda del ADN Sauvage. Persigue mantener la frescura de las versiones anteriores (EDT, EDP), pero con mayor riqueza de notas especiadas, ambarinas y resinosas; menos chispeante, más envolvente. Perfecta para uso nocturno, climas templados a fríos, ocasiones en que se quiere destacar con elegancia. </p>', NULL),
(12266, 'Armaf Odyssey Artisto 100ml EDP Men', '<p><strong>Salida / Top</strong>Bergamota, frutos secos, salvia </p><p><strong>Corazón / Medio</strong>Coco, frutas tropicales, canela</p><p><strong>Fondo / Base</strong>Vainilla, haba tonka, ámbar</p>', 29500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d141-f805-75aa-92d2-424f6d7cd568.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d141-f7b3-7116-911a-6a0763cedff5.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Odyssey Artisto</em> es una fragancia nueva de Armaf, lanzada en <strong>2025</strong>. Pertenece a la familia olfativa <strong>Amaderada‑Aromática con toques gourmand y tropicales</strong>. Combina notas frescas y especiadas al inicio, un corazón exótico/frutal/coco, y una base cálida y dulce. Se describe como bastante versátil, aunque su perfil dulce/cremoso lo hace especialmente adecuado para climas templados o frescos, así como para salidas nocturnas o momentos en que quieres destacar.</p>', NULL),
(12267, 'Burberry Her 100ml EDT Women', '<p><strong>Salida / Top</strong>Pera (pear), fresa (strawberry), grosella negra (blackcurrant), pimienta rosa (pink pepper) </p><p><strong>Corazón / Medio</strong>Peonía (peony), madreselva (honeysuckle), rosa, lirio del valle (lily‑of‑the‑valley) </p><p><strong>Fondo / Base</strong>Almizcle (musk), cedro (cedarwood)</p>', 59000, 1, 'Burberry', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d13c-17d6-764c-83ee-c90338d88239.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d13c-18d6-737f-b0bd-ab2ada14a4ec.png?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en <strong>2022</strong>. Es una versión más fresca y ligera de la línea <em>Her</em>, con un perfil frutal‑floral, dulce pero con más brillo que profundidad que la versión EDP o versiones más densas. Ideal para uso diario, primavera y verano, ocasiones casuales o ambientes donde no se quiera algo demasiado pesado. Buen aroma para ambientes de día.</p>', NULL),
(12268, 'Armaf Club De Nuit Maleka 105ml EDP Mujer', '<p><strong>Salida / Top notesLychee</strong> (lichi), <strong>Bergamota</strong>, <strong>Pimienta rosa</strong> </p><p><strong>Corazón / MedioOrris</strong> (raíz de lirio / iris) — aporta ese toque floral empolvado y elegante</p><p><strong>Base / FondoPraliné</strong> (dulce, gourmand), <strong>Sándalo</strong> (cremoso, amaderado), <strong>Ambrox / Ambroxan</strong> (nota ambarina, moderna y de fijación)</p>', 30500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d137-57ba-7188-a235-24abb76ff8f6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d137-580f-7249-9dd7-0f603f8b4f3a.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d137-563b-775f-b801-0ea8fc5d4a30.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><em>Club De Nuit Maleka</em> es una fragancia nueva de Armaf, lanzada en <strong>2025</strong>. Pertenece a la familia olfativa <strong>floral‑frutada</strong> con matices gourmand y ambarados. Tiene una mezcla de frescura frutal inicial, un corazón floral empolvado, y base dulce y cálida que lo hace bastante envolvente. Apunta a ser elegante, con presencia, apta tanto para el día como para la noche, dependiendo de aplicación.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12269, 'Jesus Del Pozo Halloween Kiss EDT 100ml Mujer', '<p><strong>Salida / Cabeza </strong>Coca‑Cola, sandía, bayas rojas, pera, naranja sanguina, violeta, bergamota</p><p><strong>Corazón / Medio </strong>Orquídea, gardenia, melocotón (durazno), peonía, fresia</p><p><strong>Fondo / Base </strong>Chocolate, vainilla, haba tonka, pachulí, teca (madera de teca) </p>', 22000, 1, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d131-6c03-77ed-aa5b-4ebdf49b6537.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d131-70ee-750a-b200-a288b4ba5638.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Halloween Kiss</em> fue lanzado en <strong>2008</strong> como una versión más romántica / sensual dentro de la línea Halloween. Se clasifica dentro de la familia <strong>Floral Acuática / Frutal</strong> (aunque con toques gourmands) para mujer. Es conocida por su carácter dulce, juguetón y algo exótico, combina elementos frutales, flores y notas gourmand como chocolate / vainilla.</p>', NULL),
(12270, 'Paco Rabanne Pure XS 100ml EDT Hombre', '<p><strong>Salida / Cabeza (Top notes) </strong>Jengibre, Tomillo, Pomelo (Grapefruit), Bergamota, Acordes verdes. </p><p><strong>Corazón / Medio </strong>Vainilla, Licor, Canela, Cuero, Manzana.</p><p><strong>Fondo / Base (Base notes) </strong>Mirra, Azúcar, Cedro, Notas Amaderadas, Cachemira, Pachulí.</p>', 53000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d11f-7122-726e-a534-8afc03e207fb.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d11f-73b7-70b5-aa7e-6b717a4aba87.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Pure XS</em> fue lanzada en <strong>2017</strong>. Es una fragancia oriental‑especiada con una mezcla llamativa de dulce, licor, vainilla, especias y notas herbales. Tiene carácter seductor y atrevido. Aunque empieza con tonos frescos y especiados, rápidamente evoluciona hacia una base cálida, avainillada y aromática, bastante intensa. Es ideal para usar de noche, en clima templado o frío, en salidas especiales.</p>', NULL),
(12271, 'Yvest Saint Laurent Myslf EDP 100ml Hombre', '<p><strong>Salida / Cabeza </strong>Bergamota de Calabria, bergamota verde — aportan frescura cítrica vibrante.</p><p><strong>Corazón / Medio </strong>Azahar de Túnez (“Tunisian orange blossom”) — una floral blanca jugosa, elegante, que suaviza las cítricas.</p><p><strong>Fondo / Base </strong>Pachulí de Indonesia, Ambrofix™ — proporcionan madurez, calidez amaderada suave, algo sensual, realzado por la duración del Ambrofix.</p>', 78000, 2, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d11a-c99e-73aa-b5e9-bdbbdfc99a43.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d11a-ca18-732b-80c9-a1e8f0571b0a.png?storeId=1681', 'Hombre', 1, 0, '<p><em>MYSLF</em>  es una fragancia lanzada en <strong>2023</strong> por YSL. Se presenta como una celebración de la masculinidad moderna: busca expresar contrastes, autenticidad, y dejar atrás estereotipos tradicionales. Aromáticamente es una fragancia <strong>woody‑floral aromática</strong>, que mezcla la frescura cítrica con flores blancas y maderas sensuales. Un aroma bastante versátil.</p>', NULL),
(12272, 'Pino Silvestre Clásica 125ml EDT Hombre', '<p><strong>Salida / Cabeza</strong>Bergamota, Limón, Lavanda, Albahaca, Bayas de Enebro (Juniper Berries)</p><p><strong>Corazón / Medio</strong>Pino (agujas de pino), Salvia (Clary Sage), Tomillo, Geranio, Clavo, Nuez moscada</p><p><strong>Fondo / Base</strong>Cedro, Musgo de roble, Almizcle, Ámbar, Haba Tonka</p>', 18000, 1, 'Pino Silvestre', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d114-334b-77ca-bbd2-b6ac594237c7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d114-38f8-703b-a8a1-b167a0828a9d.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Pino Silvestre</em> es un clásico aromático‑fougère lanzado originalmente en <strong>1955</strong> por la casa Pino Silvestre, diseñado por Lino Vida. Es una fragancia de estilo “vieja escuela”, muy reconocible, evocando bosques, naturaleza, pino, notas herbales, amaderadas y un toque limpio/masculino. </p>', NULL),
(12273, 'Givenchy Gentleman EDP 100ml Hombre', '<p><strong>Salida / Cabeza</strong>Pimienta negra, lavanda, bergamota</p><p><strong>Corazón / Medio</strong>Orris (raíz de lirio), clavos de olor, canela</p><p><strong>Fondo / Base</strong>Vainilla negra (“black vanilla husk”), bálsamo de Tolú, haba tonka, benjuí, pachulí</p>', 55000, 1, 'Givenchy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d10e-428b-7238-8cbb-effdd7a1c5ec.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d10e-4366-71fe-869e-0bfca1f1c087.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Perfume diseñado para equilibrar elegancia clásica con matices modernos, más cálido y dulce que la versión Gentleman EDT. Destaca por su carácter refinado, sofisticado y algo gourmand. Ideal para usar en noches, clima templado a frío, o en situaciones donde buscas impresionar con un perfume elegante pero con buena presencia.</p>', NULL),
(12274, 'Dolce & Gabbana The One EDP 75ml Mujer', '<p><strong>Salida / Cabeza</strong>Durazno (peach), lichi, mandarina, bergamota</p><p><strong>Corazón / Medio</strong>Jazmín, lirio de los valles (lily of the valley), azucena (“Madonna Lily”), ciruela (plum)</p><p><strong>Fondo / Base</strong>Vainilla, ámbar, almizcle, vetiver</p>', 47000, 1, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d108-a586-7638-b987-5f104e690fa5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d108-a5fb-7719-9cf5-2c405181d78f.png?storeId=1681', 'Mujer', 1, 0, '<p><em>The One</em> de Dolce &amp; Gabbana es una fragancia femenina elegante, sensual y con un carácter cálido. Fue lanzada en 2006. Pertenece a la familia <strong>Ámbar Floral / Oriental Floral</strong>; combina frutas jugosas, flores blancas opulentas y una base dulce y envolvente que aporta glamour y presencia. Suele funcionar muy bien para la noche, eventos especiales, o cuando quieres algo con presencia — no es una fragancia “liviana” ni discreta, tiende a proyectarse bastante y durar bastante tiempo.</p>', NULL),
(12275, 'Paco Rabanne Pour Homme EDT 100ml', '<p><strong>Salida / Cabeza</strong>Lavanda, tomillo, palo de rosa brasileño</p><p><strong>Corazón / Medio</strong>Clavo (clove), geranio, haba tonka </p><p><strong>Fondo / Base</strong>Musgo de roble (oakmoss), tabaco, almizcle, ámbar</p>', 32000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d101-fc75-754e-8e0f-3a0815a574ed.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d101-fef0-7539-b321-3abc108e8722.png?storeId=1681', 'Hombre', 1, 0, '<p>Fue lanzada en <strong>1973</strong> por Paco Rabanne, y es uno de los clásicos de la perfumería masculina. Pertenece a la familia olfativa <strong>Aromática Fougere</strong>: combina frescura herbal, masculinidad clásica, notas amaderadas y un fondo terroso / ambarado. Es ideal para quien le gusta un aroma elegante, veterano, con vibra un poco retro/barbería, que proyecte limpieza (como “piel recién afeitada”) y un toque de distinción.</p>', NULL),
(12276, 'Issey Miyake Pour Homme Intense 125ml EDT Hombre', '<p><strong>Salida / Cabeza</strong>Yuzu, bergamota, mandarina, naranja dulce (“sweet orange”)</p><p><strong>Corazón / Medio</strong>Nuez moscada, cardamomo, canela, loto azul, azafrán</p><p><strong>Base / Fondo</strong>Incienso (frankincense), benjuí, papiro, ámbar gris, ámbar </p>', 28000, 1, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0fc-e5d5-753e-9393-5ce2fc0fc94e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0fc-e777-730e-8b7b-3bb62088795f.png?storeId=1681', 'Hombre', 1, 0, '<p><em>L’Eau d’Issey Pour Homme Intense</em> es una versión más profunda, especiada y oscura que el original L’Eau d’Issey Pour Homme. Fue lanzada en 2007, diseñada por el perfumista Jacques Cavallier. Mantiene parte del ADN acuático / cítrico del original, pero incorpora notas cálidas, ambarinas y resinosas que le dan más carácter, presencia y sensualidad.</p><p>Es ideal para uso nocturno o en climas templados a fríos, o cuando buscas algo con más profundidad y barrera para destacar más que una fragancia puramente fresca.</p>', NULL),
(12277, 'Marc Jacobs Perfect Elixir 100ml  EDP Mujer', '<p><strong>Salida / Cabeza</strong>Purple rhubarb (acorde de ruibarbo morado), ciruela (“plum”), néctar de miel (“honey”)</p><p><strong>Corazón / Medio</strong>Ámbar dorado (golden amber woods accord), flor de azahar o “orange blossom absolute”</p><p><strong>Fondo / Base</strong>Vainilla de habas (vanilla bean extract), resinas (resin, myrrh), patchouli (“parchouli”)</p>', 66000, 1, 'Marc Jacobs', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0d8-3c87-7538-b59e-7293680c26f0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0d8-3e61-766d-8e29-6396ea82a9e9.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Perfect Elixir</em> fue lanzado en 2024 como parte de la línea <em>Perfect</em> de Marc Jacobs, pero apunta a una variante más cálida, rica y opulenta.</p><p>La fragancia está pensada para expresar auto‑aceptación y confianza: se describe como parte del viaje de “self‑love, self‑visualization” de la colección Perfect. Se mueve en la familia <strong>oriental vainilla / ámbar (amber gourmand)</strong>, mucho más dulce y profunda que versiones más ligeras de la línea Perfect.</p>', NULL),
(12278, 'Set Abercrombie Fierce Cologne 2pzas', '<h3>Clasificación olfativa:</h3><p>Familia: Aromática Amaderada</p><p>Estilo: Masculino, fresco y juvenil</p><h3><br></h3><h3>Notas olfativas:</h3><p><strong>Notas de salida: </strong>Petit grain, cardamomo, limón, naranja y abeto</p><p><strong>Notas de corazón</strong>: Jazmín, romero, rosa y lirio de los valles</p><p><strong>Notas de fondo:</strong> Almizcle, vetiver, roble, sándalo y musgo</p>', 48500, 1, 'Abercrombie', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0b1-6624-7012-9343-bf69b011b096.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Abercrombie Fierce Cologne para hombre es una fragancia icónica que combina masculinidad, energía y sofisticación. Con notas de almizcle, madera de sándalo, petit grain y cítricos frescos, este perfume destaca por su aroma envolvente y duradero, ideal para hombres seguros de sí mismos. Perfecto para el día o la noche, Fierce se ha convertido en un símbolo de estilo y personalidad. Si buscas un perfume masculino que deje huella, Abercrombie Fierce es tu mejor elección.</p>', NULL),
(12279, 'Set Perry Ellis 360 Red EDP 4pzas Mujer', '<p><strong>Salida / Cabeza </strong>Ciclamen (violeta persa), hojas de naranja, ciruela</p><p><strong>Corazón / Medio </strong>Flor de azahar del naranjo, orquídea, mimosa, jazmín </p><p><strong>Fondo / Base </strong>Ámbar, almizcle</p>', 32500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0aa-33ac-75fd-ad0c-2d84444fd84e.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p><em>360° Red</em> es una fragancia floral dulce, lanzada en 2003 por Perry Ellis.</p><p>Está pensada para uso diario, pero con presencia suficiente para ocasiones especiales si no se aplica en exceso. Se caracteriza por un perfil bastante femenino, con flores prominentes, mix de frutas dulces al inicio y una base cálida con almizcle y ámbar.</p>', NULL),
(12280, 'Giorgio Armani Stronger With You Absolutely 100ml EDP Hombre', '<p><strong>Salida / Cabeza</strong>Rum (acorde de ron), Elemi, Bergamota</p><p><strong>Corazón / Medio</strong>Lavanda (de cultivo sostenible en Francia), Davana (nota frutada/floral) </p><p><strong>Fondo / Base</strong>Castaña (chestnut), Vainilla de Madagascar, Cedro ahumado, Pachul</p>', 64000, 1, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d091-625e-759f-a620-5301475c5df9.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d091-5fb3-77d7-ae96-8412d5895882.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><em>Stronger With You Absolutely</em> es una versión más rica, cálida y sofisticada dentro de la línea <em>Stronger With You</em>. Fue lanzada en 2021 como un Eau de Parfum (EDP) / algunas versiones se la presentan como <em>parfum</em> u <em>absolutamente refinada</em>. Se inspira en el poder absoluto del amor, usando acordes evocadores como ron, vainilla, madera ahumada, y notas amables como la castaña o “chestnut”. Pretende ser más madura que las otras versiones, ideal para noches, climas fríos, momentos íntimos o especiales.</p>', NULL),
(12281, 'Versace Eros Parfum 100ml Hombre', '<p><strong>Salida (notas de cabeza):</strong></p><ul><li>Menta </li><li>Limón</li><li>Pimienta negra</li><li>Elemi </li><li>Litsea cubeba </li></ul><p><strong>Corazón (notas medias):</strong></p><ul><li>Manzana verde </li><li>Geranio</li><li>Lavanda</li><li>Salvia (salvia sclarea)</li><li>Pomarosa </li></ul><p><strong>Fondo (notas de base):</strong></p><ul><li>Haba tonka </li><li>Ámbar </li><li>Vainilla</li><li>Pachulí </li><li>Benjuí (Benzoin)</li></ul>', 53000, 2, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccef-43f4-769b-abb5-6e83746805d5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccef-3e25-74df-ac58-502c5217ef1b.png?storeId=1681', 'Hombre', 1, 0, '<p>Versace Eros Parfum (lanzado en 2021) es una variante más concentrada dentro de la línea Eros de Versace. Busca ofrecer una interpretación más profunda, elegante y refinada del concepto original, con mayor presencia de notas cálidas, ambarinas y orientales, pero sin perder su frescura inicial.</p><p>Se caracteriza por combinar elementos energizantes (cítricos, menta) con acordes herbales y especiados, antes de evolucionar hacia una base dulce, suave, amaderada y sensual. Es adecuado para quienes buscan algo distintivo, con buena duración, que se sienta masculino, poderoso pero también versátil, ideal para salidas por la noche, clima fresco, etc.</p>', NULL),
(12282, 'Carolina Herrera 212 NYC 100ml EDT Mujer', '<h3>Notas de salida / cabeza</h3><ul><li>Flor de azahar del naranjo</li><li>Mandarina </li><li>Bergamota</li><li>Flor de cactus</li></ul><h3>Notas de corazón / intermedias</h3><ul><li>Azucena</li><li>Gardenia</li><li>Camelia blanca </li><li>Fresia </li><li>Jazmín </li><li>Rosa y peonía</li><li>Lirio del valle (muguete) </li></ul><h3>Notas de fondo / salida prolongada</h3><ul><li>Almizcle blanco </li><li>Sándalo</li></ul>', 56000, 2, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccbc-8ccd-77ae-89f0-52087e7d7dc5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccbc-8daf-71bf-b9c2-bb0aa9014334.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia femenina de carácter limpio, elegante y fresco, ideal para uso diario. En su evolución combina la frescura cítrica inicial con un corazón floral y un fondo cálido sin ser demasiado pesada. </p>', NULL),
(12283, 'Lacoste L12.12 Rose Eau Fraiche EDT 100ml Mujer', '<p><strong>Notas de salida</strong></p><ul><li>Toronja (pomelo) </li><li>Naranja sanguina</li></ul><p><strong>Notas de corazón / intermedias</strong></p><ul><li>Notas ozónicas (aire, frescura) </li><li>Grosellas negras</li><li>Pimienta rosa </li></ul><p><strong>Notas de fondo</strong></p><ul><li>Cedro </li><li>Canela</li></ul>', 34500, 0, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc95-856a-736d-9b25-75dcd26a9138.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc95-84c0-763d-a213-644d5fa77fa6.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Lacoste L.12.12 Rose Eau Fraîche EDT </strong>un perfume luminoso y fresco con carácter floral y cítrico. Sus notas principales incluyen toronja y naranja sanguina al inicio, seguida de grosellas negras y pimienta rosa, y un fondo suave de cedro y canela. Es ideal para uso diurno, especialmente en climas cálidos, y su versión “Eau Fraîche” lo hace ligero y revitalizante.</p>', NULL),
(12284, 'Antonio Banderas Power of Seduction 200ml EDT Hombre', '<p>Familia: Aromático verde – fresco, herbal, ligeramente especiado y amaderado</p><p>Salida: bergamota cítrica y manzana crujiente.</p><p>Corazón: lavanda, abrótano (artemisia) y esclarea, aportando un toque aromático-herbal sofisticado</p><p>Fondo: ámbar cálido, musgo, pachulí, haba tonka y vetas amaderadas — dan profundidad y</p>', 21500, 2, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199b621-5dc7-70fd-8d09-1a03d884bea0.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199b621-5dd8-72cc-923e-e580c79a4e62.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Antonio Banderas Power of Seduction EDT (2018) es una fragancia verde-aromática con frescura citríca y apple, un corazón herbal floral y una base cálida y masculina. Ideal para uso diario o informal, ofrece una excelente relación calidad-precio y es especialmente atractiva para quienes quieren algo elegante y sin complicaciones. Aunque no es un monstruo en longevidad, su rendimiento es sólido para su precio, y su aroma ha sido comparado favorablemente con fragancias más costosas.</p>', NULL),
(12285, 'Carolina Herrera La Bomba EDP 80ml Mujer', '<p><strong>Salida (cabeza):</strong> Pitaya (fruta del dragón) exótica y vibrante. </p><p><strong>Corazón (medio):</strong> Peonía roja (o peonía cereza) y frangipani (una flor tropical), aportando un carácter cálido y floral tropical. </p><p><strong>Fondo (base):</strong> Vainilla “solar” cremosa, con un toque de pachulí para darle profundidad y carácter.</p>', 84000, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199b045-0dd5-74ed-8f4c-1b778c80d92c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199b045-0f04-72f8-9884-cd8927139024.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>La Bomba</strong> es una fragancia joven, fresca, dulce y expresiva que mezcla frutas tropicales con flores cálidas, ideal si buscas algo audaz, alegre y distinto, aunque puede no satisfacer a quienes buscan aromas más sobrios o sofisticados.</p>', NULL),
(12286, 'Xerjoff Erba Pura EDP 100ml Unisex', '<p><strong>Salida (lo primero que se huele):</strong></p><p><br></p><ul><li>Frutas cítricas (naranja de Sicilia, bergamota de Calabria, limón)</li><li>Frutas exóticas (mezcla frutal no específica, muy jugosa)</li></ul><p><br></p><p><strong>Corazón (nota intermedia):</strong></p><p><br></p><ul><li>No hay corazón floral típico — el corazón es más bien un puente entre la fruta y el fondo.</li></ul><p><br></p><p><strong>Fondo (lo que queda en la piel):</strong></p><p><br></p><ul><li>Almizcle blanco</li><li>Ámbar</li><li>Vainilla de Madagascar</li></ul>', 168000, 0, 'Xerjoff', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01999775-7341-7174-a9d7-7ae71dcd28f4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01999775-7794-724d-b7c0-b72be8e24315.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a7bfe-96db-7459-af0e-d29cf939a6ed.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><em>Erba Pura</em> es una fragancia unisex lanzada en 2013, conocida por su carácter <strong>fresco, frutal y ligeramente dulce</strong>. Tiene un aire <strong>luminoso, moderno y elegante</strong>, con un fondo suave y almizclado que le da persistencia.</p>', NULL),
(12287, 'Le Falcone Muharib Alpha Extrait De Parfum 85ml Hombre', '<p><strong>Salida / Notas de cabeza </strong>Lavanda, Menta, Canela </p><p><strong>Corazón / Notas medias </strong>Vainilla, Benjuí, Cardamomo, Nuez Moscada </p><p><strong>Fondo / Notas base </strong>Miel, Haba tonka, Tabaco</p>', 28000, 0, 'Le Falcone', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998366-f0cd-758b-8581-71c4398341f6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998366-f188-763d-b653-1b9503d2bc8a.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Su carácter olfativo mezcla elementos frescos, especiados y cálidos: arranca con notas aromáticas y especiadas, evoluciona hacia un corazón más dulce y envolvente, y culmina con una base cálida, masculina y profunda. Se sugiere ideal para noches o climas frescos, ocasiones especiales, cuando se desea dejar una impresión marcada.</p>', NULL),
(12288, 'Versace Bright Crystal 200ml EDT Mujer', '<p><strong>Notas de salida</strong>: yuzu (cítrico japonés), granada, acorde acuático / efecto hielo.</p><p><strong>Notas de corazón</strong>: peonía, magnolia, flor de loto.</p><p><strong>Notas de fondo</strong>: almizcle, caoba y ámbar vegetal.</p>', 55000, 2, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01995faa-9480-70c8-b506-2ce871d0b716.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01995faa-9403-7417-954d-bd97df58538b.png?storeId=1681', 'Mujer', 1, 0, '<p>Bright Crystal de Versace es una fragancia femenina que destaca por ser fresca, luminosa, delicada y muy floral, una combinación equilibrada de lo dulce, lo fresco y lo suavemente sensual.</p>', NULL),
(12289, 'Emper Ocean Breeze EDP 100ml Hombre', '<p><strong>Notas de salida</strong></p><ul><li>Cidra</li><li>Naranja</li><li>Menta</li><li>Limón</li><li>Grosella negra</li><li>Cilantro </li></ul><p><strong>Notas de corazón</strong></p><ul><li>Albaricoque</li><li>Albahaca</li><li>Semillas de zanahoria</li><li>Rosa de mayo</li></ul><p><strong>Notas de fondo</strong></p><ul><li>Higo</li><li>Dátiles</li><li>Ambreta (mosqueta)</li></ul><p><br></p>', 22500, 0, 'Emper', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199411a-98b5-77e8-a22a-60348b40a886.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Trae la brisa marina mezclada con un jardín costero; es como estar al borde del mar, con aire fresco, vegetación suave, y ese fondo cálido que recuerda madera al sol. No es un perfume muy pesado, sino luminoso, limpio y bastante versátil.</p>', NULL),
(12290, 'French Avenue Liquid Brun EDP 100ml Hombre', '<p><strong>Notas de salida:</strong> canela, bergamota, cardamomo, flor de azahar del naranjo. </p><p><strong>Notas de corazón:</strong> vainilla Bourbon, elemí. </p><p><strong>Notas de fondo:</strong> praliné, ambroxan, madera de gaiác, almizcle.</p>', 29500, 2, 'French Avenue', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993aee-c6d1-7069-8fd0-be7801403cd2.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993aee-c37c-7289-b5a1-7b0cacf8aa93.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Sensación general:</strong> es cálida, especiada y dulce, con una apertura vibrante gracias a los cítricos y especias, seguida por un corazón cremoso gracias a la vainilla, y un fondo profundo y envolvente con notas gourmand (praliné) y ambaradas/maderas. Ideal para noches o temporadas donde se busca destacar con elegancia.</p>', NULL),
(12291, 'Al Haramain Gold Edition 200ml EDP Unisex', '<p><strong>Salida (notas altas):</strong></p><ul><li>Bergamota y notas verdes brillantes y frescas, aportando energía y ligereza al inicio.</li></ul><p><strong>Corazón (notas medias):</strong></p><ul><li>Melón jugoso, piña dulce y un acorde gourmand junto con ámbar envolvente, que crean un perfil afrutado y sofisticado.</li></ul><p><strong>Fondo (notas base):</strong></p><ul><li>Acordes amaderados suaves, vainilla cremosa y almizcle sensual, que brindan una estela duradera, cálida y seductora. </li></ul>', 49500, 1, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993569-f6a4-73fc-b551-741b54faa732.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8a77-8adf-7654-ab04-40ac49cd0006.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><strong>Amber Oud Gold Edition</strong> es una fragancia gourmet, con frutas jugosas y dulces que evolucionan hacia una base cálida y seductora. Es muy duradera y deja huella, especialmente popular entre quienes disfrutan las fragancias intensas y dulces. Si te gustan los aromas como <em>Erba Pura</em>, ésta podría ser una excelente alternativa con ese aire dorado y moderno</p>', NULL),
(12292, 'Carolina Herrera Good Girl Very Glam 80ml Mujer', '<h3><strong>Notas de salida</strong> (las primeras que se perciben):</h3><ul><li>Cereza ácida</li><li>Almendra amarga</li></ul><h3>? <strong>Notas de corazón</strong> (el alma del perfume):</h3><ul><li>Rosa</li><li>Lirio</li></ul><h3>? <strong>Notas de fondo</strong> (las que duran más tiempo):</h3><ul><li>Vainilla bourbon</li><li>Haba tonka</li></ul><p>Es una fragancia <strong>floral frutal gourmand</strong>, intensa, femenina y con un toque chispeante gracias a la cereza, perfecta para quienes buscan dejar una impresión sofisticada y atrevida.</p>', 66500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01990622-9edd-732b-850c-c425f006f696.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01990622-a10a-74e8-862c-1ac76d88df60.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Good Girl Very Glam</strong> es una edición especial y lujosa del icónico perfume <em>Good Girl</em> de Carolina Herrera. Esta versión mantiene la dualidad audaz y sofisticada del original, pero se presenta en un frasco aún más brillante, decorado con glitter dorado que resalta su espíritu glamuroso. La fragancia combina notas dulces de jazmín y tonka con un fondo cálido y seductor, ideal para noches especiales y mujeres seguras de sí mismas.</p>', NULL),
(12293, 'Parfums De Marly Layton 125ml EDP Hombre', '<p><strong>Notas de salida (Top):</strong> manzana, bergamota, lavanda</p><p><strong>Notas de corazón (Heart):</strong> jazmín, violeta, geranio </p><p><strong>Notas de fondo (Base):</strong> vainilla, pimienta, madera de guayaco, pachulí</p>', 174000, 0, 'Parfums De Marly', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198f722-f3e5-73ca-95ad-12448d815d65.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198f722-f418-74be-ae9a-a3d7bd009b95.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Parfums de Marly Layton</strong> es una fragancia elegante, versátil y envolvente, ideal para situaciones en las que se busca dejar una impresión sofisticada y duradera. Evoca elegancia y refinamiento, capturando el <em>espíritu del galán</em> con un carácter ambarado-floral e intensidad envolvente. Abre con una chispeante y apasionada bergamota, acompañada de una frescura chic aportada por lavanda y geranio, gradualmente, se intensifica con ámbar y la sofisticación del rosa picante, mientras que su base despliega una combinación adictiva de vainilla, maderas preciosas y un intrigante toque de café caramelizado. </p>', NULL),
(12294, 'Elsatys Gentle 178ml EDP Hombre', '<p>Notas de salida: Bergamota, pimienta.</p><p>Notas de corazón: Lavanda, tintura de tierra, notas acuosas, notas metálicas, carbón vegetal.</p><p>Notas de fondo: Pachulí, Ambroxan</p>', 28800, 0, 'Reyane Tradition', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198f188-3cf6-77db-8dc7-020c39cba22c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198f188-3c7a-758c-95dc-0defc6eb7d9e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Gentle Elsatys es una fragancia masculina de la familia olfativa amaderada aromática, inspirada en el icónico Dior Sauvage. Esta fragancia destaca por su frescura cítrica y su base amaderada, ofreciendo una opción de alta calidad a un precio accesible. Es ideal para el uso diario, especialmente en climas cálidos y durante las estaciones de primavera y verano.</p>', NULL),
(12295, 'Hugo Boss Bottled Unlimited 100ml EDT Hombre', '<p><strong>Notas principales:</strong></p><p><br></p><ul><li><strong>Salida:</strong> menta, hojas de violeta</li><li><strong>Corazón:</strong> piña, canela</li><li><strong>Fondo:</strong> madera de sándalo, almizcle</li></ul><p><br></p><p>Es un perfume que transmite confianza, dinamismo y una actitud positiva. Su estela es moderada y su duración, buena para un eau de toilette fresco.</p>', 41500, 0, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198e798-a436-77c7-8102-97c1ecfa90bc.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198e798-a48c-776b-8193-e58c6cc72d35.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Hugo Boss Bottled Unlimited</strong> es una fragancia masculina fresca y energizante, lanzada por Hugo Boss como una edición moderna dentro de la línea <em>Boss Bottled</em>. Su perfil aromático combina notas de menta, piña y madera, lo que le da un carácter vigorizante y juvenil, ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12296, 'Adidas Team Force 100ml EDT Hombre', '<p><strong>Estilo del aroma:</strong> Aromático-frutal con fondo amaderado</p><p><br></p><p><strong>Notas principales:</strong></p><ul><li><strong>Salida:</strong> toronja (pomelo), mandarina, piña, aldehídos</li><li><strong>Corazón:</strong> enebro, jazmín</li><li><strong>Fondo:</strong> madera de cedro, ámbar, tabaco, almizcle</li></ul><p><br></p><p><strong>Sensaciones que transmite:</strong> Fuerza, entusiasmo, masculinidad juvenil</p><p><br></p><p><strong>Proyección y duración:</strong></p><ul><li><strong>Proyección:</strong> moderada durante la primera hora</li><li><strong>Duración:</strong> entre <strong>4 y 6 horas</strong> en piel, más en ropa</li></ul><p><br></p><p><strong>Clima y ocasión ideal:</strong></p><ul><li>Ideal para climas <strong>templados o fríos</strong></li><li>Uso <strong>diario</strong>, especialmente en contextos casuales, gimnasio o después de la ducha</li></ul>', 8500, 2, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af6b-a7ea-704f-b4c7-ddb3e17a0fcd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af6b-a9db-7548-af39-9435ab7d8b6d.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Team Force</strong> es una fragancia energizante con una apertura frutal chispeante y un fondo cálido que recuerda a colonias clásicas con un toque moderno. Perfecta para quienes buscan un perfume económico, masculino y fácil de llevar.</p>', NULL),
(12297, 'Adidas Goal 100ml EDT Hombre', '<h3><strong>Estilo del aroma:</strong> Aromático-fresco con matices cítricos y especiados.</h3><p><br></p><p><strong>Notas principales:</strong></p><ul><li><strong>Salida:</strong> limón, bergamota, menta</li><li><strong>Corazon:</strong> lavanda, geranio, especias suaves</li><li><strong>Fondo:</strong> madera de cedro, almizcle, ámbar</li></ul>', 8500, 0, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af67-b6c7-733c-843b-daa4fd437b2e.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af67-b955-75b1-8b1f-92bddb7a3812.png?storeId=1681', 'Hombre', 1, 0, '<ul><li>Una fragancia <strong>fresca, deportiva y energética</strong>, diseñada para hombres activos que buscan un aroma accesible, limpio y duradero para el día a día. Recomendada para uso diario, oficina, gimnasio o actividades al aire libre. </li></ul>', NULL),
(12298, 'Set Armaf Odyssey Mandarín Sky 100ml EDP Hombre', '<p><strong>Salida (Top):</strong> mandarina, naranja, azafrán y salvia — una apertura cítrica brillante con matices especiados y herbales </p><p><strong>Corazón (Middle):</strong> caramelo, haba tonka y cempasúchil (tagete) — aporta una dulzura gourmand delicada y floral</p><p><strong>Fondo (Base):</strong> ambroxan, cedro y vetiver — una base cálida, amaderada y ligeramente almizclada para cerrar con elegancia</p>', 38500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af11-bf30-772a-8fe6-70bcc3bc2b77.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af11-c071-703b-8525-ec245db27644.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Una fragancia vibrante y juvenil con una salida chispeante de mandarina y naranja que se mezcla con un corazón dulce de caramelo y tonka, evocando un ambiente cálido, moderno y adictivo. Ideal para climas templados y salidas casuales, con una estela moderada y una duración de 6 a 8 horas. Inspirada en <em>Scandal Pour Homme.</em></p>', NULL),
(12299, 'Armaf Odyssey Mandarín Sky 200ml EDP Hombre', '<p><strong>Salida (Top):</strong> mandarina, naranja, azafrán y salvia — una apertura cítrica brillante con matices especiados y herbales </p><p><strong>Corazón (Middle):</strong> caramelo, haba tonka y cempasúchil (tagete) — aporta una dulzura gourmand delicada y floral </p><p><strong>Fondo (Base):</strong> ambroxan, cedro y vetiver — una base cálida, amaderada y ligeramente almizclada para cerrar con elegancia</p>', 38500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af0b-75a3-75f5-bad3-7d64c5ce2a22.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af0b-79e7-77c0-a4a2-342543f88bfe.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia vibrante y juvenil con una salida chispeante de mandarina y naranja que se mezcla con un corazón dulce de caramelo y tonka, evocando un ambiente cálido, moderno y adictivo. Ideal para climas templados y salidas casuales, con una estela moderada y una duración de 6 a 8 horas. Inspirada en <em>Scandal Pour Homme. </em></p>', NULL),
(12300, 'Body Mist Ariana Grande Mood Vanilla 200ml', '<p><strong>Notas de salida (top):</strong> fresia rosa, ciruela jugosa y almizcles cremosos — una apertura dulce, frutal y ligeramente empolvada</p><p><strong>Notas de corazón (medio):</strong> manteca de raíz de iris (orris butter), praliné blanco y pétalos de jazmín — el corazón aporta una textura rica, gourmand y floral </p><p><strong>Notas de fondo (base):</strong> vainilla absoluta y manteca de cacao — una base cálida, gourmand y reconfortante que deja una estela dulce y cremosa</p>', 9000, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198aeff-7425-7107-94df-e53c32443547.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Esta línea celebra la dualidad y la libertad de expresión, buscando una elegancia moderna, sensual y distintiva. Sensación Dulce, cremosa, polvorosa, acogedora, como una vainilla moderna y elegante.</p>', NULL),
(12301, 'Body Mist Ariana Grande Mood Blush 200ml', '<p><strong>Notas de salida (top):</strong> maracuyá (fruta de la pasión), frambuesa, bergamota italiana, y pimienta rosa — una apertura vibrante y chispeante que despierta los sentidos </p><p><strong>Notas de corazón (middle):</strong> rosa (pétalos de rosa), magnolia y pera jugosa — un centro floral elegante con dulzor jugoso </p><p><strong>Notas de fondo (base):</strong> ambroxan, “Dreamwood” (una madera onírica), musks radiantes y un toque de sándalo — un secado cálido, sensual, y acogedor</p>', 9000, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198aef1-a7dc-71bf-90b8-4f9f953fd084.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Mood Blush ofrece una experiencia aromática <strong>frutal</strong> y <strong>floral</strong>, con un toque picante al inicio, que evoluciona hacia un corazón suave y termina con una base ámbar-maderosa y almizclada. Se percibe como <strong>femenino, moderno, limpio y acogedor</strong> — ideal para días frescos o para quienes buscan una fragancia ligera pero memorable.</p>', NULL),
(12302, 'Set Paris Hiiltonm Rosé Rush 4pzas', '<p><strong>Notas de salida (top):</strong> pétalos de rosa, neroli y lichi (lychee)</p><p><strong>Notas de corazón (medio):</strong> rosa de mayo, peonía y papaya jugosa</p><p><strong>Notas de fondo (base):</strong> ámbar, cedro y almizcle blanco (white musk)</p>', 38500, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198aef9-1cdf-7036-94d7-344649474971.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>La propia Hilton la describe como evocadora de <strong>confianza, romance y feminidad sofisticada. </strong>Es descrita como una fragancia que combina un bouquet floral delicado con matices frutales y una base cálida, sensual y elegante. </p>', NULL),
(12303, 'Adidas Victory League 100ml EDT Hombre', '<p><strong>Notas de salida (top):</strong> bergamota, pera y albahaca </p><p><strong>Notas de corazón (corazón):</strong> vainilla, canela y lavanda</p><p><strong>Notas de fondo (base):</strong> almizcle y cedro</p>', 8500, 2, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01989173-4ee0-774e-8f58-502de15e2f7a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01989173-cfc2-732e-9abf-c796e4a85dc9.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Adidas Victory League es una <strong>fragancia oriental amaderada</strong> lanzada en 2006 para hombres, con una vibra deportiva y enérgica que evoca espíritu de competencia y victoria. En foros especializados, es común compararla con <strong>Hugo Boss Bottled</strong>, destacando similitudes en estructura olfativa, sobre todo por su calidez especiada. </p>', NULL),
(12304, 'Elizabeth Arden 5th Avenue 125ml EDP Mujer', '<p><strong>Notas de salida</strong>:</p><ul><li>Lila</li><li>Flor de tilo</li><li>Magnolia</li><li>Mandarina</li><li>Bergamota</li></ul><p><strong>Notas de corazón</strong>:</p><ul><li>Rosa de Bulgaria</li><li>Nuez moscada</li><li>Violeta</li><li>Ylang-ylang</li><li>Jazmín</li><li>Nardos</li><li>Melocotón</li><li>Clavel</li></ul><p><strong>Notas de fondo</strong>:</p><ul><li>Almizcle</li><li>Sándalo</li><li>Vainilla</li><li>Ámbar</li><li>Iris</li><li>Clavo de olor</li></ul>', 24000, 3, 'Elizabeth Arden', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a66-8302-72d3-9c1f-0c549fb61b56.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a66-8158-76da-b50e-52d6bc3f6be3.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia <strong>refinada y madura</strong>, perfecta para mujeres que buscan una firma olfativa profesional o elegante sin ser abrumadora. Muchos la consideran una opción perfecta para el día a día, con una apertura fresca y un corazón floral que se va tornando cálido y suave en el secado.</p>', NULL),
(12305, 'Liz Claiborne Curve Clásica 125ml EDT Hombre', '<p><strong>Notas de salida</strong>: piña, bayas de enebro, lavanda, neroli y limón (lima ácida)</p><p><strong>Notas de corazón</strong>: cilantro, jengibre, violeta, cactus, salvia, bergamota y cardamomo</p><p><strong>Notas de fondo</strong>: sándalo, ámbar, almizcle, vetiver, cedro, caoba y pimienta</p>', 22500, 7, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886e5-87a3-73cf-8bbd-4224f96b2bf4.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886e5-8418-74f5-9bf5-026c48d75113.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Liz Claiborne Curve</strong> es una fragancia aromática-verde que combina frescura cítrica, especias suaves y una base amaderada cálida. Ideal para quienes buscan una fragancia accesible, ligera y con esa chispa nostálgica de los 90. Es un clásico para uso diario, especialmente en climas templados, aunque alista retoques debido a su corta duración.</p>', NULL),
(12306, 'Liz Claiborne Curve Clásica 100ml EDT Mujer', '<p><strong>Notas de salida</strong>: kiwi, lavanda, mandarina, yuzu, menta, toronja, anís y bergamota</p><p><strong>Notas de corazón</strong>: sándalo, pachulí y geranio</p><p><strong>Notas de fondo</strong>: haba tonka, almizcle, vainilla, pimienta y ámbar gris</p>', 20500, 2, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886dc-b5ee-725c-bda3-dcc7c3cb7745.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886dc-b8fa-739a-b108-5e791ce59284.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Curve by Liz Claiborne</strong> (lanzada en 1996) es una fragancia femenina perteneciente a la familia olfativa <strong>floral-frutal</strong>. Se caracteriza por un equilibrio elegante entre notas cítricas, frutales, florales y amaderadas, ofreciendo una sensación fresca, dulce e incluso un ligero toque empolvado.</p>', NULL),
(12307, 'Billie Eillish Eillish N.2 EDP 100ml Mujer', '<p><strong>Salida (Top):</strong> bergamota italiana y flor de manzano — brumas frescas, cítricas y delicadamente florales </p><p><strong>Corazón (Middle):</strong> papiro, pimienta negra y flor de amapola salvaje — mezclando toques especiados, vegetales y florales con un aire húmedo y terroso</p><p><strong>Fondo (Base):</strong> palo santo, ébano y almizcle “piel” — brindan profundidad amaderada, humo suave y una estela envolvente</p>', 40500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886ae-9a3f-758a-bd23-12d9443b1377.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886ae-999d-76e1-84f1-c824cd172c82.png?storeId=1681', 'Mujer', 1, 0, '<p>Esta fragancia define un estilo <strong>amaderado especiado floral</strong> no es empalagosa, sino sofisticada y moderna. Se inspira en sensaciones de lluvia, oscuridad y misterio, aportando una frescura inicial que evoluciona hacia una calidez envolvente. Muchos la ven como una versión más madura, menos dulce y más oriental que la primera fragancia de Billie, con matices amaderados y especiados que generan profundidad y carácter.</p>', NULL),
(12308, 'Dolce & Gabbana Devotion EDP 100ml Hombre', '<p><strong>Salida (Top):</strong> Limón italiano — fresco, vibrante y energizante.</p><p><strong>Corazón (Middle):</strong> Acorde de café — aporta profundidad, calidez y carácter.</p><p><strong>Fondo (Base):</strong> Pachulí terroso y sensual, que ancla la composición con elegancia</p>', 58500, 1, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198867a-bba9-7199-9814-6ae3267201f8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198867a-c088-73a0-a385-28e4b01d8d27.png?storeId=1681', 'Hombre', 1, 0, '<p>Devotion Pour Homme se inscribe dentro de la familia <strong>amaderada especiada</strong>, diseñada para transmitir fuerza, sofisticación y energía mediterránea. El contraste entre notas frescas (limón, lavanda) y la calidez del café con fondo terroso resulta en una fragancia moderna, intensa y decidida.</p>', NULL),
(12309, 'Dolce & Gabbana Devotion EDP Intense 100ml Mujer', '<p><strong>Notas de salida:</strong></p><ul><li>Flor de azahar del naranjo</li><li>Cítricos luminoso</li></ul><p><strong>Notas de corazón:</strong></p><ul><li>Avellana caramelizada</li><li>Vainilla intensa</li></ul><p><strong>Notas de fondo:</strong></p><ul><li>Bálsamos cálidos</li><li>Maderas suaves</li><li>Almizcle</li></ul>', 58500, 1, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988675-6e96-75e7-a930-f6ebedb75248.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988675-6e9a-74a1-8a28-528cae8f443a.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Devotion EDP Intense</strong> potencia la sensualidad del original combinando la ternura del azahar y vainilla con una cremosidad gourmand —gracias a la avellana— y un rendimiento sólido. Es una opción excelente si buscas una fragancia dulce, envolvente, con carácter reconfortante, especialmente ideal para climas fríos o para dejar una impresión memorable.</p>', NULL),
(12310, 'Versace Yellow Diamond 90ml EDT Mujer', '<p><strong>Salida (Top)</strong>: citron (de Diamante), sorbete de pera, neroli y bergamota — un inicio fresco, cítrico y luminoso.</p><p><strong>Corazón (Middle)</strong>: azahar (flor de naranjo), fresia, mimosa y nenúfar — un bouquet floral blanco delicado y aireado.</p><p><strong>Fondo (Base)</strong>: ámbarwood (madera de ámbar), palo santo y almizcle — un secado sensual, suave y ligeramente amaderado.</p>', 44500, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988666-32cd-713d-9482-270d1f2fbf77.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988666-2fcb-714a-9bc0-6b9f32a694d5.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><strong>Versace Yellow Diamond EDT</strong> es una fragancia femenina luminosa y ligera, ideal para quienes buscan frescura y elegancia sin complicaciones. Su aroma se siente “como el sol embotellado”, con una estela femenina y fácil de llevar, perfecta para temporadas cálidas y momentos casuales. Tiene un encanto universal que la convierte en una elección segura y frecuentemente alabada.</p>', NULL),
(12311, 'Versace Eros Energy 100ml EDP Hombre', '<p><strong>Salida (Top)</strong>: Una explosión cítrica refrescante con bergamota italiana, naranja sanguina, lima peruana, limón, toronja, y mandarina verde (\"sun‑kissed Italian bergamot\" junto con un mix cítrico agresivo) </p><p><strong>Corazón (Middle)</strong>: Pimienta rosa vibrante, grosella negra y ámbar blanco (Ambrofix®), aportando sensualidad y sofisticación</p><p><strong>Fondo (Base)</strong>: Una base sólida y masculina de pachulí, almizcle y musgo de roble, que añade elegancia terrosa y una estela duradera</p>', 51500, 2, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988662-220f-70fe-bcaf-53d38536f887.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988662-2053-74ea-b93f-5087ad502aff.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Versace Eros Energy</em> es una fragancia femenina masculina radiante y llena de vida — perfecta para quienes buscan un aroma cítrico con carácter y fondo sofisticado. Ideal para verano o ambientes donde quieras irradiar frescura y confianza sin perder elegancia. Puede recordar al ADN Aventus, pero con una apertura única.</p>', NULL),
(12312, 'Hugo Boss Man (Orange) 100ml EDT Hombre', '<p><strong>Salida (top):</strong> manzana roja crujiente y cilantro (coriandro), con un toque de cardamomo según algunos registros.</p><p><strong>Corazón (middle):</strong> incienso (frankincense) y pimienta de Sichuan aportan profundidad especiada.</p><p><strong>Fondo (base):</strong> vainilla suave combinada con maderas (como bubinga, sándalo o notas amaderadas en general), añadiendo una sensación cálida y masculina.</p>', 27000, 1, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198865c-d483-766b-8406-bf076a160cf3.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198865c-d392-77fa-8fb5-5dc1d3655da1.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Hugo Boss Orange Man</strong> es una fragancia masculina animada, acogedora y versátil. Con su frescura frutal, fondo especiado-amaderado y cierre dulce, resulta perfecta para acompañar un estilo de vida dinámico y relajado. Un gran clásico fresco con personalidad.</p>', NULL),
(12313, 'Jean Paul Gaultier Divine 100ml EDP Mujer', '<p><strong>Salida (Top):</strong> bergamota fresca, bayas rojas brillantes y ozonicidad marina (calypsone) aportan frescura frutal con un toque marino náutico</p><p><strong>Corazón (Middle):</strong> lirio (azucena), ylang‑ylang y jazmín conforman un bouquet floral lujoso y limpio</p><p><strong>Fondo (Base):</strong> dulce merengue, almizcle suave y pachulí profundo ofrecen un secado cremoso, ligeramente gourmand y sofisticado</p>', 62500, 2, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988640-b9fd-7734-b4b8-f0f0677845cf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988640-b9cc-73ed-911c-f927e718c043.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><strong>Jean Paul Gaultier Divine EDP</strong> es una fragancia audaz que mezcla armoniosamente lo dulce, floral y marino. Su combinación de merengue y salinidad la hace distintiva y cautivadora. Ideal para mujeres que buscan una fragancia memorable y sofisticada.</p>', NULL),
(12314, 'Jean Paul Gaultier Classique 100ml EDT Mujer', '<p><strong>Salida (Top):</strong> flor de azahar del naranjo, mandarina, anís estrellado, pera, rosa y bergamota</p><p><strong>Corazón (Middle):</strong> ylang-ylang, jengibre, orquídea, nardos, iris y ciruela</p><p><strong>Fondo (Base):</strong> vainilla, ámbar, almizcle, canela y sándalo</p>', 59000, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198863c-e7ec-764a-b0dd-e585ec4727da.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198863c-e733-77e6-b177-00a68817bd15.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Jean Paul Gaultier Classique EDT</em> es una fragancia icónica que ofrece una mezcla envolvente de flores orientales y dulzura cálida. Su diseño emblemático en forma de torso con corsé refuerza su carácter seductor. Ideal si buscas una fragancia femenina con presencia y sofisticación.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12315, 'Rasasi Hawas Elixir EDP 100ml Hombre', '<p><strong>Notas de salida (top):</strong> artemisa (mugwort), bergamota y menta verde — refrescantes, verdes y vibrantes </p><p><strong>Notas de corazón (middle):</strong> chocolate oscuro, lavanda, benjuí — revelando una mezcla cremosa, aromática y ligeramente resinosa</p><p><strong>Notas de fondo (base):</strong> vainilla, haba tonka y almizcle blanco — proporcionando un cierre cálido, dulce y envolvente</p>', 32000, 1, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885cd-b92b-7778-9d0a-86107f9275e7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885cd-b79f-75f9-b560-b11bc5f34aa6.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Rasasi Hawas Elixir</strong> es una fragancia llamativa y bien elaborada que combina una apertura refrescante con un corazón gourmand y un fondo cálido y seductor. Su excelente rendimiento, junto con la reinterpretación más refinada del ADN de <em>Le Male Elixir</em>, la convierten en una opción destacada para quienes buscan una fragancia distintiva, moderna y convincente sin gastar mucho.</p>', NULL),
(12316, 'Lattafa Vintage Radio 100ml EDP Hombre', '<p><strong>Salida (Notas de apertura):</strong> lavanda, salvia y bergamota — una frescura aromática cremosa y cálida que recuerda a una brisa nostálgica.</p><p><strong>Corazón (Notas medias):</strong> ciruela, palo santo y pimienta negra — aporta dulzor afrutado, profundidad ahumada y un matiz especiado intrigante.</p><p><strong>Fondo (Notas base):</strong> sándalo y amberwood (madera ámbar) — ofrece un secado elegante, suave, cremoso y amaderado.</p>', 26500, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885c5-ff97-7523-b27b-55b45f747369.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885c5-fe75-757b-bbb1-5e47d310cee1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Lattafa Vintage Radio</strong> es una fragancia única y refinada que combina frescura aromática con un corazón frutal ahumado y un secado cálido amaderado. Es ideal para quienes buscan algo nostálgico, elegante y longeva.</p>', NULL),
(12317, 'Lattafa Mayar Cherry Intense 100ml EDP Mujer', '<p><strong>Salida (Top):</strong> fresa, bergamota — aporta frescura jugosa y chispeante.</p><p><strong>Corazón (Middle):</strong> mermelada de cereza (cherry jam), cacao — ofrece un perfil gourmand intenso, achocolatado.</p><p><strong>Fondo (Base):</strong> vainilla cremosa, ámbar cálido y pachulí — crea un cierre envolvente con una profundidad terrosa.</p>', 28000, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885c1-98a6-72c9-8876-8e7a59655a23.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885c1-9e3f-729f-9f27-49a0fcdddef5.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Lattafa Mayar Cherry Intense</em> es una fragancia gourmand vibrante que destaca por su combinación de cereza y cacao, enmarcada por notas cálidas de vainilla, ámbar y pachulí. Ofrece una dulzura cautivadora con buena presencia inicial, perfecta para climas fríos o salidas nocturnas. Aunque puede polarizar por su intensidad y dulzor, resulta envolvente y seductora para quienes disfrutan del estilo gourmand moderno.</p>', NULL),
(12318, 'Lattafa Khamrah Dukhan 100ml EDP Unisex', '<p><strong>Notas de salida (Top):</strong> mandarina, pimiento (pimento) y especias ahumadas como medida para representar el ritual “dukhan” </p><p><strong>Notas de corazón (Middle):</strong> ládano (cistus), flor de azahar del naranjo, incienso y pachulí — creando una mezcla floral resinosa con profundidad.</p><p><strong>Notas de fondo (Base):</strong> tabaco, ámbar, praline, haba tonka y benjuí — una base cálida, dulce, cremosa y ligeramente balsámica.</p>', 29500, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885bc-f012-707d-a5b1-53faef01eb47.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885bc-f2b6-70ce-9249-aab51464a657.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><em>Lattafa Khamrah Dukhan</em> es una fragancia envolvente y atrevida que combina tradición árabe con modernidad gourmand. Si te atraen aromas especiados, ahumados y dulces, con larga duración y estela discernible, esta es una opción destacada, especialmente para ser notado en ambientes sofisticados y fríos.</p>', NULL),
(12319, 'Paco Rabanne Phantom 150ml EDT Hombre', '<p><strong>Salida (Top):</strong> lavanda fresca tipo lavandin, limón de Amalfi y cáscara cítrica vibrante</p><p><strong>Corazón (Middle):</strong> lavanda continua, manzana verde, humo seco, pachulí y notas terrosas</p><p><strong>Fondo (Base):</strong> vainilla cremosa, vetiver terroso y cedro sólido</p>', 62500, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988082-bb6d-7728-999a-f4a1dd61f431.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988082-bd24-7328-8b0f-8aaf3e67c447.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Phantom EDT</strong> es una apuesta decidida por una fragancia moderna que mezcla cítricos brillantes, lavanda adictiva y una base gourmand cálida y masculina. Ofrece un rendimiento sólido, estilo accesible y un perfil olfativo pensado para destacar sin complicaciones. Su ADN diabólico de lavanda-dulce la hace ideal para jóvenes que buscan una fragancia energética y complaciente.</p>', NULL),
(12320, 'Paco Rabanne Phantom Intense 150ml EDP Hombre', '<p><strong>Salida (Top):</strong> lavanda aromática, flor de azahar helada, limón y cardamomo — fresco y ligeramente cítrico con especias suaves.</p><p><strong>Corazón (Middle):</strong> lavanda continuada, salvia hirta (esclarea) y ron absoluto — añade una capa herbal y alcohólica cálida.</p><p><strong>Fondo (Base):</strong> vainilla cremosa, cedro seco y musgo moderno — final envolvente con profundidad especiada.</p>', 64500, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198807a-55b9-71a8-8725-266a176ff172.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198807a-543d-75df-b721-efa86ee429a7.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Paco Rabanne Phantom Intense</strong> es una fragancia masculina elegante e intensa, que combina frescura cítrica y lavanda con una base cálida de vainilla, cedro y musgo. Con excelente rendimiento y un perfil cautivador, es ideal para quienes buscan versatilidad en una fragancia moderna. Gran opción para regalar o para uso personal en ocasiones donde quieras dejar huella.</p>', NULL),
(12321, 'Paco Rabanne One Million Elixir 200ml Parfum Hombre', '<p><strong>Notas de salida:</strong> Aceite de manzana dulce, hojas de davana.</p><p><strong>Notas de corazón:</strong> Rosa de Damasco, osmanto, notas de cuero, albaricoque, haba tonka silvestre.</p><p><strong>Notas de fondo:</strong> Davana, regaliz, pachulí, aceite de madera de cedro, vainilla negra.</p>', 77000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198806f-b1fc-7569-abe0-0e0bb76b29a0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198806f-ad31-715a-b1b9-8ebda5b3192d.png?storeId=1681', 'Hombre', 1, 0, '<p>El <strong>Paco Rabanne 1 Million Elixir</strong> es una opción sofisticada para quienes buscan una fragancia intensa y duradera.Su diseño innovador y su aroma distintivo lo convierten en una elección destacada en el mundo de la perfumería masculina.</p>', NULL),
(12322, 'Paco Rabanne Fame Parfum 80ml Mujer', '<p>Esta composición combina notas frutales y especiadas con un corazón floral y un fondo amaderado y balsámico, creando una fragancia opulenta y moderna.</p><p><br></p><ul><li><strong>Salida (Top):</strong> Mango, Bergamota, Pimienta rosa</li><li><strong>Corazón (Middle):</strong> Jazmín, Incienso (Olibano), Pachulí</li><li><strong>Fondo (Base):</strong> Benjuí, Almizcle, Sándalo </li></ul>', 64000, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988069-9120-7464-93da-e8b665a71fcb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988069-9149-76a3-98b3-c015564083a8.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El <strong>Fame Parfum</strong> de Paco Rabanne es una opción sofisticada para quienes buscan una fragancia intensa y duradera. Su diseño innovador y su aroma distintivo lo convierten en una elección destacada en el mundo de la perfumería femenina.</p>', NULL),
(12323, 'Armaf Island Bliss 100ml EDP Mujer', '<p><strong>Salida (Top):</strong> bayas silvestres y notas verdes</p><p><strong>Corazón (Middle):</strong> coco lactónico, flor de azahar del naranjo y lirio de agua (nenúfar)</p><p><strong>Fondo (Base):</strong> vainilla, haba tonka y almizcle</p>', 34000, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198805d-18cf-75c0-9f78-b91c21153746.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198805d-1821-722c-ab16-b31a565334b7.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><em>Armaf Island Bliss</em> es una fragancia femenina que transporta a un ambiente tropical con su combinación de bayas, coco cremosa y secado cálido. Muy valorada por su relación calidad‑precio y diseño de botella elegante. Ideal si buscas algo agradable, dulce y evocador sin complicaciones. </p>', NULL),
(12324, 'Armaf Yum Yum 100ml EDP Mujer', '<p><strong>Notas de salida (Top):</strong> bergamota, naranja, cereza y bayas silvestres</p><p><strong>Corazón (Middle):</strong> vainilla, rosa y flores blancas</p><p><strong>Fondo (Base):</strong> ámbar, almizcle y notas polvorientas</p>', 34000, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988058-cb2e-71aa-85a4-d4d7924b50ea.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988058-cc70-735f-8896-2212d98f0151.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988058-cb52-70c1-96fc-e70472c8d003.png?storeId=1681', 'Mujer', 1, 0, '<p><em>Armaf Yum Yum</em> es una fragancia femenina dulce y juvenil que combina frutas rojas jugosas con vainilla y flores delicadas, finalizando en una base suave y empolvada. Funciona bien como opción atractiva y accesible para climas cálidos. Ideal si buscas un perfil gourmand no invasivo con un toque moderno.</p>', NULL),
(12325, 'Set Perry Ellis 360 EDT 2pzas Hombre', '<h3>Notas de salida (Top)</h3><ul><li>Bayas de enebro (juniper berries)</li><li>Bergamota</li><li>Limón</li><li>Hoja de tomate</li><li>Aquozone</li></ul><h3>Notas de corazón (Middle)</h3><ul><li>Lavanda</li><li>Salvia</li><li>Estragón</li><li>Freesia (flores suaves)</li><li>Cardamomo (en algunas fuentes)</li></ul><h3>Notas de fondo (Base)</h3><ul><li>Sándalo</li><li>Almizcle</li><li>Ámbar</li><li>Vetiver</li><li>Maderas suaves</li></ul>', 19800, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6bb0-67bf-744b-b6e2-9c4e3e375592.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p><em>Perry Ellis 360° Gray</em> es un aroma fresco, limpio y ligeramente especiado, con estructura aromática clásica. Funciona muy bien como fragancia accesible, fácil de llevar a diario, y sobre todo en climas cálidos. Tiene buena aceptación por su carácter agradable y precio accesible. <strong>Set incluye perfume 50ml y jabón corporal 200ml</strong></p>', NULL),
(12326, 'Antonio Banderas Blue Seduction 80ml EDT Mujer', '<h2>Notas de Salida (Top)</h2><ul><li>Melón</li><li>Bergamota</li><li>Pera</li><li>Hojas de violeta </li></ul><h2>Notas de Corazón (Middle)</h2><ul><li>Peonía</li><li>Gardenia</li><li>Jazmín</li><li>Lirio de los valles (muguete)</li><li>Rosa de Bulgaria (rosa Damascena) </li></ul><h2>Notas de Fondo (Base)</h2><ul><li>Frambuesa</li><li>Pachulí</li><li>Almizcle</li><li>Benjuí</li></ul>', 16800, 1, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988023-3e7c-75c9-af6b-2abe10d085a4.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988023-3e6b-730c-90e4-a1fd2bb5ebb5.png?storeId=1681', 'Mujer', 1, 0, '<p>Blue Seduction para Mujer de Antonio Banderas es una fragancia floral‑acuática con apertura frutal fresca y dulce, un corazón floral suave y un fondo cálido y ligeramente gourmand. Es una opción económica, ligera y agradable para el día a día en climas cálidos.</p>', NULL),
(12327, 'Armaf Odyssey Limoni 100ml EDP Hombre', '<h3>Notas olfativas</h3><ul><li><strong>Salida (Top Notes):</strong></li><li>Limón (lima ácida), bergamota, mandarina y naranja dulce</li><li><strong>Corazón (Middle Notes):</strong></li><li>Jengibre, flor de azahar del naranjo y notas marinas</li><li><strong>Fondo (Base Notes):</strong></li><li>Té (Blue Tea), ámbar y almizcle</li></ul>', 25500, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988019-9fbb-71e9-a932-a95bfb01025c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988019-9f40-72af-be86-a2adca205bc0.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Odyssey Limoni Fresh</strong> es una fragancia cítrica unisex con carácter moderno, perfecta para el día a día en ambientes cálidos. Destaca por su apertura limpia y refrescante y su personalidad versátil. Su perfil lucido y funcional lo convierte en una excelente opción para quienes buscan frescura sin complicaciones.</p>', NULL),
(12328, 'Dumont Nitro Blue 100ml EDP Hombre', '<h3><strong>Notas de salida (top notes):</strong></h3><ul><li>Flor de azahar del naranjo</li><li>Salvia</li><li>Albahaca</li><li>Lima (limón ácido)</li><li>Canela</li></ul><h3><strong>Notas de corazón (middle notes):</strong></h3><ul><li>Cardamomo negro</li><li>Bálsamo de Tolú</li><li>Praliné</li><li>Notas amaderadas</li></ul><h3><strong>Notas de fondo (base notes):</strong></h3><ul><li>Ámbar negro</li><li>Pachulí</li><li>Palo de rosa de Brasil</li><li>Notas dulces</li></ul>', 29000, 1, 'Dumont', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988010-7e11-751e-8ec3-f603b7f4ff07.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988010-7e42-747c-9f1a-9a15e7091a27.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><em>Dumont Nitro Blue</em> es una fragancia masculina que abre con frescura herbal y mentolada, transicionando a una base dulce y amaderada con praliné, cardamomo y ámbar negro, ofreciendo una evolución interesante y buena duración. No es un “blue fresh” tradicional, sino un oriental gourmand con carácter. Ideal para quienes buscan una opción económica pero con rendimiento sólido. Si prefieres frescura pura tipo acuática, puede que no sea lo tuyo; pero para climas templados y salidas sociales, vale cada centavo.</p>', NULL),
(12329, 'Armaf Odyssey Wild One 100ml EDP Men', '<p><strong>Salida:</strong> bergamota, limón, menta y pimienta negra — energía cítrica y especiada</p><p><strong>Corazón:</strong> jengibre, lavanda, pimienta rosa y vetiver — mezcla aromática intensa con un toque picante y verde </p><p><strong>Base:</strong> pachulí, elemi, cedro, sándalo, almizcle y vetiver — fondo sólido, amaderado y resinoso con carácter duradero</p>', 24500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988009-fcaf-7121-89e0-2d836ef94eae.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198800a-00a7-745c-9c2d-6bab3aa35206.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Armaf Odyssey Wild One Gold Edition EDP</strong> es una excelente alternativa económica para quienes buscan un aroma fresco, masculino y versátil en la línea de <strong>Dior Sauvage EDT</strong>. Su perfil sólido y precio accesible lo convierten en una opción muy recomendable como fragancia de todos los días.</p>', NULL),
(12330, 'Armaf Odyssey Homme 100ml EDP Men', '<p><strong>Salida:</strong> bergamota, lavanda y mirto — fresca y aromática</p><p><strong>Corazón:</strong> ámbar, iris empolvado y café — elegante y gourmand</p><p><strong>Fondo:</strong> cedro, cuero, pachulí y vetiver — sobrio, terroso y masculino</p>', 24500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987ce3-172d-769e-9350-95c34574b3a6.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Armaf Odyssey Homme</strong> es una fragancia de perfil gourmand‑amaderado que conjuga iris empolvado y vainilla con especias delicadas y cuero, recuerda en ocasiones a <em>TF Noir Extreme</em> o <em>Dior Homme Intense</em>, pero ofrece una interpretación propia con excelente rendimiento por su precio. Funciona especialmente bien en estaciones frías y para ocasiones donde se busca un aroma masculino moderno sin ser abrumador.</p>', NULL),
(12331, 'Giorgio Armani Acqua Di Gio Profondo 100ml EDP Men', '<h3>Notas principales:</h3><ul><li><strong>Salida:</strong> notas marinas (Aquozone, sea notes), bergamota y mandarina verde — fresca, seca y vibrante</li><li><strong>Corazón:</strong> lavanda, romero, ciprés y mastiha (resina de lentisco) — herbal, resinosa y mediterránea</li><li><strong>Fondo:</strong> ámbar mineral, pachulí y almizcle — mineral, terroso y envolvente</li></ul>', 68000, 2, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987cdc-6fa6-704a-8a76-5aa756923405.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d474-1820-746e-85c8-654b4cab9fbc.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Acqua di Giò Profondo</em> es una evolución elegante del clásico aroma marino: frescura oceánica combinada con notas aromáticas mediterráneas, finalizando en una base cálida y mineral. Su rendimiento es sólido para un acuático, y muchos lo consideran un “compliment magnet”</p>', NULL),
(12332, 'Carolina Herrera Bad Boy Extreme 100ML EDP Men', '<h3>Notas principales</h3><ul><li><strong>Salida</strong>: jengibre fresco y bergamota — chispeante y especiada</li><li><strong>Corazón</strong>: pachulí terroso y vetiver elegante</li><li><strong>Fondo</strong>: cacao cremoso, haba tonka y un ligero incienso dulzón — aporta profundidad gourmand y masculina</li></ul>', 68000, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987cd6-f4e7-740c-8e67-546f8ee908e8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199687e-cb91-721f-8940-6ed14e481fed.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Bad Boy Extreme</strong> es una fragancia masculina intensa y moderna que destaca por su perfil gourmet dominado por cacao especiado y jengibre vibrante, anclado en una base terrosa de vetiver y pachulí. Ofrece un rendimiento sólido y es especialmente adecuado para una presencia nocturna audaz. Si eres fan de los aromas gourmand con fuerza, puede ser una opción muy gratificante.</p>', NULL),
(12333, 'Carolina Herrera Bad Boy Le Parfum 100ML EDP Men', '<h3>Notas olfativas:</h3><ul><li><strong>Salida:</strong> cannabis (cáñamo) verde y pomelo, audaz y muy distintivo</li><li><strong>Corazón:</strong> pimienta negra y geranio, que aportan un carácter especiado-fresco sofisticado</li><li><strong>Base:</strong> cuero y vetiver, aportando profundidad terrosa y una estela intensa</li></ul><p><br></p>', 65000, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987cd1-cb4f-74bb-94a5-8474c5c31da1.png?storeId=1681', 'Hombre', 1, 0, '<p><em>Bad Boy Le Parfum</em> es una fragancia masculina audaz, que abre con un carácter verde y herbal muy marcado y evoluciona hacia un fondo elegante de cuero y vetiver. Es ideal para quien busca una opción rebelde y sofisticada que no pase desapercibida.</p>', NULL),
(12334, 'Marc Jacobs Daisy Eau So Fresh 125ml EDT Women', '<h3>Notas olfativas:</h3><ul><li><strong>Salida</strong>: frambuesa, pomelo y pera — jugosa, fresca y chispeante.</li><li><strong>Corazón</strong>: rosa silvestre, violeta, lichi, flor de manzano y jazmín — delicado y floral sin ser demasiado empalagoso.</li><li><strong>Fondo</strong>: almizcle suave, ciruela y cedro de Virginia — cálido y sutil.</li></ul><h3>Impresión general:</h3><p>Una fragancia ligera, divertida y femenina, ideal para primavera y verano. “Daisy Eau So Fresh” evoca energía soleada con un encanto caprichoso que inspira alegría y feminidad espontánea.</p>', 55500, 1, 'Marc Jacobs', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987cc4-e147-7412-9fb7-93ff32a696e2.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><em>Marc Jacobs Daisy Eau So Fresh</em> es una fragancia femenina fresca, afrutada y floral con un carácter ligero y encantador. Con una apertura chispeante de frutas rojas y cítricas, un corazón delicado de flores campestres y un fondo limpio de almizcle y cedro, es la elección ideal para una apariencia juvenil y alegre durante el día. Perfecta para climas cálidos y salidas casuales.</p>', NULL),
(12335, 'Valentino Uomo Born In Roma Green Stravaganza 100ml EDT Men', '<h3>Notas principales:</h3><ul><li><strong>Salida</strong>: bergamota de Calabria — fresca, brillante y refrescante</li><li><strong>Corazón</strong>: acorde de café — oscuro y sutil, aporta carácter sin ser dulce</li><li><strong>Fondo</strong>: vetiver — terroso, amaderado y elegante</li></ul>', 68500, 2, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c9e-6cc6-7501-a0d3-0b9338d07654.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019997ee-efc7-7098-9796-4454f02ad0c0.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Valentino Uomo Born in Roma Green Stravaganza</strong> es una fragancia masculina fresca y verde con un toque elegante de café, respaldada por vetiver terroso. Ideal para primavera y verano, y perfecta para quienes buscan algo ligero pero sofisticado. Aunque su duración no es muy alta y el café se desvanece pronto, su aroma delicado y versátil lo hace una opción refrescante y única dentro de la línea Born in Roma</p>', NULL),
(12336, 'Lattafa Noble Blush 100ml EDP Mujer', '<h3><strong>Familia olfativa</strong>: Floral frutal gourmand, con un carácter cremoso, dulce y suave</h3><p><strong>Notas principales:</strong></p><ul><li><strong>Salida:</strong> Rose milk — una rosa láctea cremosa, dulce, casi como un batido rosado suave</li><li><strong>Corazón:</strong> Merengue y almendra — un toque gourmand y aireado que aporta calidez y sofisticación</li><li><strong>Fondo:</strong> Sándalo, vainilla y almizcle — un cierre acogedor, levemente polvoriento y envolvente</li></ul>', 25500, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c7c-b151-712d-9aba-25bceb3fa236.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c7c-b428-75fc-91f2-b73ac3c7e660.png?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Noble Blush es una fragancia femenina que se abre con una deliciosa rosa láctea, evoluciona a un corazón dulce de merengue y almendra, y termina en una base cálida y polvorienta con sándalo, vainilla y almizcle. Es ideal para quienes buscan una rosa gourmand original y duradera, especialmente en climas templados o fríos. Si prefieres aromas más frescos o florales realistas, ten cuidado: el sándalo puede opacar el dulce inicial.</p>', NULL),
(12337, 'Dumont Nitro White 100ml EDP Hombre', '<p><strong>Familia olfativa:</strong> Cuero con matices ambarados y dulces, fresco y moderno </p><h3>Notas principales:</h3><ul><li><strong>Salida:</strong> bayas de enebro, ciprés e iris — aportan frescura especiada y un perfil distintivo </li><li><strong>Corazón:</strong> mirra y pachulí — añaden una profundidad terrosa y cálida</li><li><strong>Fondo:</strong> vainilla, miel, ámbar, almizcle y cuero — un cierre envolvente y suave</li></ul>', 29500, 1, 'Dumont', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c6d-3cee-708a-bb06-71f34dfa36f6.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Nitro White de Dumont es una fragancia masculina fresca y cremosa con matices amaderados dulces, que combina cítricos especiados con un fondo cálido de miel, vainilla y cuero. Aunque no es una “bestia” en proyección, ofrece un perfil moderno, equilibrado y asequible que agrada sin ser invasivo.</p>', NULL),
(12338, 'Armaf Odyssey Mandarín Sky Elixir 100ml EDP Men', '<p>Una fragancia <strong>unisex de la familia Oriental Amaderada Gourmand</strong>, lanzada en 2025 por Armaf, que combina frescura especiada con una base cálida, dulce y sofisticada.</p><p><br></p><ul><li><strong>Notas de salida:</strong> mandarina, naranja, lavanda, cardamomo y pimienta negra — chispeantes, especiadas y aromáticas</li><li><strong>Notas de corazón:</strong> caramelo, haba tonka, pachulí e incienso — aportan profundidad dulce y resinosa</li><li><strong>Notas de fondo:</strong> vainilla y vetiver — confieren un cierre amaderado, suave y adictivo</li></ul>', 29500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c62-b238-7783-845b-9e7576f86cbe.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>En resumen: <strong>Mandarin Sky Elixir</strong> es una fragancia audaz que inicia con cítricos especiados y evoluciona hacia una mezcla dulce y amaderada con caramelo, tonka, incienso y vainilla. Perfecta para quienes buscan una versión más sofisticada y equilibrada del ADN gourmand de Mand arin Sky.</p>', NULL),
(12339, 'Maison Alhambra Vibe 100ml EDP Men', '<p>Se considera un clon de <strong>Pacific Chill de Louis Vuitton</strong>, capturando su perfil frutal y refrescante a una fracción del precio.</p><ul><li><strong>Familia olfativa</strong>: Amaderada aromática</li><li><strong>Notas de salida</strong>: cilantro, menta, cítricos (cidra, limón, naranja), grosella negra </li><li><strong>Notas de corazón</strong>: albahaca, rosa de mayo, semillas de zanahoria, chabacano (albaricoque)</li><li><strong>Notas de fondo</strong>: higo, dátiles, almizcle ambreta</li></ul>', 29000, 0, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c5b-0bf7-77ca-bcd8-e44de8fb6a99.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Maison Alhambra Jean Lowe Vibe</strong> es una fragancia unisex fresca y energizante, con notas cítricas y herbales que evolucionan hacia un final dulce y ligero. Es una opción ideal para quienes buscan un aroma vibrante y versátil, especialmente en climas cálidos. Aunque no destaca por su duración o estela, ofrece un perfil olfativo atractivo a un precio accesible.</p>', NULL),
(12340, 'Carolina Herrera 212 VIP Black 100ML EDT Men', '<p><strong>Notas olfativas</strong>:</p><ul><li><strong>Salida</strong>: absenta, anís y hinojo — aporta frescura especiada con un leve toque alcohólico</li><li><strong>Corazón</strong>: lavanda — añade un matiz aromático limpio y elegante</li><li><strong>Fondo</strong>: vainilla negra y almizcle — envolvente, dulce y ligeramente amaderado</li></ul><p><strong>Sensación general</strong>: Sofisticado y carismático, diseñado para el hombre moderno con una presencia enérgica. Ideal para noches o eventos sociales donde quieras destacar.</p>', 56800, 3, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c0a-b41f-762a-9838-8cd9c33584a6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987c0a-b345-7798-b245-cd93b58e7641.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>212 VIP&nbsp;Black EDP</strong> es una fragancia masculina aromática‑fougère que combina un inicio especiado con lavanda y un fondo dulce de vainilla negra y almizcle. Es ideal para la noche, eventos sociales y para quienes buscan un aroma que atraiga atención sin ser abrumador.</p>', NULL),
(12341, 'Issey Miyake Rose&Rose Intense 90ML EDP', NULL, 42500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987b7b-8f5d-775c-b13a-a613d42fb4c6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987b7e-d82a-7106-82e0-e44491a4a678.jpeg?storeId=1681', 'Mujer', 1, 0, NULL, NULL),
(12342, 'Set Versace Eros EDP 3pzas', '<p><strong>Salida:</strong> menta, limón y manzana caramelizada – fresca y vibrante, pero con un dulzor moderno.</p><p><strong>Corazón:</strong> ambroxan, geranio y salvia – aportan calidez, textura y profundidad.</p><p><strong>Fondo:</strong> vainilla, cedro, vetiver y cuero – una base cálida, cremosa y con carácter.</p>', 56500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01987b78-62c5-77e4-a235-a893d0701a3f.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Una fragancia intensa, sensual y carismática que representa el poder del deseo masculino. <strong>Eros EDP</strong> conserva el ADN dulce y fresco de la versión EDT, pero con un giro más <strong>oscuro, maduro y refinado</strong>.</p>', NULL),
(12343, 'Al Haramain Dubai Night 100ml EDP Unisex', '<p><strong>Salida:</strong> bergamota fresca, esencia resinosa de elemi y especiado azafrán</p><p><strong>Corazón:</strong> mezcla lujosa de rosa búlgara, lirio de los valles y oud, que aporta profundidad floral y fumé </p><p><strong>Fondo:</strong> cálido y envolvente con haba tonka, ámbar, almizcle blanco y musgo de roble, dejando una estela sensual y duradera</p>', 46500, 2, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198668d-85c4-707a-bdf2-ff253e8b8a9b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b249b-7d73-7222-b17f-ad682159a0be.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Al Haramain Amber Oud Dubai Night</strong> es una fragancia unisex lanzada en 2024, clasificada dentro de la familia olfativa <strong>chipre/floral oriental</strong>, con una concentración de <strong>Extrait de Parfum</strong>. Se destaca por su carácter intenso, sofisticado y con gran persistencia, diseñada para ocasiones nocturnas o especiales</p>', NULL),
(12344, 'Viktor & Rolf SpiceBomb Extreme 80ML Hombre', '<p>Notas de salida: pimienta negra, comino, azafrán.</p><p>Notas de corazón: lavanda, canela, tabaco.</p><p>Notas de fondo: vainilla, ámbar, resinas</p>', 76000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-ca77-729d-bcbc-5ee594d6dce4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-09bd-76f2-8b49-6a94d897d5c1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-85ce-723c-b828-3cddcad4a5fc.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia intensa, cálida y especiada. Abre con una mezcla picante y aromática, seguida por un corazón dulce y terroso. Su fondo de vainilla y ámbar le da una estela envolvente, ideal para climas fríos y ocasiones nocturnas. Muy duradera y con proyección notable.</p>', NULL),
(12345, 'Carolina Herrera 212 VIP Rose 80ml EDP Mujer', '<p>Champagne rosé, pimienta rosa</p><p>Corazón: Flor del melocotonero , rosa</p><p>Fondo: Almizcle blanco, notas amaderada</p>', 59500, 2, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-c3e0-770a-be66-1b038b60e0a4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b02c-d1a6-72dd-9a56-64ac27f7d308.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b02c-d43b-711c-8bb5-e2d2f81e76b7.png?storeId=1681', 'Mujer', 1, 0, '<p>Carolina Herrera <strong>212 VIP Rosé</strong> es una fragancia femenina floral frutal lanzada en 2014, diseñada para evocar la sofisticación y el glamour de la vida nocturna en Nueva York. Su aroma combina la frescura del champagne rosé con la delicadeza de las flores y la calidez del almizcle, creando una estela elegante y chispeante.</p>', NULL),
(12346, 'Yves Saint Laurent La Nuit De L’Homme 3.3 EDT Sp Men', '<p>Notas de salida: Cardamomo.</p><p>Notas de corazón: Lavanda, cedro de Virginia y bergamota.</p><p>Notas de fondo: Vetiver y alcaravea</p>', 64000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790cf-77db-76ab-9fc2-bacbe3a3d2a4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790cf-791c-7009-af5d-43550eea79fb.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-91b9-727f-9030-d04fa1a2a3a2.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia amaderada especiada que combina la frescura del cardamomo con la calidez del cedro y la suavidad de la cumarina, creando una esencia sofisticada y seductora para el hombre moderno.</p>', NULL),
(12347, 'Body Spray Odyssey Limoni', '<p>Salida: limón (lima ácida), bergamota, naranja dulce y mandarina</p><p>Corazón: jengibre, notas marinas y flor de azahar del naranjo</p><p>Fondo: té, ámbar y almizcle</p>', 6000, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-b9b3-7268-8bf2-fdcc14b3c77b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-91bb-75ac-a741-70723fbf841f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-6f7b-75ba-b1b6-d81462f1cea9.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Odyssey Limoni es un body spray fresco y cítrico con notas de limón, bergamota y mandarina en la salida, combinado con un corazón suave de jengibre y flor de azahar, y un fondo sutil de té, ámbar y almizcle. Ideal para el uso diario en climas cálidos, ofrece una sensación revitalizante y ligera.</p>', NULL),
(12348, 'Crema Victoria Secret Midnight Bloom', '<p>Salida: Moon Flower, con un inicio floral fresco y delicado </p><p>Corazón: mezcla con creamy woods (maderas cremosas), que aportan calidez y suavidad al aroma </p><p>Fondo: toque de vainilla cremosa, sutil y envolvente</p>', 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-b297-709a-b5b3-66ef5bb3149d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-2211-770c-a9a7-24274ee8ac0d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-766b-7040-9cba-589bd4fdfc16.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Una fragancia floral cálida y envolvente que combina la suavidad de la flor nocturna (Moon Flower) con la calidez de las maderas cremosas y un delicado toque de vainilla. Perfecta para uso diario o para momentos especiales al anochecer, esta loción deja la piel suave, hidratada y sutilmente perfumada durante todo el día.</p>', NULL),
(12349, 'Armaf Club De Nuit Intense 105ml EDT Hombre', '<p><strong>Salida </strong>: explosiva y vibrante, con piña, limón, bergamota, grosella negra, manzana y un ligero toque de lima, dando un aire fresco-frutal .</p><p><strong>Corazón</strong> : acorde floral ahumado con jazmín, rosa y el toque firme de brezo/birch (abetún), que introduce profundidad especiada </p><p><strong>Fondo</strong>: envolvente y cálido, con vainilla, ambroxan, ámbar gris, pachulí, musk y cedro que brindan estructura y equilibrio durable</p>', 22500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-afae-7578-8f6d-117cee21849b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01991076-6aca-775e-a890-e3f424db22e2.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Intense EDT es una fragancia masculina amaderada cítrica con un toque ahumado, inspirada en parte por Creed Aventus pero con identidad propia.</p>', NULL),
(12350, 'Rasasi Hawas Fire 100ml EDP Hombre', '<p>Salvia (clary sage) herbácea y fresca</p><p>Manzana jugosa</p><p>Limón ácido y brillante</p><p>Canela cálida y envolvente</p>', 33500, 0, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-ab60-7181-a0a1-0f524b85a84a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-065a-731c-a7b3-84b5e1355919.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-1929-71fb-a483-7ad59da65d26.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia potente y vibrante que mezcla frutas jugosas y especias ardientes con un corazón marino y un fondo cálido y seductor. Diseñada para hombres audaces que buscan dejar una estela moderna, atrevida y magnética.</p>', NULL),
(12351, 'Victorinox Swiss Army Classic EDT 100ml Hombre', '<p>Notas de salida: menta, notas verdes, bergamota, yuzu, jengibre</p><p>Notas de corazón: lavanda, romero, hojas de violeta, flor de las nieves (edelweiss), geranio</p><p>Notas de fondo: ciprés, abeto balsámico, cedro, almizcle, ámbar</p>', 19000, 3, 'Victorinox', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-a6fb-75fc-a05c-144738bd2fa5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cbfa-d2eb-715e-b5b5-5cb042287d04.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia masculina fresca y versátil, ideal para el uso diario. Su apertura cítrica y herbácea se combina con un corazón floral y amaderado, ofreciendo una estela limpia y natural. Apta para climas cálidos y ocasiones informales.</p>', NULL),
(12352, 'Dolce & Gabbana L’Imperatrice 100ml EDT Mujer', '<p>Notas de salida:</p><p>Ruibarbo</p><p>Kiwi</p><p>Pimienta rosa</p><p>Notas de corazón:</p><p>Sandía</p><p>Ciclamen (violeta persa)</p><p>Jazmín</p><p>Notas de fondo:</p><p>Limonero (limonero almizclero)</p><p>Sándalo</p><p>Almizcle</p>', 35000, 6, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-a404-7222-960f-8abd491f57db.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b02a-f9db-7237-a897-4f4b5a72e79a.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>L\'Imperatrice </strong>de Dolce &amp; Gabbana es una fragancia femenina fresca, vibrante y luminosa, lanzada en 2009 como parte de la colección \"D&amp;G Anthology\", inspirada en las cartas del tarot. Representando la carta de \"La Emperatriz\", esta fragancia celebra la feminidad, el poder y la fertilidad. Es ideal para mujeres seguras de sí mismas, carismáticas y naturalmente sensuales, que buscan una fragancia que refleje su personalidad única.</p>', NULL),
(12353, 'Body Mist Pink Light & Happy', '<p>Salida: cítrica vibrante de clementina nectaria, con un toque de mango suave y flores de madreselva que aportan frescura dulce y chispeante </p><p>Corazón: acorde floral delicado con honeysuckle/jazmín helado, que añade un aire fresco, limpio y juvenil </p><p>Fondo: suavidad amaderada, con notas de maderas claras, que dan calidez sin restar frescura </p><p>fragrantica.es</p>', 11800, 0, 'Pink', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-a16c-70f3-b00e-b08713e16216.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af21-54e9-74fa-a42e-13fa48fa8f58.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pink Light &amp; Happy Body Mist es una excelente opción si buscas un aroma cítrico-floral fresco, limpio y acogedor, con una duración muy buena para un mist. Su combinación de notes logra un equilibrio entre vitalidad y suavidad, perfecto para uso diario sin ser invasivo.</p>', NULL),
(12354, 'Yves Saint Laurent Black Opium 100ml EDP Mujer', '<p><strong>Notas de salida:</strong> Pera, pimienta rosa y flor de azahar del naranjo.</p><p><strong>Notas de corazón:</strong> Café, jazmín, almendra amarga y regaliz.</p><p><strong>Notas de fondo: </strong>Vainilla, pachulí, madera de cachemira y cedro</p>', 68500, 0, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d3-7732-740e-af60-7cba4b93bb89.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d3-7576-70b8-b397-9f7ae5e8229d.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-6ea3-7191-bf03-771e52f72e95.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><strong>Black Opium</strong> es una fragancia oriental gourmand que combina la intensidad del café negro con la dulzura de la vainilla y la frescura de las flores blancas, creando una esencia seductora y moderna para la mujer audaz y sofisticada.</p>', NULL),
(12355, 'Orientica Amber Rouge 80ml EDP  Unisex', '<p>Salida: azafrán, jazmín – aporta una apertura especiada, floral y refinada </p><p>Corazón: amberwood, ámbar gris – un núcleo cremoso, ambarado y ligeramente salado </p><p>Fondo: cedro, resina de abeto – brinda un secado amaderado, terroso y perdurable</p>', 48500, 0, 'Orientica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a6e-5da8-7226-af4b-278c65e1ba3c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a6e-5e64-708a-96f0-70ae65a93151.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Amber Rouge</strong> es una fragancia unisex amaderada‑especiada inspirada en Baccarat Rouge 540, con una elegancia oriental moderna. Destaca por su dulzura cálida y sofisticada, ideal tanto para salidas nocturnas como eventos formales.</p>', NULL),
(12356, 'Bharara King 100ml EDP Hombre', '<p>Notas de salida: Naranja, bergamota y limón (lima ácida).</p><p>Nota de corazón: Notas afrutadas.</p><p>Notas de fondo: Vainilla, almizcle blanco y ámbar.</p>', 39500, 0, 'Bharara', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-95a4-7064-9c3c-73e28d218ba6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b029-29a9-7787-9dd6-99c151493279.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Bharara King</strong> Eau de Parfum para Hombre es una fragancia de la marca árabe Bharara, lanzada en 2021. Pertenece a la familia olfativa aromática y se destaca por su frescura cítrica combinada con un fondo dulce y cálido. Perfume súper potente y versátil, listo para usar en cualquier ocasión, puede durar en piel más de 12 horas y en la ropa por días.</p>', NULL),
(12357, 'Carolina Herrera Good Girl Blush Elixir 80ml Mujer', '<p>Salida: bergamota, mandarina, almendra</p><p>Corazón: rosa, ylang‑ylang</p><p>Fondo: vainilla, pachulí</p>', 66500, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d4-e095-700d-9a38-ef0d3a2f34d6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d4-e1f6-742a-9197-268136dc528d.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Carolina Herrera Good Girl Blush Elixir</strong> es una fragancia intensa, sensual y envolvente que reinterpreta el clásico Blush con un giro más profundo y sofisticado. Combina notas cremosas de vainilla y pachulí con un corazón floral de rosa e ylang-ylang, creando un perfume cálido, floral y ligeramente especiado.</p>', NULL),
(12358, 'Body Spray Lattafa Sublime', '<p>Manzana verde lichi</p><p>Notas de corazón: Ciruela</p><p>Jazmín</p><p>Notas de fondo:</p><p>Vainilla Pachulí</p>', 4500, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-8be2-766d-b143-bc31a86c6c09.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-edab-76e8-835e-427b49dc2e2d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-f207-7198-b428-3f878f97ddae.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Sublime Body Spray es una fragancia unisex vibrante y elegante que destaca por su explosiva mezcla frutal. Se abre con manzana crujiente y lichi, se enriquece en el corazón con ciruela y jazmín, y cierra con un fondo cálido de vainilla, musgo y pachulí. Fresca, dulce y sofisticada, ideal para uso diario en primavera y verano.</p>', NULL),
(12359, 'Set Guess Gold 3PZAS Mujer', '<p>Notas de salida: Bergamota, pera y grosella negra.</p><p>Notas de corazón: Jazmín, gardenia y rosa.</p><p>Notas de fondo: Ámbar, vainilla y almizcle.</p>', 39000, 0, 'Guess', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-83b7-7658-9cca-aa6be785b939.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-9426-75ae-b0ad-0ed1ef9e47c6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-bccf-750a-923b-2d8bf0012bba.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set brillante y sofisticado que captura la esencia femenina y moderna con una fragancia floral-frutal, acompañada de productos para cuidar e intensificar su aroma durante todo el día. </p>', NULL),
(12360, 'Chanel Coco Mademoiselle EDP Intense 100ml Mujer', '<p>Notas de salida: Naranja siciliana, bergamota calabresa y limón, aportando frescura y luminosidad.</p><p>Notas de corazón: Rosa, jazmín y notas frutales, que añaden un toque floral y afrutado.</p><p>Notas de fondo: Pachulí, vainilla de Madagascar, haba tonka, almizcle blanco y labdanum, creando una base cálida, dulce y amaderada.</p>', 112500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198a9dc-0d05-7784-aee6-b7f804d2e323.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b033-4be5-746b-ae93-bcbc699859a2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b033-55ab-75bc-9551-deed2f82b404.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El <strong>Coco Mademoiselle</strong> Eau de Parfum Intense de Chanel es una fragancia oriental amaderada y ambarina lanzada en 2018, diseñada para una mujer audaz y sofisticada. Esta versión intensificada del clásico Coco Mademoiselle ofrece una estela profunda y envolvente, destacando por su sensualidad y elegancia.</p>', 4),
(12361, 'Giorgio Armani Si 50ml EDP Mujer', '<p>Salida: Néctar de grosella negra (cassis)</p><p>Corazón: Rosa de mayo (rosa centifolia), fresia</p><p>Fondo: Vainilla, pachulí, notas amaderadas, ambroxan</p>', 51500, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-730f-73aa-b630-548eda915830.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b035-0df4-756c-ad9e-54398f72ea86.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Sí de Giorgio Armani es una fragancia femenina sofisticada y moderna, que combina dulzura y elegancia con un toque fresco y floral. Ideal para mujeres seguras que buscan un aroma envolvente y versátil para el día y la noche.</p>', NULL),
(12362, 'Maison Alhambra Immortel 100ml EDP Men', '<p>Salida: pomelo (toronja), jengibre, bergamota</p><p>Corazón: romero, salvia, geranio, toques acuáticos</p><p>Fondo: ambroxan, ámbar, ládano</p>', 28000, 0, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607d-04d0-704f-a524-82411e114ca9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b036-ad5d-722e-978a-d6092113ea3c.png?storeId=1681', 'Hombre', 1, 0, '<p>Immortel es una fragancia refrescante masculina inspirada en Louis Vuitton L’Immensité. Su apertura vibrante y cítrica evoluciona hacia un corazón herbal-acuático y culmina en un fondo ambarado y almizclado, ofreciendo una composición elegante, moderna y de excelente relación calidad-precio.</p>', NULL),
(12363, 'Calvin Klein Ck One 200ml EDT Unisex', '<p>Limón, bergamota, mandarina, piña, papaya, cardamomo y notas verdes </p><p>Melodía central (Corazón): Lirio de los valles, jazmín, violeta, rosa, nuez moscada, raíz de lirio y fresia</p>', 27000, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-ff29-74a8-b445-d6019c2cfb27.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b037-af9d-7278-b360-e84602f0482d.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia fresca, ligera y versátil, que combina cítricos vibrantes, un corazón limpio floral y un fondo suave amaderado. Ideal para uso diario, en cualquier estación, y perfecta para compartir entre géneros.</p>', NULL),
(12364, 'Antonio Banderas Blue Seduction 100ml EDT Hombre', '<p><strong>Salida</strong>: cítrica y afrutada con melón, bergamota, menta y grosella negra, que transmiten frescura y vitalidad desde el primer moment</p><p><strong>Corazón</strong>: mezcla aquática con agua de mar, manzana verde, capuchino, cardamomo y nuez moscada, que aportan un giro moderno y distintivo </p><p><strong>Fondo</strong>: base suave y masculina de ámbar y madera, con una sutil estela cálida</p>', 16800, 0, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-f77a-7347-9338-01b364c80d8f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198804e-bc86-7479-bee1-fa88a440249f.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Antonio Banderas Blue Seduction</strong> (2007) es una fragancia acuática y frutal que ofrece una experiencia refrescante, tonalidad veraniega y carácter juvenil. Su frescura y precio la convierten en una opción ideal para usar a diario sin pretensiones, especialmente en climas cálidos.</p>', NULL),
(12365, 'Valentino Uomo Born In Roma Intense 100ML EDP Hombre', '<p>Salida: Especias cálidas (pimienta, cardamomo) y café.</p><p>Corazón: Láudano, rosa natural.</p><p>Fondo: Cacao, vainilla amaderada y ámbar.</p>', 82000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-f5b6-74cb-9ade-c366f2195628.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b03e-540d-7170-8d74-b282da9d7244.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Valentino Uomo Born In Roma Intense, </strong>una fragancia masculina con carácter audaz y moderno, que realza la sensualidad urbana con una mezcla intensa de madera y gourmand para una impresión inolvidable. <strong>SEXY Y ENCANTADORA.</strong></p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12366, 'Calvin Klein Escape For Men EDT 100ml Hombre', '<p>Salida: melón, pomelo, mango, eucalipto, enebro y bergamota</p><p>Corazón: notas marinas, abedul, ciprés, romero, abeto y salvia</p><p>Fondo: vetiver, sándalo, ámbar, pachulí y musgo de roble</p>', 27800, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-f1fa-7457-a35c-a420056d26c6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198b040-7ef9-74ed-8337-83a7b31d1870.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Calvin Klein Escape For Men. </strong>Fragancia fresca y masculina con notas cítricas, verdes y acuáticas. Ideal para uso diario en climas cálidos, ofrece una sensación limpia, versátil y ligera. Perfecta para quien busca frescura y comodidad.</p>', NULL),
(12367, 'Armaf Odyssey White Edition 100ml EDP', '<p><strong>Notas de salida </strong></p><p>Toronja </p><p>Yuzu</p><p>Pimienta rosa</p><p>Una apertura cítrica, fresca y especiada, con energía vibrante y ligera picardía.</p><p><strong> Notas de corazón </strong></p><p>Notas marinas</p><p>Hojas de violeta</p><p>Un corazón acuático y limpio, con un toque floral verde suave que aporta serenidad.</p><p><strong>Notas de fondo </strong></p><p>Ámba</p><p>Amberwood</p><p>Madera de gaiac</p><p>Un fondo cálido, amaderado y ligeramente dulce, con un carácter envolvente y duradero.</p>', 24500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-ef2d-73f8-b2b3-5a0113af28be.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a65c5-10cf-709a-9742-167ae8679fdc.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Homme White Edition EDP es una fragancia masculina de carácter cítrico, especiado y ambarado, que equilibra frescura con calidez. Su apertura combina pimienta rosa, yuzu y toronja, ofreciendo un inicio vibrante y chispeante. El corazón introduce notas marinas y hojas de violeta, aportando un matiz limpio y acuático. Finalmente, su secado es cálido y elegante, gracias al ámbar, Amberwood y madera.</p>', NULL),
(12368, 'Marvel Iron Man 100ml EDT Niño', '<p>Salida: manzana, canela, bergamota</p><p>Corazón: clavo de olor, geranio, estragón</p><p>Fondo: sándalo, cedro, hierba, olivo</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-ed74-757b-b147-eff00d156058.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a81-10ab-731d-ad51-e28342900513.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Marvel Iron Man es una fragancia aromática‑especiada y moderna, inspirada en Tony Stark. Presenta un aroma vibrante y fresco con un toque masculino, ideal para niños y preadolescentes que desean una colonia divertida y \"de superhéroe</p>', NULL),
(12369, 'Paris Hilton Heiress 100ml EDP Mujer', '<p>● Notas de salida:</p><p>Maracuyá vibrante, champaña mimosa, melocotón granizado y naranja jugosa.</p><p>● Notas de corazón:</p><p>Jazmín estelar, flor de tiaré, ylang-ylang, madreselva, granadina y flor de mora.</p><p>● Notas de fondo:</p><p>Hojas de violeta, vetiver delicado, maderas claras y haba tonka cremosa.</p>', 26500, 2, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-e97c-739f-b8fb-52f53c16ae69.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986c80-bcc9-776e-9747-fb486172607f.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una esencia brillante, dulce y juvenil que captura el espíritu de una heredera moderna.</p><p>Paris Hilton Heiress es una fragancia encantadora y chispeante que celebra la feminidad con un cóctel frutal efervescente, flores exóticas y un fondo suave y reconfortante. Ideal para mujeres libres, coquetas y seguras de sí mismas, es una fragancia alegre que deja huella.</p>', NULL),
(12370, 'Body Spray Lattafa Yara Tous', '<p>Salida: mango, coco y maracuyá/passionfruit – olores frutales tropicales muy vibrantes </p><p>Corazón: heliotropo, jazmín y azahar — agregan un toque floral dulce y envolvente </p><p>Fondo: vainilla, almizcle y cashmeran — brindan suavidad cremosa y una base musky moderna</p>', 5000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-e57e-708e-a6b6-d1d79d976923.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fc-e331-717d-b20b-d7d9284dd3a7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-4f91-7207-9c6b-dbfa30e11b6a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Yara Tous es un body spray  con una mezcla frutal-tropical (mango‑coco), un corazón floral dulce y una base cremosa de vainilla-musky. Su mayor atractivo es esa apertura veraniega, fresca y alegre. La duración y la proyección varían según el usuario — algunos obtienen 4–6 h con buena presencia, mientras que otros lo sienten débil — por lo que la aplicación en capas y maceración son clave.</p>', NULL),
(12371, 'Orientica Royal Amber 80ml EDP Unisex', '<p><strong>Salida:</strong> bergamota, acordes verdes</p><p><strong>Corazón:</strong> piña, melón, acorde gourmand, ámbar </p><p><strong>Fondo:</strong> vainilla, almizcle, acordes amaderados (sándalo, pachulí</p>', 48500, 3, 'Orientica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-e002-735f-948f-7efbbbc24a01.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a71-aa73-7088-834c-e745ad899b49.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Royal Amber  es una fragancia unisex de la familia ámbar‑amaderada‑frutal. Abre con una mezcla fresca de cítricos y acordes verdes, evoluciona hacia un corazón cremoso y afrutado, y termina en una base cálida de maderas, vainilla y almizcle. Popular por su versatilidad y elegancia, ofrece una alternativa asequible a perfumes gourmands de gama alta. </p>', NULL),
(12372, 'Disney Princess Belle 100ml EDT', '<p><strong>Salida</strong></p><p>Manzana verde y galbanum frescura frutal muy limpia </p><p><strong>Melodía central </strong></p><p>Rosa, hoja de violeta y jazmín  notas florales suaves y elegantes </p><p><strong>Ritmo final</strong></p><p>Ámbar, maderas y almizcle blanco  base cálida, ligera y reconfortante</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-dcf2-757c-abf1-b1c0da06f0b3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-0c99-7762-a60d-0f69fb203766.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-923e-724c-ac5d-66c55a4b0990.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Un aroma femenino floral inspirado en la elegancia y la ternura de la princesa Belle. Fresco y encantador, combina un toque dulce y limpio, ideal para uso diario o para niñas que aman la magia de Disney.</p>', NULL),
(12373, 'Britney Spears Circus Fantasy EDP 100ml Mujer', '<p><strong>Notas de salida:</strong> Frambuesa, azúcar, flor del albaricoquero.</p><p><strong>Notas de corazón: </strong>Orquídea, peonía, nenúfar (lirio de agua).</p><p><strong>Notas de fondo</strong>: Notas dulces, vainilla, almizcle, violeta, notas amaderadas</p>', 15800, 1, 'Britney Spears', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-d843-7319-b4b1-bb5efabb01c6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea15-1623-748f-b4b5-3ec8e1ab9749.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Britney Spears Circus Fantasy</strong> Eau de Parfum es una fragancia femenina lanzada en 2009 como parte de la exitosa línea Fantasy. Con una calificación promedio de 4.6 sobre 5 estrellas en más de 20,000 valoraciones, ha ganado popularidad por su aroma dulce, afrutado y floral, además de su excelente relación calidad-precio. </p>', NULL),
(12374, 'Ralph Lauren Polo Blue 200ml EDT Hombre', '<p><strong>Notas de salida</strong>: Melón de Cavaillon, mandarina, pepino y sandía.</p><p><strong>Notas de corazón</strong>: Geranio, verbena, albahaca y salvia sclarea.</p><p><strong>Notas de fondo:</strong> Madera de ámbar, pachulí, gamuza y almizcle</p>', 55500, 0, 'Ralph Lauren', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-d419-7696-b127-cd534534e8eb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea16-b8f9-70dc-8dc1-160196d455bf.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y acuática que combina notas cítricas y herbales, evocando la libertad y la energía del aire libre. </p>', NULL),
(12375, 'Dolce & Gabbana Light Blue EDT 200ml Hombre', '<p><strong>Salida:</strong></p><p>Pomelo, bergamota, mandarina siciliana y enebro viriginiano — explosión fresca, jugosa y vibrante </p><p><strong>Melodía central (Corazón):</strong></p><p>Pimienta, romero y palo de rosa brasileño — aporta chispa especiada y un toque aromático refinado </p><p><strong>Ritmo final: </strong></p><p>Incienso, almizcle blanco y musgo de roble — base limpia, masculina y ligeramente terrosa</p>', 48500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-cd16-74fd-b144-7323cce773d3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea18-82da-74fd-8442-fb306e3991e9.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y vibrante inspirada en la brisa y la luz del Mediterráneo, ideal para verano y uso diario. Ganadora del FiFi Award como “Fragrance of the Year Men’s Luxe” en 2008, equilibra cítricos, especias y toques amaderados de forma elegante.</p>', NULL),
(12376, 'Set Minis Paco Rabanne Hombre', '<p>Notas de salida: Cítricos frescos, pomelo y menta.</p><p>Notas de corazón: Especias cálidas, lavanda y geranio.</p><p>Notas de fondo: Maderas ambarinas, cuero y almizcle sensual.</p>', 43500, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-cb79-718d-8216-322254b423b1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-e7b9-72ef-92c5-e2e25496c2c6.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set práctico y elegante que incluye miniaturas de las fragancias masculinas más emblemáticas de Paco Rabanne. Perfecto para el hombre moderno que quiere llevar consigo distintos aromas según la ocasión, con un toque de sofisticación y estilo inconfundible.</p>', NULL),
(12377, 'Jean Paul Gaultier Le Beau Le Parfum 125ML Hombre', '<h3><strong>Notas de salida (Top)</strong></h3><ul><li>Piña fresca y dulce</li><li>Iris (toque polvoriento)</li><li>Jengibre, con matiz especiado</li><li>Ciprés, aportando un matiz amaderado verde</li></ul><h3><strong>Notas de corazón (Middle)</strong></h3><ul><li>Coco cremoso</li><li>Acuerdos amaderados profundos</li><li>Tonka bean (sensación cálida y dulce)</li></ul><h3><strong>Notas de fondo (Base)</strong></h3><ul><li>Ámbar (gris/árbol) con carácter animal y seductor</li><li>Sándalo lactónico y cremoso</li><li>Haba tonka complementaria y vainilla suave</li></ul>', 71500, 0, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d8-8cb8-767f-9283-d3c45796a943.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790d8-9007-722c-aa91-9009d2dafe1b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-f31f-71c4-a00a-aff716238de0.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong><em>Jean Paul Gaultier Le Beau Le Parfum</em></strong> es una fragancia masculina intensa y moderna que combina piña exótica, iris polvoriento y coco cremoso sobre un fondo ambarado y seductor. Su proyección lo convierte en una excelente opción para eventos nocturnos o citas especiales. Aunque la nota dulce y cremosa puede sentirse pesada en temporadas cálidas, su mezcla tropical-amaderada lo vuelve altamente atractivo y memorable.</p>', NULL),
(12378, 'Armaf Club de Nuit Precieux 60ml Hombre', '<h3>Familia olfativa: Amaderada - Aromática - Especiada</h3><p><br></p><p><strong>Notas de salida</strong>: Bergamota, limón, pimienta negra</p><p><strong>Notas de corazón:</strong> Lavanda, geranio, rosa</p><p><strong>Notas de fondo:</strong> Ámbar, almizcle, pachulí, cedro</p><p><br></p><p>Esta fragancia combina una salida fresca y cítrica con un corazón floral y especiado, rematada por una base cálida y amaderada, ideal para un hombre elegante que busca un aroma con presencia y sofisticación.</p>', 45500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790da-0e45-73ea-ac30-edd9504b8588.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790da-0e7e-703a-be7f-1b1f8e23b7e3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-0096-775f-801b-2dca96f67d24.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Precieux es una fragancia masculina elegante y sofisticada, que combina notas frescas y especiadas con un corazón floral y un fondo amaderado y almizclado. Es ideal para hombres que buscan un aroma distintivo y refinado, perfecto para la noche y ocasiones especiales. Su equilibrio entre frescura y calidez lo hace versátil y atractivo.</p>', NULL),
(12379, 'Perry Ellis 360 Coral 100ml EDP Mujer', '<p>Bergamota italiana chispeante</p><p>Durazno prosecco jugoso</p><p>Manzana-pera asiática fresca</p><p>Pimienta rosa delicada</p>', 24500, 4, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-b937-77bd-9479-2dd0ca8205d1.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca, vibrante y femenina que combina jugosas frutas cítricas y durazno con un delicado bouquet floral, rematado por un fondo suave y cálido. Perfecta para acompañar días soleados con un toque elegante y alegre.</p>', NULL),
(12380, 'Jean Paul Gaultier Scandal Le Parfum 80ml Mujer', '<p><strong>Notas de salida (top):</strong> Jazmín, que aporta una apertura floral intensa y sofisticada</p><p><strong>Notas de corazón (media):</strong> Caramelo salado, que introduce una dulzura envolvente con un toque moderno y adictivo</p><p><strong>Notas de fondo (base):</strong> Vainilla (a menudo referida como “vainilla negra”), que ofrece una base cálida, cremosa y sensual</p>', 59000, 2, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-b437-736c-bb35-a687b8f38784.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea22-3a54-77e2-9ff1-7f9dc910f9e2.png?storeId=1681', 'Mujer', 1, 0, '<p>Jean Paul Gaultier Scandal Le Parfum es una fragancia femenina lanzada en 2022 como una reinterpretación más intensa y sofisticada de la línea Scandal. Esta edición en Eau de Parfum se caracteriza por una combinación de notas florales y gourmand, ofreciendo una experiencia olfativa seductora y envolvente.</p>', NULL),
(12381, 'Perry Ellis 360 Black 100ML EDT Hombre', '<p>Jengibre picante</p><p>Cardamomo cálido</p><p>Bergamota fresca</p>', 26000, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-ac30-7023-941c-78bde2a3f846.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia intensa, especiada y seductoramente elegante. <strong>360 Black</strong> combina el misterio del tabaco con la calidez del ámbar y la sensualidad de la gamuza, envolviendo a quien la lleva en un aura de sofisticación nocturna.</p><p>Ideal para hombres que buscan dejar huella con una estela sobria, varonil y magnética.</p>', NULL),
(12382, 'Valentino Donna Born In Roma Coral Fantasy 100ml EDP Mujer', '<p>Notas de salida: kiwi, naranja brasileña (o naranja/mandarina)</p><p>Notas de corazón: jazmín (Indian jasmine superinfusion), rosa, semillas de ambrette</p><p>Notas de fondo: almizcle blanco, cedro de Texas</p>', 75500, 1, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-a7de-73cc-8a98-203a43b766dd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a79-c93b-757a-b6ec-76b9b6b4903f.png?storeId=1681', 'Mujer', 1, 0, '<p>Fragancia floral frutal fresca y femenina, vibrante como un atardecer coral en Roma. Abre con un acorde de kiwi jugoso y cítricos, se desliza hacia un corazón elegante de jazmín y rosa, y termina en una base suave y almizclada. Ideal para primavera y verano, para un uso diario ligero o salidas casuales.</p>', NULL),
(12383, 'Set Paris Hilton Gold Rush 4zas Hombre', '<p>Notas de salida: Bergamota, mandarina y cardamomo.</p><p>Notas de corazón: Lavanda, geranio y salvia.</p>', 28800, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-a25b-747e-8e95-7f1c6eb2da25.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set elegante y seductor que captura la esencia del hombre moderno con un aroma cálido y sofisticado. Ideal para quienes buscan una fragancia ambarada y especiada, perfecta tanto para el día como la noche.</p>', NULL),
(12384, 'Al Haramain Gold Edition 120ml EDP Unisex', '<h3><strong>Familia Olfativa:</strong> Oriental - Frutal - Ambarada</h3><p><br></p><p><strong>Notas de Salida:</strong> Bergamota, notas verdes</p><p><strong>Notas de Corazón:</strong> Melón, piña, ámbar, notas dulces</p><p><strong>Notas de Fondo</strong>: Vainilla, almizcle, notas amaderadas</p><p><br></p><p>Esta fragancia ofrece una apertura fresca y frutal, seguida de un corazón dulce y jugoso, y finaliza con una base cálida, cremosa y envolvente. Es conocida por su excelente proyección y duración, lo que la convierte en una favorita entre los amantes de los perfumes árabes de alto rendimiento.</p>', 39500, 8, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-9e48-712a-993f-7ab26a57464b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a75-2309-72b9-ac74-2a333fdc22d0.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><strong>Al Haramain Amber Oud Gold Edition</strong> es una fragancia unisex lujosa y adictiva que destaca por su combinación de notas dulces, frutales y ambaradas. Su aroma se abre con una explosión de frutas jugosas y se funde con un corazón cálido de ámbar y especias suaves, mientras que el fondo es dulce y cremoso, con notas de vainilla y maderas suaves. Es ideal para quienes buscan una fragancia envolvente, duradera y con un perfil elegante pero moderno.</p>', NULL),
(12385, 'Katy Perry Meow 100ml EDP Mujer', '<p><strong>Notas de salida (de cabeza): </strong>Mandarina, Pomelo, Lichi</p><p><strong>Notas de corazón (de medio):</strong> Jazmín, Orquídea, Peonía</p><p><strong>Notas de fondo:</strong> Almizcle, Sándalo, Vainilla</p>', 23000, 1, 'Katy Perry', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-9c09-730e-9d6e-556ce080af43.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea2a-64e7-730c-82ea-cb43c30881bf.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Meow</strong> es una fragancia fresca, dulce y floral que evoca un espíritu juguetón y moderno. Combina la frescura cítrica y afrutada con un bouquet floral suave y un fondo cálido y cremoso, ideal para mujeres jóvenes que buscan una fragancia divertida y encantadora para el día a día.</p>', NULL),
(12386, 'Set Versace Eros EDT + Bolso Hombre', '<p>Notas de salida: Menta fresca, limón siciliano y manzana verde.</p><p>Notas de corazón: Geranio, ambroxan y geranio.</p><p>Notas de fondo: Vainilla, cedro y musgo de roble.</p>', 58000, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-96d2-763b-95b6-ad466675d2f6.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set potente y seductor que combina la intensidad y masculinidad de Eros con un bolso elegante y funcional, perfecto para hombres seguros que desean un aroma fresco, amaderado y energético.</p>', NULL),
(12387, 'Bvlgari Omnia Coral EDT 100ml Mujer', '<p>Notas de salida: Acorde de bayas de Goji, esencia de bergamota.</p><p>Notas de corazón: Acorde de hibisco, acorde de lirio de agua.</p><p>Notas de fondo: Acorde de granada, esencia de madera de cedro.</p>', 62500, 0, 'Bvlgari', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-940e-74e3-8e24-3815dcd2fbec.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea32-adf9-7039-bdd5-93b45ab8363e.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Bvlgari Omnia Coral Eau de Toilette es una fragancia femenina lanzada en 2012, creada por el perfumista Alberto Morillas. Inspirada en la vitalidad solar del coral rojo, esta fragancia floral-frutal captura la energía luminosa de la gema vibrante en una firma jugosa y afrutada. Su diseño de frasco rinde homenaje a la forma icónica de Omnia, mientras que su aroma permanece inalterado, ofreciendo una perspectiva más preciosa de la fascinación de Omnia.</p>', NULL),
(12388, 'Al Haramain Aqua Dubai 100ml EDP Unisex', '<h3>Familia Olfativa: Aromática Frutal</h3><p><strong>Notas de Salida</strong>: Bergamota, mandarina, notas verdes</p><p><strong>Notas de Corazón:</strong> Ámbar, piña, melón, grosellas negras</p><p><strong>Notas de Fondo:</strong> Almizcle, petitgrain, gálbano, vainilla </p><p>Esta fragancia unisex, lanzada en 2024, se caracteriza por una apertura cítrica y fresca, seguida de un corazón afrutado y un fondo suave y cremoso, ofreciendo una experiencia olfativa vibrante y sofisticada.</p>', 43500, 3, 'Al Haramain', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885d0-7a3c-71d0-b727-41ee16174971.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885d0-7cf9-752d-84e1-fa5244a1a1c1.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p><strong>Al Haramain Amber Oud Aqua Dubai</strong> es una fragancia unisex fresca y elegante que captura la esencia del lujo costero de Dubái. Lanzada en 2024, se caracteriza por una apertura cítrica y verde, seguida de un corazón afrutado y un fondo suave y amaderado. Es ideal para el uso diario en climas cálidos, ofreciendo una experiencia olfativa refrescante y sofisticada.</p>', NULL),
(12389, 'Abercrombie Fierce Cologne 100ml EDC Hombre', '<h3>Clasificación olfativa:</h3><p>Familia: Aromática Amaderada</p><p>Estilo: Masculino, fresco y juvenil</p><h3><br></h3><h3>Notas olfativas:</h3><p><strong>Notas de salida: </strong>Petit grain, cardamomo, limón, naranja y abeto</p><p><strong>Notas de corazón</strong>: Jazmín, romero, rosa y lirio de los valles</p><p><strong>Notas de fondo:</strong> Almizcle, vetiver, roble, sándalo y musgo</p>', 50500, 3, 'Abercrombie', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-880a-72ac-bb8c-4deb2a3715be.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea38-0be4-7684-94f6-73d617cc5ea0.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Abercrombie Fierce Cologne para hombre es una fragancia icónica que combina masculinidad, energía y sofisticación. Con notas de almizcle, madera de sándalo, petit grain y cítricos frescos, este perfume destaca por su aroma envolvente y duradero, ideal para hombres seguros de sí mismos. Perfecto para el día o la noche, Fierce se ha convertido en un símbolo de estilo y personalidad. Si buscas un perfume masculino que deje huella, Abercrombie Fierce es tu mejor elección.</p>', NULL),
(12390, 'Maison Alhambra Alquilo Pour Homme 100ml EDP Hombre', '<p>Salida: Mandarina, petit grain, naranja</p><p>Corazón: Algas marinas, lavanda, flor del algodonero</p><p>Fondo: Notas amaderadas, cedro de Virginia, pachulí, esclarea, ámbar</p>', 19000, 0, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a7e-1576-702c-acb0-a96a32ff0258.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a7e-16f0-713a-937f-976f3e0312ce.png?storeId=1681', 'Hombre', 1, 0, '<p>Maison Alhambra Aquilo Pour Homme es una fragancia masculina fresca y acuática, inspirada en Aqva Pour Homme de Bvlgari. Su combinación de notas cítricas, marinas y amaderadas crea un aroma limpio y revitalizante, ideal para el uso diario en climas cálidos.</p>', NULL),
(12391, 'Guess Clasico EDP 75ml Mujer', '<p>Manzana verde</p><p>Fresa</p><p>Bergamota</p><p>Mandarina </p><p>(Un inicio jugoso y cítrico que aporta vitalidad y energía) </p><p>Magnolia</p><p>Peonía</p><p>Fresia</p><p>Lirio de los valles</p><p>Baya roja</p><p>Jazmín</p><p>Durazno</p><p>Ylang-ylang</p><p>(Ramo floral frutal suave, con toques almibarados y femeninos)</p>', 20800, 0, 'Guess', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-7720-75cb-95ba-033889b2138e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea3a-6800-711b-be65-cacbd7681961.png?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2006 por Guess y creada por el perfumista Maurice Roucel, esta fragancia pertenece a la familia olfativa Floral Frutal. Representa una combinación coqueta entre juventud y sofisticación, ideal para mujeres modernas que buscan un aroma dulce, fresco y elegante</p>', NULL),
(12392, 'Set Ariana Grande Cloud 3PZAS', '<p><strong>Notas de salida: </strong>Lichi, pera y bergamota.</p><p><strong>Notas de corazón:</strong> Algodón de azúcar, crema de coco y jazmín.</p><p><strong>Notas de fondo: </strong>Almizcle suave, madera de cachemira y vainilla.</p>', 53000, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-74b6-714c-893d-5a792121ea26.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-b69b-73f3-8465-0bbfb8d7f3c5.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set que envuelve en una nube de dulzura y suavidad, con una fragancia que mezcla gourmand y floral, perfecta para un estilo femenino, moderno y soñador.</p>', NULL),
(12393, 'Set Paris Hilton Heiress 3pzas Mujer', '<p><strong>Notas de salida:</strong> Frambuesa, melón y mandarina.</p><p><strong>Notas de corazón:</strong> Jazmín, orquídea y gardenia.</p><p><strong>Notas de fondo:</strong> Almizcle, ámbar y vainilla.</p>', 30500, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-6753-757d-ae1b-a6b30b75f55c.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set elegante y glamuroso que combina una fragancia femenina y seductora con productos que realzan su aroma dulce y sofisticado, ideal para mujeres seguras y con estilo.</p>', NULL),
(12394, 'Paco Rabanne Invictus Victory EDP 100ml Hombre', '<p><strong>Salida:</strong> limón (o lima ácida), pimienta rosa </p><p><strong>Corazón:</strong> incienso (olíbano), lavanda </p><p><strong>Fondo:</strong> vainilla, haba tonka, ámbar</p>', 59500, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986c99-a0f9-725e-b060-deca742b5453.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea4b-3ab2-7609-a4bc-cb9371ce3056.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Invictus Victory</strong> es una versión intensa y oriental‑fougère lanzada en 2021. Representa una dualidad poderosa: energía y triunfo en su apertura, seguida de una base sensual y cálida. Ideal para quienes buscan una fragancia masculina moderna, con carácter y estela.</p>', NULL),
(12395, 'Perry Ellis 360 Pink EDP 100ML Mujer', '<p><strong>Notas de salida:</strong> rosa, azucena, osmanto (olivo oloroso) y flor del mandarino.</p><p><strong>Notas de corazón:</strong> flor de loto, lirio de los valles (muguete), lavanda y salvia.</p><p><strong>Notas de fondo:</strong> vainilla, sándalo, almizcle, vetiver y ámbar.</p>', 25000, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-1885-75dd-b50a-e3ac31bb6204.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-6500-76af-bd37-67e98629a941.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El Perry Ellis 360° Pink Eau de Parfum (EDP)  para mujer es una fragancia femenina que pertenece a la familia olfativa almizcle floral amaderado. Lanzada en 2011, esta fragancia está diseñada para mujeres que buscan una esencia fresca, floral y ligeramente dulce, ideal para el uso diario en climas cálidos.</p>', NULL),
(12396, 'Yvest Saint Laurent Libre EDP 100ML Mujer', '<p><strong>Notas de salida:</strong> Lavanda francesa, mandarina, grosellas negras y petit grain.</p><p><strong>Notas de corazón: </strong>Jazmín, flor de azahar de naranjo de Marruecos y lavanda francesa.</p><p><strong>Notas de fondo: </strong>Vainilla de Madagascar, almizcle, cedro y ámbar gris</p>', 72500, 0, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-182f-74bd-b488-40cfeaccc9ca.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea4e-7b1f-76d6-b893-de6301169e4f.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral oriental que fusiona la frescura de la lavanda francesa con la sensualidad de la flor de naranja marroquí, creando una esencia audaz y empoderada para la mujer moderna, sexy y femenina.</p>', NULL),
(12397, 'Christian Dior Miss Dior 100ml EDP Mujer', '<p><strong>Notas de salida</strong>: iris, peonía y lirio de los valles (muguete)</p><p><strong>Notas de corazón</strong>: rosa, chabacano (albaricoque) y durazno (melocotón) </p><p><strong>Notas de fondo</strong>: vainilla, almizcle, haba tonka, sándalo y benjuí</p>', 85000, 0, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a83-9e59-7100-a57d-6c32752ca751.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a83-9cce-71cf-88ac-77250403b9cb.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia refinada y atemporal de la familia chipre floral, relanzada en 2021 bajo la visión del perfumista François Demachy. Celebra la feminidad y la elegancia con un ramo floral brillante y sensual.</p>', NULL),
(12398, 'Marvel Spider-Man 100ml EDT Niño', '<p>Salida: naranja agria, bergamota, limón, flor de azahar</p><p>Corazón: neroli/petitgrain, lavanda, geranio (pelargonium), canela, clavo</p><p>Fondo: sándalo, cedro, vetiver, almizcle, ámbar, vainilla</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a80-6b0f-7586-a971-18fcc08f3302.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Marvel Spider‑Man es una fragancia cítrica-aromática juvenil que combina calidad, diversión y esencia aventurera inspirada en el arácnido favorito de todos los tiempos. Ideal para niños y preadolescentes, ofrece un aroma fresco y limpio con toque juguetón.</p>', NULL),
(12399, 'Set Versace Bright Crystal + Bolso', '<p><strong>Notas de salida:</strong> Yuzu, granada y limón.</p><p><strong>Notas de corazón:</strong> Peonía, magnolia y loto.</p><p><strong>Notas de fondo:</strong> Almizcle, ámbar y madera de caoba</p>', 64500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-0c00-7765-8665-45ddbb4ff6b4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-9ceb-760c-8cde-4754ef33061b.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set elegante y femenino que combina la frescura y sofisticación de Bright Crystal con un bolso chic, ideal para mujeres que buscan un aroma floral-frutal delicado y un accesorio versátil para su día a día.</p>', NULL),
(12400, 'Lacoste Touch Of Pink 90ml EDT Mujer', '<p>Notas de salida: Naranja, durazno (melocotón), naranja sanguina, cilantro, cardamomo</p><p>Notas de corazón: Jazmín, hojas de violeta, semillas de zanahoria, cilantro</p><p>Notas de fondo: Sándalo, almizcle, vainilla</p>', 27500, 2, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-0838-73ae-a63e-4fcafe5c6070.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198809b-ba31-73e5-aed6-b1a6cb759bb0.png?storeId=1681', 'Mujer', 1, 0, '<p>Lacoste Touch of Pink es una fragancia femenina que combina notas cítricas y afrutadas con un corazón floral y un fondo amaderado y dulce. Es ideal para mujeres espontáneas y enérgicas que buscan una fragancia fresca y juvenil para el día a día.</p>', NULL),
(12401, 'Christian Dior Miss Dior Blooming Bouquet 100ml EDT Mujer', '<p>Bergamota (mandarina siciliana) aportando frescura vibrante y chispeante. </p><p>Melodía central (Corazón):</p><p>Floral suave con peonía rosa, rosa de Damasco y acordes de chabacano (guisante de olor). </p><p>Ritmo final (Fondo):</p><p>Almizcle blanco que deja una estela limpia, algodonosa y suti</p>', 79000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-0402-7492-93d8-1c7b3fe11c19.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Un ramo fresco y delicado de flores recién abiertas, ideal para uso diario en primavera-verano. Alegre, limpio y elegante: una fragancia que abraza sin ser invasiva.</p>', NULL),
(12402, 'Jennifer López Miami Glow EDT 100ml Mujer', '<p><strong>Notas de salida:</strong> Maracuyá (fruta de la pasión), leche de coco y toronja rosada.</p><p><strong>Notas de corazón:</strong> Flor de azahar del naranjo, ciclamen y heliotropo.</p><p><strong>Notas de fondo:</strong> Vainilla, almizcle y ámbar.</p>', 24500, 1, 'Jennifer López', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607c-0224-70ba-ab0d-e21e216833fe.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea54-239e-720d-9fb3-6b454fa3f38e.png?storeId=1681', 'Mujer', 1, 0, '<p>Jennifer Lopez Miami Glow Eau de Toilette es una fragancia femenina lanzada en 2005, inspirada en la energía vibrante y tropical de Miami. Esta fragancia pertenece a la familia olfativa Floral Frutal y fue creada por la perfumista Caroline Sabas.</p>', NULL),
(12403, 'Clinique Happy For Men EDT 100ml Hombre', '<p><strong>Notas de salida: </strong>Mandarina, limón, lima kaffir y notas marinas, que aportan una apertura cítrica y refrescante.</p><p><strong>Notas de corazón: </strong>Fresia, jazmín y notas verdes, que brindan un toque floral y limpio.</p><p><strong>Notas de fondo: </strong>Ciprés, cedro, madera de guaiac y almizcle, que proporcionan una base amaderada y ligeramente terrosa.</p>', 32000, 0, 'Clinique Happy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-feb7-72b5-91fc-7312c2a23456.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee44-3bcd-77fd-a42d-2644b000b5af.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Clinique Happy for Men </strong>es una fragancia masculina fresca y vibrante, lanzada en 1999. Diseñada para transmitir una sensación de alegría y optimismo, es ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12404, 'Body Mist Disney Frozen Elsa 200ml Niña', '<p><strong>Notas de salida: </strong>Raspberry (frambuesa) y Apple (manzana)</p><p><strong>Notas de corazón: </strong>Jasmine (jazmín) y Rose (rosa)</p><p><strong>Notas de fondo:</strong> Moss</p>', 3900, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a8f-bd59-737b-8755-15191cc100a7.png?storeId=1681', 'Niños', 1, 0, '<p>El Body Mist Disney Frozen Elsa 8.1 oz es una fragancia ligera y fresca, especialmente diseñada para niñas que buscan una experiencia sensorial inspirada en la magia de Elsa. Este producto se presenta en un envase de 240 ml, ideal para uso diario y para llevar en el bolso.</p>', NULL),
(12405, 'Set Perry Ellis 360 Coral 100ml 3PC Mujer', '<p><strong>Notas de salida:</strong> Pera, bergamota y durazno.</p><p><strong>Notas de corazón:</strong> Jazmín, rosa y lirio del valle.</p><p><strong>Notas de fondo:</strong> Sándalo, almizcle y vainilla.</p>', 28500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-f56f-74fa-8bca-9b78037a92d1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-db89-73b3-b958-692c41a8f6ac.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set vibrante y femenino que irradia calidez y alegría. 360 Coral es una fragancia frutal y floral con un fondo cremoso, ideal para mujeres radiantes, alegres y llenas de energía. <strong>Incluye perfume 100ml, mini y gel de ducha.</strong></p>', NULL),
(12406, 'Paco Rabanne One Million Elixir 100ml Hombre', '<p><strong>Salida: </strong>Manzana, davana</p><p><strong>Corazón: </strong>Rosa damascena, osmanto, cedro</p><p><strong>Fondo: </strong>Vainilla, haba tonka, pachulí</p>', 66000, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-f2d9-72db-87df-796249209888.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee4b-904d-7584-a618-fdc6153bf9d0.png?storeId=1681', 'Hombre', 1, 0, '<p><strong>Paco Rabanne One Million Elixir</strong> es una versión intensa y sofisticada del clásico One Million. Su fragancia es opulenta, profunda y sensual, ideal para quienes buscan dejar una impresión duradera.</p>', NULL),
(12407, 'Ariana Grande Cloud 100ml EDP 100ml Mujer', '<p><strong>Salida</strong>: lavanda, pera y bergamota — una combinación fresca, chispeante y ligeramente herbal </p><p><strong>Corazón</strong>: crema batida, coco, praliné y orquídea de vainilla — un corazón dulce y cremoso tipo postre </p><p><strong>Fondo</strong>: cashmeran/maderas suaves y almizcle — aportan calidez, terciopelo y un acabado suave</p>', 43000, 3, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-f062-74ae-ac53-bf0bfa455dd7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee4f-4d79-754f-87c6-f972b86b1d0f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee4f-5399-7159-9f1d-f6168b3c73bc.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Cloud </strong>ofrece una combinación adictiva de dulce, cremoso y almizclado, con una excelente persistencia y sillage moderado. Ideal para quienes buscan una fragancia reconfortante, moderna y llamativa sin ser empalagosa, especialmente en otoño o invierno.</p>', NULL),
(12408, 'Perry Ellis 18 EDP 100ml Mujer', '<p>Notas de salida: Mojito, frambuesa y pera</p><p>Notas de corazón: Nenúfar (lirio de agua) y orquídea</p><p>Notas de fondo: Sándalo y vainilla</p>', 26000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-ebb6-71ed-84ad-55f622c3eab1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee51-3ae6-712e-95c1-b483e0254ce0.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El Perry Ellis 18 para Mujer es una fragancia fresca y femenina lanzada en 2006 por la marca estadounidense Perry Ellis. Clasificada en la familia olfativa floral frutal, es ideal para el uso diario, especialmente en climas cálidos y durante el día.</p>', NULL),
(12409, 'Christian Dior Sauvage EDP 200ml Hombre', '<p><strong>Salida:</strong></p><p>Bergamota di Calabria — chispeante, jugosa y ligeramente picante </p><p><strong>Melodía central (Corazón):</strong></p><p>Pimienta de Sichuan, lavanda, anís estrellado y nuez moscada — mezcla especiada, aromática y herbal </p><p><strong>Ritmo final </strong></p><p>Ambroxan cremoso y vainilla de Papúa Nueva Guinea — base suave, sensual y terrosa</p>', 103000, 0, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-e78a-7503-900a-f412ed27b0f0.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986c9d-369a-771d-9aa8-766192e1ee76.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia aromática-fougère oriental, lanzada en 2018 por François Demachy, que evoca el crepúsculo en el desierto. Despliega una frescura especiada que evoluciona hacia una base cálida y envolvente gracias a una dosis generosa de vainilla y ambroxan.</p>', NULL),
(12410, 'Body Mist Pink Coconut', '<p>Familia olfativa: tropical frutal, con un toque cítrico y dulce </p><p>Salida: coco fresco y jugoso, acompañado de vainilla cremosa y un toque de maracuyá (passionfruit)</p><p>Corazón/fondo: una base suave de jazmín y almizcle ligero, aportando ternura y calidez</p>', 11800, 0, 'Pink', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-e4fd-738e-a09b-d3c6607a3335.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-591d-76e2-951c-4474dc9175c3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-a5ef-7685-a2ce-32a2be0ec0b2.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pink Coconut Body Mist es ideal si te atraen los aromas cálidos y playeros tipo coco con toque de vainilla. Su estilo es relajado, cómodo y muy veraniego. El rendimiento es contenido: útil para refrescarse pero no esperes una fijación duradera. Te recomiendo reaplicarlo o complementarlo con la loción de la misma línea para intensificar el aroma.</p>', NULL),
(12411, 'Donna Karan DKNY Be Delicious 100ml EDP Mujer', '<p><strong>Notas de salida:</strong></p><p>Pepino</p><p>Toronja </p><p>Magnolia</p><p><strong>Notas de corazón:</strong></p><p>Manzana verde</p><p>Lirio de los valles </p><p>Nardos</p><p>Violeta</p><p>Rosa</p><p><strong>Notas de fondo:</strong></p><p>Ámbar blanco</p><p>Maderas</p><p>Sándalo</p>', 39000, 1, 'Donna Karan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-e10b-7576-8b7a-905d6b2b5efa.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee57-365c-7540-ac47-6ca32a10b99e.png?storeId=1681', 'Mujer', 1, 0, '<p>DKNY Be Delicious de Donna Karan es una fragancia femenina que captura la esencia de la ciudad de Nueva York: moderna, vibrante y llena de energía. Lanzada en 2004, esta fragancia ha sido un ícono por su aroma fresco, afrutado y floral, simbolizando la independencia y el estilo urbano de la mujer contemporánea. Su presentación en forma de manzana verde refleja su carácter jugoso y juvenil.</p>', NULL),
(12412, 'Lancome Miracle 100ml EDP Mujer', '<p><strong>Notas de salida:</strong> Lichi jugoso, Freesia y Pimienta rosa.</p><p><strong>Notas de corazón:</strong> Peonía, Rosa de Damasco, Magnolia delicada, Pimienta Bourbon y Jengibre.</p><p><strong>Notas de fondo:</strong> Absoluto de Jazmín, Almizcle, Pachulí y Ámbar</p>', 58000, 0, 'Lancome', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-db19-7167-bbe6-41ce0475e672.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee59-5ada-769a-9f68-ce761256533e.png?storeId=1681', 'Mujer', 1, 0, '<p><strong>Miracle de Lancôme</strong> es una fragancia floral especiada que captura la frescura y la energía de un nuevo amanecer. Con una combinación de notas frutales y florales, es ideal para mujeres activas y optimistas que buscan una esencia vibrante y elegante.</p>', NULL),
(12413, 'Dolce & Gabbana K 100ml EDP Hombre', '<p>Bergamota, Mandarina, Pomelo, Lavanda, Anís estrellado</p><p>(Frescura cítrica y aromática que abre la fragancia con energía y vitalidad)</p><p>Notas de corazón (media): Salvia, Romero, Pimienta rosa</p><p>(Toques herbales y especiados que aportan dinamismo y carácter)</p><p>Notas de fondo: Cedro, Vainilla, Almizcle, Incienso</p><p>(Base cálida, amaderada y ligeramente dulce que aporta profundidad y sensualidad)</p>', 48500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-d9f9-7416-913f-fa7faa132708.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee5b-7926-72ce-9d82-09d17b4339a4.jpeg?storeId=1681', 'Hombre', 1, 0, '<p><strong>Dolce &amp; Gabbana K </strong>es una fragancia para hombre que representa la energía, la confianza y la realeza moderna. Inspirada en la naturaleza y la fuerza del color azul (que simboliza poder y nobleza), esta fragancia es un homenaje a la masculinidad vibrante y elegante. La versión EDP (Eau de Parfum) ofrece una intensidad y duración mayores que las versiones EDT, con un aroma que combina frescura, calidez y un toque sofisticado ideal para el hombre moderno y seguro de sí mismo.</p>', NULL),
(12414, 'Body Victoria Secret Love Spell Candiet', '<p>Salida: peach gumdrop, caramelo hilado</p><p>Corazón: lirio de los valles </p><p>Fondo: remolinos de ciruela y cinta de caramelo, con un toque de almíbar dulce</p>', 11800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-d49c-758e-b0bf-a6d72e8ef3d7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-3f83-7777-aa46-26799d934b3f.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Love Spell Candied es una versión festiva y gourmand del clásico Love Spell. Con un perfil dulce y juvenil, evoca el aroma del caramelo y las gominolas, ideal para quien busca una fragancia divertida y reconfortante.</p>', NULL),
(12415, 'Versace Bright Crystal Absolu 90ml EDP Mujer', '<p><strong>Salida</strong>: yuzu, granada, acorde acuático.</p><p><strong>Corazón</strong>: peonía, magnolia, flor de loto, frambuesa.</p><p><strong>Fondo</strong>: almizcle, caoba, ámbar.</p>', 50500, 2, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986c9f-50ae-729a-89bd-5953d67646b7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee5e-cf24-739a-9a3f-a00d5376e0b6.png?storeId=1681', 'Mujer', 1, 0, '<p>Fragancia floral-frutal fresca y femenina. Abre con notas cítricas y afrutadas, seguida de un corazón floral y un fondo cálido y amaderado. Ideal para uso diario en primavera y verano.</p>', NULL),
(12416, 'Antonio Banderas King Of Seduction Absolu 200ml Hombre', '<h3>Familia olfativa: Aromática - Amaderada</h3><p><br></p><p><strong>Notas de salida: </strong>Bergamota, toronja, manzana verde</p><p><strong>Notas de corazón</strong>: Salvia, geranio, notas especiadas</p><p><strong>Notas de fondo:</strong> Cedro, ámbar, madera de sándalo, almizcle</p><p><br></p><p>Esta combinación crea una fragancia fresca y a la vez cálida y profunda, ideal para momentos en los que quieres dejar una impresión seductora y duradera.</p>', 21500, 0, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-cd57-735f-9e59-21f0b2a4293e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee60-fbe3-71ef-87d4-aa73461a851e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Antonio Banderas King of Seduction Absolu es una fragancia masculina intensa y seductora, diseñada para hombres seguros y apasionados. Combina notas frescas y cítricas en la salida con un corazón aromático y especiado, y una base cálida y amaderada que aporta profundidad y sensualidad. Ideal para usar en la noche o en ocasiones especiales, es un aroma moderno que evoca poder y magnetismo.</p>', NULL),
(12417, 'Body Spray Odyssey Mandarín Sky', '<p>Notas de salida: mandarina, naranja</p><p>Notas de corazón: caramelo, haba tonka</p><p>Notas de fondo: ambroxan, cedro, vetiver</p>', 6000, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-caac-77d8-93ab-a7a0caff15ea.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-1352-77da-9d6c-16bc6fad66ad.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-ab0c-73ae-af9c-c3e54697762d.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Odyssey Mandarin Sky es un body spray dulce y especiado inspirado en Scandal Pour Homme de Jean Paul Gaultier. Su fragancia se abre con notas cítricas de mandarina y naranja, seguidas de un corazón dulce de caramelo y haba tonka, y un fondo amaderado con ambroxan, cedro y vetiver. Ideal para noches frescas y ocasiones especiales, ofrece buena duración y proyección.</p>', NULL),
(12418, 'Body Mist Pink Cool & Bright Bubbly', '<p>Salida: mezcla cítrica chispeante de pera helada, mandarina jugosa, pomelo rosado y un matiz acuático que recuerda a agua de mar o piscina </p><p>Corazón: acorde floral ligero con orchid blanca, que aporta una faceta limpia y fresca </p><p>Fondo: base de almizcle blanco, que deja una estela suave, nítida y durader</p>', 11800, 2, 'Pink', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-cbc6-76bf-9d4e-8c3bd67e66f4.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-5839-7157-967b-5b46be3000da.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-d0e8-71c3-b6f2-f084e2aae89a.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pink Cool &amp; Bright Body Mist es una opción refrescante, limpia y agradable para el día a día, especialmente en climas cálidos. No busca ser imponente, sino brindar un toque de frescura y bienestar. Si prefieres aromas energizantes, ligeros y fáciles de aplicar, es una excelente elección.</p>', NULL),
(12419, 'Davidoff Cool Water 125ml EDT Hombre', '<p>Agua de mar , menta, lavanda, romero, cilantro y notas verdes  frescura oceánica herbal. </p><p>Melodía central </p><p>Sándalo, geranio, jazmín y neroli  bouquet floral-maderado limpio. </p><p>Ritmo final </p><p>Musgo de roble, almizcle, tabaco, cedro y ámbar gris  base masculina ligera y duradera.</p>', 25500, 0, 'David Off', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee65-9377-730d-acdb-367f8104bc02.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee65-9374-7668-95ce-507c5fb87f66.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia acuática aromática clásica lanzada en 1988, considerada un referente de frescura marina. Refleja vitalidad, energía y limpieza masculina, ideal para uso diario y climas cálidos</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12420, 'Giorgio Armani Stronger With You Intensely 100ml EDP Hombre', '<p><strong>Salida</strong>: Pimienta rosa, enebro de Virginia, violeta</p><p><strong>Corazón</strong>: Toffee, canela, lavanda, salvi</p><p><strong>Fondo</strong>: Vainilla, haba tonka, ámbar, gamuza</p>', 64000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-c06b-708a-8b6b-92a488586d7a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ee68-4856-748c-a731-795a60c50bb2.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Lanzada en 2019, esta versión más intensa del popular Stronger With You se ubica dentro de la familia olfativa Ámbar Fougère. Es una fragancia cálida, dulce y especiada, ideal para hombres que buscan una aroma envolvente con carácter </p><p>Según reseñas de tiendas en Costa Rica, su apertura presenta un toque potente de pimienta rosa, enebro y violeta, seguido de un corazón gourmand con toffee, canela, lavanda y salvia. El fondo se compone de vainilla, haba tonka, ámbar y gamuza</p>', NULL),
(12421, 'Disney Frozen Niña', '<p>mandarina, manzana, toronja (pomelo)</p><p>Notas de corazón: chocolate, grosella negra, flor de azahar del naranjo</p><p>Notas de fondo: vainilla, ámbar, sándalo</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-4093-7489-8836-d5562dff3971.png?storeId=1681', 'Niños', 1, 0, '<p>Fragancia floral‑frutal ligera creada para fans de Frozen, con una apertura fresca y afrutada (manzana, mandarina, pomelo), un corazón floral suave (azahar, grosella negra, chocolate blanco) y fondo cálido de vainilla, ámbar y sándalo</p>', NULL),
(12422, 'Maison Alhambra Victorioso EDP 100ml', '<p>Salida: notas marinas</p><p>Corazón: hoja de laurel, jazmín</p><p>Fondo: ámbar gris, musgo de roble, madera de gaiac, pachulí</p>', 19000, 0, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-b52d-731c-b335-458f6fd3d02b.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Maison Alhambra Victorioso es una fragancia masculina amaderada-acuática lanzada en 2022, inspirada en Paco Rabanne Invictus. Se caracteriza por un aroma fresco, especiado y ligeramente dulce, ideal para uso diario y salidas informales.</p>', NULL),
(12423, 'Britney Spears Fantasy 100ml EDP Mujer', '<p>Salida: lichi rojo, membrillo dorado y kiwi — frescos y exóticos </p><p>Corazón: cupcake, chocolate blanco con orquídea, y pétalos de jazmín — un acorde gourmand suave y dulce </p><p>Fondo: almizcle cremoso, raíz de lirio (orris) y maderas sensuales — aporta calidez y redondez</p>', 21500, 0, 'Britney Spears', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-b876-74e9-8589-97c18a34b8d0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199039e-3b6f-751d-b03e-c7ae2270b659.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2005, Fantasy se convirtió rápidamente en un ícono de las fragancias gourmand-florales. Su estela combina notas afrutadas, golosas y florales, dando como resultado un aroma femenino, juguetón y algo nostálgico.</p>', NULL),
(12424, 'Paco Rabanne One Million Parfum', '<p>Salida: Acorde solar, nardo</p><p>Corazón: Ámbar gris, cuero salado</p><p>Fondo: Resinas, madera de cachemira</p>', 59500, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-ae6a-757d-81cf-ee34a51fbc6f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903a5-f894-70fa-9981-a96833808120.png?storeId=1681', 'Hombre', 1, 0, '<p>Paco Rabanne One Million Parfum es una interpretación más intensa, cálida y solar del original One Million. Conserva el ADN lujoso y atrevido de la línea, pero con un giro más envolvente y audaz.</p>', NULL),
(12425, 'Versace Eros Flame 200ml EDP Hombre', '<p>Notas de salida: mandarina, pimienta negra de Madagascar, naranjo moruno, limón y romero.</p><p>Notas de corazón: pimienta, geranio y rosa.</p><p>Notas de fondo: vainilla, haba tonka, cedro de Texas, sándalo, pachulí y musgo de roble</p>', 59500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a87-b489-7111-add7-f202aaab9377.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903a9-5abc-77c8-a2e3-b6c18b91b667.png?storeId=1681', 'Hombre', 1, 0, '<p>Versace Eros Flame es una fragancia masculina que fusiona la frescura de los cítricos con la calidez de las especias y la profundidad de las maderas. Su apertura es vibrante y energética, gracias a la combinación de mandarina, pimienta negra y naranjo moruno. En el corazón, la pimienta y el geranio aportan un toque especiado y floral, mientras que en el fondo, la vainilla, haba tonka y maderas preciosas crean una base cálida y sensual.</p>', NULL),
(12426, 'Body Mist Ariana Grande God Is A Woman', '<p>Familia aromática: Frutal–floral gourmand, suave y delicada </p><p>Salida: jugosa pera y notas de ambrette ligera — fresca y chispeante </p><p>Corazón: rosa turca y orris — floral empolvado con un toque elegante </p><p>Fondo: vainilla de Madagascar y cedro cremoso — cálido y reconfortante</p>', 9000, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-a820-703e-a1b4-aabb7a37a742.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-3780-7230-b810-2fc40e75451f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-5948-732b-9823-311f9faa63eb.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>God Is a Woman” body mist ofrece un toque aireado y femenino que refleja la versión original de la fragancia, en un formato perfecto para el calor, titp diario o el cuidado personal. Ideal para quienes prefieren aromas delicados y fáciles de reaplicar sin saturar el ambiente.</p>', NULL),
(12427, 'Ariana Grande Ari 100ml EDP Mujer', '<p><strong>Salida</strong>: frambuesa, pera y toronja (pomelo) — fresca, afrutada y ligeramente chispeante </p><p><strong>Corazón</strong>: orquídea de vainilla, rosa y lirio del valle — bouquet floral cremoso y femenino </p><p><strong>Fondo</strong>: malvavisco, almizcle y maderas claras — dulce, acogedor y con una base suave</p>', 34500, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-a4a7-7206-9c85-270f2811d76b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986ca1-8e6b-7555-a149-88ceea7af84e.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Ari es una fragancia gourmand juvenil y versátil, con una mezcla atractiva de frutas, flores cremosas y malvavisco. Perfecta para el uso diario, especialmente en primavera y verano, y para quienes buscan un aroma accesible, dulce y no invasivo. Aunque no es una fragancia dominadora, cumple muy bien si te gustan los perfumes divertidos y femeninos.</p>', NULL),
(12428, 'Valentino Uomo Born In Roma 150ml EDT Hombre', '<p><strong>Notas de salida: </strong>hoja de violeta, sal, notas minerales.</p><p><strong>Notas de corazón:</strong> jengibre, salvia.</p><p><strong>Notas de fondo:</strong> vetiver, maderas ambaradas.</p>', 85500, 0, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-9ef1-707c-a4e8-c9fbacb0db1c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903ab-ff63-76aa-8e15-67eb8a640a6b.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia amaderada y especiada con un aire moderno. Abre con frescura salina y un toque mineral, sigue con un corazón aromático y especiado, y termina en una base terrosa y amaderada. Se siente urbana y distinta, con un equilibrio entre frescura y carácter cálido.</p>', NULL),
(12429, 'Tommy Hilfiger 200ml Hombre', '<p><strong>Notas de salida: </strong>Menta, lavanda, toronja (pomelo) y bergamota.</p><p><strong>Notas de corazón:</strong> Arándano, rosa y manzana Granny Smith.</p><p><strong>Notas de fondo:</strong> Ámbar, cactus y flor del algodone</p>', 39800, 1, 'Tommy Hilfiger', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-b788-764e-b782-1e88d368a90c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903af-0a0e-701a-adaf-09682d1ec2ac.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia clásica y fresca que captura el espíritu juvenil y enérgico del hombre moderno. Con una combinación de notas cítricas y florales, es ideal para el uso diario, ofreciendo una sensación de frescura y vitalidad.</p>', NULL),
(12430, 'Paco Rabanne Pure XS 50ml EDT Hombre', '<p>Mandarina roja</p><p>Menta</p><p>Canela</p><p>Rosa</p><p>Ámbar</p><p>Cuero</p>', 36800, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-9723-77f9-b1b3-fbc3cb0b2ffd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903b4-453a-768a-a4e4-03345370860c.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Lanzada en 2017, Pure XS es una fragancia masculina de la familia aromática especiada/oriental. Combina energía fresca con sensualidad profunda, ideal para noches o salidas con un aire seductor</p>', NULL),
(12431, 'Cristiano Ronaldo Discover 100ml Hombre', '<p>Naranja, limón siciliano y mandarina</p><p>Notas de corazón: Salvia esclarea, petitgrain y lavandín</p><p>Notas de fondo: Cistus (labrador tea), vetiver y pachul</p>', 28000, 0, 'Cristiano Ronaldo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-8f08-717a-99da-ca69a652d283.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y sofisticada diseñada para el hombre moderno que se aventura en el autodescubrimiento. Con una apertura cítrica vibrante, un corazón aromático y una base amaderada y terrosa, esta colonia ofrece una experiencia olfativa única y duradera.</p>', NULL),
(12432, 'Dolce&Gabbana Light Blue 100ml EDT Mujer', '<p><strong>Notas de salida: </strong>Manzana verde, Limón siciliano, Campanilla (flor de campana), Cedro</p><p>(Una apertura fresca, cítrica y frutal que aporta luminosidad y energía)</p><p><strong>Notas de corazón: </strong>Jazmín, Rosa blanca, Bambú</p><p>(Toques florales delicados y naturales que añaden feminidad y elegancia)</p><p><strong>Notas de fondo: </strong>Ámbar, Almizcle, Cedro</p><p>(Base cálida y suave que aporta profundidad y sensualidad)</p>', 41500, 11, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-841b-7685-bd9e-1d575820e17b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903b9-0caf-766d-a11b-63a9eb7f3769.png?storeId=1681', 'Mujer', 1, 0, '<p>Light Blue de Dolce &amp; Gabbana es una fragancia icónica para mujer que captura la esencia de un verano mediterráneo, fresco, luminoso y lleno de vitalidad. Es una fragancia refrescante y alegre, perfecta para la mujer moderna, espontánea y segura de sí misma que disfruta de la vida y los momentos al aire libre.</p>', NULL),
(12433, 'Carolina Herrera 212 NYC 100ml EDT Hombre', '<p>Acordes verdes frescos (hierba cortada, notas verdes)</p><p>Cítricos vibrantes (pomelo, bergamota)</p><p>Elementos aromáticos como lavanda y petitgrain</p>', 52500, 7, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-7db6-715a-ab8a-9187f4d95808.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903ba-55db-764a-9849-f30c9db31143.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca, vibrante y urbana inspirada en la energía de Nueva York. Mezcla acordes verdes y cítricos con toques especiados y un fondo amaderado elegante; perfecta para uso diario, primavera y verano.</p>', NULL),
(12434, 'Reyane Tradition Acqua Di Parisis Amber EDP 100ml Mujer', '<p>Bergamota chispeante</p><p>Pimienta rosa delicada</p>', 19800, 1, 'Reyane Tradition', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-74cf-7429-8dcf-19c74478ec33.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-bf7b-761d-ad1c-190dee4f2363.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-eb76-76c1-a998-b984b4fdf70f.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia oriental‑ambarada femenina que combina calidez resinosa, dulzura especiada y un fondo envolvente, ideal para quienes buscan un aroma sofisticado, sensual y reconfortante.</p>', NULL),
(12435, 'Calvin Klein Eternity Moment 100ml EDP Mujer', '<p><strong>Notas de salida:</strong> lichi, guayaba, granada, frambuesa, melón</p><p><strong>Notas de corazón: </strong>peonía rosada de China, jazmín, nenúfar (lirios de agua), flor de la pasión</p><p><strong>Notas de fondo:</strong> almizcle, palo de rosa de Brasil, madera de cachemira, sándalo</p>', 28500, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-3dbd-7719-b1d5-1079f737ac67.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903bf-c5a5-7741-a1ec-84166faade2e.png?storeId=1681', 'Mujer', 1, 0, '<p>Calvin Klein Eternity Moment es una fragancia femenina lanzada en 2004, diseñada para capturar la esencia de un amor romántico y espontáneo. Su perfil olfativo es floral-frutal, fresco y ligeramente dulce, ideal para el uso diario en primavera y verano.</p>', NULL),
(12436, 'Issey Miyake Sport EDT 100ml Hombre', '<p>Salida: Pomelo (toronja) y bergamota – apertura cítrica y revitalizante. </p><p>Corazón: Cuero y nuez moscada – aporta un matiz especiado y limpio. </p><p>Fondo: Vetiver, cedro de Virginia y ámbar gris – base amaderada, terrosa y ligeramente mineral.</p>', 32000, 1, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-3891-7033-be30-4458093fa1ad.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019903c3-79a4-70ee-bc76-a12c451c9074.png?storeId=1681', 'Hombre', 1, 0, '<p>L’Eau d’Issey Sport (2012) es una versión más enérgica y masculina del clásico Issey Miyake. Inspirada en el movimiento y lo acuático, combina cítricos vibrantes con un corazón especiado y un fondo amaderado. Perfecta para hombres activos que buscan frescura y elegancia casual.</p>', NULL),
(12437, 'Dolce&Gabbana The One EDT 100ml Hombre', '<p>Pomelo/toronja vibrante cilantro  albahaca apertura fresca y aromática </p><p>Melodía central </p><p>Jngibre , cardamomo  flor de azahar del naranjo especiada, cálida y sofisticada </p><p>Ritmo final </p><p>Ámbar  tabaco  cedro base masculina, terrosa y cercana</p>', 45500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-34cb-76ee-be2b-817ff332f290.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc9f-30a5-70f8-89a8-7eaf1363869c.png?storeId=1681', 'Hombre', 1, 0, '<p>Un clásico moderno de estilo amaderado especiado, elegante y seductor. Ideal para salidas nocturnas, citas o el día a día con un toque distintivo, gracias a su cálida mezcla de cítricos y especias.</p>', NULL),
(12438, 'Jesús Del Pozo Halloween Rock On EDT 125ml Hombre', '<p>Notas de salida: Limón (lima ácida), pimienta rosa, cardamomo, bambú</p><p>Notas de corazón: Manzana roja, lavanda, romero, hojas de violeta</p><p>Notas de fondo: Almizcle, musgo, sándalo, ámbar</p>', 27000, 0, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-3171-7021-b6ef-ba16fc36ccd8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd51-1a79-76f8-b2d4-3d1f97c9b1d6.png?storeId=1681', 'Hombre', 1, 0, '<p>Halloween Man Rock On de Jesús del Pozo, lanzado en 2014, es una fragancia masculina que captura la energía y el espíritu rebelde del rock. Con una mezcla de notas frescas, especiadas y amaderadas, ofrece una experiencia olfativa audaz y moderna, ideal para hombres jóvenes y enérgicos</p>', NULL),
(12439, 'Armaf Club De Nuit Urban Man Elixir 100ml Hombre', '<p><strong>Familia olfativa: </strong>Aromática - Amaderada - Especiada</p><ul><li><strong>Notas de salida:</strong></li></ul><p>Bergamota</p><p>Pimienta rosa</p><p>Jazmín</p><p>Flor de azahar</p><ul><li><strong>Notas de corazón:</strong></li></ul><p>Lavanda</p><p>Geranio</p><p>Azafrán</p><p>Elemi</p><ul><li><strong> Notas de fondo:</strong></li></ul><p>Ambroxan</p><p>Pachulí</p><p>Vetiver</p><p>Madera de cedro</p><p>Ládano</p>', 30500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-304e-734a-b722-d1d8e81f7906.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01996886-75b1-7138-af00-4c6971691402.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Urban Man Elixir es una fragancia masculina intensa y moderna que combina notas cítricas frescas con un corazón especiado y una base amaderada y almizclada. Está diseñada para hombres seguros y urbanos que buscan un aroma sofisticado y duradero, ideal para la noche y ocasiones especiales. Su perfil olfativo ofrece energía, elegancia y presencia.</p>', NULL),
(12440, 'Armaf Odyssey Aoud EDP 100ml Hombre', '<p>Notas de salida:</p><p>Pimienta negra</p><p>Bergamota</p><p>Notas verdes Notas de corazón:</p><p>Cedro</p><p>Lavanda</p><p>Salvia</p><p> Notas de fondo:</p><p>Oud</p><p>Pachulí</p><p>Vetiver</p><p>Ámbar</p><p>Esta fragancia combina la frescura especiada con un corazón amaderado y una base profunda de oud, ideal para destacar en ocasiones formales y nocturnas con un aroma elegante y sofisticado.</p>', 24500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-2859-7196-b963-5ebe9660e856.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aaddf-6f39-722f-bea9-c9e979fd0b12.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Aoud es una fragancia masculina intensa y sofisticada que combina la riqueza del oud con notas especiadas y amaderadas. Esta esencia ofrece un aroma profundo y envolvente, ideal para hombres que buscan un perfume elegante y con presencia duradera. Perfecto para la noche y ocasiones especiales, destaca por su carácter oriental y moderno.</p>', NULL),
(12441, 'Lattafa Fakhar 100ml EDP Hombre', '<p><strong>Notas de salida:</strong> Manzana, Bergamota, Jengibr</p><p><strong>Notas de corazón:</strong> Lavanda, Salvia, Bayas de Enebro, Geranio</p><p><strong>Notas de fondo:</strong> Haba Tonka, Ámbar, Cedro, Vetiver</p>', 25000, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-2398-70d2-8e15-e8e98605946c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01991077-e88b-76ff-a4b2-0a87fee675a6.png?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Fakhar es una fragancia masculina que destaca por su perfil aromático y amaderado, ideal para quienes buscan una esencia fresca, elegante y versátil. Con una combinación de notas frutales, herbales y amaderadas, es adecuada para uso diario y ocasiones especiales.</p>', NULL),
(12442, 'Tommy Hilfiger NOW GIRL EDT 100ml', '<p>Salida: Bergamota, mandarina y cassis.</p><p>Corazón: Magnolia, menta y mahonia.</p><p>Fondo: Cachemira y almizcle.</p>', 32000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-2107-754b-9107-dc9e6d7377da.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc5e-094d-70aa-a9ca-994ac7eb232a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y vibrante que captura la energía del momento. Con una mezcla de notas cítricas y florales, es ideal para mujeres modernas que buscan una esencia ligera y dinámica.</p>', NULL),
(12443, 'Giorgio Armani Stronger With You EDT 100ml Hombre', '<p>Notas de salida: Cardamomo, hoja de violeta y pimienta rosa.</p><p>Notas de corazón: Piña, melón y salvia.</p><p>Notas de fondo: Cachemira, castaña, cedro y vainilla</p>', 52000, 3, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-1b65-775c-99cb-c7c8c3c3a015.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d088-442a-76af-b74a-d76a7ea41dfb.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Emporio Armani Stronger With You es una fragancia masculina lanzada en 2017, creada por la perfumista Cecile Matton. Esta Eau de Toilette pertenece a la familia olfativa Aromática Fougère y está diseñada para hombres modernos, seguros de sí mismos y con una personalidad magnética. La fragancia simboliza una conexión profunda y auténtica, destacando por su calidez y elegancia.</p>', NULL),
(12444, 'CUBA VICTORY WOMAN', 'Notas de salida: Flor de jengibre, jazmín de agua, mandarina verde.\nNota de corazón: Vainilla.\nNotas de fondo: Sándalo, cachemira, ámbar gris', 5800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-2452-765f-bcc5-acd16b6fd20f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-8dfc-70f9-b482-ed7e8851577a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-efc5-74db-aa21-ce37497583d1.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia dulce, floral y ligeramente especiada, inspirada en perfumes icónicos como Olympea de Paco Rabanne. Ideal para mujeres modernas que buscan una esencia femenina y elegante', NULL),
(12445, 'Ariana Grande Thank U Next 100ml EDP Mujer', '<p>Salida: frambuesa y pera blanca, aportando una apertura jugosa y fresca.</p><p>Corazón: coco cremoso y pétalos de rosa rosa, ofreciendo una sensación suave y femenina.</p><p>Fondo: macaron dulce y almizcle, brindando una base cálida y reconfortante</p>', 38000, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-1469-73bd-9159-98fc32babf7a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6160-ee4a-70cd-90e6-6256cea51dc4.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Ariana Grande Thank U, Next EDP para Mujer es una fragancia femenina lanzada en 2019, inspirada en el crecimiento personal y la superación. Su composición combina notas dulces y afrutadas con un toque cremoso y floral, reflejando una actitud positiva y moderna</p>', NULL),
(12446, 'Lattafa Mayar  EDP 100ml Mujer', '<p>Notas de salida: lichi, frambuesa, hojas de violeta </p><p>Notas de corazón: peonía, jazmín y rosa blanca </p><p>Notas de fondo: vainilla y almizcle</p>', 22000, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-1181-722f-9b5a-2020c5831450.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993a9e-17e0-77ef-88cd-f9498aa3e028.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Dulce, jugoso y femenino: explota al principio con frutas ácidas, evoluciona a un corazón floral suave y remata en una base cálida de vainilla y almizcle súper ligera.</p>', NULL),
(12447, 'Lattafa Mayar Natural Intense 100ml EDP Women', '<p>Salida tropical: la combinación de higo, melón y mandarina verde crea una sensación de bebida fresca, realzada por el agua de coco. </p><p>Corazón acuático refinado: notas florales suaves y ligeramente jabonosas, con loto, nenúfar y jazmín, aportan una sensación impecable y femenina. </p><p>Secado cálido y cremoso: la base mezcla almizcle con ambroxan, vainilla y sándalo, ofreciendo una estela acogedora y cremosa.</p>', 26000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-0f2f-745d-ba31-cfbbd0f24792.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-d091-722d-939f-cb8c063c693f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-f6ef-74b4-ae2c-906b3318e258.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>*Lattafa Mayar Natural Intense* Fresco y tropical con un inicio jugoso, un corazón acuático floral y un secado cremoso y envolvente.</p>', NULL),
(12448, 'BODY PINK WARM & COZZY', 'Vainilla suave: aportando dulzura sin ser empalagosa.\nCoco tostado: añadiendo una sensación cálida y cremosa.\nMaracuyá : brindando un toque afrutado y ligeramente ácido.', 11800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-0ab8-7089-bede-7b1bc299ef2f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-eda6-7331-8451-238bd5c2ecbd.jpeg?storeId=1681', NULL, 1, 0, 'Si buscas una fragancia dulce, cálida y reconfortante para el uso diario, el Warm & Cozy Body Mist es una excelente opción. Su aroma suave lo hace adecuado para cualquier ocasión, y su precio accesible lo convierte en una opción atractiva para quienes desean una fragancia agradable sin gastar mucho.', NULL),
(12449, 'Billie Eillish Eillish EDP 100ml Mujer', '<p>Salida: frutos rojos azucarados y mandarina — fresca y chispeante .</p><p>Corazón: vainilla bourbon cremosa, cacao y especias suaves — envolventes y ricas </p><p>Fondo: almizcles cálidos, maderas suaves y tonka — añaden sensualidad y profundidad</p>', 41500, 1, 'Billie Eillish ', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-0768-77bb-8e38-ce972b092a28.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019af580-14fa-77ef-9979-c66b350d421c.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Eilish es una fragancia gourmand elegante y accesible que combina dulzura afrutada y rica con un acabado sofisticado. Perfecta para quienes desean un aroma cálido y moderno con excelente rendimiento. Si te interesa explorar perfumes similares con matices orientales o variantes más frescas, dime y con gusto te recomiendo.</p>', NULL),
(12450, 'Paris Hilton JUST ME EDP 100ml Mujer', '<p>Salida: Pimienta rosa, frambuesa jugosa, violeta empolvada y bergamota cítrica </p><p>Corazón: Rosa blanca, fresia, iris, lirio de los valles y ylang‑ylang florido </p><p>Fondo: Sándalo cremoso, almizcle suave, vainilla de Tahití y maderas claras</p>', 23800, 2, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-055e-7159-a158-c904bfa13868.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5635-9493-70d0-a3da-fb3d595c4dfc.png?storeId=1681', 'Mujer', 1, 0, '<p>Just Me es una fragancia floral‑frutal elegante y femenina, creada por Steve DeMercado en 2005. Se abre con una chispa juguetona y juvenil, pero evoluciona hacia un corazón elegante y un fondo suave que deja una estela acogedora.</p>', NULL),
(12451, 'Body Mist Paris Hilton Can Can Burlesque 8.0 Mujer', '<p>Notas de salida: Clementina, frambuesa, nectarina y grosella negra (cassis).</p><p>Notas de corazón: Orquídea salvaje, flor de azahar (orange blossom) y clementina.</p><p>Notas de fondo: Ámbar, almizcle y maderas.</p>', 7800, 5, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607b-046c-702a-a155-1a1ff3b7cedf.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-9b56-7475-aad4-00bc6cedd656.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-6143-775c-8802-7ed7efb156e9.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Paris Hilton Can Can Burlesque 8.0 oz es una fragancia femenina fresca y moderna, inspirada en el glamour del Moulin Rouge. Lanzada en 2014, esta bruma corporal combina notas frutales y florales, ofreciendo una experiencia sensorial ligera y seductora.</p>', NULL),
(12452, 'Armaf Club De Nuit 100ml EDP Mujer', '<p><strong> Notas de salida:</strong></p><p>Toronja (pomelo)</p><p>Naranja</p><p>Durazno</p><p>Bergamota</p><p> <strong>Notas de corazón:</strong></p><p>Rosa</p><p>Jazmín</p><p>Lichi</p><p>Geranio</p><p><strong> Notas de fondo:</strong></p><p>Pachulí</p><p>Vainilla</p><p>Almizcle</p><p>Vetiver</p><p><br></p><p>Esta fragancia es dulce, floral y con un toque elegante de frutas, ideal para mujeres que buscan un perfume versátil con una excelente proyección y duración</p>', 22500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-fde7-71a3-9194-975a929966eb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ec3-0afb-73fa-b6a8-06d979700a96.png?storeId=1681', 'Mujer', 1, 0, '<p>Armaf Club de Nuit Woman es una fragancia femenina elegante, floral y afrutada, pensada para mujeres sofisticadas y seguras. Su aroma combina notas frescas y dulces con un corazón floral clásico y una base cálida y ambarada. Es perfecta para el día o la noche, y se destaca por su feminidad envolvente y su estilo atemporal.</p>', NULL),
(12453, 'BODY BRITNEY SPEARS CORIOUS', 'Aroma: conserva el ADN de Curious EDP, mezclando notas frutales como pera y pomelo con toques florales suaves y una base cremosa de vainilla y ámbar.\nExperiencia sensorial: se absorbe rápidamente, dejando la piel hidratada, suave y ligeramente perfumada', 9000, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-fae3-75e8-9dc9-df11702fb8b1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-04d5-742d-82e1-c3b66284aaa8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-c310-7498-8351-6f084b68ed24.jpeg?storeId=1681', NULL, 1, 0, 'Un excelente complemento para quien disfruta de Curious y quiere mantener su aroma durante más tiempo. Perfecto para pieles normales que buscan hidratación ligera y una estela suave y deliciosa.', NULL),
(12454, 'Ariana Grande Cloud 2.0 Intense 3.4 EDP Sp Women', '<p>Salida: fresca y afrutada con un trío luminoso de lavanda, bergamo</p><p>Corazón: gourmand: crema de coco, praliné, vainilla orquídea y crema batida, creando un bouquet dulce y cremoso </p><p>Fondo: más sofisticado que la versión original, con cashmeran, ambroxan, musks y maderas claras que aportan calidez, profundidad y una textura suave</p>', 40500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-f7fd-72da-8079-70d2559b0a8b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-ec94-71f2-862e-9aec124db400.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-e614-71c6-992c-af987e2dedb9.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Cloud 2.0 Intense es una fragancia gourmand moderna: inicia luminosa y afrutada, evoluciona a un corazón dulce-cremoso, y termina con un fondo cálido y amaderado. Es una opción perfecta si te gustó Cloud pero quieres más riqueza olfativa, mayor rendimiento y una estela más refinada. Especialmente recomendada para otoño/invierno, noches y ocasiones donde un aroma placentero y envolvente marca la diferencia.</p>', NULL),
(12455, 'Lacoste L.12.12 Blanco 100ml EDT Hombre', '<p>Salida: toronja (pomelo), limón verde (finger lime), cardamomo, romero, hojas de cedro </p><p>Corazón: ylang-ylang, tuberosa (y olíbano/incienso leve) </p><p>Fondo: cedro, vetiver, gamuza/leather suave, georgywood</p>', 39800, 5, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc98-f1c9-703e-b60c-0ea2a3cd5e10.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6b95-514c-723d-ae87-ab4d79af0ab4.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fresco, limpio y elegante: un aroma cítrico-verde con un corazón floral suave y un secado amaderado-sutil, perfecto para uso diario en primavera y verano.</p>', NULL),
(12456, 'BODY SPRAY LATTAFA MAYAR', 'Notas de salida: lichí, frambuesa y hojas de violeta (frutal, fresco y verde)\nNotas de corazón: jazmín, peonía y rosa blanca (floral, elegante y femenina)\nNotas de fondo: almizcle blanco y vainilla (suave, dulce y cremosa)', 5000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-ec14-77cc-88bd-1fcde628707b.jpeg?storeId=1681', NULL, 1, 0, 'Lattafa Mayar Body Spray para mujer es una fragancia frutal‑floral jugosa y femenina que despierta los sentidos. Su salida brillante mezcla lichi y frambuesa con un toque verde de hojas de violeta, seguido por un corazón elegante de jazmín, peonía y rosa blanca, y rematado por una base suave de almizcle y vainilla. Ideal para primavera y verano, es fresca, dulce y perfecta para el día a día.', NULL),
(12457, 'Kids Cars 100ml EDT Niño', '<p>Salida : cítricos frescos como toronja, mandarina o maracuyá, con toques de hierba de limón.</p><p>Corazón ): notas suaves afrutadas o florales muy ligeras (frutitas o flor de azahar).</p><p>Fondo : toques de madera ligera y almizcle, cerrando con calidez y sencillez .</p>', 7500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e3c5-eeaa-770d-a981-304a67bd90c8.png?storeId=1681', 'Niños', 1, 0, '<p>Eau de Toilette infantil de 100 ml con temática de Cars. Viene en frasco decorado con el icónico Rayo McQueen y caja alusiva, lo que lo convierte en un producto divertido y emocionante para los niños; fomenta la rutina de higiene con una fragancia fresca y agradable</p>', NULL),
(12458, 'Bharara King 200ml EDP Hombre', '<p>Notas de salida: Naranja, bergamota y limón.</p><p>Nota de corazón: Tutti frutti.</p><p>Notas de fondo: Almizcle blanco, ámbar y vainilla.</p>', 49500, 5, 'Bharara', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-e8d5-75ad-8db5-882fc890cffc.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Bharara King Eau de Parfum (6.7 oz / 200 ml) es una fragancia masculina lanzada en 2021 por la marca Bharara. Esta versión de 200 ml ofrece una excelente relación calidad-precio, ideal para quienes buscan una fragancia duradera y versátil.</p>', NULL),
(12459, 'Armaf Odyssey Candee 100ml EDP Women', '<ul><li><strong>Notas de Salida:</strong></li></ul><p>Fresa</p><p>Frambuesa</p><p>Durazno </p><p>Bergamota</p><p>Geranio </p><ul><li><strong>Notas de Corazón</strong></li></ul><p>Caramelo</p><p>Jazmín</p><p>Maracuyá </p><ul><li><strong> Notas de Fondo</strong></li></ul><p>Almizcle</p><p>Pachulí</p><p>Ámbar</p>', 24500, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-e3da-76e8-98a4-a6d9f37d36f7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eb2-bdda-7309-9ab5-953ccd7b347c.png?storeId=1681', 'Mujer', 1, 0, '<p>Un aroma dulce y alegre, sin caer en lo empalagoso extremo. <strong>Odyssey Candee </strong>atrae la mezcla de frutas jugosas y toques gourmand (caramelo + maracuyá). Llamativo y femenino para el día o noche en climas cálidos</p>', NULL),
(12460, 'Chanel Coco Mademoiselle EDP 100ml Mujer', '<p>Notas de salida: naranja, mandarina, bergamota y flor de azahar del naranjo.</p><p>Notas de corazón: rosa turca, jazmín, mimosa y ylang-ylang.</p><p>Notas de fondo: pachulí, almizcle blanco, vainilla, vetiver, haba tonka y opopónaco.</p>', 109500, 0, 'Chanel', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-e0db-76dc-9e24-2db297bfb325.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199b05f-f188-71e7-bd0f-9902be432bec.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Chanel Coco Mademoiselle es una fragancia femenina lanzada en 2001, creada por el perfumista Jacques Polge. Pertenece a la familia olfativa oriental floral y se caracteriza por su elegancia moderna y sofisticada.</p>', NULL),
(12461, 'Body Mist Ariana Grande ARI', '<p>Familia olfativa: frutal - floral gourmand, suave y alegre </p><p>Salida: pera crujiente, frambuesa y pomelo rosado — fresca, chispeante y jugosa</p><p>Corazón: orquídea de vainilla, lirio de los valles y capullos de rosa — floral cremoso y femenino</p><p>Base: malvavisco dulce, maderas claras y almizcle — suave, reconfortante y acogedor</p>', 9000, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986ca9-3266-74c8-a5d3-26ba78ebb319.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Ari Body Mist es una opción excelente si quieres disfrutar del aroma de Ariana Grande Ari en un formato ligero, práctico y fácil de aplicar durante el día. Ofrece un aura frutal-floral dulce, versátil para refuerzos rápidos y sensaciones frescas sin voluntad de imposición.</p>', NULL),
(12462, 'Chanel Allure Homme Sport 100ml EDT Hombre', '<p>Notas de salida: mandarina roja, naranja, aldehídos y notas marinas.</p><p>Notas de corazón: pimienta, nerolí y cedro.</p><p>Notas de fondo: haba tonka, vainilla, almizcle blanco, ámbar, vetiver y resina de elemí.</p>', 94000, 0, 'Chanel', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-d921-75c4-882b-757d414d67dc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019921d1-4e86-779d-b082-55aae7cefbfa.png?storeId=1681', 'Hombre', 1, 0, '<p>Chanel Allure Homme Sport es una fragancia masculina lanzada en 2004, creada por el perfumista Jacques Polge. Pertenece a la familia olfativa amaderada especiada y está diseñada para evocar frescura, energía y sofisticación.</p>', NULL),
(12463, 'BODY SPRAY MAHAAR LEGACY', 'Salida: Lima, menta, pomelo, lavanda y piña — frescas, cítricas y vivas \nCorazón: Enebro, pimienta negra, romero, geranio e incienso — especiado, herbal y sofisticado \nFondo: Ambroxan, vetiver, musgo de roble, haba tonka y cashmeran — amaderado, ambarado y ligeramente cremoso', 5000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-cf2b-7428-af05-7a0a5e32dffd.jpeg?storeId=1681', NULL, 1, 0, 'Lattafa Maahir Legacy es una fragancia aromática-especiada fresca con similitudes al Parfums de Marly Sedley — destaca por su salida cítrica y herbal, y un fondo ambarado-sutil. Ofrece buen rendimiento por su precio (~USD 20–30), aunque sufre de cierta inconsistencia lote a lote y puede sentirse sintética al principio.', NULL),
(12464, 'Giorgio Armani Acqua Di Gio PARFUM 125ml Hombre', '<p>Salida: Bergamota, mandarina verde y acordes marinos </p><p>Corazón: Geranio, salvia esclarea y romero </p><p>Fondo: Incienso, pachulí, vetiver y maderas cálidas</p>', 79500, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-d0f1-7590-b650-590fab275f39.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4ac0-f6ad-716c-b4df-d183b2835681.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Acqua di Giò Parfum fue relanzada en 2023 como una versión moderna de la emblemática Acqua di Giò Profumo (2015), con una fórmula refinada que acentúa la frescura marina y añade profundidad gracias al incienso. Es una fragancia masculina fino-olímpica, elegante y sofisticada, que equilibra lo limpio con lo amaderado.</p>', NULL),
(12465, 'Lattafa YARA 50ml Mujer', '<p>Salida: orquídea, heliotropo, mandarina tangerina </p><p>Corazón: acorde gourmand y frutas tropicales </p><p>Fondo: vainilla, sándalo y almizcle</p>', 13000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-d31a-77bd-bff5-bebee09a9805.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5801-cc86-70fe-882a-2e0366354b2e.png?storeId=1681', 'Mujer', 1, 0, '<p>Dulce y sofisticado: una mezcla cremosa y afrutada con toque almizclado, ideal para uso diario con un aire femenino y moderno.</p>', NULL),
(12466, 'Liz Claiborne Curve Chill 125ml EDT Hombre', '<p>Salida: Aldeídos, lima (limón verde), bergamota</p><p>Corazón: Violeta, té verde, pimienta blanca, cilantro</p><p>Fondo: Sándalo, cardamomo, almizcle, vetiver</p>', 14500, 8, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a8c-bb37-73fc-bbdf-e95b282bef80.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a8c-b928-70ca-b579-440c2e343947.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Liz Claiborne Curve Chill es una fragancia masculina fresca y ligera, ideal para el uso diario en climas cálidos. Su combinación de notas cítricas, florales y amaderadas ofrece una experiencia olfativa equilibrada y energizante.</p>', NULL),
(12467, 'Body Mist Perry Ellis Reserve', '<p>Salida: jengibre fresco y manzanilla suave, con un toque herbal de salvia y camomila que aporta limpieza inmediata </p><p>Corazón: flores delicadas como fresia, violeta, loto, caléndula y rosa que ofrecen un bouquet floral refinado y reconfortante </p><p>Fondo: notas cálidas de sándalo, musgo de roble y pachulí que aportan profundidad y un acabado suave y terroso</p>', 8500, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-c761-756d-9858-55b88a6ddc33.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-c954-7578-82af-4f3c30db3b62.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-4a22-75f7-b11d-b146dfc100c1.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Perry Ellis Reserve Body Mist es una excelente opción si buscas una fragancia fresca y floral, con un toque limpio y terroso, en un formato cómodo y económico. Perfecto para personas que prefieren aromas suaves, fáciles de llevar y discretos, especialmente en primavera o verano.</p>', NULL),
(12468, 'Paco Rabanne Invictus Victory Elixir 100ml Hombre', '<p>Salida: lavanda, cardamomo, pimienta negra — fresca, aromática y picante </p><p>Corazón: incienso, pachulí — profundo, resinoso y masculino </p><p>Fondo: vainilla, haba tonka — dulce, cremosa y adictiva</p>', 58500, 2, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972aa-3b6b-71be-a642-0cc1d73e3412.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972aa-38e3-730c-9a5c-e591c4fa71da.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Invictus Victory Elixir (2023) es la expresión más intensa y seductora de la línea Invictus. Es un parfum intense que mezcla frescura especiada con un fondo ultra sensual ambarado‑avainillado, pensado para destacar en la noche o climas fríos, evocando triunfo y elegancia masculina</p>', NULL),
(12469, 'Rasasi Hawas Ice EDP 100ML Hombre', '<p>Manzana verde “helada”</p><p>Limón italiano luminoso</p><p>Bergamota siciliana chispeante</p><p>Toque especiado de anís estrellado</p>', 34000, 0, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-c036-7677-aaf6-517a87079c64.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993aa0-8785-7348-9099-7f3b3ca74dd6.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia energética, fresca y versátil, que combina jugosa fruta y cítricos helados con un trasfondo amaderado-amazónico. Pensada para hombres que buscan un aroma afrutado-limpio con excelente rendimiento a precio competitivo.</p>', NULL),
(12470, 'Elizabeth  Arden  Green  Tea  EDP 100ml Mujer', '<p>Notas de salida: Limón (lima ácida), bergamota, menta, cáscara de naranja y ruibarbo.</p><p>Notas de corazón: Jazmín, musgo de roble, hinojo, almizcle, clavel y ámbar blanco.</p><p>Notas de fondo: Té verde, jazmín, musgo de roble, almizcle, semillas de apio, alcaravea, clavos de olor y ámbar.</p>', 17800, 1, 'Elizabeth Arden', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-bb4d-74dc-bd4f-28e3a8675aea.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b1386-2b66-76bc-b162-8975897af0cf.png?storeId=1681', 'Mujer', 1, 0, '<p>Green Tea de Elizabeth Arden es una fragancia femenina lanzada en 1999, creada por el perfumista Francis Kurkdjian. Esta fragancia pertenece a la familia olfativa cítrica aromática y está diseñada para evocar sensaciones de frescura, energía y bienestar. Es ideal para el uso diario, especialmente en climas cálidos y durante las estaciones de primavera y verano</p>', NULL),
(12471, 'Kids Hot Wheels EDT 100ml', '<p>Salida: cítricos suaves (mandarina, pomelo), notas verdes (hierba de limón o trébol)</p><p>Corazón: afrutado ligero o floral juvenil</p><p>Fondo: almizcle blanco y un toque de maderas suaves</p>', 8500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-b875-724f-b98f-26dc7a83ee5c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-bc9e-725a-b282-b93a4cd61c76.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-7762-719f-8e2d-54767e3ef51c.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Un body splash o eau de toilette infantil de 100–240 ml, inspirado en Hot Wheels con frasco y etiqueta de carro blanco. Es una fragancia ligera y fresca diseñada para niños activos, que convierte la rutina en una experiencia divertida.</p>', NULL),
(12472, 'Christian Dior J’adore 3.4 EDT Sp Women', 'Pera, melón, magnolia, durazno, mandarina y bergamota — apertura fresca, jugosa y solar. \nMelodía principal (Corazón): Jazmín sambac, lirio de los valles, nardos, fresia, rosa, orquídea, ciruela y violeta — florales vibrantes y elegantes. \nRitmo final (Fondo): Almizcle, vainilla, cedro y mora — base suave, cremosa y redondeada.', 72500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-b8b8-75f2-8913-3693667d9b04.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-92c5-770a-a568-e9e5bbb14749.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-7616-7405-932d-31fb2275031c.png?storeId=1681', NULL, 1, 0, 'Una refinada fragancia floral frutal lanzada en 1999 por Calice Becker. Es alegre, luminosa y moderna, ideal para uso diario elegante y sofisticado.', NULL),
(12473, 'Maison Alhambra Delilah 100ml EDP Mujer', '<p><strong>Notas de salida</strong>: ruibarbo, lichi y bergamota </p><p><strong>Notas de corazón</strong>: rosa turca, peonía y azucena (o lirio, según versiones) </p><p><strong>Notas de fondo</strong>: almizcle blanco, vainilla y cachemira (cashmeran) </p>', 27000, 1, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019ae119-5fbe-70d5-a971-d0f214850396.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019ae119-6103-761c-858b-46823d6ea493.png?storeId=1681', 'Mujer', 1, 0, '<p>Delilah es una fragancia femenina sofisticada y moderna, con un aura floral frutal cautivadora. Comienza con un toque chispeante de ruibarbo y lichi, evoluciona hacia un ramo floral suave de rosa y peonía, y se asienta sobre una base cremosa y almizclada de vainilla, almizcle blanco y cachemira. Una opción elegante y versátil para el día a día y ocasiones especiales.</p>', NULL),
(12474, 'Dolce & Gabbana Q 100ml EDP Mujer', '<p>Notas de salida: Bergamota, Mandarina, Litchi</p><p>(Cítricos frescos y frutales que aportan luminosidad y energía)</p><p>Notas de corazón: Rosa, Jazmín, Magnolia</p><p>(Notas florales que aportan feminidad y elegancia)</p><p>Notas de fondo: Pachulí, Almizcle, Vainilla</p><p>(Base cálida, amaderada y ligeramente dulce que brinda profundidad y sensualidad)</p>', 46500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-aa4d-7121-93dd-74b138337bb3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cca0-12c6-7220-8895-4126c987c8d3.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>La fragancia Q 3.3 de Dolce &amp; Gabbana para mujer es una creación elegante y sofisticada, diseñada para una mujer moderna que busca un aroma femenino, sensual y distintivo. Esta fragancia de tipo Eau de Parfum ofrece una mayor intensidad y duración, ideal para quienes prefieren un perfume con carácter para la noche o eventos especiales.</p>', NULL),
(12475, 'Chacarel ANAIS ANAIS EDT 100ml Mujer', '<p>Salida: jacinto, flor de azahar, madreselva, bergamota y gálbano </p><p>Corazón: rosa, lirio blanco, jazmín, ylang-ylang, clavel, tuberosa y lirio de los valles </p><p>Fondo: sándalo, incienso, vetiver, cedro, musgo de roble y almizcle</p>', 27500, 1, 'Chacarel', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-a63d-739e-8c41-c6a8259f03af.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4ad0-14d7-72ef-af7a-367006389a26.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Cacharel Anaïs Anaïs es un clásico de 1978, relanzado en 2014 como “L’Original”. Representa la pureza y feminidad a través de un bouquet floral romántico y algo empolvado.</p>', NULL),
(12476, 'Lattafa Yara Moi 100ml EDP Mujer', '<p>Salida: Jazmín, melocotón</p><p>Corazón: Caramelo, ámbar</p><p>Fondo: Pachulí, sándalo</p>', 20000, 3, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-9f32-728d-bb25-9d00cb44da95.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a57fe-4b5e-7598-a06a-e40577c517bd.png?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Yara Moi es una fragancia femenina que combina la frescura del jazmín y el melocotón con la dulzura del caramelo y la calidez del ámbar, sobre una base de pachulí y sándalo. Su aroma elegante y sofisticado la convierte en una opción ideal para ocasiones especiales.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12477, 'Jennifer Lopez LIVE EDP 100ml Mujer', '<p>Notas de salida: Piña, toronja (pomelo), naranja.</p><p>Notas de corazón: Cereza roja, peonía, violeta.</p><p>Notas de fondo: Caramelo, sándalo, haba tonka, vainilla, almizcle.</p>', 22000, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-9630-70f9-84b0-f6a84a9152ee.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019ac09e-c7b4-765c-abd9-b1fabfc72f3b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019ac09e-caed-7450-8d69-4ece91bed114.png?storeId=1681', 'Mujer', 1, 0, '<p>Jennifer Lopez Live es una fragancia femenina lanzada en 2005, destacada por su perfil tropical, afrutado y ligeramente dulce. Esta fragancia ha sido bien recibida por su frescura y versatilidad, siendo adecuada para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12478, 'Perry Ellis 360 Blanca EDT 100ml Hombre', '<p>Notas de salida: Lima (limón verde), cardamomo y bergamota.</p><p>Notas de corazón: Flor de azahar del naranjo, lirio de los valles (muguete) y raíz de lirio.</p><p>Notas de fondo: Vainilla, haba tonka, almizcle blanco y cedro</p>', 24500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-494d-70d0-962e-c45a748456f7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-bbab-7283-87fc-2eb1a6ce9b3e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31b-4821-72a6-a8a6-b3d42f3b9c59.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>El Perry Ellis 360° White for Men es una fragancia masculina lanzada en 2005, reconocida por su perfil fresco, limpio y ligeramente dulce. Ideal para el uso diario, especialmente en climas cálidos, ofrece una experiencia olfativa equilibrada y sofisticada</p>', NULL),
(12479, 'Hugo Boss The Scent 100ml EDP Mujer', '<p>Salida: Melocotón y fresia — una apertura dulce, afrutada y fresca </p><p>Corazón: Osmanthus (flor con aroma a albaricoque/apricot) y azahar — aporta sofisticación floral, suave y elegante .</p><p>Fondo: Cacao tostado (cocoa), a veces con matices de vainilla — añade un toque gourmand cálido y sensual</p>', 49500, 0, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-44ac-7150-87b4-1fd8e30401ab.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-ca1a-779b-b23b-368c3c55c6a8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-79ba-72c7-966d-1976d0e91c28.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Boss The Scent For Her es una fragancia sensual y sofisticada lanzada en 2016. Con su mezcla de frutas jugosas, flores delicadas y fondo gourmand, está diseñada para transmitir elegancia femenina y magnetismo. Ideal para ocasiones especiales y citas nocturnas, también se puede disfrutar durante el día en otoño‑invierno</p>', NULL),
(12480, 'Perry Ellis 360 Clasico EDT 100ml Mujer', '<p>Notas de salida: Melón, mandarina, osmanthus y rosa azul.</p><p>Notas de corazón: Lirio de los valles, lirio de agua, lavanda y salvia.</p><p>Notas de fondo: Almizcle, sándalo, vetiver, ámbar y vainilla</p>', 25500, 2, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-4149-769c-bf12-5f257571aa21.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El Perry Ellis 360° Classic para Mujer es una fragancia floral fresca lanzada en 1992, diseñada por la perfumista Sophia Grojsman. Esta fragancia se caracteriza por su perfil limpio, ligero y versátil, ideal para el uso diario y especialmente adecuada para climas cálidos</p>', NULL),
(12481, 'Lattafa Amethyst 100ml EDP Unisex', '<p>Notas de salida: Pimienta rosa, Bergamota.</p><p>Notas de corazón: Rosa turca, Rosa de Bulgaria (Damascena), Jazmín.</p><p>Notas de fondo: Madera de oud, Ámbar, Vainilla</p>', 22000, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4ade-1fc6-702a-b200-57b69c3ecb00.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4ade-1fe6-70da-a2d5-a7624c25e11c.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Bade’e Al Oud Amethyst es una fragancia unisex que fusiona notas florales, especiadas y orientales. Con una apertura fresca y especiada, un corazón floral elegante y un fondo cálido y envolvente, es ideal para quienes buscan una esencia sofisticada y duradera</p>', NULL),
(12482, 'Lacoste Red EDT 125ml Hombre', '<p>Notas de salida: Manzana verde</p><p>Notas de corazón: Pino</p><p>Notas de fondo: Pachulí y vetiver</p>', 34500, 2, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cac-1d95-713f-8ff5-4a831e3ad682.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc88-9327-75c9-bcde-c9d4736d1ccc.png?storeId=1681', 'Hombre', 1, 0, '<p>Lacoste Red es una fragancia masculina que destaca por su frescura y energía. La manzana verde en la salida aporta una sensación vibrante, mientras que el pino en el corazón añade un toque aromático. Las notas de fondo de pachulí y vetiver proporcionan una base amaderada y terrosa, creando un equilibrio perfecto para un aroma fresco y duradero</p>', NULL),
(12483, 'LATTAFA QAED AL FURSAN', 'Salida: piña dulce y azafrán \nCorazón: jazmín y abeto balsámico \nFondo: ámbar, cedro, oud (y a veces almizcle)', 28000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-3749-71c0-ad31-89eba6b42c72.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f4-f46b-719e-b322-01be2ec3d25f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-89b3-737e-9238-9f91bb61d2bf.jpeg?storeId=1681', NULL, 1, 0, 'Jugosa explosión de piña con un toque especiado, seguida por jazmín ambarado y una base cálida de madera y oud.', NULL),
(12484, 'Crema Victoria Secret Pure Seduction', '<p>Salida: jugosa ciruela roja (juiced plum) con un toque cítrico moderado </p><p>Corazón: fresia floral brillante (crushed freesia), con acentos de peonía en algunas versiones como la edición \"Sol\" </p><p>Fondo: suave sándalo cálido y vainilla cremosa, que aportan calidez y una estela dulce moderad</p>', 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-3478-71f3-b4c7-25cd82e8a5d5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-f5cd-729f-a6b4-bbc2249cd11c.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una loción irresistiblemente jugosa y seductora, con notas de ciruela roja y fresia brillante que envuelven la piel en un aroma dulce y femenino. Su fórmula ligera y de rápida absorción hidrata intensamente hasta por 24 horas, dejando la piel suave, perfumada y lista para enamorar.</p>', NULL),
(12485, 'Set Tommy Hilfiger Perfume + Crema Hombre', '<p>Notas de salida: Pomelo, menta y lavanda.</p><p>Notas de corazón: Romero, geranio y albahaca.</p><p>Notas de fondo: Cedro, ámbar y pachulí.</p>', 34000, 0, 'Tommy Hilfiger', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-3183-7520-bbe2-eaef229f5a62.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-77cf-76d8-b7f2-698c461ef876.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set fresco y enérgico que combina la fragancia icónica de Tommy Hilfiger con una crema corporal hidratante, perfecto para hombres modernos que buscan un aroma vibrante, limpio y casual para el día a día.</p>', NULL),
(12486, 'BODY VICTORIA SECRET CAYON FLORA', 'Salida: flor de cactus — fresca, verde y ligeramente exótica\nCorazón: jazmín y flores silvestres — un bouquet delicado y natural\nFondo: almizcle floral — suave y reconfortante, con toques etéreos y empolvados', 11800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-2e0e-74ad-975d-c438d39e6b19.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a02-a571-70bc-a577-1587d7fd5108.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-3217-746e-bb2d-b97a3645b5a3.jpeg?storeId=1681', NULL, 1, 0, 'Canyon Flora evoca la frescura crepitante y relajante de las flores del desierto y los pétalos silvestres impulsados por el viento, con un aire floral‑almizclado que trae serenidad y sofisticación.', NULL),
(12487, 'Clinique Happy 100ml Parfum Mujer', '<p>Ruby red grapefruit, mandarina, bergamota — pura explosión cítrica y chispeante. </p><p>Melodía principal (Corazón): Hawaiian wedding flower (plumeria/orchid), lily‑of‑the‑valley, freesia y rosa — flores frescas y alegres. </p><p>Ritmo final : Mimosa, magnolia, musk  y amber  base suave, limpia y reconfortante.</p>', 24800, 0, 'Clinique Happy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-28ee-76bc-9413-016b904e8ae6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199a608-df40-7690-96e8-3c62dc5ffb64.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y luminosa que transmite optimismo al instante. Une vibrantes toques cítricos con un corazón floral delicado sobre una base suave y limpia. Ideal para usar a diario y llenar tu día de energía positiva.</p>', NULL),
(12488, 'GIVENCHY POUR HOMME EDT 100ML', 'Salida: Mandarina, toronja, cilantro y violeta – aportan una frescura cítrica con un sutil toque verde especiado .\nCorazón: Vetiver y lavanda – ofrecen un perfil aromático, limpio y ligeramente terroso .\nFondo: Cedro y ládano – una base amaderada cálida que fija bien el aroma', 43800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-26f4-7623-8974-2872d438bb2f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-cd44-77ba-979e-259dd7130dec.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-fc02-700a-a5cd-cc277eebe952.jpeg?storeId=1681', NULL, 1, 0, 'Givenchy Pour Homme EDT se lanzó en 2002, obra de los perfumistas Alberto Morillas e Ilias Ermenidis . Se trata de una fragancia amaderada especiada, refinada y versátil, pensada para el hombre elegante que busca un aroma limpio pero con carácter.', NULL),
(12489, 'Lattafa Yara 100ml EDP Mujer', '<p>Salida: Orquídea, heliotropo, mandarina</p><p>Corazón: Notas golosas, frutas tropicales</p><p>Fondo: Vainilla, almizcle, sándalo</p>', 22000, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-231a-736a-9b7f-c24d1d43232c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5805-a416-74ca-815c-b8a8346212f1.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Yara es una fragancia femenina que combina notas frutales y florales con una base dulce y cremosa. Su apertura fresca y afrutada da paso a un corazón floral, mientras que su fondo suave y dulce le otorga una sensación envolvente y elegante.</p>', NULL),
(12490, 'Liz Claiborne Curve Connect 125ml EDT Hombre', '<p>Salida: Bergamota, pimienta negra</p><p>Corazón: Té negro, té mate</p><p>Fondo: Sándalo, cumarina, haba tonka</p>', 14500, 24, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-1e61-749e-b45e-231463b13ab5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-109d-75e9-8fa4-1004474e3504.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-3001-72ba-984c-a53deb68fff9.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Liz Claiborne Curve Connect es una fragancia masculina lanzada en 2008, que combina notas especiadas y amaderadas con un toque fresco y ligeramente afrutado. Su aroma versátil la convierte en una opción ideal para el uso diario en climas cálidos.</p>', NULL),
(12491, 'Tommy Hilfiger Tommy Girl 100ml EDT Mujer', '<p>Notas de salida: Grosella negra, camelia, mandarina y flor de manzano.</p><p>Notas de corazón: Madreselva, lirio, violeta, menta, pomelo, limón y rosa.</p><p>Notas de fondo: Magnolia, cuero, sándalo, jazmín y cedro.</p>', 27800, 3, 'Tommy Hilfiger', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-1b2d-727b-bf4b-a6ec511fa3da.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc5a-6685-71e8-927c-7d9016e7cc89.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y floral que captura la esencia de una joven moderna y enérgica. Con una combinación de notas florales y frutales, es ideal para el uso diario, ofreciendo una sensación de frescura y vitalidad.</p>', NULL),
(12492, 'Dolce & Gabbana K 100ml EDT Hombre', '<p>Notas de salida: Bergamota, Pomelo, Mandarina, Lavanda, Anís estrellado</p><p>(Cítricos frescos y aromáticos que aportan energía y vitalidad)</p><p>Notas de corazón: Salvia, Romero, Pimienta rosa</p><p>(Toques herbales y especiados que dan dinamismo y frescura)</p><p>Notas de fondo: Cedro, Vainilla, Almizcle, Incienso</p><p>(Base amaderada, cálida y suave que aporta profundidad y sensualidad)</p>', 42000, 1, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-1751-706a-844b-506b00affd75.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cca1-58ec-738b-8a4f-8b399c237159.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Dolce &amp; Gabbana K Eau de Toilette es una fragancia masculina fresca, vibrante y enérgica, diseñada para un hombre moderno, seguro de sí mismo y con un espíritu libre. Esta versión EDT es ligera y fresca, ideal para el día a día y para ambientes casuales o cálidos. Representa la conexión con la naturaleza y la fuerza del color azul, que simboliza nobleza, confianza y poder.</p>', NULL),
(12493, 'Giorgio Armani Acqua Di Gio EDT 100ml Mujer', '<p>Notas de salida: Peonía, piña, vodka con sabor a dulces de musk, violeta, durazno (melocotón), hoja de plátano y limón (lima ácida).</p><p>Notas de corazón: Azucena, fresia, jazmín, jacinto, ylang-ylang, lirio de los valles (muguete), rosa y calone.</p><p>Notas de fondo: Sándalo, ámbar, almizcle, cedro y styrax.</p>', 54500, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-1411-76ab-b2b7-d0a266187c2e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4ac3-a723-752d-ab1a-1213b7f99d85.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Acqua di Giò para mujer es una fragancia clásica lanzada en 1995 por Giorgio Armani. Creada por el perfumista Alberto Morillas, esta Eau de Toilette pertenece a la familia olfativa floral frutal. Está inspirada en la isla de Pantelleria, donde Armani pasa sus vacaciones, evocando sensaciones de libertad y bienestar. Es una fragancia fresca y suave, ideal para el uso diario y especialmente en climas cálidos</p>', NULL),
(12494, 'Set Jesus Del Pozo Halloween Man 125ml EDT 4PC', '<p>Notas de salida: Bergamota, limón y anís estrellado.</p><p>Notas de corazón: Canela, clavo y menta.</p><p>Notas de fondo: Cedro, pachulí y almizcle.</p>', 32800, 0, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-11f1-7137-b009-1324bd074708.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set audaz y misterioso que refleja la fuerza y la masculinidad, con una fragancia aromática y especiada, ideal para hombres que buscan un aroma intenso y sofisticado para la noche.</p>', NULL),
(12495, 'ROBERTO VERINO MELLOW EDT 90ML', 'Notas de salida: Pera, melocotón, bergamota y naranja.\nNotas de corazón: Rosa, jazmín y violeta.\nNotas de fondo: Sándalo, vainilla, almizcle blanco y ámbar', 16800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-0df7-758c-b933-251012d343a5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-15ad-720a-9d79-a74395d423fb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-6fa2-745f-8e16-01af3d8eff1e.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia floral, afrutada y almizclada, pensada para mujeres jóvenes que buscan un aroma dulce y alegre', NULL),
(12496, 'Disney MINNIE EDT 100ml Niña', '<p>Salida: naranja, limón, bergamota, durazno (algunos reportes también mencionan clavo) </p><p>Corazón: jazmín, rosa, clavel, flor blanca</p><p>Fondo: almizcle, sándalo, ámbar suave y vainilla ligera</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-2b43-7289-a002-06df94a381d7.png?storeId=1681', 'Niños', 1, 0, '<p>Un perfume encantador y alegre para niñas inspirado en Minnie. Lanzado originalmente en 1992 por Air‑Val International, está diseñado para ser divertido, suave y encantador</p>', NULL),
(12497, 'MAISON ALHAMBRA L´IMPRESSIO EDP 100ML', 'Salida: sandía, fresa (algunos también indican kiwi, ruibarbo y pimienta rosa) \nCorazón: rosa de Damasco, peonía rosa, cyclamen (violeta persa), magnolia, jazmín (según algunas versiones) \nFondo: ámbar ahumado, sándalo, almizcle y notas amaderadas', 21000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197607a-071e-747c-88e0-0ab199e4d270.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-d806-72c2-a4df-4bf36c596e83.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-d64d-7729-96a0-79f720395e1e.jpeg?storeId=1681', NULL, 1, 0, 'L’Impressio III es una fragancia femenina inspirada en Dolce & Gabbana L’Imperatrice 3. Ofrece un aroma fresco, vibrante y afrutado, ideal para primavera y verano, con un perfil dulce-botánico y buen desempeño.', NULL),
(12498, 'Body Spray Armaf Odyssey Tryant 200ml', '<p>Salida: Toronja (pomelo) y notas cítricas, que aportan frescura y energía.</p><p>Corazón: Geranio, pimienta, resina de elemi y lavanda, creando una combinación especiada y floral que añade profundidad y carácter</p><p>Fondo: Ambroxan, cedro, vetiver y notas amaderadas, proporcionando una base cálida, elegante y duradera</p>', 5500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a8e-b4a5-722f-a3da-35d041e64b23.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Odyssey Tyrant inicia con una explosión fresca y energética de toronja y cítricos, seguida de un corazón especiado y floral que añade complejidad. Su base amaderada y terrosa le confiere una presencia duradera y sofisticada.</p>', NULL),
(12499, 'Victorinox Swiss Army Sport EDT 100ml Hombre', '<p>Notas de salida: manzana verde, yuzu, cilantro. </p><p>Notas de corazón: cedro (cedro blanco), romero, lavanda. </p><p>Notas de fondo: almizcle, ámbar blanco</p>', 19800, 1, 'Victorinox', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-fe12-775c-bb43-db75e4ec9fde.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cbf8-9bd7-753a-8c71-2d60bc423691.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia masculina en la familia aromática fougère. Su apertura fresca y afrutada (manzana verde y cítricos) evoluciona a un corazón aromático con notas herbales y amaderadas, terminando en una base limpia y almizclada con ámbar blanco. Ideal para un estilo de vida activo y aventurero, con duración y proyección moderadas.</p>', NULL),
(12500, 'Ralph Lauren Club PARFUM 100ml Hombre', '<p>Lavandin fresco – aporta limpieza y carácter herbal </p><p>Acorde frutal de manzana y pomelo – añade luminosidad y vigor</p><p>Cardamomo especiado – un toque picante que despierta los sentidos</p>', 58000, 1, 'Ralph Lauren', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-f9f3-755a-8866-68065ddaeaf5.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e364-857c-7675-a5ba-6a39a08d6b2c.png?storeId=1681', 'Hombre', 1, 0, '<p>Una reinterpretación elegante y sofisticada del icónico Ralph’s Club, esta versión Parfum intensifica su firma amaderada-ambarada con ingredientes de alta calidad, pensados para acompañar las noches más memorables con una estela cautivadora y moderna</p>', NULL),
(12501, 'Lattafa Honor& Glory 3.4 EDP Unisex', 'Notas de salida: Piña, crema bruleé\nNotas de corazón: Coco, vainilla\nNotas de fondo: Ámbar, madera', 25500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-f569-7599-834e-b68721285fd1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-b647-743f-8059-61adc2b15d5d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-8e3c-7701-bf8f-deabbe3f90d0.jpeg?storeId=1681', NULL, 1, 0, 'Lattafa Honor & Glory es una fragancia unisex de la casa árabe Lattafa, reconocida por sus perfumes inspirados en aromas internacionales. Lanzada en 2024, esta fragancia destaca por su combinación dulce y cremosa, con un toque afrutado y un fondo amaderado. Es ideal para quienes buscan una esencia única y envolvente.', NULL),
(12502, 'Emper Stallion 53 100ml EDP Unisex', '<p>Notas de salida: Bergamota, limón y pimienta rosa.</p><p>Notas de corazón: Lavanda, geranio y madera de cedro.</p><p>Notas de fondo: Ámbar, almizcle y vainilla.</p>', 19000, 2, 'Emper', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-f21c-718c-8a45-03ec4ca64676.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5817-0d49-72af-a3e6-4dd176bdfde7.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia unisex que equilibra fuerza y sofisticación, ideal para quienes buscan un aroma versátil, moderno y elegante que se adapta tanto a hombres como a mujeres.</p>', NULL),
(12503, 'Tous LoveMe The Silver 90ml Parfum Mujer', '<p>Salida: Mandarina, durazno, pera.</p><p>Corazón: Jazmín, rosa.</p><p>Fondo: Almizcle, sándalo.</p>', 39000, 2, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cb5-4a6a-70e9-9fc8-f535df129b03.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cb5-4ad1-72fb-9696-88f663d128f4.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral‑frutada elegante y luminosa con destellos almizclados y amaderados, evocando sofisticación moderna.</p>', NULL),
(12504, 'Calvin Klein One Shock 200ml Hombre', '<p>Notas de salida: lavanda, clementina y pepino.</p><p>Notas de corazón: osmanto (olivo oloroso), cardamomo, albahaca y pimienta.</p><p>Notas de fondo: almizcle, pachulí, ámbar, tabaco y notas amaderadas.</p>', 29500, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-ea77-73af-bee0-29418a2ddd6c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eca-3c4f-7730-8241-f8dd4d92d86f.png?storeId=1681', 'Hombre', 1, 0, '<p>Calvin Klein CK One Shock for Him es una fragancia masculina lanzada en 2011, perteneciente a la familia olfativa Oriental Especiada. Creada por Ann Gottlieb y IFF, esta colonia se caracteriza por su mezcla audaz y moderna, ideal para hombres que buscan una esencia distintiva y energética.</p>', NULL),
(12505, 'Carolina Herrera Good Girl Blush 80ml EDP Mujer', '<p>Salida: Bergamota y almendra amarga — inicio fresco y ligeramente dulce.</p><p>Corazón: Peonía y ylang-ylang — aportan un toque floral y exótico.</p><p>Fondo: Vainilla y cumarina — crean una base cálida y envolvente.</p>', 68500, 4, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199836b-308d-7669-b395-2bbb18add088.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199836b-3218-76a9-8483-b6455c3c0de6.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina floral chipre lanzada en 2023, creada por los perfumistas Quentin Bisch, Shyamala Maisondieu y Christophe Raynaud. Su aroma combina notas frescas y florales con una base cálida y dulce, evocando elegancia y feminidad.</p>', NULL),
(12506, 'Paris Hilton Platinum Rush EDP 100ml Mujer', '<p>Notas de salida:</p><p>Mango tropical</p><p>Pera asiática crujiente</p><p>Manzana roja jugosa</p>', 26000, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-e488-739e-b908-99bb4a471ef7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5637-362e-70fc-9ce6-a809e60f0ebf.png?storeId=1681', 'Mujer', 1, 0, '<p>Un perfume sofisticado y vibrante que encarna el brillo de un romance eterno. Inspirado en el simbolismo de un anillo de compromiso de platino, es una mezcla refinada de frutas frescas, flores verdes y una base profundamente cálida y acariciante</p>', NULL),
(12507, 'Cuba VIP Mujer', '<p>Notas de salida: Champagne Rosé, Té, Bergamota, Freesia, Rosa</p><p>Notas de corazón: Praliné, Café, Heliotropo, Bayas rojas, Orquídea</p><p>Notas de fondo: Caramelo, Benjuí, Iris, Sándalo, Almizcle, Pachulí</p>', 5800, 1, 'Cuba', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-dfc5-71b2-bcd1-06329a7751f2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-ed78-730e-9659-71f5fd983010.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-8c86-73e7-b00f-4ab2dbac042a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina de la familia olfativa Oriental Floral, lanzada en 2018 por Cuba Paris. Inspirada en perfumes icónicos como 212 VIP Rosé de Carolina Herrera, ofrece una experiencia dulce, floral y elegante a un precio accesible.</p>', NULL),
(12508, 'Set Ariana Grande Thank You Next 3PZAS', '<p>Notas de salida: Ruibarbo y pera.</p><p>Notas de corazón: Gardenia y jazmín sambac.</p><p>Notas de fondo: Almizcle cremoso y madera de cachemira.</p>', 46500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-db2a-7099-9e49-d95205d513e4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-9488-740b-8787-e4059d3202ea.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-27a3-708b-b049-d9b6f8e2d1c7.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set vibrante y fresco que refleja confianza y energía positiva, con una fragancia floral y afrutada, perfecta para quienes buscan un aroma juvenil, alegre y moderno.</p>', NULL),
(12509, 'Elsatys Gentle 100ml EDP Hombre', '<p>Notas de salida: Bergamota, pimienta.</p><p>Notas de corazón: Lavanda, tintura de tierra, notas acuosas, notas metálicas, carbón vegetal.</p><p>Notas de fondo: Pachulí, Ambroxan</p>', 19800, 0, 'Reyane Tradition', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-d558-75ac-bc14-ea4bf5d8b052.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198f183-8702-759a-94b7-78274420e1ef.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Gentle Elsatys es una fragancia masculina de la familia olfativa amaderada aromática, inspirada en el icónico Dior Sauvage. Esta fragancia destaca por su frescura cítrica y su base amaderada, ofreciendo una opción de alta calidad a un precio accesible. Es ideal para el uso diario, especialmente en climas cálidos y durante las estaciones de primavera y verano.</p>', NULL),
(12510, 'Set Versace Eros Flame 3pzas Hombre', '<p>Notas de salida: Bergamota, pimienta roja y naranja sanguina.</p><p>Notas de corazón: Cedro, geranio y rosa.</p><p>Notas de fondo: Vainilla, haba tonka y musgo de roble.</p>', 55500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-ce58-7168-bcf9-06f69056759d.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set intenso y apasionado que refleja el poder y la energía ardiente de Eros Flame, con una fragancia masculina vibrante, especiada y amaderada, acompañada de productos para prolongar su irresistible aroma.</p>', NULL),
(12511, 'Issey Miyake Pour Homme EDT 200ml Hombre', '<p>Salida: Yuzu, limón, bergamota, mandarina, ciprés, cilantro, estragón, salvia, verbena, calone (acorde marino) </p><p>Corazón: Loto azul, nuez moscada, lirio de los valles, azafrán, canela de Ceylán, geranio bourbon, reseda </p><p>Fondo: Vetiver de Tahití, almizcle, cedro, sándalo, tabaco, ámbar</p>', 48500, 1, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-c829-748d-bf7e-986eb8197b9c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01999794-27d4-74ab-8504-36ebfdcd1d5e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>L’Eau d’Issey Pour Homme, lanzada en 1994 por Issey Miyake y creada por Jacques Cavallier, es un clásico fresco de la perfumería masculina que evoca la pureza del agua. Con una mezcla de cítricos, especias leves y maderas suaves, es ideal para uso diario, especialmente en estaciones cálidas y climas templados</p>', NULL),
(12512, 'Calvin Klein Eternity EDT 200ml Hombre', '<p>Notas de salida: lavanda, mandarina, bergamota, limón</p><p>Notas de corazón: cilantro, azucena, flor de azahar del naranjo, bayas de enebro, albahaca, jazmín, salvia, lirio de los valles, geranio</p><p>Notas de fondo: sándalo, ámbar, almizcle, vetiver, palo de rosa de Brasil</p>', 38500, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-c284-7656-a425-a60695a550b9.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ecb-981a-7399-b230-48bef73eedca.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Calvin Klein Eternity EDT 200ml es una fragancia masculina clásica y atemporal, lanzada en 1990. Su perfil olfativo se caracteriza por una mezcla fresca y especiada, con notas de salida de lavanda, mandarina, bergamota y limón. En el corazón, se encuentran el cilantro, la azucena, la flor de azahar del naranjo, las bayas de enebro, la albahaca, el jazmín, la salvia, el lirio de los valles (muguete) y el geranio. Las notas de fondo incluyen el sándalo, el ámbar, el almizcle, el vetiver y el palo de rosa de Brasil. Esta combinación crea una fragancia equilibrada y versátil, adecuada para el uso diario y para diversas ocasion</p>', NULL),
(12513, 'Bvlgari Omnia Amethyste 100ml EDT Mujer', '<p>Salida: toronja rosa (pomelo rosa) y toques verdes que aportan frescura chispeante </p><p>Corazón: iris aterciopelado y rosa de Bulgaria; floral empolvado, elegante y femenino </p><p>Fondo: heliotropo (con un ligero matiz vainillado/almendrado) y maderas suaves, que brindan calidez y estabilidad</p>', 62800, 1, 'Bvlgari', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa821-c3e5-7321-a725-7d3c5ef74437.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa821-c4f1-7189-b474-6f9569d78234.png?storeId=1681', 'Mujer', 1, 0, '<p>Bvlgari Omnia Amethyste 3.4 EDT es una fragancia femenina fresca y elegante, inspirada en la delicadeza de la amatista. Combina notas florales empolvadas de iris y rosa con un toque cítrico de toronja y un fondo suave de maderas y heliotropo. Ideal para el uso diario en primavera o verano, transmite una sensación limpia, sofisticada y femenina.</p>', NULL),
(12514, 'Body Mist Paris Hilton Pink Rush 200ml Mujer', '<p>Notas de salida: Nashi (pera asiática), bergamota, goji berries y membrillo.</p><p>Notas de corazón: Hibisco, osmanthus, peonía rosa y rosa turca.</p><p>Notas de fondo: Vainilla, almizcle, madera de cachemira, ámbar y haba tonka</p>', 7800, 1, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-afe0-73f2-9474-6f3109dbba04.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-9e4d-764e-9174-a915d1e607e6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-9ec7-77d9-afa5-816ee93bda68.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Paris Hilton Pink Rush 8.0 oz es una fragancia femenina fresca y moderna, diseñada para reflejar la personalidad audaz y libre de París Hilton. Lanzada como parte de su línea de productos, esta bruma corporal combina notas frutales y florales, ofreciendo una experiencia sensorial ligera y seductora.</p>', NULL),
(12515, 'Body Mist Ariana Grande Thank You Next 2.0', '<p>Salida: manzana jugosa y crema de fresa silvestre — frutales y frescas.</p><p>Corazón: orquídea blanca exuberante y pétalos de jazmín — florales y delicadas.</p><p>Fondo: malvavisco batido, almizcle y sándalo — cálidos y reconfortantes.</p>', 9000, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-a4d4-7179-bf82-47865bb347cf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-1230-746e-acd5-feeeccb2cc20.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-52b6-7605-9ab0-6980f2df1cb5.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Thank U Next 2.0 Body Mist es una opción encantadora y accesible para quienes buscan un aroma dulce, afrutado y floral en un formato práctico y ligero. Ideal para quienes prefieren fragancias suaves y fáciles de llevar.</p>', NULL),
(12516, 'Body Mist VICTORIA SECRET Midnight Bloom', '<p>Salida: esencia de Moon Flower, con matices suaves y etéreos que aportan un aire nocturno y floral ligero. </p><p>Corazón: flores cremosas realzadas por una pincelada amaderada, otorgando calidez y elegancia.</p><p>Fondo: maderas cremosas y suaves, con una base musky que envuelve y cierra la fragancia con un toque sofisticado.</p>', 11800, 10, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-5313-7628-b894-b043b59edd4e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-0276-76e7-b48f-3fe47b62f041.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-242e-759a-83bc-8ed410eefde7.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Victoria’s Secret Midnight Bloom es un body mist elegante y envolvente, ideal para momentos íntimos, inspirado en fragancias gourmand nocturnas. Su aroma equilibra flores nocturnas y maderas suaves, con una duración respetable para su formato y mejorando con capas . Puede variar según química e incluso lotes, pero es una opción destacada si buscas un mist cálido, sofisticado y de tendencia.</p>', NULL),
(12517, 'Set Paris Hilton Platinum Rush 4PC Mujer', '<p>Notas de salida: Pera jugosa, mango y manzana roja.</p><p>Notas de corazón: Magnolia, lirio del valle y orquídea.</p><p>Notas de fondo: Ámbar, almizcle y pachulí.</p>', 34800, 1, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-4e3d-7285-ab5f-725a2731ae64.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set radiante y glamoroso que refleja el brillo de la elegancia moderna. Platinum Rush es una fragancia chispeante, floral y sensual, perfecta para mujeres que deslumbran con confianza y sofisticación.</p>', NULL),
(12518, 'Body Mist Perry Ellis 360 Red Mujer', '<p>Notas de salida: Cítricos (naranja, mandarina, limón)</p><p>Notas de corazón: Especias (pimienta, canela)</p><p>Notas de fondo: Almizcle, ámbar</p>', 8500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-4c22-7624-a8ca-5f42585d6ec7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-625d-714b-9a08-c90f5e895034.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-af1c-778e-83cc-fdcad2ce313d.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Perry Ellis 360° Red 8.0 oz para mujer es una fragancia cítrica y especiada que forma parte de la línea 360° de Perry Ellis. Diseñada para ofrecer una experiencia sensorial vibrante y energética, esta bruma corporal es ideal para el uso diario y ocasiones especiales.</p>', NULL),
(12519, 'Versace Eros 200ml EDT Hombre', '<p>Notas de salida: menta, manzana verde y limón italiano.</p><p>Notas de corazón: geranio, haba tonka y Ambroxan.</p><p>Notas de fondo: cedro de Atlas y Virginia, vetiver, musgo de roble y vainilla.</p>', 54500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988a92-7a19-735d-936c-1ffe375ec7a3.png?storeId=1681', 'Hombre', 1, 0, '<p>Eros abre con una explosión fresca y energética gracias a la menta y los cítricos. En el corazón, el geranio y la haba tonka aportan un toque floral y especiado. El fondo revela una base amaderada y cálida, con la suavidad de la vainilla y la profundidad del musgo de roble, creando una fragancia masculina, intensa y seductora</p>', NULL),
(12520, 'Armaf Odyssey Mandarín Sky 100ml EDP Hombre', '<p><strong>Notas de salida:</strong></p><p>Mandarina</p><p>Naranja</p><p>Azafrán</p><p>Salvia</p><p>Apertura cítrica, fresca y ligeramente especiada, con un toque herbal aromático.</p><p><strong>Notas de corazón:</strong></p><p>Caramelo</p><p>Haba tonka</p><p>Cempasúchil </p><p>Centro gourmand, dulce y cremoso, con un leve tono floral especiado.</p><p> <strong>Notas de fondo:</strong></p><p>Ambroxan</p><p>Cedro</p><p>Vetiver</p>', 24500, 8, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-429d-7749-bf0a-c5ceba3fd9e7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01991079-ab6a-72b9-8ff2-09bdae505929.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Mandarin Sky es una fragancia masculina vibrante y envolvente, con una apertura cítrica de mandarina y naranja, un corazón dulce de caramelo y haba tonka, y un fondo cálido de ambroxan y maderas. De estilo gourmand especiado, es ideal para noches frescas y climas otoñales, ofreciendo un aroma moderno con gran proyección y duración.</p>', NULL),
(12521, 'Ariana Grande Sweet Like Candy 100ml EDP Mujer', '<p>0Salida: brillante y chispeante con zarzamora (blackberry), bergamota y pera hermosa y jugosa </p><p>Corazón: un acorde tierno y cremoso que combina grosella negra, crema batida, malvavisco, jazmín sambac, frangipani y madreselva </p><p>Fondo: cálido y adictivo con vainilla suave y notas de madera cachemira que aportan ternura y estructura</p>', 32500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-3d7c-72a2-9722-b0d3f2b26b3a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f87-0600-741e-8419-dc0769d85bfd.png?storeId=1681', 'Mujer', 1, 0, '<p>Sweet Like Candy de Ariana Grande es un perfume juvenil, coqueto y cómodo, perfecto para el día a día o salidas casuales. Si te atraen los aromas dulces tipo postre con un toque frutal, esta fragancia ofrece una experiencia agradable a un precio asequible. Si buscas mayor longevidad o proyección, podrías considerar reaplicar o explorar opciones similares como Pink Sugar o Prada Candy.</p>', NULL),
(12522, 'Reebok Move Your Spirit 100ml EDT Mujer', '<p>Notas de salida: Frutos rojos, flor de cerezo y pimienta rosa.</p><p>Notas de corazón: Peonía, orquídea y fresia.</p><p>Notas de fondo: Vainilla, crema batida y almizcle.</p>', 6800, 4, 'Reebok', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ee0-61df-77b9-a38b-cefc779238cb.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina de la familia olfativa floral afrutada, lanzada en 2022, que combina notas dulces y florales con un toque cremoso y almizclado, ideal para mujeres activas y modernas.</p>', NULL),
(12523, 'Armaf Odyssey Aqua EDP 60ml Hombre', '<p>Pirámide Olfativa</p><p>Notas de salida</p><p>Naranja</p><p>Toronja (pomelo)</p><p>Artemisia </p><p>fragrantica</p><p>Notas de corazón</p><p>Menta</p><p>Lavanda</p><p>Notas de fondo</p><p>Ambroxan</p><p>Pachulí</p><p>Ciprés</p>', 18500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-36ec-739e-b383-dea0fec9297f.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aade0-8a71-71c2-8758-36012d4acc1c.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Aqua EDP es una fragancia masculina fresca y vibrante, que combina notas acuáticas y cítricas con un fondo amaderado y almizclado. Perfecta para el día a día y climas cálidos, ofrece una sensación refrescante y energizante, con una estela suave pero duradera. Ideal para hombres activos que buscan un aroma moderno y versátil.</p>', NULL),
(12524, 'Jean Paul Gaultier Le Beau Paradise Garden 125ML Hombre', '<p>Notas de salida: menta, jengibre, notas verdes y acuáticas</p><p>Notas de corazón: coco, higo y sal</p><p>Notas de fondo: haba tonka y sándalo</p>', 64500, 4, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-2ef0-769b-adc2-ae12ab24c470.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198fca9-78cb-7341-b610-924146ff2279.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Le Beau Paradise Garden es una fragancia masculina lanzada en 2024, diseñada por el perfumista Quentin Bisch. Esta edición se distingue por su perfil verde, acuático y tropical, ofreciendo una interpretación fresca y sofisticada del ADN característico de la línea Le Beau.</p>', NULL),
(12525, 'Liz Claiborne Curve Wave 125ml EDT Hombre', '<p>- Salida (Top): cítricos brillantes, menta, anís y bayas de enebro de Virginia.</p><p>- Corazón (Middle): (según una versión alternativa) carambola (fruta estrella), madreselva, frambuesa, orquídea, frangipani, azucena, flor de pasión y hibisco.</p><p>- Fondo (Base): almizcle, sándalo y ámbar.</p>', 14500, 17, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-2da5-778b-88db-ef4af20adf8c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fd-29f9-719b-b3b3-ac5de4ed36da.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-92c0-7638-8e2f-cc2c363bd65a.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Liz Claiborne Curve Wave es una fragancia masculina fresca y acuática, lanzada en 2005. Su combinación de notas cítricas, menta, anís azul y enebro crea un aroma revitalizante y energizante, ideal para el uso diario en climas cálidos.</p>', NULL),
(12526, 'Jean Paul Gaultier Scandal EDT 100ml Hombre', '<p>Notas de salida: Mandarina, Esclarea</p><p>Notas de corazón: Caramelo, Haba Tonka</p><p>Nota de fondo: Vetiver</p>', 58000, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f8d-9073-70e9-b0f0-7ef613620e33.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f8d-9383-714d-979b-ab93f53a1cd5.png?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Scandal Pour Homme Eau de Toilette 100ml es una fragancia masculina lanzada en 2021, destacada por su perfil dulce y amaderado. Esta fragancia ha sido bien recibida por su rendimiento y originalidad.</p>', NULL),
(12527, 'Paco Rabanne Invictus EDT 100ml Hombre', '<p>Salida: pomelo (grapefruit), mandarina y acordes marinos — brillante, vibrante y fresca </p><p>Corazón: hoja de laurel y jazmín — agrega un matiz verde-leñoso que equilibra lo acuático</p><p>Fondo: madera de guayaco (guaiac wood), musgo de roble, pachulí y ámbar gris</p>', 54500, 6, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972b0-a788-759d-b543-b2c98c93adc3.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972b0-aa43-728c-9ddd-bd1f64a2054c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972b0-a740-770d-afbf-d1dfcfaed64e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Invictus, lanzada en 2013, es una fragancia masculina emblemática, deportiva y juvenil. Combina frescura acuática con dulzura cítrica, evocando vitalidad, fuerza y un aire de triunfo casual. Ha alcanzado gran popularidad por su atractivo masivo</p>', NULL),
(12528, 'Body Mist Perry Ellis 360 Coral Mujer', '<p>Notas de salida: Bergamota italiana, prosecco de durazno, pera asiática y pimienta rosa.</p><p>Notas de corazón: Jazmín blanco, peonía y lirio de los valles.</p><p>Notas de fondo: Ámbar blanco, maderas de cachemira, haba tonka y almizcle.</p>', 8500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-1fd9-7433-aa41-fd637dbaf804.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-2129-734f-82be-e85e5f91a910.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-4b38-7713-8a0d-452ec4d908b8.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Perry Ellis 360° Coral 8.0 oz es una fragancia femenina fresca y afrutada, lanzada en 2014 como parte de la línea 360° de Perry Ellis. Diseñada para ofrecer una experiencia sensorial ligera y sofisticada, esta bruma corporal es ideal para el uso diario y ocasiones especiales.</p>', NULL),
(12529, 'Victorinox Swiss Army For Her Ginger Lily EDT 100ml', '<p>Notas de salida: jengibre, geranio</p><p>Notas de corazón: lirio de los valles (muguete), rosa mosqueta</p><p>Notas de fondo: almizcle, maderas suaves</p>', 18800, 2, 'Victorinox', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-1ec8-770e-91a0-0f50eaff7d60.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cbfd-8ece-7488-832c-27122306a3d5.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Fragancia femenina fresca y energética que combina la picante esencia de jengibre con la delicadeza floral del lirio de los valles y la rosa mosqueta. Su base amaderada y almizclada aporta profundidad y suavidad, creando una estela limpia y luminosa. Ideal para el uso diario, especialmente en climas cálid</p>', NULL),
(12530, 'Perry Ellis 360 Red EDP 100ml Mujer', '<p>Notas de salida: ciclamen (violeta persa), hojas de naranja y ciruela.</p><p>Notas de corazón: mimosa, flor de azahar del naranjo, jazmín y orquídea.</p><p>Notas de fondo: ámbar y almizcle</p>', 26000, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-1638-71e0-b795-acfbbb4e059e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fc-cabe-73ca-805f-6297f39887d1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-8332-73e6-84a1-8f81b008eb06.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El Perry Ellis 360° Red Eau de Parfum (EDP) 100 ml para mujer es una fragancia lanzada en 2003 que pertenece a la familia olfativa floral oriental. Está diseñada para mujeres que buscan una esencia femenina, delicada y romántica, ideal para el día y especialmente para la primavera.</p>', NULL),
(12531, 'Set Marc Jacobs Daisy 3PC Mujer', '<p>Notas de salida: Fresas silvestres, pomelo y hojas verdes.</p><p>Notas de corazón: Gardenia, violeta y jazmín.</p><p>Notas de fondo: Almizcle blanco, vainilla y madera de cedro.</p>', 59800, 0, 'Marc Jacobs', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-1332-702f-8277-f023914db70b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-a403-70d1-bc1e-9b6610f31bd6.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set fresco y alegre que refleja la feminidad joven y vibrante, con una fragancia floral-frutal ligera y luminosa, perfecta para el día a día y para realzar la energía positiva.</p>', NULL),
(12532, 'Perry Ellis 360 Red 100ml EDT Hombre', '<p>Bergamota italiana: fresca y ligeramente amarga, aporta una apertura cítrica y vibrante.</p><p>Limón verde: ácido y refrescante, con un toque energizante.</p><p>Mandarina: dulce y jugosa, con una sensación de suavidad.</p><p>Naranja: cítrica y dulce, con una nota alegre.</p><p>Canela roja: especiada y cálida, con un toque picant</p>', 24500, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-0d54-7413-9167-bc98160c83de.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fc-992f-71f9-9e82-53d488cdf039.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-0f47-719e-b3db-ddeb44907fde.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina que combina la frescura de los cítricos con la calidez de las especias y la profundidad de las maderas, creando una estela envolvente y energética. Ideal para hombres que buscan un aroma distintivo y sofisticado.</p>', NULL),
(12533, 'Body Spray Odyssey Mega', '<p>Salida: Naranja, jengibre, bergamota, limón (lima ácida) y menta</p><p>Corazón: Piña, geranio, enebro de Virginia y salvia</p><p>Fondo: Almizcle, haba tonka, cedro y vetiver</p>', 6000, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cc8-776b-77d9-b022-7d52ea566733.png?storeId=1681', 'Hombre', 1, 0, '<p>El Body Spray Odyssey Mega de Armaf es una fragancia amaderada y aromática para hombres, lanzada en 2023. Su perfil olfativo se caracteriza por una apertura fresca y especiada, seguida de un corazón afrutado y un fondo cálido</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12534, 'Versace Eros 100ml EDP Hombre', '<p><strong>Salida</strong>: limón italiano, mandarina, menta, manzana confitada.</p><p><strong>Corazón</strong>: flor de geranio, salvia, Amber.</p><p><strong>Fondo</strong>: cedro de Atlas y Virginia, vetiver, pachulí, sándalo, vainilla.</p>', 45000, 5, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-0581-734c-8eda-5474cdc577e6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019915a2-a9f7-700e-ad84-c72b970d3417.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia masculina que encarna la sensualidad y el poder. Combina notas frescas y cítricas con un fondo amaderado y dulce, creando una experiencia olfativa intensa y cautivadora.</p>', NULL),
(12535, 'Versace Dylan Blue 100ml EDP Mujer', '<p>otas de salida: grosella negra, manzana Granny Smith, trébol blanco, nomeolvides y shiso (menta púrpura)</p><p>Notas de corazón: rosa eglantina, jazmín, pétalia, jazmín y melocotón helado.</p><p>Notas de fondo: styrax, maderas blancas lisas, almizcle y pachulí.</p>', 42800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976079-0310-708d-be4b-8bb4d7fbb1df.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aa82f-7388-746f-b29f-4ac9e45aa5bb.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fuerte y sensual que fusiona notas afrutadas y florales con un fondo amaderado, evocando la feminidad y el poder de la mujer moderna.</p>', NULL),
(12536, 'Set Jesus Del Pozo Halloween 100ml 4PC Mujer', '<p>Notas de salida: Mandarina, frambuesa y ciruela.</p><p>Notas de corazón: Jazmín, azahar y canela.</p><p>Notas de fondo: Vainilla, pachulí y almizcle.</p>', 36000, 0, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-fca3-71fe-bf7c-eb13bec47265.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set misterioso y seductor que captura la esencia de Halloween, con una fragancia femenina, dulce y especiada, ideal para mujeres que buscan un aroma envolvente y cautivador para ocasiones especiales.</p>', NULL),
(12537, 'Lattafa Sublime 100ml EDP Unisex', '<p>Salida: Manzana, lichi, rosa</p><p>Corazón: Ciruela, jazmín</p><p>Fondo: Vainilla, musgo, pachulí</p>', 24000, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-fb3e-7361-bebb-e14a1d4d1521.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a17fe-1ebb-70a0-b62b-4b1879762bf5.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Sublime es una fragancia unisex que combina notas frutales y florales con una base amaderada y dulce. Su apertura fresca y afrutada da paso a un corazón floral, mientras que su fondo cálido y terroso le otorga profundidad y sofisticación.</p>', NULL),
(12538, 'LORIENTALE NIGHT DE PARIS INTENSO EDP 100ML', 'mandarina, limón italiano (lima), grosella negra, ámbar blanco \nCorazón: ylang-ylang, violeta y un bouquet floral indeterminado \nFondo: pachulí, sándalo blanco, madera seca, almizcle blanco', 39500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-f41a-7779-adc4-73f4681f1391.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-4204-701a-837a-3a623574e722.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-3ce0-75d6-acf7-96c6426df46c.jpeg?storeId=1681', NULL, 1, 0, 'Ambienta sofisticada y moderna: un oriental amaderado que combina cítricos chispeantes, florales suaves y una base cálida de maderas y almizcle, ideal para el día o la noche.', NULL),
(12539, 'Lattafa Yara Tous 100ml EDP Mujer', '<p>Salida: Jazmín, melocotón</p><p>Corazón: Caramelo, ámbar</p><p>Fondo: Pachulí, sándal</p>', 20000, 4, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-ed4f-7567-97ba-571305e3d3e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd7f-00ac-77bc-a16e-3454b156662e.png?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Yara Moi es una fragancia femenina que combina la frescura del jazmín y el melocotón con la dulzura del caramelo y la calidez del ámbar, sobre una base de pachulí y sándalo. Su aroma elegante y sofisticado la convierte en una opción ideal para ocasiones especiales.</p>', NULL),
(12540, 'Body Mist Paris Hilton Heiress 200ml Mujer', '<p>Salida: granadina, pomelo, durazno granita, fruta de la pasión, naranja y champán mimosa </p><p>Corazón: jazmín estelar, flor de tiaré, ylang-ylang, madreselva, dewberry y granadina </p><p>Fondo: hoja de violeta, vetiver, tonka y maderas rubias</p>', 7800, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-e631-77de-9713-1d0d690f5893.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-656f-76ed-ac69-8406b6ffc543.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-c892-736f-86bb-9d4476acc86d.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Un body mist femenino que mezcla notas afrutadas, florales y chispeantes, evocando una sensación alegre, juvenil y un toque elegante, muy en la línea de los primeros clásicos de Paris Hilton.</p>', NULL),
(12541, 'Adidas Get Ready 100ml EDT Hombre', '<p>Familia olfativa: Aromática - Frutal</p><p><br></p><p>Salida (notas de apertura): Piña, mandarina, notas marinas</p><p><br></p><p>Corazón (notas medias): Lavanda, frutas exóticas, salvia</p><p><br></p><p>Fondo (notas de base): Sándalo, cedro, pachulí</p><p><br></p><p>Esta estructura da como resultado una fragancia refrescante, tropical y ligeramente especiada, perfecta para un estilo de vida activo y juvenil.</p>', 8500, 0, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-e215-759f-bfc0-1a9f08fce789.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af6c-e687-703a-9ff9-b55074fcb2df.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Adidas Get Ready es una fragancia fresca y energizante, diseñada para hombres activos y deportivos. Lanzada como parte de una colaboración con eventos deportivos internacionales, esta fragancia combina notas cítricas vibrantes con un toque exótico y amaderado. Su aroma abre con piña, mandarina y notas marinas, que evolucionan hacia un corazón especiado con lavanda y salvia, para terminar en una base cálida de sándalo, pachulí y cedro. Es ideal para el uso diario, especialmente en climas cálidos o después del ejercicio.</p>', NULL),
(12542, 'Lacoste L.12.12 Rose EDP 100ml Mujer', '<p>Notas de salida: Mandarina verde y menta</p><p>Notas de corazón: Rosa y frangipani (plumeria)</p><p>Notas de fondo: Almizcle y almizcle ambreta</p>', 38500, 0, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc8e-cb75-75b9-ac67-fb0c4e52356d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc8e-cd0c-7594-b8e0-a37be2863810.png?storeId=1681', 'Mujer', 1, 0, '<p>Lacoste L.12.12 Rose es una fragancia femenina que combina la frescura de la mandarina verde y la menta con la suavidad de la rosa y el frangipani. Su base de almizcle y almizcle ambreta aporta una sensación de elegancia y libertad. El diseño del frasco y la caja presenta el icónico patrón \"petit piqué\", inspirado en el tejido del polo Lacoste, y cada frasco cuenta con el auténtico cocodrilo bordado.</p>', NULL),
(12543, 'Moschino Toy 2 Bubble Gum EDP 100ml Mujer', '<p><strong>Notas de salida (frutales y frescas):</strong></p><p><br></p><p>Chicle (Bubble Gum)</p><p>Cítricos (naranja amarga, limón)</p><p>Canela</p><p>Jengibre</p><p><br></p><p><strong>Notas de corazón (florales y dulces):</strong></p><p><br></p><p>Rosa búlgara</p><p>Melocotón</p><p>Arándano (blueberry)</p><p>Piel de durazno</p><p>Pimienta</p><p><br></p><p><strong>Notas de fondo (cálidas y cremosas):</strong></p><p><br></p><p>Almizcle</p><p>Cedro</p><p>Ambroxan</p>', 38000, 2, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ee7-31e4-7125-85e9-d79038792374.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ee7-d0a1-74f4-9145-1902d8354f02.png?storeId=1681', 'Mujer', 1, 0, '<p>Moschino Toy 2 Bubble Gum es una fragancia femenina divertida y juvenil inspirada en el chicle de fresa de los 90. Empieza con explosión dulce y afrutada, evoluciona a un corazón floral especiado, y termina en un fondo amaderado-musculado. Perfecta para quienes buscan una experiencia olfativa juguetona y energética.</p>', NULL),
(12544, 'Issey Miyake Pour Homme 125ml EDT Hombre', '<p><strong>Salida</strong>: Yuzu, limón, bergamota, mandarina, ciprés, cilantro, estragón, salvia, verbena, calone (acorde marino) </p><p><strong>Corazón:</strong> Loto azul, nuez moscada, lirio de los valles, azafrán, canela de Ceylán, geranio bourbon, reseda </p><p><strong>Fondo:</strong> Vetiver de Tahití, almizcle, cedro, sándalo, tabaco, ámbar</p>', 38000, 15, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-c6ca-775f-b4ae-4909bff63367.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01999795-d3c7-758b-975c-f3a2bdefd612.png?storeId=1681', 'Hombre', 1, 0, '<p>Lanzada en 1994 y creada por Jacques Cavallier, esta fragancia masculina es un clásico acuático‑amaderado que evoca pureza, frescura y naturaleza. Combina cítricos chispeantes con especias suaves y un fondo amaderado, perfecta para hombres que buscan un aroma limpio y versátil para el día a día</p>', NULL),
(12545, 'Paco Rabanne Invictus EDT 200ml Hombre', '<p>Pomelo</p><p>Mandarina</p><p>Acordes marinos</p>', 62000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972a8-a3cd-7249-8149-9282a823612b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972b2-f4b7-77fb-a619-1cf15140ddb0.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972b3-564c-716b-a5bb-db4f4460cdbb.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Invictus de Paco Rabanne es una fragancia masculina fresca, intensa y deportiva. Representa el espíritu de victoria, poder y energía. Ideal para hombres seguros, activos y que disfrutan destacar. Su aroma combina frescura marina con un fondo amaderado y cálido.</p>', NULL),
(12546, 'Versace Eros 100ml EDT Hombre', '<p><strong>Salida</strong>: limón italiano, mandarina, menta, manzana confitada.</p><p><strong>Corazón</strong>: flor de geranio, salvia, Amber.</p><p><strong>Fondo</strong>: cedro de Atlas y Virginia, vetiver, pachulí, sándalo, vainilla.</p>', 43000, 7, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-af9e-70a2-be14-1efa360275f1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019915a5-b8fc-73b8-94bb-837e19ac3642.png?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia masculina que encarna la sensualidad y el poder. Combina notas frescas y cítricas con un fondo amaderado y dulce, creando una experiencia olfativa intensa y cautivadora.</p>', NULL),
(12547, 'CAROLINA HERRERA CLASICO MUJER PUNTOS EDP', 'Notas de salida: cítricos frescos como bergamota, naranja/chabacano, flor de azahar y toques verdes \nNotas de corazón: un bouquet floral intenso: jazmín, nardo de la India, madreselva, lirio de los valles, narciso, jacinto, ylang‑ylang \nNotas de fondo: base cálida y sólida de sándalo, cedro, vetiver, musgo de roble, ámbar, almizcle y civet', 59500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-8135-72b8-bbce-aeadc0481fbc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-60e8-74bc-84e4-b0cd30155a48.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-37ef-7327-ad60-304b3491b845.jpeg?storeId=1681', NULL, 1, 0, 'Carolina Herrera Clásico Mujer es una fragancia elegante, floral y atemporal, lanzada en 1988. Representa la esencia de la feminidad sofisticada, con una combinación envolvente de flores blancas, notas verdes y maderas cálidas. Su aroma es refinado, ideal para mujeres que buscan una presencia clásica pero con carácter.', NULL),
(12548, 'Prada Luna Rossa Ocean 100ml EDT Mujer', '<p>Bergamota vibrante: chispeante y refrescante </p><p>Abrótano herbal: un toque distintivo y aromático </p><p>Pimienta rosa: suave y especiada, añade energía al conjunto</p>', 60500, 1, 'Prada', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8a21-e8ae-74e4-be3e-0ef5e5f1878c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a8a21-e5f3-738e-a95c-bf71a518f399.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Un aroma fresco y elegante que evoca la sensación de brisa marina combinada con sofisticación tecnológica. Ideal para el hombre moderno que busca una fragancia limpia, energética y polivalente.</p>', NULL),
(12549, 'CREMA VICTORIA SECRET BARE VAINILLA UNTAMED', 'Vainilla absoluta: rica, cremosa y cálida\nFlor de manzano: floral suave, ligeramente frutal\nFrutas del bosque: dulces, jugosas y maduras (tono afrutado oscuro)\nNéctar de albaricoque: dulce y meloso, con un toque aterciopelado', 11800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-770b-71be-81f5-6e14b59145e9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-204c-75ab-b791-7ced0953bc7c.jpeg?storeId=1681', NULL, 1, 0, 'La Bare Vanilla Untamed de Victoria’s Secret es una loción corporal limited edition dentro de la línea Untamed, diseñada para llevar la iconica vainilla a un entorno más salvaje y sofisticado.', NULL),
(12550, 'Katy Perry Purr 100ml EDP Mujer', '<p>Notas de salida: Gardenia, Bambú, Durazno (Melocotón), Manzana Roja</p><p>Notas de corazón: Jazmín, Fresia, Rosa</p><p>Notas de fondo: Almizcle, Sándalo, Ámbar, Vainilla, Coco, Orquídea</p>', 22000, 2, 'Katy Perry', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-7514-7469-96ec-359fcc5dff20.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6baa-4dae-747a-8af2-0c7e74f80bdf.png?storeId=1681', 'Mujer', 1, 0, '<p>Purr es una fragancia floral frutal lanzada en 2010 que combina notas dulces y cremosas con un toque floral sofisticado. Su salida fresca y afrutada se suaviza con un corazón floral y un fondo cálido y envolvente, ideal para quienes buscan una fragancia femenina, dulce y versátil.</p>', NULL),
(12551, 'BODY SPRAY LATTAFA OUD FOR GLORY', 'Notas de salida: azafrán, nuez moscada y lavanda.\nNotas de corazón: madera de oud y pachulí.\nNotas de fondo: madera de oud, pachulí y almizcle.', 5000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-2d12-76da-a057-c3c5321ae4fe.jpeg?storeId=1681', NULL, 1, 0, 'Lattafa Oud For Glory es una fragancia unisex intensa y elegante, con una combinación cálida y especiada de azafrán, nuez moscada y lavanda, que se funde con la riqueza amaderada del oud y pachulí. Su aroma envolvente y duradero lo hace perfecto para ocasiones especiales y climas frescos.', NULL),
(12552, 'Afnan 9AM Dive EDP 100ml Hombre', '<p>Familia olfativa: Aromática - Acuática - Cítrica</p><p><br></p><p>Notas de salida: Menta, limón, pimienta rosa, mandarina</p><p>Notas de corazón: Lavanda, canela, jengibre, notas marinas</p><p>Notas de fondo: Ámbar, pachulí, madera de gaiac, cedro</p><p><br></p><p>Esta fragancia ofrece una apertura refrescante y chispeante, seguida por un corazón especiado y limpio, y culmina en una base cálida y amaderada que le da profundidad sin perder su frescura.</p>', 26000, 5, 'Afnan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-7617-7135-acd5-f774b56162d0.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eab-1344-72aa-b604-ee9deda31aac.png?storeId=1681', 'Hombre', 1, 0, '<p>Afnan 9AM Dive es una fragancia masculina vibrante y acuática, ideal para el verano. Su aroma fresco y energizante combina notas cítricas y marinas con un fondo amaderado y ligeramente especiado. Es una fragancia que evoca la sensación de una inmersión matutina en aguas cristalinas, perfecta para hombres que buscan una esencia limpia, dinámica y duradera.</p>', NULL),
(12553, 'BODY VICTORIA SECRET SOLAR SANDS', 'Notas altas: Peonía coral al atardecer, flor de guayaba, arenas cálidas.\nNotas medias: Acacia dulce, vainilla dorada, jazmín en ciernes.\nNotas base: Acacia dulce, vainilla dorada, jazmín en ciernes.', 11800, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-6c41-7598-a610-6f7ec55383bd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-5201-739a-9028-7da00e7d8c4a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-442d-741a-9253-1dd6e966106f.jpeg?storeId=1681', NULL, 1, 0, 'Solar Sands captura la esencia de un viaje por el desierto, combinando notas florales cálidas con toques dulces y cremosos. Es ideal para quienes buscan una fragancia que evoque la calidez del sol y la serenidad del desierto.', NULL),
(12554, 'Antonio Banderas Power of Seduction 100ml EDT Hombre', '<p>Familia: Aromático verde – fresco, herbal, ligeramente especiado y amaderado</p><p>Salida: bergamota cítrica y manzana crujiente.</p><p>Corazón: lavanda, abrótano (artemisia) y esclarea, aportando un toque aromático-herbal sofisticado</p><p>Fondo: ámbar cálido, musgo, pachulí, haba tonka y vetas amaderadas — dan profundidad y</p>', 15500, 1, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-6962-7659-b794-32662f6eb772.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198d8f2-edf2-740b-b51b-280a5968b782.png?storeId=1681', 'Hombre', 1, 0, '<p>Antonio Banderas Power of Seduction EDT (2018) es una fragancia verde-aromática con frescura citríca y apple, un corazón herbal floral y una base cálida y masculina. Ideal para uso diario o informal, ofrece una excelente relación calidad-precio y es especialmente atractiva para quienes quieren algo elegante y sin complicaciones. Aunque no es un monstruo en longevidad, su rendimiento es sólido para su precio, y su aroma ha sido comparado favorablemente con fragancias más costosas.</p>', NULL),
(12555, 'Ariana Grande Moonlight 100ml EDP Mujer', '<p>Familia: Floral–frutal gourmand, suave y acogedora.</p><p>Salida: notas jugosas de ciruela y grosella negra — frutal, sensual y un poco chispeante </p><p>Corazón: combinación dulce y aterciopelada de malvavisco y peonía — crea una sensación tierna y femenina </p><p>Fondo: calidez envolvente con vainilla, sándalo y ámbar negro, aportando profundidad y confort </p>', 34500, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a230a-c270-70ff-bbe7-b8dddd464a65.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a230a-c480-7358-a9c0-c0973e2ab4ac.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a230a-c4a8-76fa-ad51-6d45f126b177.png?storeId=1681', 'Mujer', 1, 0, '<p>Ariana Grande Moonlight EDP es una fragancia frutal y gourmand, con una apertura jugosa, un corazón dulce como malvavisco, y un fondo cálido ambarado. Ideal para un uso diario relajado, en climas fríos o para ocasiones íntimas. Su rendimiento es adecuado pero no espectacular: si buscas calidez moderna con proyección suave, es una opción encantadora; si prefieres algo duradero o potente, puede requerir reaplicaciones.</p>', NULL),
(12556, 'Body Spray Club De Nuit Woman', '<p>Salida: cítricos chispeantes de naranja, pomelo (toronja), bergamota y un toque jugoso de durazno </p><p>Corazón: bouquet floral elegante con rosa, geranio, jazmín y un matiz dulce‑ácido de lichi </p><p>Fondo: rica base dulce-Amaderada de pachulí, vainilla cremosa, almizcle suave y vetiver terroso</p>', 5500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-6519-7759-b90a-c5a19894efab.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-044c-77ad-b864-199ff707efd7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-4218-72a4-8ce4-c6962034a932.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Club de Nuit Woman Body Spray de Armaf es una fragancia femenina elegante y sofisticada, con un aroma floral-cítrico envolvente. Combina notas brillantes de bergamota, durazno y toronja, con un corazón floral de rosa y jazmín, y un fondo sensual de vainilla, pachulí y almizcle. Inspirado en Chanel Coco Mademoiselle, este body spray es ideal para el uso diario, ofreciendo frescura con un toque de lujo a un precio accesible.</p>', NULL),
(12557, 'Liz Claiborne Curve Crush 125ml EDT Hombre', '<p>Bergamota, albahaca, cilantro, mandarina, pera y manzana </p><p>Melodía principal (Corazón): Jengibre, lavanda, salvia, geranio y hojas de violeta </p><p>Ritmo final (Fondo): Cardamomo, cedro, vetiver, musgo de roble, ámbar y almizcle</p>', 21500, 3, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-09a6-71d8-adbe-3213ade6d79d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886c5-6381-7038-9cd7-6120ed651905.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca, chispeante y juvenil, con una mezcla vibrante de cítricos y manzana, respaldados por un fondo amaderado suave. Ideal para uso casual diario, especialmente en clima cálido.</p>', NULL),
(12558, 'Body Spray Odyssey Homme Black', '<p>Salida: mandarina, neroli y cardamomo</p><p>Corazón: rosa y flor de azahar </p><p>Fondo: sándalo, vainilla, ámbar y acordes amaderados</p>', 5500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-59a8-7565-92d2-1da168d7f158.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-d472-72a8-894a-e87d543fd15b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-86da-76b9-9ee9-404548dd7f5e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Odyssey Homme Black es un body spray ambarado y especiado, con notas de mandarina, rosa, vainilla y sándalo. Su aroma cálido y sofisticado es ideal para noches frescas y ocasiones especiales, ofreciendo buena duración y proyección.</p>', NULL),
(12559, 'Body Mist Perry Ellis 360 Purple 200ml Mujer', '<p>Notas de salida: Bergamota italiana, prosecco de durazno, pera asiática y pimienta rosa.</p><p>Notas de corazón: Jazmín blanco, peonía y lirio de los valles.</p><p>Notas de fondo: Ámbar blanco, maderas de cachemira, haba tonka y almizcle.</p>', 8500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-57ed-70ab-995d-b0179bd0f92c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-8ec6-73dd-b550-f3f90a74abaf.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-04c5-7739-8bf9-3eab2f7ababc.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Perry Ellis 360° Purple 8.0 oz para mujer es una fragancia femenina que forma parte de la línea 360° de Perry Ellis. Esta bruma corporal ofrece una experiencia olfativa fresca y sofisticada, ideal para el uso diario.</p>', NULL),
(12560, 'Jean Paul Gaultier Scandal Pour Homme 50ml EDT Hombre', '<p>Notas de salida: Salvia</p><p>Notas de corazón: Caramelo, haba tonka</p><p>Notas de fondo: Vetiver</p>', 42800, 0, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-5075-768b-8994-3b81a928236e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Scandal Pour Homme Eau de Toilette 1.7 oz (50 ml) es una fragancia masculina lanzada en 2021, reconocida por su aroma dulce, amaderado y ligeramente especiado. Diseñada para hombres audaces y sofisticados, esta fragancia ha sido bien recibida por su longevidad y proyección.</p>', NULL),
(12561, 'BODY BATH&BODY WORKS DENIN DAISIES', 'Aroma principal: Flores blancas frescas sobre un fondo limpio y suave, con un toque de frescura \"denim\" que recuerda a prendas recién lavadas.\nSensación en la piel: Se transforma en una espuma densa y cremosa, limpiando sin resecar y dejando la piel suave, ligeramente perfumada y confortable', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-4d33-7064-b766-c77ec4202539.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-4387-769d-aa19-2631be2e19fa.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-3d3f-718a-a686-c2eb8a048681.jpeg?storeId=1681', NULL, 1, 0, 'Denim Daisies ofrece una experiencia de baño floral ligera, dulce y limpia, con buena espuma y sensación hidratante. Perfecta para empezar el día con energía y delicadeza.', NULL),
(12562, 'Armaf Club De Nuit Sillage 105ml Hombre', '<p>Familia olfativa: Amaderada - Aromática - Especiada</p><p><br></p><p>Notas de salida: Bergamota, limón, pimienta negra</p><p><br></p><p>Notas de corazón: Lavanda, geranio, canela</p><p><br></p><p>Notas de fondo: Ámbar, almizcle, pachulí, cedro</p><p><br></p><p>Esta fragancia ofrece una combinación de frescura cítrica y un corazón especiado, con una base cálida y amaderada, creando un aroma potente y sofisticado, ideal para la noche y ocasiones especiales.</p>', 26500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-4c4d-7528-bdad-8b3486323556.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199de94-ff5e-7525-a248-cf182aded809.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Sillage es una fragancia masculina intensa y moderna que combina notas frescas, especiadas y amaderadas para crear un aroma vibrante y duradero. Está diseñada para hombres seguros que buscan destacar con una presencia elegante y seductora. Ideal para la noche y eventos especiales, ofrece una estela potente y memorable.</p>', NULL),
(12563, 'Versace DYLAN TOURQUOISE EDP 100ml Mujer', '<p>Salia: Limón, mandarina, pimienta rosa.</p><p>Corazón: Guayaba, fresia, grosella negra, jazmín.</p><p>Fondo: Almizcle, Clearwood</p>', 46500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bf9-f4da-7005-9f18-a09531b82b6a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bf9-f7d7-715d-bc77-0e11ee85d301.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y luminosa que combina notas cítricas y florales, evocando la esencia de un verano mediterráneo. Ideal para mujeres que buscan una esencia vibrante y elegante</p>', NULL),
(12564, 'Set Paco Rabanne 1 Million 3.4 EDT Sp + 0.34 EDT Hombre', '<p>Notas de salida: Pomelo, menta y mandarina roja.</p><p>Notas de corazón: Canela, rosa y especias.</p><p>Notas de fondo: Cuero, ámbar y madera blanca.</p>', 56800, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-4506-77db-a3b3-326fc515fa1c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-d4e0-7539-a783-d3d10615df55.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-4570-76bb-b121-7653bf4c7435.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set icónico y audaz que refleja lujo y confianza, combinando la fragancia intensa y cálida de 1 Million con un práctico tamaño mini para llevar tu aroma distintivo a donde vayas.</p>', NULL),
(12565, 'Marc Jacobs Perfect 100ml EDP Mujer', '<p>Salida: Ruibarbo, narcisos y flor de narciso (mostrando un carácter verde, jugoso y floral) </p><p>Corazón: Leche de almendra, aportando una dimensión cremosa suave y reconfortante</p><p>Fondo: Cashmeran y cedro, que añaden una base amaderada y ligeramente almizclada</p>', 58000, 2, 'Marc Jacobs', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-44a8-761d-b66a-9fec1047b31d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d0d9-9db9-7078-9a96-53283dab3934.png?storeId=1681', 'Mujer', 1, 0, '<p>Perfect es una fragancia femenina moderna y reconfortante que celebra el amor propio y la autenticidad. Evoca una sensación de confort floral con un toque optimista y elegante — ideal para quienes buscan un aroma suave, femenino y versátil</p>', NULL),
(12566, 'Tom Ford OUD WOOD 100ml Hombre', '<p>Salida: Cardamomo, pimienta de Sichuan y palo de rosa.</p><p>Corazón: Oud, sándalo y vetiver.</p><p>Fondo: Haba tonka, vainilla y ámbar.</p>', 165000, 0, 'Tom Ford', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-3f3a-713a-93c4-1e426270457b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bfb-d483-709b-8ae5-3fffeddbe40b.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia sofisticada y moderna que presenta el oud de manera accesible, fusionando notas amaderadas y especiadas con un toque suave y elegante, ideal para quienes buscan un aroma distintivo pero no abrumador.</p>', NULL),
(12567, 'Body Mist Victoria Secret Pure Seduction', '<p>Salida: melón dulce y aloe vera, aportando una frescura inicial.</p><p>Corazón: ciruela roja madura, añadiendo un toque afrutado y jugoso.</p><p>Fondo: fresia y manzanilla, brindando una base floral suave y reconfortante.</p>', 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-3b28-730a-9856-584abe9cd071.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-1000-703b-986b-a781ad35461c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-d781-76ae-8a44-76451681fc21.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pure Seduction es una fragancia dulce y afrutada que combina notas jugosas con un toque floral suave. Su aroma evoca una sensación de frescura y feminidad, ideal para quienes buscan una fragancia ligera y encantadora para el uso diario.</p>', NULL),
(12568, 'Animale 100ml EDT Hombre', '<p>Notas de salida: Fresia, limón y neroli</p><p>Notas de corazón: Bayas de enebro, lavanda y geranio.</p><p>Notas de fondo: Cuero, musgo de roble y vetiver.</p><p>Esta combinación crea una fragancia equilibrada que destaca por su calidez y sofisticación.</p><p>Características generales</p><p>Familia olfativa: Amaderada especiada.</p><p>Estilo: Sofisticado, masculino y atemporal.</p><p>Uso recomendado: Ideal para ocasiones formales y nocturnas.</p><p>Duración: Moderada; se recomienda reaplicar durante el día.</p>', 24000, 0, 'Animale', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-3862-7190-a79e-f29f93e29db6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3ea-dffa-77ab-af4f-c8e68ae39b59.png?storeId=1681', 'Hombre', 1, 0, '<p>Animale for Men Eau de Toilette es una fragancia masculina clásica lanzada en 1993 por Animale Parfums. Perteneciente a la familia olfativa amaderada especiada, se caracteriza por su aroma distintivo y atemporal, evocando una sensación de sofisticación y masculinidad.</p>', NULL),
(12569, 'Reebok Move Your Spirit 100ml EDT Hombre', '<p>Notas de salida: Notas marinas, lavanda congelada y bergamota.</p><p>Notas de corazón: Ciprés, sal marina y salvia.</p><p>Notas de fondo: Abeto y pachulí ámbar.</p>', 6800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993edc-e871-77c5-91b1-a6ccdf66f901.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993edc-edca-7439-b696-748b21bc02e0.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina de la familia olfativa amaderada acuática, diseñada para hombres activos que buscan frescura y vitalidad en su día a día.</p>', NULL),
(12570, 'Calvin Klein Euphoria 100ml EDP Mujer', '<p>Granada, caqui, notas verdes y frutales (pomegranate, persimmon, green accord) </p><p>Melodía central (Corazón): Orquídea negra, flor de loto, champaca (lotus blossom, black orchid, champaca flower) </p><p>Ritmo final (Fondo): Ámbar líquido, maderas de caoba (mahogany), violeta negra, acorde cremoso y almizcle suave</p>', 34500, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-3043-74b7-8e5c-c4d86c5a5869.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ecd-350b-76ba-801b-52f58450c939.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia oriental-floral sofisticada, misteriosa y sensual, perfecta para la noche o el clima fresco. Combina frutas oscuras y flores exóticas, con un toque cálido y amaderado que deja una estela elegante y duradera</p>', NULL),
(12571, 'Giorgio Armani Stronger With You 50ml EDT Hombre', '<p>Salida: Cardamomo, Pimienta rosa, Hoja de violeta, Menta</p><p>Corazón: Piña, Canela, Melón, Salvia</p><p>Fondo: Castaño, Vainilla, Ámbar, Cedro</p>', 42000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-3304-72f7-8a04-037c89d05354.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-817d-732f-bc16-e2303b57d6f1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-1adc-717e-8746-bce67c650f1a.png?storeId=1681', 'Hombre', 1, 0, '<p>Lanzado en 2017, Emporio Armani Stronger With You es una fragancia masculina de la familia olfativa aromática fougère. Creada por la perfumista Cécile Matton, esta fragancia celebra la conexión emocional y la complicidad, simbolizada por el anillo grabado en su botella, que representa el vínculo entre dos personas</p>', NULL),
(12572, 'Crema VICTORIA´S SECRET Bare Vainilla', '<p>La fragancia se caracteriza por una mezcla de notas dulces y cremosas, evocando la suavidad de la vainilla combinada con la calidez del cashmere. Aunque las notas específicas no se detallan públicamente, la combinación de estos elementos crea una experiencia sensorial envolvente y reconfortante.</p>', 11800, 1, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-2b14-7698-bbd0-21ba2087bba3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fc-d162-708e-845d-db11ed91b26c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-4938-725d-b872-9a3028dfb96b.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>La loción corporal Victoria’s Secret Bare Vanilla es una fragancia femenina de la familia olfativa gourmand. Es conocida por su aroma dulce, cálido y envolvente, ideal para quienes buscan una fragancia reconfortante y sensual.</p>', NULL),
(12573, 'Michael Kors EDP 100ml MUJER', '<p>Salida: freesia, incienso marroquí, tuberosa </p><p>Corazón: peonía, lirio, iris y flor de loto </p><p>Fondo: maderas cremosas (cashmere wood), ámbar, almizcle y vetiver</p>', 47000, 0, 'Michael Kors', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-2705-75a5-9d86-3181721f2318.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0c01-2273-7564-a72c-a58e1ee062f4.png?storeId=1681', 'Mujer', 1, 0, '<p>Es una fragancia floral-cremosa y sofisticada que combina flores blancas, especias suaves y maderas cremosas. Elegante y elegante, ideal tanto para el uso diario como para ocasiones especiales.</p>', NULL),
(12574, 'Lattafa Asad Zanzibar EDP 100ml Hombre', '<p>Notas de salida: Lavanda, pimienta negra</p><p>Notas de corazón: Agua de coco, iris, sal</p><p>Notas de fondo: Vainilla, incienso</p>', 20000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-2166-72b2-a9d2-69312591eaf2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cd05-f7d4-7308-af4c-e2d4888a9c56.png?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Asad Zanzibar es una fragancia unisex que combina notas frescas, especiadas y dulces, evocando la esencia tropical de la isla de Zanzíbar. Su apertura presenta lavanda y pimienta negra, seguida de un corazón cremoso de agua de coco e iris, con un toque salino. El fondo cálido de vainilla e incienso proporciona una estela duradera y envolvente.</p>', NULL),
(12575, 'Givenchy GENTLEMAN EDT 100ml Hombre', '<p>Salida: Pera, cardamomo y piña (tocando matices dulces y únicos) </p><p>Corazón: Iris, lavanda, geranio y un toque de orris </p><p>Fondo: Pachulí, cuero, vetiver e incienso, creando una base masculina y duradera</p>', 42800, 1, 'Givenchy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bff-efae-756c-8b7a-d84844a3aee2.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bff-ef3b-726c-85be-fd99a4058569.png?storeId=1681', 'Hombre', 1, 0, '<p>Lanzada en 2017, Gentleman Givenchy EDT es una reimaginación moderna del clásico de 1974, con un enfoque fougère amaderado y floral </p><p> Está diseñada para el hombre sofisticado y elegante, con una mezcla equilibrada entre notas frescas, especiadas y profundas.</p>', NULL),
(12576, 'Paco Rabanne Lady Million EDP 80ml Mujer', '<p>Salida: frambuesa, limón de Amalfi, neroli (azahar amargo)</p><p>Corazón: jazmín sambac, flor de naranjo africano (azahar), gardenia</p><p>Fondo: miel blanca, pachulí, ámbar</p>', 58500, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-1b38-76ac-b621-59a018d85731.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bfd-a26f-7766-a894-e478b8d0167b.png?storeId=1681', 'Mujer', 1, 0, '<p>Lady Million (2010) es una fragancia femenina floral-frutal oriental, diseñada para transmitir lujo, confianza y sensualidad. Su esencia combina la dulzura jugosa de la frambuesa y el limón con un corazón floral elegante, finalizando en un fondo cálido de miel, pachulí y ámbar. Ideal para destacar tanto de día como en la noche</p>', NULL),
(12577, 'Lattafa Pride Shaheen Gold 100ml EDP Unisex', '<p>Salida: Bergamota, limón, canela, azafrán</p><p>Corazón: Jazmín, rosa, notas amaderadas</p><p>Fondo: Ámbar, madera de oud</p>', 29000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd3e-56aa-74cc-aff2-58c036e6176e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd3e-56d6-715a-b404-56e8e331bcc6.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Pride Shaheen Gold es una fragancia unisex sofisticada que combina notas cítricas frescas con un toque especiado y floral. Su corazón floral se enriquece con un fondo cálido y amaderado, creando una experiencia olfativa elegante y envolvente.</p>', NULL),
(12578, 'Nautica Voyage Sport EDT 100ml Hombre', '<p>Salida: brisa marina, sal de mar, cítricos, coriandro </p><p>Corazón: manzana, geranio, hoja de palmera, pimienta verde </p><p>Fondo: almizcle, pachulí, vetiver, secoya roja brasileña</p>', 18800, 3, 'Nautica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-1319-71db-a165-49f9903a7b78.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc01-f9ce-70ae-ba72-66407b8c8529.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Nautica Voyage Sport es una fragancia masculina fresca, acuática y amaderada, lanzada en 2016 como una versión más deportiva y cítrica del original Voyage. Ideal para uso diario, especialmente ideal para climas cálidos y actividades al aire libre</p>', NULL),
(12579, 'MONTBLANC LEGEND SPIRIT 100ML', '<p>Notas de salida: Pomelo, bergamota y pimienta rosa.</p><p>Notas de corazón: Lavanda, cardamomo y notas acuáticas.</p><p>Notas de fondo: Almizcle blanco, maderas blancas, madera de cachemira y musgo de roble.</p>', 30500, 0, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-0d4a-773b-ba3f-cbef95c60fdf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-0c00-732b-9fad-651a2cfd03c2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c318-fa68-728f-9686-f478a6fd6e31.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Montblanc Legend Spirit es una fragancia masculina lanzada en 2016, creada por los perfumistas Olivier Cresp y Nathalie Lorson. Pertenece a la familia olfativa amaderada aromática y está diseñada para hombres que buscan una fragancia fresca, elegante y versátil. Ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12580, 'Nautica Blue 100ml EDT Hombre', '<p>Salida: piña, bergamota, durazno (melocotón)</p><p>Corazón: lirio de agua (nenúfar), jazmín </p><p>Fondo: sándalo, almizcle, cedro</p>', 13800, 0, 'Nautica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-0a93-701c-8f29-c71b8e1090bb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cbff-97b6-75da-9768-6696094c440a.png?storeId=1681', 'Hombre', 1, 0, '<p>Nautica Blue, lanzada en 2005 y creada por Maurice Roucel, es una fragancia masculina aromática‑acuática fresca y energizante. Evoca la brisa marina y la vitalidad del mar, perfecta para el día a día durante climas cálidos o actividades al aire libre</p>', NULL),
(12581, 'Body Mist VICTORIA SECRET Velvet Petals', '<p>Notas de salida: Almendra azucarada, fruta estrella.</p><p>Notas de corazón: Leche de coco, flor de loto azul, flor de albaricoquero.</p><p>Notas de fondo: Sándalo, almizcles, vainilla de Madagascar</p>', 11800, 10, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-0844-76bb-9fcc-20cc322fa9b8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-95dc-73f4-8e32-050516879dc9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-51a1-77ff-a5e7-e143ed070dc6.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Velvet Petals es una fragancia floral dulce y cremosa que combina notas de almendra azucarada, flor de loto y vainilla de Madagascar. Es ideal para quienes buscan una fragancia femenina, cálida y reconfortante.</p>', NULL),
(12582, 'Kenzo Flower By Kenzo 100ml Mujer', '<p>Notas de salida: Rosa de Bulgaria (rosa Damascena), flor del espino, grosellas negras y mandarina.</p><p>Notas de corazón: Violeta de Parma, rosa, opopónaco y jazmín.</p><p>Notas de fondo: Vainilla, almizcle blanco e incienso</p>', 46000, 1, 'Kenzo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-0517-7798-b277-128e4b549210.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccda-dfa2-7289-90df-84bb416e50fd.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Flower by Kenzo es una fragancia femenina lanzada en el año 2000, creada por los perfumistas Alberto Morillas y Christian Dussoulier. Esta fragancia pertenece a la familia olfativa Ámbar Floral y está inspirada en la amapola, una flor sin aroma que florece en lugares inesperados, simbolizando la belleza en medio del caos urbano. Es ideal para el uso diario, especialmente en climas frescos y durante las estaciones de otoño e invierno</p>', NULL),
(12583, 'Versace Pour Homme EDT 100ml Hombre', '<p>Notas de salida: bergamota, neroli, cidra de diamante, hojas de naranja amarga</p><p>Notas de corazón: geranio, salvia, jacinto azul, madera de cedro</p><p>Notas de fondo: madera, ámbar mineral, haba tonka, almizcle</p>', 42500, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-0442-72b9-aa60-282bbec58b3a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6af1-7dae-724f-a38a-b3d349da43bf.png?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia masculina fresca y sofisticada que combina notas cítricas y florales con una base amaderada y ligeramente especiada. Ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12584, 'Jean Paul Gaultier Le Male Elixir 125ml Hombre', '<p>Notas de salida: Lavanda, menta, bergamota</p><p>Notas de corazón: Vainilla, benjuí</p><p>Notas de fondo: Miel, haba tonka, tabaco</p>', 69500, 3, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976078-01fa-773c-a4f4-a0e913a18606.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3e8-e4f4-757b-ab8a-bf287ee4172d.png?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Le Male Elixir es una fragancia masculina lanzada en 2023 como una versión más intensa y seductora del clásico Le Male. Esta edición en Eau de Parfum se caracteriza por una combinación de notas aromáticas, dulces y especiadas, ofreciendo una experiencia olfativa profunda y envolvente.</p>', NULL),
(12585, 'Crema Victoria Secret Velvet Petals', '<p>: Flores blancas suaves y frescas</p><p>Melodía principal (Corazón): Almendra cremosa y delicada</p><p>Ritmo final (Fondo): Toques suaves de vainilla y sándalo que dan calidez y profundidad</p>', 11800, 2, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-fe5f-740c-963b-bed3e4babd44.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-993f-753c-801e-d4ba1987b4cd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31b-4ea8-7006-bcfd-8f77354987a0.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Victoria’s Secret Velvet Petals es una crema corporal ligera y de rápida absorción que hidrata profundamente mientras deja un aroma dulce y floral con notas cremosas de almendra y vainilla, ideal para un toque femenino y elegante en tu rutina diaria.</p>', NULL),
(12586, 'Carolina Herrera CH 100ml EDT Mujer', '<p>Salida: Frutas tropicales, bergamota, toronja, limón de Amalfi y notas acuáticas.</p><p>Corazón: Praliné, canela, flor de azahar, jazmín y tintura de rosa.</p><p>Fondo: Ante, pachulí, madera de cachemira, sándalo, almizcle, cedro de Virginia y ámbar</p>', 56500, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199a5ff-5ce4-7327-976b-6680180613cb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199a5ff-5c91-73be-b9a2-75bbc6d1b314.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina floral chipre lanzada en 2007, creada por los perfumistas Olivier Cresp y Rosendo Mateu. Su aroma combina frescura cítrica con notas florales y una base cálida y amaderada, evocando elegancia y sofisticación.</p>', NULL),
(12587, 'Paris Hilton Can Can 100ml EDP Mujer', '<p>Salida: nectarina jugosa, grose­llas negras y clementina chispeante </p><p>Corazón: orquídea silvestre y flor de azahar del naranjo</p><p>Fondo: ámbar cálido, almizcle sedoso y tonos amaderados</p>', 24000, 2, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-f17c-7670-9bd1-e94bfbf4ef12.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a5631-2561-7788-991a-08d4d2f3d776.png?storeId=1681', 'Mujer', 1, 0, '<p>Paris Hilton Can Can EDP 3.4 oz es una fragancia femenina lanzada en 2007, creada por el perfumista Jean-Claude Delville. Pertenece a la familia floral‑frutal ambarada, diseñada para evocar una sensación juguetona y femenina inspirada en el ambiente del Moulin Rouge</p>', NULL),
(12588, 'Lacoste Pour Homme EDT 100ml Hombre', '<p>Notas de salida: Mandarina, Manzana roja, Frambuesa negra (zarzamora)</p><p>Notas de corazón: Macaron, Algodón de azúcar, Lirio de los valles (muguete)</p><p>Notas de fondo: Almizcle, Vetiver, Madera de cachemira, Pachulí</p>', 44500, 0, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-dfc1-76fe-a8f4-5803f3ce3593.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc9a-180a-713d-ab07-eb43b62a7b71.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Esta fragancia pertenece a la familia olfativa Floral Frutal Gourmand y fue lanzada en 2015. Su composición combina notas dulces y afrutadas con un toque floral y un fondo amaderado, ofreciendo una experiencia olfativa alegre y sofisticada.</p>', NULL),
(12589, 'Disney Princesa Ariel EDT 100ml Niña', '<p>Salida: cáscara de naranja y notas verdes/frutales (también se mencionan neroli, bergamota y frutos rojos) </p><p>Corazón: flor de azahar (lirio de los valles), jazmín y violeta (y ocasionalmente lilac) </p><p>Fondo: praliné, almizcle y notas amaderadas (tono dulce y tierno)</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-c0bf-731f-aa80-bd6527d4b169.png?storeId=1681', 'Niños', 1, 0, '<p>Una fragancia fresca y juvenil inspirada en Ariel, La Sirenita, diseñada para niñas que sueñan con el océano. Presenta un perfil aromático brillante y divertido, ideal para uso diario o como expresión de alegría infantil.</p>', NULL),
(12590, 'Tous Baby Pink Friends EDC 100ml Niña', '<p>Notas de salida: Bergamota, neroli y frambuesa.</p><p>Notas de corazón: Magnolia, flor de azahar del naranjo y peonía.</p><p>Notas de fondo: Almizcle, madera de cedro y heliotropo.</p>', 20800, 1, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-c9eb-75e9-8da8-49cd8e1bb583.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd81-cb1b-71e6-9a08-b17e53c05aaf.png?storeId=1681', 'Niños', 1, 0, '<p>Una fragancia fresca y delicada, ideal para niñas y adolescentes. Con una combinación de notas florales y frutales, ofrece una esencia suave y encantadora, perfecta para el uso diario.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12591, 'Body Mist Paris Hilton 200ml Mujer', '<p>Notas de salida: Manzana verde, durazno y melón.</p><p>Notas de corazón: Mimosa, tuberosa, lirio, lirio de los valles, jazmín y fresia.</p><p>Notas de fondo: Sándalo, almizcle, musgo de roble y ylang-ylang</p>', 7800, 5, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-c097-714e-b324-3389dd1783e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-afd2-72fc-92d3-6375ccb3e598.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-c5af-729a-9144-6de7eba18c12.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Paris Hilton 8.0 oz es una fragancia femenina fresca y floral, diseñada para capturar la esencia de la personalidad y estilo de vida de Paris Hilton. Esta bruma corporal es ligera y perfecta para el uso diario, ofreciendo una experiencia sensorial envolvente.</p>', NULL),
(12592, 'Set Giorgio Armani Acqua Di Gio Profondo 2pzas', '<p>Notas de salida: Bergamota, notas marinas y limón.</p><p>Notas de corazón: Salvia, lavanda y geranio.</p><p>Notas de fondo: Incienso, pachulí y madera de cedro.</p>', 72000, 0, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-bc36-7779-969f-57cc6edf6ee4.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-504f-73ef-8ec3-5b203bb1f506.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-3085-70a9-86ed-56dc9638d19b.png?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set masculino que evoca la frescura profunda del océano, combinando intensidad y sofisticación en una fragancia aromática y acuática, acompañada de un producto complementario para una experiencia completa y revitalizante.</p>', NULL),
(12593, 'BODY PINK WARM & COZZY BUBBLY', 'Nota de salida: Champaña rosada (burbujeante y afrutada)\nNota de corazón: Peonía espumosa (floral ligera y chispeante)\nNota de fondo: Vainilla cremosa (dulce, cálida y reconfortante)', 11800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-b455-74eb-949f-67285958f869.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-3cd8-7413-addf-bfbba35d5146.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-2d5d-7288-b507-f62a3cf95e48.jpeg?storeId=1681', NULL, 1, 0, 'Una mezcla envolvente de vainilla suave, toques de peonía espumosa y champaña brillante, que despierta los sentidos y deja una sensación cálida y alegre en la piel. Perfecta para quienes buscan un aroma dulce, femenino y con un giro festivo.', NULL),
(12594, 'Afnan 9PM Rebel EDP 100ml Hombre', '<p>Familia Olfativa: Aromática Frutal</p><p>Notas de Salida: Piña, mandarina y manzana Granny Smith</p><p>Notas de Corazón: Vainilla, cedro y musgo de roble</p><p>Notas de Fondo: Ámbar gris, madera seca, caramelo y almizcle </p><p>Esta fragancia unisex, lanzada en 2024 y creada por el perfumista Gaël Montero, combina una apertura frutal y fresca con un corazón cálido y una base dulce y amaderada, ofreciendo una experiencia olfativa moderna y envolvente.</p>', 28500, 0, 'Afnan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-b203-7732-9c0f-cb381bf4d97c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eac-6ecc-748d-9468-86140a58ebd5.png?storeId=1681', 'Hombre', 1, 0, '<p>Afnan 9PM Rebel es una fragancia intensa, moderna y atrevida, pensada para hombres que buscan destacar con un aroma distintivo y seductor. Se caracteriza por una mezcla audaz de notas dulces, especiadas y amaderadas, que crean una estela cálida y carismática, ideal para salidas nocturnas o climas fríos. Es una evolución más atrevida del clásico 9PM, con un carácter más oscuro y rebelde.</p>', NULL),
(12595, 'Tous L´eau EDP 90ml Mujer', '<p>Salida: Mandarina y limón de Amalfi.</p><p>Corazón: Fresia, peonía blanca, grosella negra y jazmín.</p><p>Fondo: Almizcle, ámbar y pachulí.</p>', 28000, 0, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-ab36-774e-8b62-392544376787.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd84-d819-7699-bdaa-c033eff38176.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y femenina que combina notas cítricas con un corazón floral y un fondo almizclado, creando una esencia limpia y elegante, ideal para el uso diario.</p>', NULL),
(12596, 'BODY PINK SOFT & DREAMY', 'alida: delicadas violetas y pétalos de peonía fresca, creando un aroma suave y etéreo .\nCorazón: acorde limpio y acogedor con maderas suavemente besadas por el sol', 11800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-a101-74a5-ad86-361fa441e34f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-483c-75cd-8772-3a612eb2d06c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-dd25-7682-b626-228915b3a270.jpeg?storeId=1681', NULL, 1, 0, 'Pink Soft & Dreamy es una bruma delicada y femenina, perfecta para quienes buscan un aroma florescente, acogedor y no invasivo, con un rendimiento notable dentro de los body mists. Ideal para llevar en el bolso, rociar tras la ducha o en capas suaves varias veces al día.', NULL),
(12597, 'MAISON ALHAMBRA SALVO INTENSE EDP 100ML', 'Salida: bergamota (de Calabria), mandarina, pimienta de Sichuan, anís estrellado \nCorazón: lavanda, nuez moscada \nFondo: ambroxán, vainilla (y toques amaderados y ámbar)', 21000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-9c75-707d-ad91-643102d0796d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-a508-7709-b025-e1533daa906e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-db9c-769f-bbf5-0ddf75d99d41.jpeg?storeId=1681', NULL, 1, 0, 'Salvo Intense es una fragancia masculina intensa y especiada, inspirada en Dior Sauvage EDP. Ofrece una apertura cítrica y especiada que evoluciona hacia un corazón aromático amaderado, con un fondo cálido de ambroxán y vainilla. Ideal para quienes buscan una opción asequible con estilo nocturno y urbano.', NULL),
(12598, 'Carolina Herrera 212 Sexy 100ml EDP Mujer', '<p>Pimienta rosa, mandarina y bergamota — chispeante y fresca con un punto especiado. </p><p>Melodía principal (Corazón): Gardenia, algodón de azúcar, geranio, rosa y flores blancas — dulce, floral y cautivador. </p><p>Ritmo final (Fondo): Vainilla, almizcle, sándalo, caramelo, pachulí y violeta — cálido, cremoso y envolvente.</p>', 54500, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-9a47-702f-84ff-031ddff85d84.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-7a78-712f-ae3c-3b4cad38c58b.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia seductora y femenina con un estilo oriental-floral gourmand, ideal para la noche o eventos especiales. Su aroma combina un toque dulce y picante que resulta sofisticado y magnético.</p>', NULL),
(12599, 'Armaf Club De Nuit Intense 105ml Parfum (Limited Edition 2023)', '<p>Familia: Amaderado‑cítrico con toque fumado y afrutado</p><p>Salida: piña dulce, limón, manzana, bergamota y grosella negra dan un inicio fresco y vibrante </p><p>Corazón: jazmín, rosa y lirio de los valles sobre un corazón ahumado (brezo/birch) </p><p>Fondo: ámbar gris, almizcle, pachulí, vainilla y cedro redondean la fragancia con calidez y profundidad</p>', 47800, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-96d4-700a-bdc2-987d2131a261.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-21cc-75f6-a4ac-0855d1e136ce.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c318-ed76-761e-a4ab-c5370f8c9594.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Club de Nuit Intense Parfum comienza con un acorde frutal‑cítrico potente, evoluciona a un corazón floral-smoky y concluye en una base amaderada-ambarada embriagadora. Es un clon accesible y sofisticado que remite al estilo Creed Aventus, dejando una estela masculina y elegante.</p>', NULL),
(12600, 'Set Hugo Boss Boss Bottled Men 3PC', 'Notas de salida: Manzana, bergamota y canela.\nNotas de corazón: Clavel, geranio y cedro.\nNotas de fondo: Vainilla, sándalo y vetiver.', 58000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-94af-74da-a1aa-d80999a0cf8a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-79bc-751a-a57b-3a4b0ed4e56f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-420c-72bb-a1ac-77a2ef21560f.jpeg?storeId=1681', NULL, 1, 0, 'Un set clásico y elegante que reúne la esencia del hombre moderno con una fragancia cálida, amaderada y fresca, acompañada de productos que prolongan y potencian su aroma distintivo.', NULL),
(12601, 'Liz Claiborne Curve Sport 125ml EDT Hombre', '<p>Manzana roja, bergamota y romero </p><p>Melodía principal (Corazón): Lavanda, cardamomo y salvia esclarea</p><p>Ritmo final (Fondo): Sándalo, vetiver, musgo y tabaco</p>', 21500, 12, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-903a-7017-a59d-ed516339706e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886e0-ab26-717d-9a70-81df41ae0e62.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y masculina de la familia amaderada-aromática, con un balance limpio y deportivo, perfecta para el día a día y climas cálidos. Proyección leve, ideal para el gym, oficina y uso casual.</p>', NULL),
(12602, 'LATTAFA HAYAATI FLORENCE EDP100ML', 'Salida: Lichi, pomelo rosa, bayas rojas\nCorazón: Rosa, durazno, cedro\nFondo: Vainilla, praliné, ámbar', 24500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-8d12-751f-9eae-bca39cb607d4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-eff9-725f-9f96-8563519c83e7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-ef24-74cd-b42f-8928d0a3f6da.jpeg?storeId=1681', NULL, 1, 0, 'Ligera y jugosa al inicio, evoluciona hacia un corazón suave de rosa y durazno sobre una base cálida de vainilla y praliné. Equilibra elegancia y frescura; perfecta para primavera-verano o uso diario.', NULL),
(12603, 'Lattafa Hayaati Al Maleky EDP 100ml Unisex', '<p>Salida: Nuez moscada, pimienta rosa, bergamota, jengibre</p><p>Corazón: Cedro, maderas, ládano, incienso</p><p>Fondo: Almizcle, ámbar gris, ámbar</p>', 22500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3ec-cf7a-748d-9721-ab30239dad9a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d3ec-cfe5-7180-98b9-ff7e4f762120.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia unisex ambarada especiada, diseñada como alternativa al popular Phantom de Paco Rabanne. Abre con un cóctel cálido de especias cítricas, evoluciona hacia un corazón amaderado con incienso, y culmina en un fondo rico en almizcle y ámbar</p>', NULL),
(12604, 'Christian Dior Fahrenheit 100ml EDT Hombre', '<p>Sicilian mandarina, bergamota, limón, lavanda, flor de espino, manzanilla, cedro y nuez moscada brillante. </p><p>Melodía principal (Corazón): Violeta (hoja), clavel, jazmín, lirio de los valles, sándalo y cedro, aportando una sensación floral, </p><p>Ritmo final (Fondo): Cuero auténtico, vetiver, ámbar, pachulí, almizcle y haba tonka, creando una estela masculina, terrosa y envolvente.</p>', 65000, 1, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-8498-75ff-9676-8cba3c969f05.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a73b2-a272-7498-a004-0a5cecf760eb.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia icónica amaderada floral almizclada, lanzada en 1988. Destaca por su combinación distintiva de frescura cítrica con una inesperada nota metálica/petrolera, seguida de un corazón floral y una base rica en cuero y resinas. Atemporal, intensa y con carácter.</p>', NULL),
(12605, 'Carolina Herrera Good Girl EDP 80ml Mujer', '<p>Un floral-gourmand sensual, con salida de almendra y café, corazón de jazmín sambac y tuberosa, y base de tonka, cacao y vainilla que aporta calidez y profundidad.</p>', 66500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-801f-771a-b8b4-a06de1dbfabe.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-d0cd-703c-ad62-ea119b76d3a3.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Good Girl encarna la dualidad femenina: floral, dulce y poderosa. Su duración larga y proyección moderada lo hacen ideal para salidas nocturnas, citas o eventos formales. El envase en forma de tacón lo dota de presencia visual. Aunque no es único, es apreciado como opción sensual, contundente y elegante.</p>', NULL),
(12606, 'CREMA VICTORIAS SECRET PASTEL SUGAR SKY', 'Notas dulces de azúcar y frutas suaves\nMelodía principal (Corazón): Toques cremosos y gourmand (vainilla, caramelo)\nRitmo final (Fondo): Base suave y cálida, con toques ambarinos y almizclados', 12800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-7bb9-7616-b1dc-1b219f72bb2a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-fbd9-77ee-a082-5136413aed83.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-3a47-77b6-af49-3946e94d570d.jpeg?storeId=1681', NULL, 1, 0, 'Una crema dulce y fresca que hidrata la piel dejando un aroma delicado y gourmand, inspirado en dulces y frutas suaves, ideal para quienes aman las fragancias juguetonas y femeninas.', NULL),
(12607, 'Tous LoveMe The Onyx 90ml Parfum Mujer', '<p>Salida: Avellanas, pomelo y peonía.</p><p>Corazón: Orquídea negra y heliotropo.</p><p>Fondo: Vainilla, vetiver y sándalo.</p>', 39000, 2, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cec-1c4d-7738-bb5e-23e728465b25.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986cec-bb91-77f4-90bf-fc6a040c2c2a.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral oriental afrutada que combina notas dulces y amaderadas, inspirada en la intensidad de la piedra preciosa ónix. Ideal para ocasiones especiales, ofrece una estela sofisticada y envolvente.</p>', NULL),
(12608, 'Lancome La Vie Est Belle 75ml EDP Mujer', '<p>Notas de salida: Grosella negra, pera.</p><p>Notas de corazón: Iris, jazmín, flor de azahar del naranjo.</p><p>Notas de fondo: Praliné, vainilla, pachulí, haba tonka</p>', 56800, 0, 'Lancome', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-7375-756d-b1a7-e429aa101806.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a52dd-fb0e-7525-9ea6-d89402c0353e.png?storeId=1681', 'Mujer', 1, 0, '<p>La Vie Est Belle es una fragancia floral gourmand que celebra la belleza de la vida. Con una combinación de notas dulces y florales, es un perfume elegante y sofisticado, ideal para mujeres que buscan una fragancia que exude felicidad y feminidad.</p>', NULL),
(12609, 'Versace Bright Crystal 90ml Mujer', '<p>Salida: Yuzu, granada y notas acuáticas.</p><p>Corazón: Peonía, flor de loto y magnolia.</p><p>Fondo: Almizcle, caoba y ámbar.</p>', 43500, 5, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-7097-715c-89a6-2afd82d6de38.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccdd-419f-7160-9441-fddf2a879ca0.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y femenina que combina notas florales y afrutadas, ideal para el uso diario y ocasiones especiales.</p>', NULL),
(12610, 'Body Mist Ariana Grande Thank You Next', '<p>Salida: peras blancas jugosas y frambuesas silvestres — frutales y chispeantes.</p><p>Corazón: coco cremoso y delicados pétalos de rosa rosa — dulces y florales.</p><p>Fondo: almendra y almizcle aterciopelado — cálidos y reconfortantes.</p>', 9000, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a231b-6cc5-70dd-9dab-28bcc35f4122.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Thank U, Next Body Mist es una opción encantadora y accesible para quienes buscan un aroma dulce, afrutado y floral en un formato práctico y ligero. Ideal para quienes prefieren fragancias suaves y fáciles de llevar.</p>', NULL),
(12611, 'MAISON ALHAMBRA LEONIE EDP 100ML', 'Salida: lavanda, mandarina, petitgrain y grosella negra \nCorazón: flor de azahar, lavanda y jazmín \nFondo: almizcle, vainilla, cedro y ámbar gris', 21000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-6ae2-770a-8fc5-5fe217e7bb7f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fc-b55d-757e-8c7f-de535956f074.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-7df7-7726-afed-efb3502dfde0.jpeg?storeId=1681', NULL, 1, 0, 'Maison Alhambra Léonie es una fragancia femenina elegante y sofisticada, inspirada en YSL Libre. Combina notas frescas cítricas y aromáticas con un corazón floral limpio y un fondo dulce-amaderado, creando una estela refinada y moderna', NULL),
(12612, 'Body Mist VICTORIA SECRET Love Spell', '<p>Salida: durazno, manzana roja y flor de cerezo/cherry blossom </p><p>Corazón: lirio de los valles, jazmín blanco y lilac</p><p>Fondo: tamarindo, almizcle suave y maderas claras</p>', 11800, 10, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-63ee-73a2-ae1a-b96a0a2e2fe8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a02-147c-775b-abaf-5b5bbdf743e4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-78b3-768a-83cc-b5aacd86b72e.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Love Spell es un body mist afrutado-floral vibrante y refrescante, ideal para uso diario. Su fragancia combina la dulzura jugosa del durazno y la cereza con un toque limpio y floral, evocando juventud, alegría y nostalgia.</p>', NULL),
(12613, 'POUR LUI OSCAR DE LA RENTA EDT 90ML', 'Notas de salida: aldehídos, alcaravea, bayas de enebro, lavanda, gálbano, albahaca, salvia, anís y bergamota.\nNotas de corazón: ciclamen (violeta persa), clavel, pachulí, canela, vetiver, cedro y geranio.\nNotas de fondo: ládano, cuero, sándalo, almizcle y musgo de roble', 22800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-58d1-7535-83ed-d7fb6e4841d1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-d395-73cc-9efa-094a88a17c99.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-e403-7533-bd11-a9b64780e00a.jpeg?storeId=1681', NULL, 1, 0, 'Oscar de la Renta Pour Lui EDT 90 ml es una fragancia masculina clásica lanzada en 1980. Se destaca por su carácter elegante y sofisticado, siendo ideal para hombres maduros y para ocasiones formales. Su aroma es una mezcla rica y compleja, representativa de la perfumería de finales de los 70 y principios de los 80.', NULL),
(12614, 'Giorgio Armani Acqua Di Gio EDT 100ml Hombre', '<p>Notas de salida: Bergamota de Calabria, neroli, mandarina verde.</p><p>Notas de corazón: Romero, caqui, pachulí de Indonesia.</p><p>Notas de fondo: Almizcle, notas marinas, chipre.</p>', 52000, 1, 'Giorgio Armani', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-56fa-75e3-b29b-550caf6e0b2f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4abd-daa0-7597-87cc-5e570dc29824.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Acqua di Giò es una fragancia masculina icónica lanzada en 1996 por Giorgio Armani. Creada por los perfumistas Alberto Morillas y Annick Menardo, esta Eau de Toilette pertenece a la familia olfativa aromática acuática. Está inspirada en la frescura del mar Mediterráneo y la calidez del sol, ofreciendo una experiencia olfativa limpia, refrescante y elegante.</p>', NULL),
(12615, 'ARMAF CIELO', '<p>Salida: Melón, manzana, bergamota y limón (lima ácida)</p><p><br></p><p>Corazón: Lavanda, violeta y ciprés</p><p><br></p><p>Fondo: Vainilla, almizcle, ámbar y cedro</p>', 22500, 1, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-5397-7322-b11c-d2ed1cc69f1f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-df07-73da-8981-c8af4d7e6196.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-579f-70bd-8c94-78001cf66c56.jpeg?storeId=1681', NULL, 1, 0, '<p>Armaf El Cielo Pour Homme es una fragancia masculina de la familia olfativa cítrica aromática, diseñada para ofrecer una experiencia fresca, juvenil y versátil. Su composición equilibra notas frutales, florales y amaderadas, creando una fragancia ligera y agradable.</p>', NULL),
(12616, 'BODY PINK FRESH & CLEAN', 'Familia olfativa: fresca y limpia con un toque frutal y floral ligero \nSalida: manzana fresca, tangerina y toques de brisa marina con flor de tiaré — una sensación “recién salida de la ducha”\nCorazón/fondo: almizcle blanco suave y ligeros matices florales — aporta suavidad y calidez de fondo', 11800, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-4f83-70fc-8f5e-56e22010e619.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-fd77-7258-9372-d603a4e42d91.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-6a60-701a-8859-892caf92e772.jpeg?storeId=1681', NULL, 1, 0, 'Pink Fresh & Clean es ideal si buscas un body mist ligero, fresco y fácil de usar, con un aroma limpio y revitalizante. Perfecto para el día a día, cuando prefieres algo sencillo que no necesite reaplicaciones intensas.', NULL),
(12617, 'David Off Cool Water Mujer EDT 100ml', '<p>Melón, piña, membrillo, limón/lima, grosella negra, flor de loto, azucena y calone — una apertura jugosa, cítrica y acuática. </p><p>Melodía principal (Corazón):</p><p>Lirio de agua, lirio de los valles, jazmín, rosa, flor de espino y miel — un ramo floral fresco y delicado. </p><p>Ritmo final (Fondo):</p><p>Almizcle, sándalo, vetiver, vainilla, durazno, frambuesa/zarzamora, raíz de violeta — base suave, cremosamente afrutada y amaderad</p>', 22500, 2, 'David Off', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-4857-7772-a4f5-5a6af0d920b6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ed6-6e09-760c-9ea8-1adc0b553962.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia acuática-floral fresca y vibrante, perfecta para el uso diario, especialmente en climas cálidos y veraniegos. Evoca la brisa marina y la sensación de frescura que renueva el ánimo.</p>', NULL),
(12618, 'Joop Pour Homme EDT 200ml Hombre', '<p>Notas de salida: Flor de azahar del naranjo, mandarina, bergamota y limón de Amalfi.</p><p>Notas de corazón: Jazmín, heliotropo, lirio de los valles, cardamomo y canela.</p><p>Notas de fondo: Sándalo, haba tonka, pachulí y vainilla</p>', 28500, 3, 'Joop', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-45e2-77db-8d02-dda809c81a21.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cbf3-761d-73bd-81dc-17b98222e1eb.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Joop! Homme Eau de Toilette 200 ml es una fragancia masculina clásica lanzada en 1989, reconocida por su aroma oriental fougère distintivo. Su composición única ha generado opiniones divididas entre los usuarios, pero sigue siendo una opción popular para quienes buscan una fragancia intensa y duradera.</p>', NULL),
(12619, 'LATTAFA FAKHAR EXTRAIT EDP 100ML', 'Notas de salida: Toronja (pomelo), cardamomo, pimienta rosa\nNotas de corazón: Nardos, notas solares, abrótano\nNotas de fondo: Ámbar, cachemira, cuero, ládano', 28000, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-42d0-7059-bc7b-7f01e7c9610c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-1550-717f-a107-ef24d1811e90.jpeg?storeId=1681', NULL, 1, 0, 'Fakhar Extrait es una fragancia envolvente que inicia con una salida cítrica y especiada, seguida de un corazón floral y cálido. Su base amaderada y animalic le otorga profundidad y sofisticación. Es una opción destacada para quienes buscan una fragancia potente y duradera.', NULL),
(12620, 'LATTAFA HAYATI EDP 100ML', 'Salida: Manzana verde y bergamota\nCorazón: Canela y notas amaderadas\nFondo: Almizcle y vainilla', 24500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-4389-71ad-b7d9-b41951a8d805.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-012a-77eb-8207-61cc50c5fde7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-47a0-7669-851b-feef09bd1942.jpeg?storeId=1681', NULL, 1, 0, 'Inicia brillante y refrescante con un acorde frutal herbal, evoluciona hacia un corazón especiado y amaderado, y se asienta en un fondo cálido, dulce y ambarado .\nPerfecta para uso diario en climas cálidos o templados, y también adecuada para evento casual por su versatilidad', NULL),
(12621, 'NIGHT DE PARIS MOTION EDP 100ML', 'Salida: bergamota, acordes verdes \nCorazón: ámbar, melón, piña, acorde gourmand \nFondo: vainilla, almizcle blanco, notas amaderadas, ámbar', 44500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-3c82-70b9-b7be-1d1ccddb7240.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-7dd5-740a-9495-02a9a6a91e08.jpeg?storeId=1681', NULL, 1, 0, 'Night De Paris Motion (2019) de L’orientale Fragrances es una fragancia unisex oriental‑vainilla que captura la frescura nocturna de una metrópoli cosmopolita. Mezcla acordes vibrantes y frutales con un fondo cálido y sensual, evocando sofisticación y misteriosa energía urbana', NULL),
(12622, 'Givenchy Amarige 100ml EDT Mujer', '<p>Salida: Flor de azahar del naranjo, durazno (melocotón), ciruela, neroli, palo de rosa de Brasil, violeta y mandarina.</p><p>Corazón: Nardos, mimosa, gardenia, ylang-ylang, jazmín, acacia negra (robinia), clavel, grosellas negras, bayas rojas, casia (canela china), rosa y orquídea.</p><p>Fondo: Sándalo, ámbar, notas amaderadas, vainilla, almizcle, haba tonka y cedro</p>', 46500, 0, 'Givenchy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-3bc9-73f1-b0a3-ffbc09dcd28b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e3ab-05f0-70ae-aed2-a7734cef8784.png?storeId=1681', 'Mujer', 1, 0, '<p>Amarige de Givenchy, lanzada en 1991, es una fragancia femenina que celebra la feminidad radiante y llena de alegría. Con su combinación de notas florales y dulces, evoca la frescura y la belleza del Mediterráneo, convirtiéndola en una opción ideal para mujeres que buscan una fragancia clásica y elegante.</p>', NULL),
(12623, 'Paris Hilton For Men EDT 100ml', '<p>Salida: mango tropical, hoja de higuera, acordes acuáticos (“sky air”), pomelo, limón, lima ácida </p><p>Corazón: salvia blanca, albahaca verde, enebro, pimienta rosa, jugo de higuera </p><p>Fondo: ámbar, almizcle, cedro marroquí, pepino fresco</p>', 23500, 2, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-371e-72ee-b34b-e2337f57062d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e355-60bb-767e-bace-92ea4c006b35.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia aromática-afrutada diseñada para el uso diario. Es fresca, ligera y fácil de llevar, perfecta para climas cálidos y planes informales</p>', NULL),
(12624, 'Victorinox Swiss Army Altitude 100ml EDT Hombre', '<p>Notas de salida: bayas de enebro, cedro de Virginia, cilantro</p><p>Notas de corazón: menta, salvia, gálbano</p><p>Notas de fondo: pino suizo, almizcle</p>', 20800, 1, 'Victorinox', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-330d-7723-b796-adc9de27a427.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd60-9fcb-7499-bc8d-04c7e44aa9de.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y natural que evoca la pureza del aire alpino, ideal para hombres activos que buscan una esencia ligera y energizante.</p>', NULL),
(12625, 'Paco Rabanne 1 Million 50ml EDT Hombre', '<p>Notas de salida: mandarina roja, toronja (pomelo) y menta.</p><p>Notas de corazón: canela, notas especiadas y rosa.</p><p>Notas de fondo: ámbar, cuero, notas amaderadas y pachulí hindú.</p>', 42000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-2bd1-74ec-b98e-02042e104cf2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd62-6a91-751b-87b6-5d6efb616760.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Paco Rabanne 1 Million Eau de Toilette 1.7 oz es una fragancia masculina lanzada en 2008 que ha ganado popularidad por su aroma distintivo y su diseño icónico en forma de lingote de oro. Es ideal para hombres que buscan una fragancia audaz y sofisticada, adecuada para ocasiones especiales y uso nocturno.</p>', NULL),
(12626, 'Crema Victoria Secret Aqua Kiss', '<p>Notas de salida: Fresia mojada</p><p>Notas de corazón: Margarita brillante</p>', 11800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-2941-72aa-9807-cc941be2863d.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>La Loción Corporal Aqua Kiss de Victoria\'s Secret es una fragancia femenina de la familia olfativa fresca, lanzada como parte de la colección Fantasies Fragrance. Está diseñada para brindar una experiencia sensorial ligera y revitalizante, ideal para el uso diario.</p>', NULL),
(12627, 'Perry Ellis Reserve EDP 100ml Mujer', '<p>Notas de salida: jengibre, sándalo, manzanilla y pachulí.</p><p>Notas de corazón: violeta, fresia, musgo de roble y flor de loto.</p><p>Notas de fondo: caléndula y rosa</p>', 27000, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976077-1cfe-7228-97a9-fee997006f0a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>El Perry Ellis Reserve Eau de Parfum para mujer (100 ml) es una fragancia lanzada en 2002 que pertenece a la familia olfativa floral oriental. Creada por el perfumista Jean-Louis Grauby, esta fragancia está diseñada para mujeres que buscan una esencia elegante, sofisticada y cálida, ideal para ocasiones especiales o uso diario en climas frescos</p>', NULL),
(12628, 'Azzaro The Most Wanted EDP Intense 100ml Hombre', '<p>Salida: cardamomo vibrante y refinado, aportando un frescor especiado distintivo </p><p>Corazón: acorde cálido y dulce de toffee, ligeramente acaramelado y cremoso </p><p>Fondo: ámberwood amaderado, resinosa y profunda, aporta elegancia y cohesión</p>', 54500, 2, 'Azzaro', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-f678-7238-a6b9-0fb70f64043a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989d2-d9d7-70ca-96bc-7b0225e0a2d5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989d2-d96d-7690-8c75-3aaffaa7d52a.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Azzaro The Most Wanted Intense abre con un golpe especiado fresco  evoluciona hacia un corazón gourmand —rico y dulce— y termina con una base cálida y amaderada. Destaca por sus buenas prestaciones, especialmente en climas fríos y entornos nocturnos, y su perfil seductor y moderno lo hace ideal para quienes buscan un aroma envolvente con carácter.</p>', NULL),
(12629, 'Hugo Boss Man EDT 200ml', '<p>Notas de salida: Manzana verde, menta, albahaca, pomelo</p><p>Notas de corazón: Clavel, salvia, geranio, jazmín</p><p>Notas de fondo: Pachulí, bálsamo de abeto, cedro</p>', 37500, 1, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-e961-7292-912c-ca47c4c71685.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd67-820c-7566-8442-914def36141a.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Hugo Man de Hugo Boss es una fragancia masculina lanzada en 1995, diseñada para hombres que buscan una fragancia fresca, moderna y audaz. Con una combinación de notas herbales, frutales y amaderadas, ofrece una experiencia olfativa energizante y distintiva. Ideal para el uso diario y especialmente en climas cálidos.</p>', NULL),
(12630, 'Kenneth Cole Reaction EDT 100ml', '<p>Melón y sandía jugosos</p><p>Manzana verde crujiente</p><p>Limón y lima vibrantes</p><p>(fragranticamente refrescante desde el primer atomizador)</p>', 27000, 0, 'Kenneth Cole', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-df91-708e-86af-bb9165c060db.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Un aroma juvenil y vibrante que mezcla jugosas frutas verdes y notas acuáticas con una base amaderada suave. Es fresco, versátil y perfecto para días soleados y salidas casuales.</p>', NULL),
(12631, 'Reebok Cool Your Body 100ml EDT Mujer', '<p>Notas de salida: Durazno (melocotón), pera y toronja (pomelo).</p><p>Notas de corazón: Bambú, jazmín y gardenia.</p><p>Notas de fondo: Sándalo y almizcle.</p>', 6800, 2, 'Reebok', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993edf-3c5b-70df-8142-6f8312859b45.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993edf-3f0e-742d-b846-4bc3879d69d1.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral frutal fresca y revitalizante, diseñada para mujeres activas y modernas que buscan un toque de frescura en su día a día.</p>', NULL),
(12632, 'Body Mist Ariana Grande Cloud 200ml', '<p>Salida: lavanda fresca, jugosa pera y bergamota chispeante.</p><p>Corazón: crema de coco, praliné indulgente y orquídea vainilla.</p><p>Fondo: almizcles sensuales y maderas cremosas.</p>', 9500, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988684-e589-76b9-a674-5f80d3670ad9.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Cloud Body Mist es una opción encantadora y accesible para quienes buscan un aroma dulce, afrutado y floral en un formato práctico y ligero. Ideal para quienes prefieren fragancias suaves y fáciles de llevar.</p>', NULL),
(12633, 'Burberry Her 100ml EDP Women', '<p>Fresa Mora</p><p>Cereza negra</p><p>Grosella negra Pera Mandarina Limón</p>', 66000, 0, 'Burberry', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-e6c7-72f0-90ac-70bdd7cd6459.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d13c-c1fe-7167-9c12-43568821105b.png?storeId=1681', 'Mujer', 1, 0, '<p>Burberry Her es una fragancia claramente frutal-gourmand, creada por perfumistas detrás de éxitos como Baccarat Rouge 540, aunque con una personalidad más fresca y juvenil. Tiene un aroma suave a bayas — especialmente fresa, frambuesa, mora y cereza — sobre una base de jazmín, violeta, ámbar, almizcle y maderas .</p>', NULL),
(12634, 'Adidas Best Of The Best 100ml EDP Hombre', '<p>Salida: Lavanda fresca, hojas de violeta y limón (lima ácida), que le dan un inicio limpio, brillante y ligeramente afrutado </p><p>Corazón: Salvia esclarea, manzana fresca y el moderno toque amaderado de cashmeran, que balancean frescura y calidez </p><p>Fondo: Pachulí, vainilla y almizcle, que suavizan la fragancia aportando un secado dulce y acogedor</p>', 9500, 0, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-c904-71be-8142-d1f61185564e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af6f-107d-738b-9736-6bf2d2d17751.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Ideal para adolescentes, uso deportivo o diario, ofrece un perfil limpio-frutal con un toque dulce y amaderado. Perfecto si buscas una opción fresca, accesible y con buena sensación general, aunque no destaque por su durabilidad.</p>', NULL),
(12635, 'Crema Victoria Secret Coconut Passion', '<p>Notas de salida: Emana principalmente coco isleño, evocando calor de playa y arena templada </p><p>Notas de corazón: Una mezcla cremosa de vainilla, complementada con matices suaves de lirio de los valles y aloe </p><p>Notas de fondo: Tonos cálidos y sutilmente amaderados que redondean la fragancia, manteniéndola dulce pero refinada .</p>', 11800, 1, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-c594-727e-9e0f-197a930f663e.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>La Crema corporal Coconut Passion de Victoria’s Secret (también llamada Coco Passion) es una fragancia dulce y tropical que despierta sensaciones veraniegas.</p>', NULL),
(12636, 'Nautica Voyage N-83 EDT 100ml', '<p>Salida: acordes marinos, menta picante, petitgrain/cardamomo (aromatica.cr, countryclubformen.com) </p><p>Corazón: lavanda, cardamomo, nuez moscada (countryclubformen.com, fragflex.com) </p><p>Fondo: almizcle, cedro, sándalo</p>', 16800, 0, 'Nautica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-c75d-71ca-b4fb-743b279b1ef8.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd6d-6e65-76fd-b16b-6f4a2ec92bf9.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Voyage N‑83 (2013) es una fragancia masculina acuática-aromática con un estilo fresco y deportivo, evocando sensaciones marítimas intensas con un toque especiado que la distingue de la versión clásica. </p>', NULL),
(12637, 'Lattafa Haya 100ml EDP Mujer', '<p>Notas de salida: Champán, fresa, rosa, mandarina, naranja sanguina</p><p>Notas de corazón: Gardenia, jazmín, orquídea de vainilla</p><p>Notas de fondo: Ámbar, sándalo, castaña</p>', 22000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-1c02-7677-9875-0786afaa2aab.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd6f-845e-7266-9a6f-71b0187cf3c3.png?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Haya es una fragancia femenina lanzada en 2022 que combina notas frutales, florales y amaderadas, creando una esencia dulce, elegante y sofisticada. Es ideal para quienes buscan un perfume versátil para el día a día o para ocasiones especiales.</p>', NULL),
(12638, 'Crema Victoria Secret Amber Romance', '<p>Notas de salida: Cereza ácida (guinda)</p><p>Notas de corazón: Natilla</p><p>Notas de fondo: Vainilla, sándalo</p>', 11800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-bca1-7411-920d-99c38c4e8c5c.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>La Loción Corporal Amber Romance de Victoria\'s Secret es una fragancia femenina de la familia olfativa oriental vainilla, lanzada en 2003. Es conocida por su aroma cálido, dulce y envolvente, ideal para quienes buscan una fragancia reconfortante y sensual</p>', NULL),
(12639, 'Set Yvest Saint Laurent Y EDP 2Pzas', '<p>Notas de salida: Bergamota, jengibre y manzana.</p><p>Notas de corazón: Salvia, geranio y abedul.</p><p>Notas de fondo: Almizcle blanco, madera de cedro y ámbar gris.</p>', 70500, 0, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-b6f2-71ac-8fd1-70fd9faa26a9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-c590-71df-a365-4a08cdd34a6a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c318-e409-766c-bd73-a58a6cc1a8d8.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set moderno y audaz que captura la esencia del hombre contemporáneo, con una fragancia fresca, aromática y sofisticada, ideal para quienes buscan un aroma elegante y lleno de energía.</p>', NULL),
(12640, 'Juicy Couture Viva La Juicy 100ml EDP Mujer', '<p>Notas de salida </p><p>Bayas silvestres</p><p>Mandarina</p><p>Notas de corazón </p><p>Gardenia</p><p>Madreselva</p><p>Jazmín</p><p>Notas de fondo </p><p>Caramelo</p><p>Praliné</p><p>Vainilla</p><p>Ámbar</p><p>Sándalo</p>', 33800, 1, 'Juicy Couture', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-b45a-76d2-9907-f679bfe9cb68.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd72-d074-72ea-8621-9fe37213f1bd.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Viva La Juicy (lanzada en 2008) es una fragancia floral frutal gourmand emblemática de Juicy Couture. Con una mezcla apta para cualquier momento del día, presenta un aroma dulce, juvenil y femenino que se ha convertido en un clásico moderno</p>', NULL),
(12641, 'Tous Baby 100ml EDC Unisex', '<p>Notas de salida: Neroli, mandarina y bergamota.</p><p>Notas de corazón: Flor de azahar del naranjo, pera, manzana y rosa.</p><p>Notas de fondo: Almizcle, petit grain y cedro.</p>', 19800, 0, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-b032-70f9-91b1-8f374536730e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd76-1a63-72f2-835d-7cb3ab56bd03.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Una fragancia fresca y suave que evoca la ternura y pureza de la infancia. Con una combinación de notas cítricas, florales y almizcladas, es ideal para el uso diario, ofreciendo una sensación de limpieza y confort.</p>', NULL),
(12642, 'Hugo Boss Deep Red EDP 90ml Mujer', '<p>Notas de salida: Pera, naranja sanguina, mandarina, grosella negra</p><p>Notas de corazón: Jengibre, flor de jengibre, nardos, fresia, semillas de hibisco</p><p>Notas de fondo: Vainilla, sándalo, almizcle, cedro de California</p>', 27500, 1, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-acf1-70e1-96e5-3a440f526d8a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd77-fe2e-718b-a718-0404b57d6ae9.png?storeId=1681', 'Mujer', 1, 0, '<p>Hugo Boss Deep Red es una fragancia femenina lanzada en 2001, diseñada para mujeres audaces, sensuales y seguras de sí mismas. Con una combinación de notas frutales, florales y amaderadas, esta fragancia ofrece una experiencia olfativa intensa y envolvente, ideal para la noche y ocasiones especiales.</p>', NULL),
(12643, 'Body Mist Britney Spears Midnight Fantasy 8.0 Sp Women', '<p>Notas de salida: Cereza negra, frambuesa, ciruela.</p><p>Notas de corazón: Orquídea nocturna, freesia, iris.</p><p>Notas de fondo: Ámbar, almizcle, vainilla</p>', 7800, 7, 'Britney Spears', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-a66c-732a-b067-104d1d4baf87.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-1116-704e-bf0c-aaf0a41a1639.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-599d-7403-8cf3-318495af5d39.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Britney Spears Midnight Fantasy 8.0 oz es una fragancia femenina lanzada en 2006 como parte de la línea Fantasy de la cantante. Esta versión en spray corporal ofrece una experiencia sensorial envolvente y dulce, ideal para quienes buscan una fragancia ligera y accesible</p>', NULL),
(12644, 'Body Mist Pink Bronzed Coconut', '<p>Salida: mango jugoso y notas tropicales radiantes – frescas y frutales </p><p>Corazón: pétalos de tiare (flor de Tahití) que añaden un toque floral delicado </p><p>Fondo: coco tostado cremoso y sándalo suave – evocan bronceado, espuma de playa y calidez solar</p>', 11800, 1, 'Pink', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-a3d3-70c8-9258-ed0a493504c6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-3a85-7398-bcd1-f2dc28a5ca71.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-79c4-725d-8926-365b0857c852.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pink Bronzed Coconut Mist es ideal si buscas una bruma corporal ligera que evoque sol, playa y una atmósfera veraniega acogedora. Su fragancia tropical con coco tostado y flores exóticas lo convierten en una elección encantadora para el calor, aunque su rendimiento no rivaliza con un EDP: se disfruta por su frescura y sensación más que por durabilidad.</p>', NULL),
(12645, 'Ralph Lauren RALPH 100ml EDT Mujer', '<p>Flor de cactus nocturna: fresca y ligeramente exótica</p><p>Lirio de los valles (muguete): blanca, limpia y primaveral</p><p>Casia (canela suave): un toque especiado y acogedor</p><p>Violeta: dulce, suave y ligeramente empolvada</p>', 41000, 2, 'Ralph Lauren', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-9f89-722e-aafe-44cd6d02e06f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d07b-62f0-71aa-8b71-9c547f794758.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y sofisticada que combina notas florales blancas con matices verdes, resina de ron y una pizca de cuero, evocando sensación de elegancia audaz y femenina, ideal para mujeres seguras y únicas.</p>', NULL),
(12646, 'Crema Victoria Secret Love Spell', '<p>Salida: durazno, cerezo (cherry blossom/flower), manzana roja — una entrada afrutada fresca y jugosa </p><p>Corazón: lilas, jazmín blanco y lirio de los valles — florales suaves que equilibran el dulzor </p><p>Fondo: tamarindo, almizcle y maderas blancas — una base ligeramente exótica</p>', 11800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-9b82-7062-81a1-9a34708f50bf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-d497-7099-b1bf-20a0a8236541.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-e755-77cf-a73e-2cbce716beaf.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Aroma: frutal‑floral dulce con una base suave de almizcle y maderas.</p><p>Ideal para: quienes buscan una fragancia ligera, fresca y evocadora de nostalgia.</p><p>Destacada por: su versatilidad, frescura y el respaldo de una gran legión de fans — aunque no es del gusto de todos.</p>', NULL),
(12647, 'Cuba La Vida Mujer', '<p>Notas de salida: Pera, grosellas negras</p><p>Notas de corazón: Iris, flor de azahar del naranjo, jazmín</p><p>Notas de fondo: Pachulí, vainilla, haba tonka, pralin</p>', 5800, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-97b3-7732-843e-c303235bf479.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-c610-741d-9d88-b448ac8b2672.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-4453-754d-a3ae-6cbf04063865.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral afrutada lanzada en 2019 por Cuba Paris. Inspirada en perfumes icónicos como La Vie Est Belle de Lancôme, ofrece una experiencia dulce, femenina y elegante a un precio accion</p>', NULL),
(12648, 'Santos De Cartier EDT 100ml Hombre', '<p>Notas de salida: Lavanda, bayas de enebro, albahaca, cedrón (hierba luisa), bergamota, gálbano y nerolí.</p><p>Notas de corazón: Pimienta, nuez moscada, vetiver, romero, geranio, esclarea y clavos de olor.</p><p>Notas de fondo: Sándalo, ámbar, coco, pachulí, vainilla y cedro.</p>', 38800, 0, 'Cartier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-943d-71af-973e-1d3ea92c04b7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd7c-bfe3-7618-9377-7fc29262a8a5.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina de la familia olfativa amaderada especiada, lanzada en 1981, que combina notas frescas y especiadas con una base cálida y amaderada, ideal para hombres que buscan una fragancia sofisticada y duradera.</p>', NULL),
(12649, 'Moschino Toy 2 100ml EDP Mujer', '<p>Salida: manzana, mandarina, magnolia </p><p>Corazón: grosella blanca, peonía, jazmín </p><p>Fondo: almizcle, amberwood (ambramadera), sándalo</p>', 38500, 4, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-8ce1-701e-9b90-9a8f9c83a06a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eeb-32ab-71db-b532-af173e91bc12.png?storeId=1681', 'Mujer', 1, 0, '<p>Moschino Toy 2 (2018) es una fragancia femenina que equilibra lo frutal, floral y almizclado. Creada por Alberto Morillas y Fabrice Pellegrin, es fresca y versátil, perfecta para el día a día en ambientes cálidos.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12650, 'Body Spray Odyssey Aqua', '<p>Salida: cítricos refrescantes — pomelo, naranja y artemisia / abrótano </p><p>Corazón: menta herbal y lavanda aromática</p><p>Fondo: cypres, pachulí y ambroxan, creando un fondo amaderado limpio y duradero</p>', 5500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-8b91-71ce-876e-7e0876cd292f.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-eb59-7357-8a2c-9d9e612eca2f.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-146f-77cd-9fbc-3d33e555d65b.png?storeId=1681', 'Hombre', 1, 0, '<p>Odyssey Aqua es un body spray versátil y asequible, inspirado en Paco Rabanne Invictus Platinum. Ofrece una explosión de frescura cítrica-mentolada seguida de un fondo amaderado limpio. Su rendimiento es sobresaliente para su precio, con proyección notable y duración prolongada. Eso sí, su apertura puede resultar fuerte para algunos, y conviene darle algo de reposo después de la compra.</p>', NULL),
(12651, 'Body Mist Ariana Grande Sweet Like Candy', '<p>Salida: frambuesa, pera y bergamota italiana — frutales, jugosas y chispeantes.</p><p>Corazón: crema de cassis, jazmín sambac, frangipani y madreselva — dulces, florales y envolventes.</p><p>Fondo: malvavisco, maderas de cashmere y vainilla sexy — cálidos, cremosos y reconfortantes.</p>', 9000, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f87-a3e5-740a-993f-11354cf19512.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Sweet Like Candy Body Mist es una opción encantadora y accesible para quienes buscan un aroma dulce, afrutado y floral en un formato práctico y ligero. Ideal para quienes prefieren fragancias suaves y fáciles de llevar.</p>', NULL),
(12652, 'Calvin Klein Ck Be 200ml EDT Unisex', '<p>Intro (Salida): Lavanda, bergamota, mandarina, menta, baye de enebro y notas verdes </p><p>Melodía central (Corazón): Fresia, magnolia, orquídea, jazmín, durazno y hierbas verdes </p><p>Ritmo final (Fondo): Sándalo, cedro, opopónax, almizcle, ámbar, vainilla y haba tonka</p>', 26000, 2, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-81ff-74ae-aec0-a7023841385c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ed0-ddb6-74f0-b443-5588ec6e8203.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Una fragancia fresca, ligera y versátil, diseñada para ser una expresión de libertad e individualidad. Su aroma limpio combina toques herbales, cítricos y suaves notas florales, rematadas por una base almizclada y amaderada — perfecta para uso diario, en cualquier momento del año</p>', NULL),
(12653, 'Set Ariana Grande Moonlight 3PC Women', '<p>Notas de salida: Frambuesa, pera y bergamota.</p><p>Notas de corazón: Jazmín, iris y flor de azahar.</p><p>Notas de fondo: Almizcle, vainilla y madera de cachemira.</p>', 39500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-898d-770b-9793-dd77ec848029.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-5941-7118-829a-1dbb026bfc70.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-d10a-709e-8d26-0bf2d8fb0ea0.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set encantador que envuelve en una fragancia dulce y fresca, perfecta para mujeres que buscan un aroma delicado, floral y afrutado, ideal para el día a día con un toque de magia y ternura.</p>', NULL),
(12654, 'Mont Blanc Starwalker 75ml Hombre', '<p>Salida: bambú, bergamota, mandarina </p><p>Corazón: sándalo, almizcle blanco, cedro </p><p>Fondo: jengibre, nuez moscada, resina de abeto, ámbar</p>', 23500, 2, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-7934-70dc-9df5-b1f84ab8b785.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a9e35-969b-75cb-8bb2-97b6fe92edc8.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Starwalker es una fragancia masculina fresca y amaderada con un carácter elegante y juvenil, diseñada para el uso diario. Combina notas cítricas, bambú y especias ligeras, perfectas para climas templados y veraniegos.</p>', NULL),
(12655, 'Body Mist Perry Ellis 360 Pink Mujer', '<p>Salida: azucena, rosa, osmanto y flor de mandarina — una apertura fresca y floral con un toque cítrico </p><p>Corazón: flor de loto, lirio de los valles, lavanda y salvia — delicado y femenino </p><p>Fondo: vainilla, sándalo, almizcle, vetiver y ámbar — un cierre suave, cálido y reconfortante</p>', 8500, 0, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-752c-7198-af9d-c715ea49d12a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-4a6c-7702-9070-38289fafb81e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-1f08-74eb-9f97-fd345eae31ce.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El 360 Pink Body Mist es una opción económica, versátil y femenina si buscas un aroma floral‑amaderado con dulce frescor. Ideal para climas cálidos y para quienes prefieren brumas corporales suaves y fáciles de reaplicar.</p>', NULL),
(12656, 'Perry Ellis Very Blue EDT 100ml Hombre', '<p>Notas de salida: bergamota italiana, ozono crujiente, pera blanca y menta verde.</p><p>Notas de corazón: lavanda inglesa, hoja de violeta y abedul fresco.</p><p>Notas de fondo: sándalo indonesio, musgo de árbol, cristales de ámbar, haba tonka y almizcle sensual.</p>', 24500, 2, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-70c7-778d-bf71-ced2a39ca5b9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-0c07-7210-b005-365c119a6f2f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-b281-7608-bd9a-07d05e616910.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>El Perry Ellis 360° Very Blue para Hombre es una fragancia fresca y moderna lanzada en 2017, que forma parte de la clásica colección 360° de Perry Ellis. Diseñada para hombres activos y elegantes, ofrece una combinación de notas cítricas, marinas y amaderadas, creando una esencia ligera y sofisticada ideal para el día a día</p>', NULL),
(12657, 'Jesús Del Pozo Halloween Clásica 100ml EDT Mujer', '<p>Salida: Petitgrain, violeta, hoja de plátano, acordes marinos </p><p>Corazón: Tuberosa, magnolia, lirio de los valles, violeta, pimienta rosa </p><p>Fondo: Sándalo, incienso, mirra, vainilla de Madagascar</p>', 23800, 4, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-6dda-75e2-a532-0f990e640652.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bb29-4f69-71ca-8f3a-5af724ba121c.png?storeId=1681', 'Mujer', 1, 0, '<p>Halloween es una fragancia femenina lanzada en 1997 por Jesús del Pozo, diseñada para la mujer misteriosa y seductora. Su aroma fresco-floral, con un ligero toque oriental, es elegante y versátil para el día y la noche.</p>', NULL),
(12658, 'Nautica Classic 100ml EDT Hombre', '<p>Salida: aldehídos, lima (limón verde), bergamota, limón ácido, nerolí, ciprés, estragón, salvia esclarea, cilantro y canela </p><p>Corazón: jazmín, ciclamen (violeta persa), rosa, alcaravea y geranio </p><p>Fondo: sándalo, cedro, almizcle, pachulí, musgo de roble y ámbar</p>', 14800, 0, 'Nautica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-69fc-7117-b6d9-f0be5a63ae44.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc06-4965-7500-a21c-dc0511669640.png?storeId=1681', 'Hombre', 1, 0, '<p>Nautica Classic (1992) es una fragancia masculina de la familia olfativa amaderada-chipre. Evoca una mezcla limpia y fresca con matices cítricos, especiados y marinos, perfecta para uso diario</p>', NULL),
(12659, 'Body Mist VICTORIA´S SECRET Aqua Kiss', '<p>Notas de salida: Goji berry, pomelo rosado, pepino.</p><p>Notas de corazón: Melón Kiwano, sapote, lirio, rosa azul, osmanthus.</p><p>Notas de fondo: Alga marina, ámbar blanco, almizcle</p>', 11800, 9, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-68d9-7388-bb0a-cdd2c73749fc.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f4-e394-734c-9a4d-1dd76a202e7f.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-762c-726d-b0be-0e574f9258ee.png?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Victoria’s Secret Aqua Kiss es una fragancia fresca y ligera, ideal para el uso diario, especialmente en climas cálidos. Su aroma evoca la sensación de frescura y limpieza, similar a la de un baño refrescante.</p>', NULL),
(12660, 'Body Spray Lattafa Khamrah', '<p>Salida: canela, nuez moscada y bergamota — especiada, cálida y vibrante </p><p>Corazón: dátiles, praliné, tuberosa, nardos y mahonial (acorde floral-blanco) — dulce y sofisticado </p><p>Fondo: vainilla, haba tonka, benjuí, ámbar, mirra, Akigalawood (madera resinosa) — envolvente y adictivo</p>', 4500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-c87d-7748-933e-560c3c23744d.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Khamrah Body Spray es una fragancia unisex cálida y adictiva, con un aroma especiado y dulce que recuerda a un pastel de canela. Combina notas de canela, praliné, vainilla y ámbar, creando una estela envolvente y sofisticada. Ideal para climas fríos o noches especiales, destaca por su excelente duración y proyección.</p>', NULL),
(12661, 'Antonio Banderas Black Seduction 100ml EDT Hombre', '<p><strong>Salida:</strong> bergamota y grosella negra — fresco, frutal y ligeramente amargo </p><p><strong>Corazón:</strong> cardamomo, nuez moscada y cilantro — cálido, especiado y refinado</p><p><strong>Fondo:</strong> ámbar, haba tonka, cedro de Virginia y almizcle — envolvente, amaderado y sensual</p>', 17500, 2, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198d8f0-943a-76cf-9d10-2bdbc322be9a.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198d8f0-950b-741e-bdfc-6555f0e42aad.png?storeId=1681', 'Hombre', 1, 0, '<p>Un eau de toilette audaz y moderno, que ofrece una combinación atractiva de frescor frutal, especias aromáticas y fondo cálido-amaderado. Ideal para hombres jóvenes o quienes buscan proyectar confianza y seducción sin exceso, a un precio accesible. Su punto débil es la longevidad, pero su equilibrio entre aroma y precio lo convierte en una opción popular.</p>', NULL),
(12662, 'Paco Rabanne Fame 80ml EDP Mujer', '<p>Salida (Top): mango jugoso, bergamota refrescante y pimienta rosa, que aportan energía y chispa inicial </p><p>Corazón (Middle): un corazón floral-incienso que combina jazmín puro, olíbano (incienso) y pachulí, con un toque ligeramente especiad</p><p>Fondo (Base): una base cálida y envolvente de vainilla cremosa, sándalo suave, benjuí y almizcle, que se asienta con elegancia y</p>', 62800, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-5ed9-700a-bde1-bd8dceb16af4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199d17f-aac6-75fd-9907-574d744ee6d5.png?storeId=1681', 'Mujer', 1, 0, '<p>Fame (2022) es una fragancia femenina del grupo frutal-floral amaderado que busca celebrar la dualidad de la mujer moderna: sofisticada pero sensual. Su estela es vibrante, cálida y elegante, ideal para eventos nocturnos o el día a día con un toque de glamour .</p>', NULL),
(12663, 'Body Mist Ariana Grande Moonlight', '<p>Familia: Floral‑frutal gourmand, suave y seductor</p><p>Salida: jugoso black currant (grosella negra) y plum (ciruela) – fresco, afrutado y chispeante </p><p>Corazón: delicado marshmallow (malvavisco esponjoso) y fresh peony – tierno, suave y ligeramente floral </p><p>Fondo: cremoso y elegante con sandalwood, amber negro y vainilla – cálido, reconfortante y suave</p>', 9000, 2, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a2305-9fbd-74a7-a644-483c0f7d18a7.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Moonlight Body Mist ofrece una experiencia olfativa dulce, afrutada y cremosa en un formato ligero y práctico: ideal para usar a diario sin saturar el ambiente, refrescarse tras la ducha o complementar tu perfume favorito de la línea Moonlight.</p>', NULL),
(12664, 'Tommy Hilfiger EDT 100ml Hombre', '<p>Notas de salida: Menta, lavanda, toronja (pomelo) y bergamota.</p><p>Notas de corazón: Arándano, rosa y manzana Granny Smith.</p><p>Notas de fondo: Ámbar, cactus y flor del algodonero.</p>', 25800, 2, 'Tommy Hilfiger', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-53e3-7688-84f4-ec9620608407.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc59-115a-77e9-91c0-d8ec372104c3.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia clásica y fresca que captura el espíritu juvenil y enérgico del hombre moderno. Con una combinación de notas cítricas y florales, es ideal para el uso diario, ofreciendo una sensación de frescura y vitalidad</p>', NULL),
(12665, 'Set Carolina Herrera Good Girl Blush 50ML + CREMA', '<p>Notas de salida: Mandarina, durazno y grosella roja.</p><p>Notas de corazón: Jazmín sambac, gardenia y rosa.</p><p>Notas de fondo: Almizcle blanco y ámbar gris.</p>', 66500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-5765-75fc-8d3b-96cfd583eb09.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f7-34a1-769c-9d79-b551422d4761.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-6581-74da-adf0-506c3a2e6d4b.png?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set femenino y sofisticado que combina la intensidad y dulzura de Good Girl Blush con una crema corporal nutritiva, para una experiencia sensorial completa que realza la feminidad y elegancia con un toque fresco y floral</p>', NULL),
(12666, 'Lacoste L12.12 Rose Sparkling EDT 100ml Mujer', '<p>Notas de salida: Mandarina, Manzana roja, Frambuesa negra (zarzamora)</p><p>Notas de corazón: Macaron, Algodón de azúcar, Lirio de los valles (muguete)</p><p>Notas de fondo: Almizcle, Vetiver, Madera de cachemira, Pachulí</p>', 44500, 0, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-0bae-765c-956e-e74824b82a12.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988099-1611-716f-b23d-f13fdbc93201.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lacoste L.12.12 Rose Sparkling es una fragancia femenina de la familia olfativa Floral Frutal Gourmand, lanzada en 2015. Su composición combina notas dulces y afrutadas con un toque floral y un fondo amaderado, ofreciendo una experiencia olfativa alegre y sofisticada.</p>', NULL),
(12667, 'CRISTIANO RONALDO CR7 100ML', 'Notas de salida: Lavanda, cardamomo, bergamota y abrótano.\nNotas de corazón: Tabaco, canela, cedro e iris.\nNotas de fondo: Vainilla, almizcle, sándalo y ámbar.', 25000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976076-001a-704a-bea6-27a21608c6df.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-8783-7309-b615-58c7365b163c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-97db-703e-b4fa-c2bf58f0a70e.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia masculina que combina notas frescas y especiadas con un toque amaderado, ideal para el hombre moderno y seguro de sí mismo.', NULL),
(12668, 'Halloween Man X 125ml EDT Hombre', '<p>Salida: Cardamomo, lavanda, limón (lima ácida) </p><p>Corazón: Café, whisky, canela, cuero, notas minerales </p><p>Fondo: Haba tonka, ámbar, incienso</p>', 24500, 2, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-f544-70ee-b938-e96631b14b12.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd5c-25d8-76ca-8924-a35f4b43346b.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Halloween Man X (2019) es una fragancia masculina de estilo ámbar fougère, que mezcla notas especiadas, gourmand y amaderadas. Está diseñada para hombres dinámicos que buscan una fragancia moderna, original y con carácter. </p>', NULL),
(12669, 'Carolina Herrera 212 VIP 100ml EDT Hombre', '<p>Maracuyá (pasión), lima verde tipo caviar lime, pimienta y jengibre</p><p>Melodía principal (Corazón): Vodka, ginebra, menta fresca y especias</p><p>Ritmo final (Fondo): Ámbar, cuero y notas amaderadas / tonka bean &amp; kingwoo</p>', 52500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-f2aa-703e-9f08-c185f5eae173.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e397-5df3-7466-ba32-e34fc377ea5e.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina oriental amaderada creada en 2011, ideal para salidas nocturnas, fiestas y ambientes sociales. Su aroma boozy y fresco combina frutas exóticas, especias y toques elegantes que transmiten carisma y distinción</p>', NULL),
(12670, 'Set Moschino Toy Boy Men 4PC', '<p>Notas de salida: Bergamota, mandarina y pimienta negra.</p><p>Notas de corazón: Jazmín, lavanda y salvia.</p><p>Notas de fondo: Cedro, pachulí y vainilla.</p>', 50500, 1, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-e77e-73c3-b603-5fb1103ddbbe.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-1d7e-770f-9b6a-886e5d80fafc.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set audaz y sofisticado que combina la frescura cítrica con un carácter amaderado y especiado, ideal para hombres modernos que buscan una fragancia versátil y con personalidad.</p>', NULL),
(12671, 'Moschino Toy Boy 100ml EDP Hombre', '<p>Salida: bergamota (Italia), pera verde, pimienta rosa, nuez moscada de Indonesia, elemi </p><p>Corazón: rosa absoluta, clavo, magnolia, lino/flax flowers </p><p>Fondo: cachemira (cashmeran), vetiver de Haití, sándalo, ambermax (ámbar sintético), sylkolide (almizcle), ámbar</p>', 39500, 3, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-c90f-757d-ac46-c7ca7d3b4b43.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eee-2219-7448-88bd-25ed7d042ac1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Toy Boy (2019) de Moschino es una fragancia masculina (también unisex) con un carácter especiado–amaderado. Su chispa inicial de bergamota y pera evoluciona hacia una rosa intensa y se asienta en una base profunda de vetiver y ámbar, ofreciendo elegancia con un toque audaz. Fue creada por Yann Vasnier y captura la dualidad del hombre: fuerte pero sensible.</p>', NULL),
(12672, 'ARMAF MAGNIFICENT SATIN', 'Familia olfativa: Almizcle - Floral - Frutal\n Notas de salida:\nNotas cítricas\nNotas frutales\n Notas de corazón:\nJazmín\nRosa\n Notas de fondo:\nAlmizcle\nVainilla\nÁmbar\nEsta fragancia unisex combina frescura y calidez, con una base suave y envolvente, ideal para diversas ocasiones', 38500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-e08a-7289-8688-b1d2ed8d5325.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-4acb-73e9-b8b7-84c2d9438ae8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-7269-7638-9f21-3b54ee267b27.jpeg?storeId=1681', NULL, 1, 0, 'Armaf Magnificent Satin es una fragancia masculina sofisticada y envolvente, diseñada para hombres que buscan una esencia elegante y duradera. Combina notas frutales y florales con una base cálida y amaderada, creando un aroma que destaca por su frescura y sensualidad. Ideal para ocasiones especiales o para el uso diario, su estela deja una impresión duradera y refinada', NULL),
(12673, 'LATTAFA JASSOR EDP 100ML', 'Salida: Manzana, bergamota, cardamomo (+ piña en algunas versiones) \nCorazón: Lavanda, tabaco, geranio \nFondo: Haba tonka, cuero, pachulí, vetiver', 28000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-de17-7428-8b5d-054e6b0bee18.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-065a-72fc-9730-698df8e659d9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-9575-70f9-9d2c-d59699c5e5b0.jpeg?storeId=1681', NULL, 1, 0, 'Lattafa Jasoor ofrece una gran relación calidad-precio, combinando frescura frutal, lavanda floral y tabaco con una base cálida amaderada. Perfecta como fragancia unisex para día o noche en climas medianamente frescos, especialmente si te agrada el estilo estilo Coral Fantasy pero buscas ahorrar.', NULL),
(12674, 'Carolina Herrera Good Girl Supreme 80ml EDP Mujer', '<p>Salida: Frutas del bosque y jazmín egipcio — inicio fresco y afrutado.</p><p>Corazón: Haba tonka y nardos — aportan dulzura y un toque floral cremoso.</p><p>Fondo: Vetiver — crea una base terrosa y sofisticada.</p>', 64500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199836e-2155-71fd-95d5-b4e1d9c62998.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199836e-2522-748d-89ff-8a32f6b23abf.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina oriental floral lanzada en 2020, creada por la perfumista Louise Turner. Su aroma combina notas afrutadas y florales con una base cálida y terrosa, evocando elegancia y sofisticación.</p>', NULL),
(12675, 'Dolce & Gabbana Light Blue 125ml EDT Men', '<p>Bergamota</p><p>Pomelo (toronja)</p><p>Mandarina siciliana</p><p>Enebro de Virginia</p><p>Notas de corazón:</p><p>Romero</p><p>Pimienta</p><p>Palo de Rosa de Brasil</p><p>Notas de fondo:</p><p>Almizcle</p><p>Incienso</p>', 39500, 3, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998c9b-f6d5-74c3-89f5-02c037eaed8f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998c9b-f85f-70cc-b18f-1856e6247fb2.png?storeId=1681', 'Hombre', 1, 0, '<p>Light Blue Pour Homme de Dolce &amp; Gabbana es una fragancia masculina que captura la esencia del espíritu aventurero y dinámico del hombre moderno. Inspirada en la frescura del Mediterráneo, esta fragancia ofrece una experiencia sensorial única que evoca la sensualidad de la piel bañada por los rayos del sol y la estimulante brisa marina. Con su combinación de notas cítricas y amaderadas, es ideal para el uso diario, especialmente en climas cálidos y durante las estaciones de primavera y verano .</p>', NULL),
(12676, 'Carolina Herrera Bad Boy 100ml EDT Hombre', '<p>Pimienta blanca, pimienta negra y bergamota verde italiana — inicio fresco y especiado.</p><p>Corazón: Salvia y madera de cedro — aportan profundidad y elegancia.</p><p>Fondo: Haba tonka y cacao — crean un aroma seductor e irresistible.</p>', 61000, 2, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-d000-728e-97b3-2457def71f8a.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199ccaa-ecbb-71a4-a2f9-4a884b30296a.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina oriental aromática lanzada en 2019, diseñada para hombres audaces y seguros de sí mismos. Su aroma combina frescura especiada con una base cálida y dulce, reflejando la dualidad del hombre moderno: fuerte y sensible, rebelde y encantador.</p>', NULL),
(12677, 'Body Mist Paris Hilton Platinum Rush 8.0', '<p>Notas de salida: Pera asiática, manzana roja y mango fresco.</p><p>Notas de corazón: Magnolia, flor de muguet (lirio de los valles) y flores verdes húmedas.</p><p>Notas de fondo: Almizcle de cachemira, pachulí sutil y ámbar líquido.</p>', 7800, 5, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979109-56dc-76dc-974a-355389646f2b.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>l Body Mist Paris Hilton Platinum Rush 8.0 oz es una fragancia femenina que combina notas florales y frutales, diseñada para ofrecer una experiencia sensorial fresca y sofisticada.</p>', NULL),
(12678, 'Liz Claiborne Curve Chill 100ml EDT Mujer', '<p>Salida: Té verde, limón (lima ácida), jengibre</p><p>Corazón: Peonía, guisante de olor, </p><p>Fondo: Almizcle, vetiver, cedro</p>', 14500, 15, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886d7-ea24-7145-b5b4-a68f949d692b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886d7-e91c-708d-9e20-9c174342d36b.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Liz Claiborne Curve Chill es una fragancia femenina fresca y floral, ideal para climas cálidos y ocasiones diurnas. Su combinación de notas cítricas y florales ofrece una sensación de ligereza y vitalidad, mientras que las notas de fondo aportan una base suave y amaderada.</p>', NULL),
(12679, 'Chanel Bleu EDT 100ml Hombre', '<p>Notas de salida: toronja (pomelo), limón (lima ácida), menta y pimienta rosa.</p><p>Notas de corazón: jengibre, nuez moscada, jazmín y Iso E Super.</p><p>Notas de fondo: incienso, vetiver, cedro, sándalo, pachulí, ládano y almizcle blanco.</p>', 92500, 1, 'Chanel', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-c405-721c-8e6b-6800ae984a2c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a17cc-ae28-74d8-b521-2f25b0240342.png?storeId=1681', 'Hombre', 1, 0, '<p>Chanel Bleu Eau de Toilette es una fragancia masculina lanzada en 2010, creada por el perfumista Jacques Polge. Pertenece a la familia olfativa amaderada aromática y está diseñada para evocar frescura, elegancia y libertad.</p>', NULL),
(12680, 'Lattafa Fakhar Lattafa 3.4 EDP Women', '<p>Salida: Frutas, granada, lirio, aldehídos</p><p>Corazón: Tuberosa, gardenia, jazmín, ylang-ylang, peonía, rosa, madreselva</p><p>Fondo: Vainilla, ambroxan, almizcle blanco, sándalo</p>', 25000, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-be9e-7715-b4eb-4db03069f814.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993eb6-b510-751a-983c-07c724b178e5.png?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Fakhar es una fragancia femenina, sofisticada y encantadora, con un aroma floral y afrutado que recuerda a perfumes de alta gama, pero a un precio accesible. Ideal para quienes buscan un perfume versátil para el día a día o ocasiones especiales.</p>', NULL),
(12681, 'Moschino Toy 2 Pearl EDP 100ml Unisex', '<p>Salida: limón sorbete, corazón de limón, orégano</p><p>Corazón: jazmín hidroponico, arena (arena aromática), freesia</p><p>Fondo: ciprés, vetiver, almizcle (sinfonide)</p>', 42000, 1, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-bf89-713d-ac76-0d5006c4cdbc.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ef0-41a7-76e4-875e-f2e67929ae1a.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Toy 2 Pearl es una fragancia unisex fresca y moderna con un giro mágico: cítricos chispeantes y notas marinas refrescantes.</p>', NULL),
(12682, 'MAISON ALHAMBRA PINK SHIMMER EDP 100ML', 'Salida: pomelo, piña, fresa \nCorazón: peonía, bayas rojas, orquídea, azucena, jazmín \nFondo: musgo de roble, notas amaderadas, almizcle', 21000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-ba29-7378-8bc6-21670d6d127c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-d04a-76dc-9278-d1f04dffcb2e.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-b34b-74ff-8348-99f4cd0d4d34.png?storeId=1681', NULL, 1, 0, 'Pink Shimmer Secret es una fragancia femenina fresca, afrutada y flor‑amaderada, inspirada en Victoria’s Secret Bombshell. Combina una apertura vibrante de cítricos y frutas rojas con un corazón floral elegante y culmina en un fondo suave y almizclado, ideal para uso diario y salidas veraniegas.', NULL),
(12683, 'Set Versace Eros EDT 2PZS', '<p>Notas de salida: Menta fresca, limón siciliano y manzana verde.</p><p>Notas de corazón: Ambroxan, geranio y vainilla.</p><p>Notas de fondo: Cedro, musgo de roble y vetiver.</p>', 46800, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-b421-7545-9909-30626d283a13.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set vibrante y lleno de energía que captura la esencia de la masculinidad moderna, combinando frescura, sensualidad y potencia en una fragancia amaderada y aromátic</p>', NULL),
(12684, 'GUCCI GUILTY ABSOLUTE POUR FEMME', 'Zarzamora (blackberry)\nBergamota\nPimienta rosa', 79000, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-b53f-73cc-ba0f-b8c3ae48541e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-6f15-77ad-bb20-a031e7254231.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-0ef9-727a-8717-c50589036baf.jpeg?storeId=1681', NULL, 1, 0, 'Lanzada en 2018 como contraparte femenina del icónico Guilty Absolute masculino, esta fragancia fue creada por Alberto Morillas bajo la visión creativa de Alessandro Michele\nDiseñada para la mujer contemporánea, combina la sofisticación del estilo chypre con una pizca de dulzura frutal, describiéndose como “una fragancia chypre afrutada no tradiciona', NULL),
(12685, 'Antonio Banderas THE GOLDEN SECRET 100ml EDT Hombre', '<p>Familia olfativa: Aromática - Amaderada</p><p><br></p><p>Notas de salida: Bergamota, limón, notas verdes</p><p>Notas de corazón: Geranio, pimienta negra, lavanda</p><p>Notas de fondo: Cedro, almizcle, ámbar, madera de sándalo</p><p><br></p><p>Esta fragancia ofrece un equilibrio entre frescura, especias y calidez amaderada, ideal para una presencia elegante y seductora, especialmente en la noche o en eventos especiales.</p>', 20800, 0, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aae66-8c5b-75bd-a1b7-abdc237b78a1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aae66-8d40-7228-88e8-95a87a310f45.png?storeId=1681', 'Hombre', 1, 0, '<p>Antonio Banderas The Golden Secret es una fragancia masculina elegante y sofisticada, ideal para ocasiones especiales y la noche. Combina notas cítricas frescas con un corazón aromático y especiado, mientras que su fondo amaderado y almizclado aporta calidez y sensualidad. Es un aroma que refleja misterio y confianza, perfecto para hombres que quieren dejar una impresión duradera.</p>', NULL),
(12686, 'BODY PINK FRESH & CLEAN BUBBLY', 'alida frutal vibrante: pera jugosa, granada rosa y bayas heladas \nCorazón dulce y floral: pétalos de jazmín helado, que le añaden frescura limpia \nFondo suave y ligero: maderas azucaradas, que ofrecen un toque cálido y elegante', 11800, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-a845-77ac-89be-e028b3449bd9.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-b591-7743-9fb9-14e35a18f986.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-38ad-7722-b44c-e5be373da291.jpeg?storeId=1681', NULL, 1, 0, 'Fresh & Clean Bubbly es perfecto si buscas un mist con carácter divertido, frutal y un dejo floral-limpio. Es ideal para usar en reuniones informales o salidas diurnas, proporcionando frescura con ese toque festivo y delicado.', NULL),
(12687, 'MONTBLANC LEGEND SPIRIT 200ML', '<p>alida: pomelo, bergamota, pimienta rosa </p><p>Corazón: lavanda, cardamomo, notas acuáticas</p><p>Fondo: almizcle blanco, madera de cachemira, roble musgoso, maderas blancas</p>', 44500, 0, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-a692-71f8-811d-9ad9f2e2ad8c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-1b0a-70dd-a0e8-6019c24e737e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-7dc3-7117-b76c-1ade5ae26c7c.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Montblanc Legend Spirit es una fragancia masculina fresca y elegante, ideal para uso diario. Su perfil aromático amaderado combina cítricos vibrantes con un corazón acuático y especiado, culminando en una base suave y amaderada que aporta sofisticación.</p>', NULL),
(12688, 'Jovan Black Musk Cologne 88ml Hombre', '<p>Notas de salida: Hojas de violeta, mandarina, caléndula.</p><p>Notas de corazón: Bambú, ciprés, lavanda.</p><p>Notas de fondo: Ámbar, almizcle, labdanum</p>', 6800, 0, 'Jovan Musk', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-a0e8-7298-b6ff-90e1c825815d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aadd9-4d33-707a-9dbd-51ce84569e73.png?storeId=1681', 'Hombre', 1, 0, '<p>Jovan Black Musk 3.0 Cologne Spray para Hombre es una fragancia masculina lanzada en 2009 por la marca Jovan, reconocida por sus perfumes accesibles y de calidad. Este eau de cologne destaca por su aroma amaderado y almizclado, ideal para quienes buscan una fragancia masculina y versátil.</p>', NULL),
(12689, 'Nina Ricci Clásica EDT 80ml Mujer', '<p>Salida: limón de Amalfi (lima), lima — aportando una apertura cítrica fresca y chispeante </p><p>Corazón: manzana Granny Smith, peonía, datura, praliné — crea un corazón jugoso, floral y gourmand </p><p>Fondo: manzano (madera), cedro de Virginia, almizcle blanco — con un secado suave, amaderado y limpio</p>', 45500, 1, 'Nina Ricci', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-a01f-761c-97b8-cb9d99271560.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a6e81-4c78-739c-a870-630573ac678c.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Nina Ricci Nina (lanzada en 2006, creada por Olivier Cresp y Jacques Cavallier) es una fragancia femenina floral frutal gourmande, inspirada en la ternura y frescura de una manzana acaramelada. Es alegre, moderna y muy juvenil, ideal para el día a día y momentos casuales con un toque encantador.</p>', NULL),
(12690, 'Afnan 9pm 100ml EDP Hombre', '<p>Notas de salida: Manzana, canela, lavanda silvestre y bergamota.</p><p>Notas de corazón: Flor de azahar del naranjo y lirio de los valles (muguete).</p><p>Notas de fondo: Vainilla, haba tonka, ámbar y pachulí.</p><p>Esta combinación crea una fragancia cálida, dulce y ligeramente especiada, con una base cremosa y envolvente.</p><p><strong> Características generales</strong></p><p>Familia olfativa: Ámbar Vainilla.</p><p>Estilo: Dulce, cálido y envolvente.</p><p>Uso recomendado: Ideal para ocasiones nocturnas y eventos especiales.</p>', 25000, 6, 'Afnan', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-96f7-7127-9694-bd92f1c99c86.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01991074-44c7-72e8-b814-a267c22006e8.png?storeId=1681', 'Hombre', 1, 0, '<p>Afnan 9PM Eau de Parfum es una fragancia masculina lanzada en 2020 por la marca emiratí Afnan. Perteneciente a la familia olfativa Ámbar Vainilla, se caracteriza por su aroma dulce, cálido y envolvente, ideal para ocasiones nocturnas y eventos especiales.</p>', NULL),
(12691, 'Armaf Odyssey Dubai Chocolate EDP 100ml Hombre', '<p>Familia olfativa: Oriental - Vainilla - Gourmand</p><p> Notas de salida:</p><p>Chocolate negro</p><p>Canela</p><p>Nuez moscada</p><p> Notas de corazón:</p><p>Praliné</p><p>Ámbar</p><p>Café</p><p> Notas de fondo:</p><p>Vainilla</p><p>Madera de sándalo</p><p>Almizcle</p><p>Esta fragancia es rica, dulce y especiada, con un perfil profundo y cálido que la hace ideal para el otoño, el invierno o noches especiales. Su aroma evoca lujo y placer, con una marcada presencia de chocolate y notas orientales envolventes.</p>', 25500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-9496-76ca-aaa5-d13c4bdf1413.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199deba-9caf-70cf-9c13-b5ea16593bcb.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Dubai Chocolat es una fragancia unisex de la familia olfativa Oriental Vainilla, lanzada en 2025. Inspirada en los famosos postres de chocolate de Dubái, esta esencia combina notas dulces y especiadas para crear una experiencia olfativa envolvente y sofisticada. Con una apertura rica y cálida, se desarrolla en un corazón cremoso y culmina en una base dulce y amaderada, ofreciendo una estela adictiva</p>', NULL),
(12692, 'Body Mist Victoria´s Secret BARE VAINILLA', '<p>Vainilla cremosa</p><p>Cashmere cálido</p><p>Almizcle suave</p>', 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-90a9-752b-a220-c89b15c6cd2b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-21e7-76ad-b092-500627fa3cc6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31d-2a90-77de-8478-aaf1b28092cd.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Victoria’s Secret Bare Vanilla es una fragancia suave y reconfortante que ha ganado popularidad por su aroma dulce y cálido. Es ideal para quienes buscan una fragancia ligera y cotidiana</p>', NULL),
(12693, 'Adidas Pure Game 100ml EDT Hombre', '<p>amilia: Amaderada‑Especiada, fresca y deportiva </p><p>Salida: cítrica y herbal con pomelo, mandarina, albahaca y un toque de pimienta para un inicio vibrante y limpio </p><p>Corazón: aromático y ligeramente terroso, combina lavanda, ciprés y madera de gaiac </p><p>Fondo: cálido y acogedor gracias al sándalo, incienso, pachulí y haba tonka</p>', 8500, 2, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-8b4e-713b-96d2-378134cadcda.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af6f-e8ea-71bf-95da-2da60d28fafa.png?storeId=1681', 'Hombre', 1, 0, '<p>Adidas Pure Game EDT es una fragancia fresca, cítrica y ligeramente especiada, con un corazón aromático amaderado y un fondo dulce‑resinoso. Perfecta para un uso juvenil, deportivo y casual, ofrece un gran aroma por su precio, aunque conviene reaplicar a lo largo del día si buscas más duración.</p>', NULL),
(12694, 'Versace Pour Homme Dylan Blue 100ml EDT Hombre', '<p>Notas de salida: bergamota de Calabria, notas acuáticas, toronja (pomelo) y hojas de higuera.</p><p>Notas de corazón: ambroxan, pimienta negra, pachulí, hojas de violeta y papiro de Egipto.</p><p>Notas de fondo: incienso, almizcle, haba tonka y azafrán</p>', 43500, 3, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197910b-2c99-72af-8829-57f3ed921715.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197910b-2eb3-762e-9a1b-85392039aa27.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y masculina que combina notas acuáticas y cítricas con un toque amaderado y especiado, evocando la esencia del Mediterráneo</p>', NULL),
(12695, 'Body Spray Lattafa Asad', '<p>Salida: pimienta negra, tabaco y piña — especiado, algo tropical – </p><p>Corazón: pachulí, café e iris — profundo y aromático – </p><p>Fondo: vainilla, ámbar, madera seca, benjuí y ládano — cálido, resinosa y amadera</p>', 4500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-816a-774a-b146-4c8566cbc618.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-eb06-764d-bfa6-f24eb7ddd6f1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-0936-764a-903f-684fde4a7b7d.png?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Asad es un body spray masculino de la familia ambarada–especiada, inspirado en Dior Sauvage Elixir con buenas bases de vanilila, ámbar y madera. Su rendimiento es notable, destacando por su proyección fuerte y duración prolongada, especialmente en ropa. Sin embargo, su salida puede ser abrumadora, sintética o irritante si se usa directo tras abrirse, y su calidad puede variar según lote.</p>', NULL),
(12696, 'Mont Blanc Explorer 100ml EDP Hombre', '<p>Salida: bergamota, pomarrosa (mezcla de pomelo y rosa), salvia (sage) </p><p>Corazón: vetiver (Haití), cuero y sándalo </p><p>Fondo: pachulí, ambrofix (ambroxan), akigalawood (patchouli indonesio), cacao</p>', 39500, 1, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-7ee4-7058-a2dd-37a8d3c77c13.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b33c1-86b0-7749-b2a9-e92f0ade67ed.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Explorer es una fragancia masculina amaderada‑aromática con una vibrante apertura cítrica, un corazón herbáceo‑leñoso y una base ambroxánica intensa. Comparte ADN con Creed Aventus, pero con un carácter más asequible y versátil</p>', NULL),
(12697, 'Disney Rapunzel 3.4 EDT Sp Girls', 'Notas de salida: Acorde verde, cítricos.\nNotas de corazón: Flor de vainilla, cedro, flores blancas.\nNotas de fondo: Sándalo, ámbar, almizcle', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-5a2a-71ee-872c-711624b5727c.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia encantadora inspirada en la princesa Rapunzel, diseñada especialmente para niñas. Con una combinación de notas florales y amaderadas, ofrece una experiencia olfativa fresca y juguetona, perfecta para el uso diario.', NULL),
(12698, 'Christian Dior Sauvage 100ml EDT Hombre', '<p>Notas de salida: bergamota de Calabria, pimienta. </p><p>Notas de corazón: lavanda, geranio, vetiver, pachulí, pimienta rosa y pimienta de Sichuan. </p><p>Notas de fondo: ambroxan, cedro, lábdano</p>', 71500, 0, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197910c-e3c1-70f0-a047-fd5a844ced67.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-fa14-71d9-a17e-4918dec0f1a3.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Es una fragancia masculina versátil, moderna, que puede adaptarse tanto al día como a ciertas salidas de noche, combinando frescura y presencia. Sauvage EDT ofrece una apertura fresca, cítrica con pimienta que llama la atención, seguida por un corazón aromático-amaderado que aporta carácter y finalmente un fondo limpio pero potente gracias al ambroxan y las maderas.</p>', NULL),
(12699, 'Liz Claiborne Curve Black 125ml EDT Hombre', '<p>Notas de salida: Bergamota, nuez moscada, hojas de violeta</p><p>Notas de corazón: Salvia esclarea, lavanda, musgo de roble</p><p>Notas de fondo: Cuero, sándalo, teca, haba tonka</p>', 21500, 3, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-6ef6-7394-8a20-eaf6bdbc6dc8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886de-5163-7426-b977-5b28608bdca1.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina que combina notas frescas y especiadas con un toque amaderado, ideal para el hombre moderno y seguro de sí mismo.</p>', NULL),
(12700, 'CHACAREL AMOR AMOR', 'Salida: grosella negra, naranja, mandarina, pomelo rosado, bergamota, casia\nCorazón: rosa roja, jazmín, lirio de los valles (muguete), albaricoque (chabacano)\nFondo: vainilla, haba tonka, ámbar, almizcle, cedro de Virginia', 29000, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197910e-83fd-7652-8aee-521ebc7eafba.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197910e-85d2-7288-96b9-8fabd88da257.png?storeId=1681', NULL, 1, 0, 'Cacharel Amor Amor  es una fragancia femenina de la familia floral‑frutal, lanzada en 2003 por los perfumistas Laurent Bruyere y Dominique Ropion .', NULL),
(12701, 'Paco Rabanne Fame Blooming Pink EDP 80ml Mujer', '<p><strong>Salida</strong>: mango jugoso y bergamota chispeante</p><p><strong>Corazón</strong>: jazmín puro e incienso de olíbano, aportando un matiz sensual y resinoso</p><p><strong>Fondo</strong>: vainilla cremosa y sándalo suave para un secado cálido y envolvente</p>', 68800, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-6b88-7322-90b8-0d51141781f0.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01990b34-f168-7789-946b-261b921b5a16.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Fame Blooming Pink (2023) es una edición limitada de la línea Fame de Paco Rabanne. Se presenta en un hermoso frasco rosa brillante y encapsula energía femenina: frutal, floral y cremosa. Es sofisticada, moderna y pensada para quienes buscan elegancia y frescura con un toque suave</p>', NULL),
(12702, 'Set Paris Hilton 4PC Mujer', '<p>Notas de salida: Manzana, melón y durazno.</p><p>Notas de corazón: Freesia, jazmín y lirio del valle.</p><p>Notas de fondo: Almizcle, sándalo y ylang-ylang.</p>', 31500, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976075-5f93-74f2-b519-4271747e79ff.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-fdae-700b-82e9-efd6d3fd8533.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31b-6082-71b5-b843-bf94a423c9af.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set glamuroso y femenino que reúne las fragancias más icónicas de Paris Hilton, ideal para mujeres que disfrutan de aromas seductores, dulces y sofisticados, perfectos para cada momento del día.</p>', NULL),
(12703, 'Paris Hilton Can Can Burlesque 100ml EDP Mujer', '<p>lida (Top): frutas jugosas: frambuesa, nectarina, grosella negra (cassis) y clementina.</p><p>Corazón (Middle): orquídea silvestre y flor de azahar del naranjo (orange blossom).</p><p>Fondo (Base): almizcle blanco y maderas blancas</p>', 24000, 3, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979101-76d1-7308-9e47-84cbd3be4b1c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979101-7480-765a-9aab-2b8cac060b16.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-0255-76d8-89c3-bdc90041a0ef.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Paris Hilton Can Can Burlesque EDP 3es un flanker de la línea Can Can, lanzado en 2014, orientado a un público femenino que busca un perfil divertido, afrutado y floral, ideal para climas cálidos o uso diario.</p>', NULL),
(12704, 'Body Mist VICTORIA SECRET Amber Romance', '<p>Salida: cereza negra (black cherry), albaricoque dorado</p><p>Corazón: crema anglaise (natilla), nube de canela</p><p>Fondo: vainilla cremosa, ámbar dorado, sándalo suave y un toque de almizcle</p>', 11800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-b17f-73cf-943b-a07e0d5eb9c7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-e00f-73fe-8a28-a898600ad729.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-ac29-776c-b2a9-3403ddd2b0f4.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Amber Romance es una fragancia cálida, dulce y envolvente que combina ámbar dorado, vainilla cremosa y toques de cereza y almizcle. Ideal para climas frescos o momentos íntimos, su aroma suave y romántico deja una estela acogedora y femenina.</p>', NULL),
(12705, 'Set Bharara King EDP 4PZAS', '<p>Notas de salida: Bergamota, limón y pimienta negra.</p><p>Notas de corazón: Canela, lavanda y geranio.</p><p>Notas de fondo: Ámbar, cuero y madera de cedro</p>', 54000, 0, 'Bharara', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-ae16-741a-aa8d-631dc1746170.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-aef3-748a-8e6d-7e6134afa1e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-a49d-768f-b518-508cfa3170e2.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set masculino que refleja poder y elegancia, con fragancias intensas y sofisticadas. Ideal para hombres que buscan destacar con aromas cálidos, amaderados y especiados, perfectos para cualquier ocasión especial</p>', NULL),
(12706, 'Disney Frozen Elsa 3.4 EDT Sp Girl', 'Frambuesa jugosa y manzana verde  entrada dulce y fresca \nMelodía central \nRosa suave y jazmín delicado  toques florales ligeros\nRitmo final \nMusgo, vainilla y almizcle blanco base cálida, acogedora y limpia', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-22d6-72fa-b71a-2a7796a44cd1.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia suave, alegre y encantadora, inspirada en la princesa Elsa. Combina un toque afrutado con delicadas flores y un fondo reconfortante, ideal para niñas que aman la magia de Frozen', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12707, 'Jesús Del Pozo Halloween Man EDT 125ml Hombre', '<p>Notas de salida: Mandarina, martini de manzana, hojas de violeta, albahaca</p><p>Notas de corazón: Lavanda, flor de azahar, flor de jengibre, canela</p><p>Notas de fondo: Almizcle, ámbar, vainilla, cuero</p>', 25800, 5, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199bd5e-1ea0-76b3-8a1c-05937bb6b4b5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199e962-5193-738b-b772-74db67cc1555.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Halloween Man de Jesús del Pozo, lanzado en 2012, es una fragancia masculina que combina notas frescas, especiadas y cálidas. Ideal para el día y especialmente para climas cálidos, ofrece una experiencia olfativa ligera y envolvente.</p>', NULL),
(12708, 'ULTRAVIOLET MAN PACO RABANNE 100ML', 'Salida: Jengibre, cardamomo y mandarina\nCorazón: Pimienta rosa, lavanda y salvia\nFondo: Vetiver, tonka y cedro', 32800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-a4a3-732e-9179-24873ee92875.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-2ab9-7005-a40a-66800cd772ce.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-fb27-77a9-a3a2-32566536732c.jpeg?storeId=1681', NULL, 1, 0, 'Una fragancia moderna y vibrante que combina notas especiadas y amaderadas, ideal para hombres seguros que buscan una esencia versátil y con carácter para el día a día o salidas nocturnas.', NULL),
(12709, 'Tommy Hilfiger Impact 100ml EDT + 4ml Hombre', '<p>Salida: Naranja amarga, toronja y pimienta rosa.</p><p>Corazón: Ciprés francés, elemi y salvia esclarea.</p><p>Fondo: Cedro, sándalo, almizcle y Akigalawood</p>', 33800, 0, 'Tommy Hilfiger', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-a08f-753d-8dfc-e54df087af7b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199cc5c-04a1-726f-89c7-1a16effbf946.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia moderna y energética que combina notas cítricas y amaderadas con un toque especiado, ideal para hombres audaces que buscan dejar una impresión duradera.</p>', NULL),
(12710, 'Paris Hilton Clasica EDP 100ml Mujer', '<p>Salida: melón, manzana, durazno (melocotón), ozono, fresia </p><p>Corazón: mimosa, jazmín, nardo, lirio de los valles, azucena, tuberosa </p><p>Fondo: sándalo, almizcle, musgo de roble, ylang‑ylang</p>', 26500, 2, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-99c6-77b8-8577-3a4ad7f3717b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-c9a4-7329-a5b7-b1cc68366435.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-98de-7710-9cdf-2609c4ddc9f3.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina de la familia floral‑frutal lanzada en 2005. Refleja un estilo juvenil, limpio y optimista, ideal como firma diaria fresca y accesible</p>', NULL),
(12711, 'Lattafa Oud for Glory 100ml EDP Hombre', '<p>Salida: Azafrán, nuez moscada, lavanda</p><p>Corazón: Madera de oud, pachulí</p><p>Fondo: Madera de oud, pachulí, almizcle</p>', 22500, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-9528-751b-81a9-ecad8d84c23c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198801b-d85b-7322-bc18-94018bed496b.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Oud for Glory es una fragancia elegante y sofisticada, que combina la riqueza del oud con notas especiadas de azafrán y nuez moscada, junto con toques amaderados y almizclados. Perfecta para quienes buscan un aroma cálido y distintivo, ideal para noches y climas frescos.</p>', NULL),
(12712, 'Set Ralph Lauren Polo Blue 125ml EDT + Mini', '<p>Notas de salida: Melón, mandarina y pepino.</p><p>Notas de corazón: Albahaca, salvia y geranio.</p><p>Notas de fondo: Almizcle, gamuza y notas amaderadas.</p>', 49000, 0, 'Ralph Lauren', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-92c7-75b6-823c-2c888fca9d90.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f4-91ff-765e-b8b8-fc977b5199b8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-42b7-773f-8e5d-697357ad4b8f.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set refrescante y sofisticado que captura la libertad del cielo azul y la brisa del mar. Ideal para hombres activos y elegantes, con un aroma limpio y vibrante que puedes llevar contigo a donde vayas.</p>', NULL),
(12713, 'Body Mist Victoria´s  Secret COCONUT PASSION', '<p>Salida: coco cremoso (island coconut)</p><p>Corazón: vainilla suave y leche condensada</p><p>Fondo: sutiles matices ambarados y notas amaderadas ligeraS</p>', 11800, 4, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-8e6d-732e-aa71-d319fb474a42.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-5382-77ac-a1f0-eb31fce36ce3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c323-80d7-7598-98d5-61f31dd78546.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Un body mist cálido y gourmand que mezcla cremosidad de coco isleño con suaves toques de vainilla, evocando una sensación de playa y atardeceres tropicales que abrazan la piel con dulzura y confort.</p>', NULL),
(12714, 'Hugo Boss Bottled PARFUM 100ml Hombre', '<p>Notas de salida: Incienso de olíbano (franquincienso), mandarina</p><p>Notas de corazón: Árbol de higuera, raíz de lirio</p><p>Notas de fondo: Cedro, cuero</p>', 51500, 0, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-8ad7-7358-b949-40f8a66613df.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b0bf6-b5d1-7549-a78e-aab2add4abd2.png?storeId=1681', 'Hombre', 1, 0, '<p>Hugo Boss Bottled Parfum es una fragancia masculina lanzada en 2022, que representa una evolución de la icónica línea Boss Bottled. Esta versión Parfum destaca por su intensidad y sofisticación, combinando notas amaderadas y especiadas con un toque moderno y elegante. Es ideal para hombres que buscan una fragancia duradera y distintiva para ocasiones especiales o uso diario</p>', NULL),
(12715, 'Lacoste Essential 125ml EDT Hombre', '<p>Salida: bergamota, mandarina, hojas de tomatera, cassis (grosella negra) </p><p>Corazón: rosa y pimienta negra </p><p>Fondo: sándalo y patchouli</p>', 36000, 2, 'Lacoste', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-86f8-700d-899d-208f9a9c9d55.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f78-f42c-73a2-9c01-c9e4a95aed1c.png?storeId=1681', 'Hombre', 1, 0, '<p>Fresco, verde y amaderado con un corazón ligeramente especiado, ideal para uso diario y climas cálidos.</p>', NULL),
(12716, 'Lattafa Khamrah Qahwa EDP 100ml Unisex', '<p>Salida: jengibre, canela y cardamomo (especiado, vibrante)</p><p>Corazón: praliné dulce, frutas confitadas y flores blancas</p><p>Fondo: café arábica, haba tonka, benjuí, vainilla y almizcle</p>', 24000, 2, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979102-628e-740d-ae88-088ed1a09ff4.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979102-5f89-702c-acbb-6d0eed3ba9c4.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Khamrah Qahwa es una fragancia gourmand de alto rendimiento, ideal para los amantes del café especiado, praliné y especias dulces. Una opción adictiva y cálida para climas fríos, con una excelente relación calidad‑precio</p>', NULL),
(12717, 'Bvlgari Man In Black 100ml EDP Hombre', '<p>Salida: potente mezcla de especias, ron y tabaco </p><p>Corazón: cuero, iris y tuberosa añaden un carácter refinado y floral </p><p>Fondo: tonka, madera de guayaco y benjoin aportan un cierre dulce, amaderado y cálido</p>', 64500, 0, 'Bvlgari', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01986d29-a0f2-7062-9233-9ab242a18ad5.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aaddb-6f34-77ac-be71-0275c2d4ad19.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Bvlgari Man In Black 3.4 EDP es una fragancia masculina intensa y sofisticada, con notas de ron especiado, cuero y ámbar. Ideal para noches frías y ocasiones elegantes, destaca por su carácter cálido, seductor y envolvente.</p>', NULL),
(12718, 'Mercedes Benz Club Black EDT 100ml Hombre', '<p>Salida: bergamota chispeante</p><p>Corazón: incienso, jazmín</p><p>Fondo: vainilla, benjuí (benzoin), ambroxan y maderas doradas ([turn0image1, turn0image3, turn0search0])</p>', 38500, 0, 'Mercedes Benz', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-7a7d-773a-862f-f0d705984270.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019aaddc-b17f-7358-9d1d-e62b6003f614.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Mercedes-Benz Club Black es una fragancia masculina intensa y sofisticada, con un perfil oriental-amaderado dominado por una vainilla cremosa, incienso ahumado y un ligero toque cítrico. Ideal para la noche y climas fríos, proyecta elegancia y poder.</p>', NULL),
(12719, 'Tous Llove Me The Emerald Elixir 90ml', '<p>Salida: Néctar de pera verde, pomelo y naranja dulce.</p><p>Corazón: Madreselva, jazmín solar y violeta apolvada.</p><p>Fondo: Vainilla caramelizada, pachulí de Indonesia, cistus y almizcle.</p>', 42000, 1, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979105-90b5-70bb-b0be-718c1ce54a1f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979105-94b8-76da-bd49-f335f3065046.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia oriental floral gourmand que combina notas frutales y florales con un fondo dulce y amaderado, inspirada en la esmeralda para transmitir lujo y sofisticación.</p>', NULL),
(12720, 'Versace Man Eau Fraiche 100ml EDT Hombre', '<p><strong>Salida</strong>: Limón (lima ácida), bergamota, carambola, cardamomo y palo de rosa de Brasil.</p><p><strong>Corazón</strong>: Cedro, estragón, salvia y pimienta.</p><p><strong>Fondo</strong>: Almizcle, notas amaderadas, azafrán, ámbar y madera de sicómoro.</p>', 39500, 7, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979107-b846-720f-a1f0-7a3eb567cfbf.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01979107-b6d9-716d-a431-9cac96c12ac6.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y vibrante que combina cítricos y especias con un toque amaderado, evocando la brisa marina mediterránea.</p>', NULL),
(12721, 'Jean Paul Gaultier Le Male Le Parfum 125ml EDP Men', '<p>Notas de salida: Lavanda, menta</p><p>Notas de corazón: Vainilla, benjuí</p><p>Notas de fondo: Miel, haba tonka, tabaco</p>', 64500, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-7077-7488-8dad-711378dc38eb.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972a7-08d4-70fc-bf38-0ffac376093c.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Le Male Le Parfum es una fragancia masculina lanzada en 2020 como una versión más intensa y sofisticada del clásico Le Male. Esta edición en Eau de Parfum se caracteriza por una combinación de notas aromáticas, dulces y especiadas, ofreciendo una experiencia olfativa profunda y envolvente.</p>', NULL),
(12722, 'REPLICA 919 PURE MEN', 'Salida: cítricos frescos y afrutados; predominan manzana verde/crujiente y limón, aportando un inicio vibrante y limpio.\nCorazón (hipotético): posiblemente notas ligeras de madera o flores blancas, para un carácter suave pero presente.\nFondo: sugiere almizcle limpio y un toque amaderado muy sutil, que ayuda a equilibrar y otorgar longevidad al aroma.', 4500, 1, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-68b6-717f-833e-1ec3fc86a441.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-85b9-772e-a4c0-eb09987bba4c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-7394-7399-98b3-fa182267e55b.jpeg?storeId=1681', NULL, 1, 0, 'Un perfume fresco, limpio y moderno que combina notas cítricas y afrutadas con un ligero trasfondo amaderado y almizclado. Su estilo minimalista busca transmitir pureza y elegancia discreta, ideal para uso diario y ocasiones informales.', NULL),
(12723, 'Ariana Grande God is a Woman 100ml EDP Mujer', '<p>Salida: pera jugosa y almizcle ambret; un inicio fresco, dulce y suavemente musgoso </p><p>Corazón: orris (raíces de lirio) y pétalos de rosa turca, aportando un matiz floral refinado y empolvado </p><p>Fondo: vainilla de Madagascar y cedro cremoso que otorgan calidez y sofisticación</p>', 38500, 1, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-651e-757b-9997-d2b7d965b262.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a2302-3d4c-727b-a6dc-2e7c7988a0aa.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>God Is a Woman es una fragancia suave, femenina y moderna, ideal para el día a día o momentos relajados, especialmente para quienes buscan algo elegante y con conciencia ambiental. Su gran fortaleza es su perfil aromático limpio y elegante; su principal limitante, la duración moderada, pero se compensa con su versatilidad y carácter.</p>', NULL),
(12724, 'Valentino Donna Born In Roma 100ml EDP Mujer', '<p>Notas de salida: grosella negra, bergamota, pimienta rosa.</p><p>Notas de corazón: jazmín, jazmín sambac, té de jazmín.</p><p>Notas de fondo: vainilla Bourbon, madera de guayaco, cashmeran</p>', 83000, 0, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-6006-710d-8751-8d36e4ebea69.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019afa65-4379-735e-b699-1183ff951fc8.png?storeId=1681', 'Mujer', 1, 0, '<p>Fragancia floral oriental cálida y moderna. Abre con un acorde afrutado y ligeramente picante gracias a la combinación de grosella, rosa y cítricos. El corazón gira en torno al jazmín con un toque suave de té, aportando elegancia y delicadeza. El secado revela una base cremosa y amaderada con vainilla, cashmeran y guayaco, creando una estela sofisticada y envolvente, ideal para uso diario o salidas nocturnas en cualquier estación</p>', NULL),
(12725, 'Jesus Del Pozo Halloween Man Hero EDT 125ml', '<p>Notas de salida: Pomelo, Limón (lima ácida), Jengibre fresco, Granizado de manzana</p><p>Notas de corazón: Lavandín, Acorde marino, Aquaflora, Salvia</p><p>Notas de fondo: Amber Xtreme, Cashmeran, Pachulí de Indonesia, Musgo</p>', 24500, 3, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-5895-7310-996f-7164d721d356.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b2-f5c6-77de-9584-de8adbcb4739.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Halloween Man Hero es una fragancia masculina lanzada en 2021 por Jesús del Pozo. Con una composición fresca y acuática, combina notas cítricas y florales con un fondo amaderado, ofreciendo una experiencia olfativa energética y moderna. Ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12726, 'Jean Paul Gaultier Scandal 80ml EDP Mujer', '<p>Notas de salida: Naranja sanguina, mandarina.</p><p>Notas de corazón: Miel, jazmín, flor de azahar del naranjo, gardenia, durazno.</p><p>Notas de fondo: Cera de abejas, caramelo, pachulí, regaliz</p>', 58000, 0, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-4f59-76a1-9854-032c88c9fc08.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b4-3464-7522-bd32-5be890db876a.png?storeId=1681', 'Mujer', 1, 0, '<p>Jean Paul Gaultier Scandal Eau de Parfum 2.7 oz (80 ml) es una fragancia femenina lanzada en 2017, reconocida por su aroma dulce, floral y ligeramente amaderado. Diseñada para mujeres audaces y sofisticadas, esta fragancia ha sido bien recibida por su longevidad y proyección.</p>', NULL),
(12727, 'Armaf Odyssey Tryant 100ml EDP Men', '<p><strong>Notas de salida:</strong></p><p>Pomelo</p><p>Notas cítricas frescas</p><p><strong> Notas de corazón:</strong></p><p>Elemi</p><p>Geranio</p><p>Lavanda</p><p>Pimienta negra</p><p><strong>Notas de fondo:</strong></p><p>Ambroxan</p><p>Cedro</p><p>Vetiver</p>', 24500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-4a39-76ba-a16f-af82b2e3aa67.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b5-7eb6-763d-bc90-70b5efca7087.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Tyrant EDP es una fragancia masculina lanzada en 2023, que pertenece a las familias olfativas cítrica, fougère y amaderada. Su composición se caracteriza por una apertura fresca y energética, con un acorde cítrico vibrante y notas de pomelo. En el corazón, se encuentran notas especiadas y aromáticas de elemi, geranio, lavanda y pimienta negra, que aportan profundidad y complejidad. La base está dominada por notas amaderadas y terrosas de ambroxan, cedro y vetiver, que le confieren una estructura robusta y elegante.</p>', NULL),
(12728, 'Tester Versace Eros EDT 100ml', '<p>Salida: Menta fresca, manzana verde y limón ácido </p><p>Corazón: Haba tonka, geranio y ambroxan </p><p>Fondo: Vainilla de Madagascar, vetiver, musgo de roble, cedro de Virginia y cedro del Atlas</p>', 36500, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-4227-73cb-83e2-d6a4ecb296de.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fe-df0b-709c-93fe-fdf74b57e55d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-b46f-777b-9299-f114112cd871.jpeg?storeId=1681', NULL, 1, 0, '<p>Un aroma potente y sensual que evoca fuerza y pasión, combinando frescura intensa inicial con un fondo cálido y amaderado. Ideal para la noche, citas o eventos en climas frescos.</p>', NULL),
(12729, 'Armaf Club De Nuit Milestone EDP 105ml Hombre', '<p>Familia olfativa: Aromática - Amaderada - Especiada</p><p><br></p><p>Notas de salida: Bergamota, mandarina, pimienta negra</p><p><br></p><p>Notas de corazón: Lavanda, nuez moscada, canela</p><p><br></p><p>Notas de fondo: Vainilla, madera de cedro, pachulí, almizcle</p><p><br></p><p>Esta fragancia combina frescura cítrica con un corazón cálido y especiado, y una base cremosa y amaderada, ofreciendo un aroma sofisticado y duradero ideal para hombres que buscan versatilidad y estilo.</p>', 30500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b8-19b9-7763-b1ba-8b3713a8ec3f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b8-19fa-77c2-9a10-a5faa2da2f9e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Milestone es una fragancia masculina moderna y versátil que destaca por su frescura aromática combinada con un toque especiado y amaderado. Es ideal para hombres dinámicos que buscan un aroma elegante pero fácil de llevar, perfecto tanto para el día como para la noche. Su carácter equilibrado lo hace adecuado para diversas ocasiones y temporadas.</p>', NULL),
(12730, 'Perry Ellis 360 Clásico 100ml Hombre', '<p>Notas de salida: Bayas de enebro, limón (lima ácida) y bergamota</p><p>Notas de corazón: Lavanda, salvia, cardamomo y fresia</p><p>Notas de fondo: Notas amaderadas, vetiver y almizcle</p>', 24500, 4, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-28f0-769f-8ab0-a3e19dd69116.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-ae3b-701a-ba6d-018f7dd72a32.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31e-f503-73a3-a767-775c42ebb7e1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>El Perry Ellis 360° for Men es una fragancia masculina clásica lanzada en 1995, reconocida por su perfil aromático fresco, especiado y ligeramente amaderado. Ideal para el uso diario, especialmente en climas cálidos, ofrece una experiencia olfativa equilibrada y sofisticada</p>', NULL),
(12731, 'Michael Kors Glam Jasmine EDP 100ml Mujer', '<p>Salida: Grosella negra y cítricos suaves </p><p>Corazón: Jazmín egipcio y sambac  </p><p>Fondo: Sándalo y cedro, que aportan una base amaderada cremosa</p>', 45000, 1, 'Michael Kors', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-221a-765e-8a9d-16112c516bda.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b9-e226-7073-acc5-7208424ac8fb.png?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2013, esta fragancia está protagonizada por un elegante bouquet de jazmín realzado con grosella negra y una base cremosa de sándalo </p><p>. Diseñada por Harry Fremont, su aire es sofisticado, femenino y glamuroso — justo lo que dice su nombre. En el sitio oficial, se menciona como “overtly feminine” y “fabulous</p>', NULL),
(12732, 'Perry Ellis 360 Purple 100ml EDP Mujer', '<p>Durazno (melocotón): jugoso y dulce, aporta una apertura afrutada y cálida.</p><p>Zarzamora (frambuesa negra): añade un toque ligeramente ácido y profundo.</p><p>Flor de manzano: fresca y ligera, con un matiz floral delicado.</p>', 24800, 5, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-1d58-77b1-8cf3-88fad067488c.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina que fusiona la frescura de las frutas con la sofisticación de las flores blancas y un toque amaderado, creando una estela envolvente y elegante. Ideal para mujeres modernas que buscan un aroma distintivo y encantador.</p>', NULL),
(12733, 'Ariana Grande Cloud Pink EDP 100ml Mujer', '<p>Familia olfativa: Gourmand - Floral - Frutal</p><p><br></p><p>Notas de salida: Lavanda, pera, bergamota</p><p><br></p><p>Notas de corazón: Cocos, durazno, jazmín</p><p><br></p><p>Notas de fondo: Vainilla, almizcle, praliné, azúcar</p><p><br></p><p>Esta combinación crea un aroma dulce, cremoso y ligero, perfecto para quienes buscan una fragancia femenina, dulce y envolvente con un toque moderno y suave.</p>', 46500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-19f4-715d-b203-b536a4599d7e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f77-cd87-7201-9859-44ad578bd473.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f77-cf60-713a-9119-4e31ad1983c5.png?storeId=1681', 'Mujer', 1, 0, '<p>Ariana Grande Cloud Pink es una fragancia femenina dulce y aérea que combina notas gourmand con toques florales y frutales. Destacan aromas de lavanda, durazno y vainilla, que crean una sensación cálida, suave y acogedora, como una nube dulce y esponjosa. Ideal para el día a día, especialmente en primavera y otoño, es un perfume juvenil y moderno con un toque de fantasía.</p>', NULL),
(12734, 'Montblanc Femme Individuelle EDT 75ml', '<p>Notas de corazón: Rosa, flor de loto y espino.</p><p>Notas de fondo: Pachulí, vainilla, ámbar y almizcle</p>', 25500, 0, 'Mont Blanc', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-12b6-7245-852f-1d5e1d7b60f4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989bd-aae8-759b-ab7e-4da790d769c4.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Montblanc Femme Individuelle es una fragancia femenina lanzada en 2004, creada por el perfumista Michel Almairac. Esta eau de toilette pertenece a la familia olfativa oriental floral, destacándose por su equilibrio entre notas frescas, florales y cálidas. Es una opción ideal para mujeres que buscan una fragancia distintiva y elegante para el uso diario</p>', NULL),
(12735, 'Lattafa Eclaire EDP 100ml Mujer', '<p>Notas de salida: Caramelo, leche, azúcar</p><p>Notas de corazón: Miel, flores blancas</p><p>Notas de fondo: Vainilla, praliné, almizcle</p>', 25000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976074-0f5a-710e-9356-896242a9679b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885c8-6d75-70b9-aa7e-c691331a2f14.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Esta fragancia pertenece a la familia olfativa Gourmand y fue lanzada en 2024. Es una creación de la marca árabe Lattafa, reconocida por sus perfumes intensos y duraderos. Eclaire es unisex y se inspira en el perfume Giardini di Toscana Bianco Latte.</p>', NULL),
(12736, 'Body Spray LATTAFA AJWAD Unisex', '<p>Salida: fresca y afrutada, con un toque de frutas jugosas tipo uva, ciruela o pomelo </p><p>Corazón: bouquet floral de rosa y jazmín </p><p>perfumeriamiracle.com</p><p>Fondo: voluptuosa mezcla de vainilla, ámbar, almizcle y cedro (sándalo aparece en algunas versiones)</p>', 4500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790fd-53d5-76b7-ad02-f0eea45de063.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Ajwad es un body spray o EDP unisex con una mezcla intensa de frutas dulces, rosa y jazmín, rematada por una base cremosa de vainilla, ámbar, almizcle y cedro. Su rendimiento es de alto nivel —proyección potente y larga duración—, pero su apertura puede resultar demasiado sintética o agresiva para narices sensibles. Es una fragancia de “amor u odio”, típica de muchas creaciones árabes, y mejora notablemente tras un periodo de reposo.</p>', NULL),
(12737, 'Carolina Herrera Very Good Girl 80ml EDP Mujer', '<p>Lichi y grosella roja — aportan una apertura fresca y afrutada.</p><p>Corazón: Rosa — corazón floral que añade feminidad y sofisticación.</p><p>Fondo: Vainilla y vetiver — brindan calidez y profundidad, creando una base envolvente.</p>', 64500, 2, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790fc-028e-72c9-916d-1e33e5adb645.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790fc-049f-7259-a19e-d5e3972003ec.png?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2021, Very Good Girl es una fragancia femenina de la familia olfativa floral frutal. Creada por las perfumistas Louise Turner, Quentin Bisch y Shyamala Maisondieu, esta fragancia busca reinterpretar el concepto de la mujer audaz y sofisticada. Su distintivo frasco en forma de tacón de aguja rojo simboliza el empoderamiento y la elegancia.</p>', NULL),
(12738, 'Prada Luna Rossa Carbon 100ml EDT Hombre', '<p>Bergamota italiana: fresca y ligeramente amarga, aporta una apertura cítrica y vibrante.</p><p>Pimienta: especiada y picante, con un toque estimulante.</p>', 68500, 1, 'Prada', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-a03e-731f-a6f6-2757c7cad017.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989ce-42f1-712d-a1b0-d710a899f20e.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina que fusiona la frescura de los cítricos con la sofisticación de la lavanda y un toque mineral, creando una estela moderna y energética. Ideal para hombres dinámicos que buscan un aroma distintivo y elegante.</p>', NULL),
(12739, 'Azzaro The Most Wanted Parfum 100ml Hombre', '<p>Familia: Amaderado especiado gourmand.</p><p>Salida: jengibre picante con un toque cítrico, generando un inicio potente y fresco </p><p>Corazón: acorde cremoso de toffee/bourbon vanilla que suaviza el paso inicial y otorga calidez deliciosa </p><p>Fondo: madera ámbar y almizcle, que consolida la fragancia en una base acogedora y elegante</p>', 56500, 1, 'Azzaro', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989d5-6d22-71e6-be08-c1d42e357256.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989d5-6e91-770c-8629-db641875dfeb.png?storeId=1681', 'Hombre', 1, 0, '<p>Azzaro The Most Wanted Parfum Intense 100 ml es una versión más concentrada y seductora de la línea “Most Wanted”, consolidándose como una fragancia ámbar-gourmand especiada diseñada para el hombre moderno, confiado y sofisticado</p>', NULL),
(12740, 'Armaf Club De Nuit Oud EDP 105ml Unisex', '<p>Familia olfativa: Oriental - Amaderada - Especiada</p><p><br></p><p>Notas de salida: Bergamota, limón, pimienta rosa</p><p><br></p><p>Notas de corazón: Rosa, nuez moscada, canela, clavo</p><p><br></p><p>Notas de fondo: Oud, ámbar, almizcle, vainilla, madera de cedro</p><p><br></p><p>Esta fragancia ofrece una apertura fresca y especiada que evoluciona hacia un corazón floral y cálido, culminando en una base rica y profunda dominada por el oud, creando un aroma sofisticado y envolvente, ideal para la noche y ocasiones especiales.</p>', 42500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-9d2c-77a9-a196-e7cfd9d85ddf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dc8-1903-75ae-80d6-034c06476a2b.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Armaf Club de Nuit Oud es una fragancia intensa y elegante que destaca por su rica composición basada en el oud, combinada con notas especiadas y amaderadas. Es ideal para quienes buscan un aroma sofisticado, profundo y duradero, perfecto para ocasiones especiales y la noche. Su carácter oriental y exótico aporta un aire de misterio y lujo.</p>', NULL),
(12741, 'Maison Alhambra Como Moiselle EDP 100ml Mujer', '<p>Salda: naranja, mandarina, bergamota, flor de azahar</p><p>Corazón: rosa turca, jazmín, mimosa, ylang‑ylang</p><p>Fondo: pachulí, vetiver, haba tonka, vainilla, almizcle blanco, opoponax</p>', 21000, 0, 'Maison Alhambra', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-1ab3-75df-9318-86b7b9414ccb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dca-5e78-729c-b1be-ef70c000bbf7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dca-5bf3-755d-b2cc-e8d28c19a3a0.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Como Moiselle es una fragancia femenina oriental‑floral inspirada en Coco Mademoiselle de Chanel: comienza fresca y cítrica, evoluciona a un corazón florar profundo y madura en un cierre cálido, dulce y con un toque amaderado.</p>', NULL),
(12742, 'Rasasi Hawas 100ml EDP Hombre', '<p>Notas de salida: Manzana, bergamota, limón y canela.</p><p>Notas de corazón: Azahar, cardamomo y ciruela.</p><p>Notas de fondo: Pachulí, ámbar gris, madera derretida y almizcle</p>', 26000, 1, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-923f-710c-86ad-456d5c743c52.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dce-61c9-7256-8ffa-aa357abf68b1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia acuática y afrutada que combina notas cítricas, especiadas y amaderadas, diseñada para evocar la fuerza y el vigor masculinos</p>', NULL),
(12743, 'Paris Hilton Gold Rush EDP 100ml Mujer', '<p>Salida: nectarina, limón (zest), bergamota </p><p>Corazón: orquídea aterciopelada, rosa, violeta</p><p>Fondo: vainilla de praliné, praliné dorado, maderas de cachemira</p>', 28000, 0, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-91a3-7309-aa51-6abc83eb3e82.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886b6-67cc-74ce-bf04-f75a9125a179.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Gold Rush es la veinteava fragancia de Paris Hilton, creada para evocar el glamur del Hollywood clásico con un aire sofisticado, intenso y irresistible.</p>', NULL),
(12744, 'Armaf Club De Nuit Untold EDP 105ml Unisex', '<p>Familia olfativa: Amaderada - Aromática - Especiada</p><p><br></p><p>Notas de salida: Bergamota, limón, pimienta negra</p><p><br></p><p>Notas de corazón: Lavanda, geranio, canela</p><p><br></p><p>Notas de fondo: Ámbar, almizcle, cedro, pachulí</p><p><br></p><p>Esta fragancia ofrece una apertura fresca y especiada, un corazón floral aromático y una base cálida y amaderada, perfecta para un hombre que busca sofisticación y un aroma versátil para la noche.</p>', 30500, 5, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-926c-7668-9990-b02be300291a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dd1-7a6b-74b8-b30c-beba71e6dde1.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Armaf Club de Nuit Untold es una fragancia masculina sofisticada y misteriosa, que combina notas frescas y especiadas con un corazón floral y un fondo amaderado y almizclado. Está diseñada para hombres elegantes que buscan un aroma distintivo y versátil, ideal para la noche y ocasiones especiales. Su perfil olfativo ofrece un equilibrio perfecto entre frescura, calidez y sensualidad.</p>', NULL),
(12745, 'Kids Mickey Mouse 100ml', '<p>Salida: Cítricos predominantes como limón, bergamota, naranja y algunas notas verdes </p><p>Corazón: Floral suave (jazmín, flor de azahar y flores blancas) </p><p>Fondo: Almizcle blanco, ámbar, vainilla y maderas ligeras</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-8788-70b0-805e-d95ccde09cf1.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Una fragancia infantil tematizada con Mickey Mouse, presentando un frasco divertido decorado con el personaje. Ideal para introducir a los pequeños al mundo de los perfumes con una experiencia alegre y segura</p>', NULL),
(12746, 'Set Tous Baby 100ml + Accesorios', '<p>Notas de salida: Manzana verde y pera.</p><p>Notas de corazón: Flores blancas suaves.</p><p>Notas de fondo: Almizcle blanco y ámbar</p>', 39000, 0, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-881d-765b-83f1-dc26539d7a31.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Un set tierno y delicado diseñado para los más pequeños, que ofrece una fragancia suave, fresca y limpia, ideal para cuidar la piel y envolverlos en una esencia ligera y dulce</p>', NULL),
(12747, 'Boucheron Pour Femme EDP 100ml Mujer', '<p>Notas de salida: Flor de azahar del naranjo, mandarina.</p><p>Notas de corazón: Jazmín, ylang-ylang, nardos.</p><p>Notas de fondo: Sándalo, ámbar, vainilla.</p>', 37000, 0, 'Boucheron', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dd8-ae10-772e-9d12-e645bd2ddd4c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998dd8-ac45-7227-bc5c-6a2fa8137463.png?storeId=1681', 'Mujer', 1, 0, '<p>Boucheron Pour Femme Eau de Parfum es una fragancia femenina de la familia olfativa floral oriental, lanzada originalmente en 1988 y reformulada en 2012. Esta versión moderna mantiene la elegancia y sofisticación de la original, adaptándose a los gustos contemporáneos.</p>', NULL),
(12748, 'Versace Dylan Purple EDP 100ml Mujer', '<p>Salida: Bergamota italiana, naranja amarga, jugo de pera.</p><p>Corazón: Fresia morada, mahonial, pomarosa.</p><p>Fondo: Ambroxan, Iso E Super, cedro de Virginia, belambre, sylkolide.</p>', 49000, 1, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790ff-2a69-75ed-8f84-6dfd4c11e6b8.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790ff-2811-7039-a17d-b3a4bff745d9.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y afrutada que combina notas cítricas con un corazón floral y un fondo amaderado, evocando la elegancia y sofisticación de la mujer moderna.</p>', NULL),
(12749, 'Elizabeth Arden Sunflowers EDT 100ml Mujer', '<p>Notas de salida: Melón, durazno (melocotón), flor de azahar del naranjo, limón (lima ácida), mandarina, bergamota y palo de rosa de Brasil.</p><p>Notas de corazón: Ciclamen (violeta persa), osmanto (olivo oloroso), rosa, jazmín y raíz de lirio.</p><p>Notas de fondo: Sándalo, ámbar, almizcle, musgo de roble y cedro.</p>', 16800, 0, 'Elizabeth Arden', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-7b50-76af-8299-4e915f1ef27d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998ddd-8e2e-750a-b2e6-15d2c253b628.png?storeId=1681', 'Mujer', 1, 0, '<p>Sunflowers de Elizabeth Arden es una fragancia femenina lanzada en 1993, creada por el perfumista David Apel. Esta fragancia pertenece a la familia olfativa Floral Frutal y está inspirada en la frescura y vitalidad de un campo de girasoles. Es ideal para el uso diario, especialmente en climas cálidos y durante las estaciones de primavera y verano.</p>', NULL),
(12750, 'Cristiano Ronaldo FEARLESS EDT 100ml Hombre', '<p>Notas de salida: Pomelo, hoja de violeta, longoza, hoja de laurel.</p><p>Notas de corazón: Geranio de Madagascar, violeta, nuez moscada.</p><p>Notas de fondo: Tonka, vainilla, cachemira,</p>', 25500, 0, 'Cristiano Ronaldo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-860a-707b-a42c-e89e03575eb7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998994-b3a7-7288-a3bc-096a36f53e1f.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia amaderada y especiada lanzada en 2023, diseñada para hombres decididos y seguros de sí mismos. Inspirada en la mentalidad de Cristiano Ronaldo, esta colonia busca transmitir confianza y ambición.</p>', NULL),
(12751, 'Reebok Inspire Your Mind 100ml EDT Hombre', '<p>Notas de salida: Pimienta blanca de Indonesia, yuzu, açaí, cidra y lavanda.</p><p>Notas de corazón: Palo de rosa brasileño, cactus y cipriol.</p><p>Notas de fondo: Vainilla y ámbar</p>', 6800, 2, 'Reebok', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-77bf-77e8-91e2-8f9b5a5f4ec1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-a63e-706f-adc5-2c6243c958fd.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-c1ba-70cf-9e45-cd6fd10865e1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina de la familia olfativa oriental especiada, diseñada para hombres activos y seguros de sí mismos que buscan una esencia fresca y energética</p>', NULL),
(12752, 'Jennifer Lopez Glow EDT 100ml Mujer', '<p>Notas de salida: Neroli, flor de azahar del naranjo y toronja (pomelo).</p><p>Notas de corazón: Jazmín, rosa y nardos.</p><p>Notas de fondo: Almizcle, sándalo, raíz de lirio, ámbar y vainilla.</p>', 24500, 2, 'Jennifer López', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-71d9-72f5-9c66-925d59f2415a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998996-73d3-723b-b706-b1916c827ed6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998996-76a6-739b-9261-96d9dbd83deb.png?storeId=1681', 'Mujer', 1, 0, '<p>Glow by Jennifer Lopez Eau de Toilette 100 ml es una fragancia femenina lanzada en 2002, que marcó el inicio de la exitosa línea de perfumes de la cantante. Esta fragancia se caracteriza por su aroma limpio, floral y ligeramente almizclado, evocando la sensación de piel recién bañada.</p>', NULL),
(12753, 'Hugo Boss Boss Bottled #6 100ml EDT Hombre', '<p>Salida: Manzana verde, ciruela, limón, bergamota, geranio, musgo de roble </p><p>Corazón: Canela dominante, clavel, caoba/mahogany </p><p>magnaperfumes.com</p><p>Fondo: Vainilla, sándalo, cedro, vetiver, oliva, almizcle, pachulí, incienso, cashmeran</p>', 45800, 2, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-6e03-77b4-b163-8ae2f0d944e4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998997-f362-73b9-8d69-5f57092ac8e5.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Boss Bottled #6 es una fragancia masculina clásica lanzada en 1998, conocida por su mezcla cálida, espaciada y manzana‑vainilla, ideal para el día y oficina. Es versátil, elegante y con un aire tradicional que persiste a lo largo del tiempo .</p>', NULL),
(12754, 'Rasasi Hawas Black EDP 100ml Hombre', '<p>Bergamota chispeant</p><p>Piña dulce y jugosa</p><p>Pomelo fresco y ácido</p>', 32000, 0, 'Rasasi', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998999-532a-73fb-b3dc-c48a0891a855.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998999-5443-7485-ada2-f6118f029c01.png?storeId=1681', 'Hombre', 1, 0, '<p>Un perfume moderno e intenso que fusiona cítricos vibrantes con un corazón amaderado-musgoso y un fondo cálido. Ideal para hombres que buscan una fragancia masculina audaz y polivalente, con una estela de confianza y sofisticación.</p>', NULL),
(12755, 'Lancome Hypnose EDP 75ml Mujer', '<p>Notas de salida: Flor de la Pasión</p><p>Notas de corazón: Jazmín, Notas Solares</p><p>Notas de fondo: Vetiver, Vainilla</p>', 50800, 0, 'Lancome', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-64ac-706a-ac47-476a5af4ae21.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199899a-a876-744d-966d-ba23ec59692a.png?storeId=1681', 'Mujer', 1, 0, '<p>Hypnôse de Lancôme, lanzado en 2005, es una fragancia femenina que exuda una feminidad cautivadora y moderna. Su aroma radiante, suave y terso combina notas florales y frutales, creando una experiencia olfativa seductora y sofisticada. Ideal para el uso diario, especialmente en climas cálido</p>', NULL),
(12756, 'Azzaro Pour Homme EDT 100ml', '<p>Familia olfativa: Aromático‑Fougère clásico — fresco, herbal, con un toque especiado y un fondo cálido‑amaderado</p><p>Salida: una mezcla brillante y limpia de lavanda, limón/bergamota, anís estrellado, alcaravea, albahaca, iris y esclarea</p><p>Corazón: vetiver, sándalo y cedro, enriquecidos con pachulí, bayas de enebro y algo de cardamomo</p><p>Fondo: musgo de roble, cuero, ámbar, almizcle y haba tonka le aportan calidez, elegancia y un toque terroso</p>', 28800, 0, 'Azzaro', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-5d9d-743e-a557-51e30b4299e3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199899b-ee56-763f-a8ae-7108a4fa9948.png?storeId=1681', 'Hombre', 1, 0, '<p>Un perfume aromático clásico, que inicia con un acorde limpio y especiado, evoluciona hacia un corazón amaderado y culmina en un fondo cálido, elegante y sutil. Es una elección segura para quien busca un aroma varonil, sobrio y refinado.</p>', NULL),
(12757, 'Adidas Ice Dive 100ml EDT Hombre', '<p>Salida (top): una mezcla enérgica de cítricos y notas verdes: pomelo, bergamota, mandarina, yuzu, kiwi, lavanda, menta y un toque de anís </p><p>Corazón (middle): se abre paso un acorde aromático con geranio, sándalo y pachulí, añadiendo un ángulo suave y terroso </p><p>Fondo (base): base cálida y levemente dulce con haba tonka, vainilla, almizcle, ámbar gris y un matiz de pimienta</p>', 8500, 2, 'Adidas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-5a2a-7747-8c7b-2fb057d7af83.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af75-42a9-7639-b21d-3c27c7a20d68.png?storeId=1681', 'Hombre', 1, 0, '<p>Adidas Ice Dive EDT es una opción muy refrescante, con salida cítrica‑mentolada y un fondo aromático suave. Funciona genial como fragancia deportiva, para gimnasio o uso diario en calor, con una sensación limpia y dinámica. No destaca por su duración, así que si buscas algo más duradero, conviene aplicarlo con más generosidad o re­difundir.</p>', NULL),
(12758, 'Carolina Herrera 212 Heroes 50ml EDT Hombre', '<p>Pera jugosa, jengibre fresco y un acorde ligero de cannabis (Lemon Haze) </p><p>Melodía principal (Corazón): Salvia aromática y geranio madagascar, aportan frescura herbal y floral </p><p>Ritmo final (Fondo): Cuero cálido y almizcle limpio, con fondo amaderado tenue</p>', 39500, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-53a6-727e-8db6-186f7d8423dc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199899d-0b87-7643-b269-107061f2a7a6.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia aromática frutal amaderada creada en 2021, diseñada para un espíritu libre y auténtico. Envuelta en un frasco con forma de monopatín, refleja juventud, libertad y estilo urbano.</p>', NULL),
(12759, 'Body Spray Lattafa Amethyst Unisex', '<p>Salida: pimienta rosa y bergamota — fresca y especiada </p><p>Corazón: rosas turca y de Bulgaria, acompañadas de jazmín </p><p>Fondo: madera de oud (sutil), ámbar y vainilla — aporta</p>', 4500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-4ed3-7058-8f01-bce92513a136.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-1ad6-7664-b7a6-88b9a2df3040.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-a667-7519-97b3-ccef1aedec08.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Amethyst es un body spray unisex con un intenso enfoque en rosas suaves, oud ligero y una base cálida de ámbar-vainilla. Su rendimiento es excelente, especialmente en ropa, pero su apertura puede sentirse muy fuerte o sintética para algunas narices. Mejora significativamente tras un periodo de maceración. Es ideal para quienes buscan un aroma floral-oud profundo y duradero con presencia notable.</p>', NULL),
(12760, 'Set Ariana Grande ARI 3PC Mujer', '<p>Notas de salida: Pera, pomelo rosado y frambuesa.</p><p>Notas de corazón: Lirio de los valles, capullos de rosa y orquídea de vainilla.</p><p>Notas de fondo: Malvavisco, almizcle cremoso y maderas rubias</p>', 43500, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-426f-7078-bb4f-206820ff9ccc.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Este set reúne la esencia dulce y femenina de Ari en tres productos imprescindibles: el Eau de Parfum, la loción corporal y la bruma ligera. Perfecto para envolver tu día en una fragancia fresca, cremosa y frutal que evoca juventud, alegría y sofisticación. Ideal para mujeres que buscan un aroma vibrante, delicado y lleno de energía positiva.</p>', NULL),
(12761, 'Moschino I Love Love 100ml EDT Mujer', '<p>Salida: naranja, pomelo, limón, grosella roja </p><p>Corazón: rosa de té, lirio de los valles, espadaña, caña de azúcar, canela </p><p>Fondo: almizcle, cedro, madera de tanaka/amaderada</p>', 28800, 0, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-398c-76b2-8879-8a0a8deb5263.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ef1-56f0-765b-9d13-f0793049655a.png?storeId=1681', 'Mujer', 1, 0, '<p>Moschino I Love Love (anteriormente Cheap &amp; Chic I Love Love) es una fragancia femenina vibrante y juvenil, lanzada en 2004 y creada por el perfumista Olivier Cresp. Pertenece a la familia olfativa flor‑almizclada‑amaderada y evoca sensaciones de alegría, frescura y energía, ideal para días de primavera y verano</p>', NULL),
(12762, 'Lattafa Khamrah 100ml EDP Unisex', '<p><strong>Notas de salida:</strong> Canela, nuez moscada, bergamota</p><p><strong>Notas de corazón:</strong> Dátiles, praliné, tuberosa, mahonial</p><p><strong>Notas de fondo:</strong> Vainilla, haba tonka, benjuí, mirra, madera de ámbar, madera de Akigalawood</p>', 24000, 3, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790ea-2feb-732b-8dfc-6d42600c3c71.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790ea-eaca-703c-87e7-c03fe36fed67.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-52d0-75da-a85a-3383a1918c34.jpeg?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Lattafa Khamrah es una fragancia unisex cálida y especiada, que combina notas dulces de dátiles y praliné con toques orientales de canela, vainilla y madera. Su aroma envolvente y sofisticado es ideal para quienes buscan una esencia elegante y con carácter, perfecta para noches y climas frescos.</p>', NULL),
(12763, 'Adidas Dynamic Pulse 100ml EDT Hombre', '<p>Familia: Aromática, fresca y deportiva.</p><p>Salida: Cítricos vibrantes (bergamota, limón, mandarina o toronja), mezclados con menta refrescante y cedro</p><p>Corazón: Notas aromáticas de lavanda, romero y manzana aportan frescura herbal-frutal .</p><p>Fondo: Base sencilla pero limpia de almizcle, haba tonka, pachulí y labdanum</p>', 8500, 2, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-339d-75a9-8284-9ca800387b69.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198af77-d9ca-771b-a009-21e97877dc40.png?storeId=1681', 'Hombre', 1, 0, '<p>Un eau de toilette fresco, limpio y deportivo que combina cítricos, menta y notas aromáticas sobre una base suave. Con una duración moderada de 2–3 horas y estela discreta, es ideal para actividades casuales, gimnasio o uso diario. Si buscas frescura sin complicaciones y gran relación calidad-precio, Adidas Dynamic Pulse es una opción accesible, clara y sin pretension.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12764, 'Yvest Saint Laurent Y EDP 100ml Hombre', '<p>Notas de salida: manzana verde, jengibre y bergamota.</p><p>Notas de corazón: salvia, bayas de enebro y geranio.</p><p>Notas de fondo: ámber, haba tonka, cedro, vetiver e incienso de olíbano.</p>', 76000, 0, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-2928-736f-89a1-2d03945ac378.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a0-1e9c-74ba-a8b4-20f9cde9e029.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia moderna y versátil que combina frescura, energía y sofisticación, ideal para el hombre contemporáneo que busca una esencia distintiva y duradera.</p>', NULL),
(12765, 'Jovan Musk 3.0 Cologne Hombre', '<p>Salida: Pimienta, limón Amalfí, lima, clavel.</p><p>Corazón: Lavanda, ámbar, menta, especias.</p><p>Fondo: Maderas y, sobre todo, almizcle.</p>', 7800, 0, 'Jovan Musk', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-24bb-7650-8f80-a782c82d85c3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a1-7f13-76a9-9dd0-a7ee628cb7fd.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Jovan Musk es un clásico de 1972/73, parte de la línea Jovan y elaborada hoy por Coty. Es una colonia con estilo fougère-musky, que combina hierbas, especias cálidas y un toque amaderado, resultando en un aroma limpio, nostálgico y con carácter masculino</p>', NULL),
(12766, 'Givenchy PI EDT 100ml Hombre', '<p>Salida: Mandarina, estragón, romero y albahaca </p><p>Corazón: Anís, neroli, geranio y lirio de los valles (muguete) </p><p>Fondo: Vainilla, almendra, haba tonka, benjuí y cedro</p>', 46500, 0, 'Givenchy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-2150-72f9-ae47-a9f8990e4f4d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a2-cbc6-74ca-9e72-2fb992851989.png?storeId=1681', 'Hombre', 1, 0, '<p>Pi de Givenchy es un clásico masculino de la familia Ambar Amaderada, lanzado en 1998, creado por Alberto Morillas. Evoca una sensación cálida, elegante y reconfortante, perfecta para el día o ambientes relajados en clima fresco.</p>', NULL),
(12767, 'Paco Rabanne Fame Intense 80ml Mujer', '<p>Salida: agua de coco, bergamota, pimienta rosa – aportan frescura y un matiz tropical picante </p><p>Corazón: jazmín solar, trío de incienso, ylang‑ylang – crean una mezcla floral resplandeciente con profundidad ambarada </p><p>Fondo: sándalo cremoso, cedro, almizcle mineral – base cálida, leñosa y ligeramente sensual</p>', 67000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-d24f-76ab-9a0c-ffed59b363ce.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a6-fc99-77f3-a3d9-e7aacf8457ee.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Fame Intense (2024) es la versión más rica y adictiva de la línea Fame. Con un frasco dorado recargable, ofrece una mezcla elegante y sensual de jazmín, incienso y sándalo, diseñada para destacar en la noche y momentos especiales.</p>', NULL),
(12768, 'Hugo Boss In Motion 100ml EDT Hombre', '<p>Salida: Bergamota y naranja efervescente, hojas de violeta y albahaca </p><p>Corazón: Pimienta rosa, cardamomo, canela, nuez moscada </p><p>Fondo: Maderas preciosas, sándalo, vetiver y almizcle</p>', 27000, 2, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-1dda-75cd-a8d2-3bc2882e3d6c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a8-a303-714c-a39a-d9b4ee084f81.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989a8-a349-7178-9c2c-8856244c3beb.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Boss In Motion de Hugo Boss (nuevo empaque, 3.3 oz / 100 ml EDT) es una fragancia masculina moderna, inspirada en el movimiento y la energía. Se posiciona dentro de la familia ámbar fougère, combinando frescura cítrica con especias cálidas y una base de maderas sensuales—ideal para días activos y uso urbano.</p>', NULL),
(12769, 'Carolina Herrera 212 Heroes 90ml Hombre', '<p>Notas de salida: pera, jengibre y cannabis (Lemon Haze)</p><p>Notas de corazón: geranio y salvia</p><p>Notas de fondo: almizcle y cuero</p>', 57000, 3, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-bab1-77c2-99b1-09db1beb0d93.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989ac-1afa-77b2-a7a7-d3b29b8c4e84.png?storeId=1681', 'Hombre', 1, 0, '<p>Carolina Herrera 212 Heroes for Him es una fragancia masculina lanzada en 2021, diseñada para celebrar la juventud, la libertad y la autenticidad. Su aroma fresco y moderno se presenta en un envase innovador con forma de monopatín, simbolizando la creatividad y el estilo urbano. Es una opción ideal para quienes buscan una fragancia versátil y energética.</p>', NULL),
(12770, 'Issey Miyake L’Eau D’Issey 100ml EDT Mujer', '<p>Salida:</p><p>Melón, rosa, loto, ciclamen, freesia, rosa de agua, calone</p><p>Lirio de los valles, peonía, clavel.</p><p>Fondo:</p><p>Almizcle, sándalo, cedro, ámbar, osmanthus</p>', 36000, 1, 'Issey Miyake', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989ad-41a4-7671-9e51-6a65144e5156.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989ad-419a-743b-b589-bc647bf95374.png?storeId=1681', 'Mujer', 1, 0, '<p>L’Eau d’Issey es una fragancia femenina clásica lanzada en 1992 por Issey Miyake, creada por el perfumista Jacques Cavallier. Se caracteriza por su perfil floral y acuático, evocando la frescura de una gota de agua en una flor. Es ideal para quienes buscan un aroma limpio, elegante y atemporal.</p>', NULL),
(12771, 'Set Paco Rabanne Invictus 1.7 EDT Sp + 0.33 EDT Sp Men', '<p>Notas de salida: Pomelo, notas marinas y mandarina.</p><p>Notas de corazón: Jazmín, laurel y hojas de violeta.</p><p>Notas de fondo: Ámbar gris, musgo de roble y pachulí.</p>', 48800, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-174e-70da-aa72-a01c70542e97.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-50e2-711f-96f9-70801b0aff5f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-4fd9-761d-8ba4-7f11da9039dc.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set vibrante y enérgico que celebra la fuerza y la victoria, combinando la fragancia fresca y acuática de Invictus con un tamaño mini ideal para llevar la esencia del triunfo a todas partes.</p>', NULL),
(12772, 'Tous LoveMe 90ml EDP Mujer', '<p>Salida: Pomelo rosa, pimienta rosa y lichi.</p><p>Corazón: Peonía Firbest, rosa centifolia y pétalos de jazmín.</p><p>Fondo: Cedro, acorde cashmere y mousse crystal.</p>', 39000, 2, 'Tous', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-1183-715a-b880-07515a0281f2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f82-828c-7064-9c3f-2da0f1be397a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia floral afrutada que celebra la feminidad moderna con una combinación de notas frescas y elegantes, ideal para mujeres que buscan una esencia sofisticada y versátil</p>', NULL),
(12773, 'Carolina Herrera 212 Sexy 100ml EDT Hombre', '<p>Mandarina, bergamota y notas verdes — ofrece frescura cítrica y un matiz herbal sutil. </p><p>Melodía principal (Corazón): Cardamomo, pimienta y un toque floral — especiado, audaz y masculino. </p><p>Ritmo final (Fondo): Vainilla, madera de gaiac, sándalo, ámbar y almizcle — crea una estela cálida</p>', 46800, 2, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-0c81-737f-9753-1236161941b6.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989ae-f31b-7033-87b1-fb5142ec68fa.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia masculina oriental-fougère lanzada en 2006, diseñada para un toque seductor y moderno. Combina toques especiados dulces con una base amaderada cálida y envolvente, perfecta para noches o climas fríos.</p>', NULL),
(12774, 'Prada Paradoxe EDP 90ml Mujer', '<p>Salida: pera, naranja tangerina y bergamota.</p><p>Corazón: flor de azahar del naranjo, esencia de neroli y jazmín sambac.</p><p>Fondo: vainilla Bourbon, ámbar, almizcle blanco y benjuí.</p>', 76000, 0, 'Prada', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-0a5e-716c-a463-0a64b890d486.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019989b1-6681-779a-9cbc-ffd2f52ce216.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Prada Paradoxe Eau de Parfum es una fragancia femenina lanzada en 2022 que celebra la dualidad de la mujer moderna: suave y poderosa, clásica y contemporánea. Su composición olfativa combina notas florales, cítricas y amaderadas, creando una estela elegante y duradera</p>', NULL),
(12775, 'Little Pony EDT 100ml', '<p>Salida: bergamota, naranja, ciruela </p><p>Corazón: flor de azahar, orquídea y rosa </p><p>Fondo: almizcle suave, vainilla y maderas ligeras</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-06bb-76ec-a10b-c65d61d30f0f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f4-c622-72c3-b321-2dcdfe6d23e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-92c9-74fb-ab93-bbb78252cd89.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Dulce y juguetón, pensado para niñ@s: cítrico‑afrutado con un toque floral suave y una base cremosa y reconfortante.</p>', NULL),
(12776, 'Set Ariana Grande Sweet Like Candy 3pc', '<p>Notas de salida: Frambuesa, mandarina y grosella negra.</p><p>Notas de corazón: Jazmín, peonía y flor de azahar del naranjo.</p><p>Notas de fondo: Almizcle, caramelo y ámbar</p>', 46000, 0, 'Ariana Grande', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-06bf-7651-8564-fbb5e5659d91.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-c102-7618-ac78-9ecfb46cc9e1.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-6f62-726d-92f9-0933ddba6a37.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set delicioso y encantador que captura la esencia dulce y juguetona de Sweet Like Candy, ideal para quienes disfrutan de fragancias gourmand con un toque frutal y femenino.</p>', NULL),
(12777, 'Jesus Del Pozo Halloween Magic EDT 100ml Mujer', '<p>Notas de salida: Helado de pera, frambuesa, mandarina amarilla</p><p>Notas de corazón: Fresia, peonía rosa, jazmín sambac</p><p>Notas de fondo: Vainilla, haba tonka, pachulí</p>', 22800, 1, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976073-01e4-7449-ac9d-85d8e5b6e5dc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998975-eb43-73fb-a282-f2f760ba5f1d.png?storeId=1681', 'Mujer', 1, 0, '<p>Halloween Magic de Jesús del Pozo, lanzado en 2018, es una fragancia femenina que combina notas florales y frutales con un toque dulce y envolvente. Ideal para el día y especialmente para climas cálidos, ofrece una experiencia olfativa ligera y fresca.</p>', NULL),
(12778, 'Clinique Happy Heart 100ml Parfum Mujer', '<p>Mandarina destellos cítricos chispeantes</p><p>Pepino frescura acuática y vitalidad </p><p>Modía central</p><p>Primula amarilla, jacinto de agua  y zanahoria  flores suaves y un toque verde envolvente</p>', 24800, 0, 'Clinique Happy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-fe32-7629-92ce-a7e8327df3f8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998977-2f9f-7454-bee3-ebb69fb134aa.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia fresca y luminosa con un toque floral y amaderado, diseñada para transmitir alegría y optimismo. Tiene un estilo corporal espontáneo: radiante, acogedora y perfecta para el día a día.</p>', NULL),
(12779, 'Armaf Club De Nuit Iconic EDP 105ml Hombre', '<p>Familia olfativa: Amaderada - Aromática - Especiada</p><p><br></p><p>Notas de salida: Bergamota, limón, pimienta rosa</p><p><br></p><p>Notas de corazón: Jazmín, lavanda, geranio</p><p><br></p><p>Notas de fondo: Almizcle, ámbar gris, cedro, pachulí</p><p><br></p><p>Esta fragancia ofrece un equilibrio entre frescura cítrica, un corazón floral aromático y una base cálida y amaderada, perfecta para hombres que buscan un aroma elegante y duradero, ideal para la noche y eventos formales.</p>', 32500, 3, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-f9f1-7189-b960-4dacd69d61f4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ebe-bd62-752b-84d8-a108d49ebf5e.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Club de Nuit Iconic es una fragancia masculina sofisticada y poderosa, diseñada para hombres que buscan elegancia y presencia. Combina notas frescas y especiadas con un corazón floral y un fondo amaderado y almizclado. Es ideal para la noche y ocasiones especiales, ofreciendo un aroma intenso, duradero y con un toque moderno que deja una impresión memorable.</p>', NULL),
(12780, 'Versace Eros Flame 100ml EDP Hombre', '<p><strong>Salida:</strong> Mandarina, pimienta negra de Madagascar, Chinotto, limón (lima ácida) y romero.</p><p><strong>Corazón:</strong> Pimienta, geranio y rosa.</p><p><strong>Fondo:</strong> Vainilla, haba tonka, cedro de Texas, sándalo, pachulí y musgo de roble.</p>', 48000, 5, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-335f-704f-a4b6-2624d4f139bc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198ea2f-9f4b-71ee-8691-803339540a8b.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia apasionada y sofisticada que fusiona notas cítricas y especiadas con un fondo amaderado y dulce, evocando la intensidad del amor.</p>', NULL),
(12781, 'Liz Claiborne Curve Wave 100ml EDT Mujer', '<p>Salida: Carambola (fruta estrella), madreselva, frambuesa, orquídea</p><p>Corazón: Azucena, frangipani (plumeria), flor de pasionaria, hibisco</p><p>Fondo: Almizcle, sándalo, ámbar</p>', 14500, 8, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998979-6d4b-7459-96fa-927336dd5c1b.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998979-6125-740d-a432-4fdf52d2530c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199897a-cdad-70e6-8831-950905786ba6.png?storeId=1681', 'Mujer', 1, 0, '<p>Liz Claiborne Curve Wave es una fragancia femenina fresca y tropical, lanzada en 2005. Su combinación de notas frutales y florales, junto con un fondo amaderado y almizclado, la convierte en una opción ideal para el uso diario en climas cálidos</p>', NULL),
(12782, 'Set Versace Eros Flame EDP + Bolso Hombre', '<p>Notas de salida: Bergamota, pimienta roja y naranja sanguina.</p><p>Notas de corazón: Cedro, geranio y rosa.</p><p>Notas de fondo: Vainilla, haba tonka y musgo de roble</p>', 62000, 2, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-2862-76de-b79f-5695943e7615.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a01-7029-77d7-a36b-973b84351104.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set ardiente y sofisticado que combina la energía intensa de Eros Flame con un bolso elegante y práctico, perfecto para hombres que buscan una fragancia poderosa, especiada y amaderada, junto a un accesorio con estilo.</p>', NULL),
(12783, 'Body Mist Perry Ellis 360 8.0 Sp Women', '<p>Notas de salida: Mandarina, melón y lirio amazónico.</p><p>Notas de corazón: Salvia, lavanda y muguet </p><p>Notas de fondo: Ámbar, vetiver y almizcle</p>', 8500, 3, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-20b5-746a-928a-c2031f750e75.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-1008-75f1-a3c6-9a755a8967df.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-11d3-76fe-b2a4-ff32df2bba64.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Perry Ellis 360° for Women 8.0 oz es una fragancia femenina clásica que ha sido popular durante décadas. Lanzada en 1992, esta bruma corporal ofrece una experiencia olfativa fresca y floral, ideal para el uso diario</p>', NULL),
(12784, 'Kim Kardashian Glam EDP 100ml Mujer', '<p>Salida: Sandía, frutos rojos y cítricos — una mezcla jugosa y fresca&nbsp;</p><p>Corazón: Tuberosa, jazmín estelar y rosa — un bouquet blanco-limpiador y femenino&nbsp;</p><p>Fondo: Musc, raíz de lirio (orris butter) y sándalo — aportan una base suave, cremosa y en polvo</p>', 16800, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-1cc7-751f-9e53-04555e627daa.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199897e-ec97-73eb-ae04-2fa6651828bf.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2012 como el tercer flanker tras Kim Kardashian y Gold, Glam es una fragancia floral‑frutal femenina pensada para un estilo sofisticado pero juvenil&nbsp;</p><p>. Su botella redonda en degradé rosa es un guiño al glamour que le da nombre y se volvió icónica entre los fans&nbsp;.</p>', NULL),
(12785, 'Ralph Lauren Polo Blue 75ml EDT Hombre', '<p>Notas de salida: Melón, pepino, mandarina y bergamota.</p><p>Notas de corazón: Geranio, salvia, albahaca y verbena.</p><p>Notas de fondo: Suede (cuero suave), almizcle, pachulí y ámba</p>', 30500, 0, 'Ralph Lauren', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998981-4f2e-7572-b51a-0adf8b815398.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998981-4e7b-7697-9fe3-028bc646f2ab.png?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y acuática que combina notas cítricas y herbales, evocando la libertad y la energía del aire libre.</p>', NULL),
(12786, 'Jovan White Musk 96ml Cologne Mujer', '<p>Salida: Bergamota, jazmín, lirio de los valles, jacinto — apertura limpia, ligeramente brillante </p><p>Corazón: Ylang-ylang, espinas suaves, especias muy ligeras </p><p>Fondo: Almizcle blanco, ámbar, pachulí, sándalo — secado cálido y acogedor</p>', 8800, 1, 'Jovan Musk', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998984-c6c3-758d-9b0a-f0c0312f11db.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998984-c605-756e-bb18-de8d7bd8e4b3.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 1992 por Jovan (actualmente bajo Coty), White Musk es una colonia femenina con un aroma blanco, limpio y ligeramente floral, ideal para uso diario, ligera y acogedora. Se percibe como un perfume fresco y suave, evocando sensaciones de “recién salida de la ducha” o “piel con talco”</p>', NULL),
(12787, 'Armaf Odyssey Spectra EDP 100ml Hombre', '<p><strong>Notas de salida</strong></p><p>Canela</p><p>Manzana</p><p>Bergamota</p><p><strong> Notas de corazón</strong></p><p>Lavanda</p><p>Haba tonka</p><p>Vainilla</p><p>Ámbar</p><p>Pachulí</p>', 29500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-1621-737d-adbf-a7c89f9db044.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998985-917b-7319-a9d6-048b673b3637.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Spectra EDP es una fragancia unisex lanzada en 2024, que pertenece a la familia olfativa oriental especiada. Se caracteriza por su apertura cálida y especiada, combinando notas de canela, manzana y bergamota. En su corazón, se encuentran notas florales y especiadas de lavanda, lirio de los valles y flor de azahar del naranjo, mientras que su fondo es profundo y envolvente, con notas de tabaco, haba tonka, vainilla, ámbar y pachulí.</p>', NULL),
(12788, 'Valentino Uomo Born In Roma Coral Fantasy 100ml EDT Hombre', '<p>Salida: manzana roja, cardamomo, bergamota de Calabria.</p><p>Corazón: lavanda, geranio bourbon, esclarea.</p><p>Fondo: hojas de tabaco, pachulí, vetiver de Haití.</p>', 68500, 1, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e5-2af8-72ce-bfaf-c638171659ac.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998987-f829-7495-9d3d-2d6f6adf1315.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Fragancia amaderada-aromática con apertura fresca y afrutada, corazón aromático y fondo cálido de tabaco y vetiver. Moderno y cautivador, con una mezcla de notas gourmands y especiadas.</p>', NULL),
(12789, 'Set Moschino Bubble Gum 3PZAS Mujer', '<p>Notas de salida: Frambuesa, mandarina y limón.</p><p>Notas de corazón: Peonía, flor de azahar y jazmín.</p><p>Notas de fondo: Almizcle blanco, caramelo y ámbar.</p>', 51000, 0, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-0f0b-700c-b315-881fce205624.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-38ce-707f-83ed-cb2a57184484.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31c-3889-726e-96b1-274857739948.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set divertido y juvenil que captura la esencia dulce y juguetona del chicle, ideal para quienes buscan una fragancia fresca, vibrante y llena de energía positiva.</p>', NULL),
(12790, 'Moschino Funny  EDT 100ml Mujer', '<p>Salida: naranja amarga, grosella roja, pimienta rosa</p><p>Corazón: té verde, peonía, jazmín, violeta</p><p>Fondo: cedro, almizcle, musgo de roble, ámbar</p>', 27000, 0, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-0a66-73fe-a097-937715b5cadc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ef3-bb94-776d-9896-9f3f18c6f9f3.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Moschino Funny es una fragancia femenina divertida y vibrante, con un perfil cítrico, floral y fresco. Ideal para uso diario, especialmente en primavera y verano, despierta alegría y energía con su toque casual y juvenil.</p>', NULL),
(12791, 'Body Mist Paris Hilton Rose Rush 8.0 Sp Women', '<p>Notas de salida: Pétalos de rosa, neroli y lichi.</p><p>Notas de corazón: Rosa de mayo, peonía y papaya jugosa.</p><p>Notas de fondo: Ámbar chispeante, madera de cedro y almizcle blanco.</p>', 7800, 5, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-071e-720d-9f5e-1bf864b562b3.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-d89d-76c4-a6f7-3feec21568ae.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Paris Hilton Rose Rush 8.0 oz es una fragancia femenina que combina notas florales y afrutadas, diseñada para ofrecer una experiencia sensorial fresca y sofisticada.</p>', NULL),
(12792, 'Set Versace Man Eau Fraiche 3.4 EDT Sp + 3.4S/G Men', '<p>Notas de salida: Limón, bergamota y carambola.</p><p>Notas de corazón: Cedro, estragón y salvia.</p><p>Notas de fondo: Ámbar, almizcle y madera de sicómoro.</p>', 45500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976072-02f5-732b-9264-40db68940324.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f6-ed90-77df-87e0-a3a9e82f3938.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-1423-720d-83d8-16115f2364ee.jpeg?storeId=1681', 'Sets Hombre', 1, 0, '<p>Un set fresco y sofisticado que combina la energía del Mediterráneo con el estilo elegante de Versace. Perfecto para el hombre moderno, espontáneo y seguro de sí mismo.</p>', NULL),
(12793, 'Body Spray Odyssey  WILD ONE GOLD', '<p>Salida: pimienta negra, bergamota, limón y menta — combinación fresca y especiada</p><p>Corazón: vetiver, lavanda, jengibre y pimienta rosa — equilibrio interesante entre tierra, herbalidad y chispa</p><p>Fondo: vetiver (deja doble rastro), sándalo, pachulí, elemi, cedro y almizcle — base cálida, amaderada y duradera</p>', 5500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e6-05ae-745f-9ce2-7c36d7c7d29f.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Wild One Gold es un body spray masculino con un perfil amaderado y especiado, que combina notas frescas de limón, bergamota y menta con un corazón de lavanda y jengibre, sobre una base cálida de vetiver, sándalo y almizcle. Inspirado en aromas modernos como Dior Sauvage, es ideal para uso diario o salidas nocturnas.</p>', NULL),
(12794, 'Body Mist VICTORIA SECRET Scandalous', '<p>Salida: Licor de frambuesa, aportando una apertura dulce y afrutada.</p><p>Corazón: Peonía negra, ofreciendo una nota floral rica y profunda.</p><p>Fondo: Praliné, brindando una base dulce y cremosa que equilibra la composición</p>', 15000, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-fb33-76c8-a539-e9ab3ab5c3a7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fd-3d64-70c3-944a-122bde1604bc.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-6543-7739-b81b-1f874d5477e1.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Scandalous es una fragancia femenina y sensual que combina notas frutales y florales con un toque dulce. Lanzada en 2014, esta fragancia busca evocar una sensación de audacia y sofisticación.</p>', NULL),
(12795, 'Body Mist Pink Sugar Sky', '<p>Salida: azúcar granulada tipo algodón de azúcar envuelta en una suavidad cremosa, asemejando vainilla batida con un matiz afrutado (algunas versiones mencionan frutas rojas o coco) </p><p>Corazón: fondo de almizcle lavanda o musk floral, que aporta limpieza y suavidad, creando un aire etéreo y delicado </p><p>Fondo: una mezcla cálida y reconfortante con toques de lavanda musk, vainilla suave y almizcle acogedor .</p>', 11800, 3, 'Pink', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-f8de-71f8-8bed-9583db1075a8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f8-f0fa-7000-b04e-b88fc65591f8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c326-22d4-72ef-9c6f-97df5e090fa0.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Pink Sugar Sky es una bruma corporal ideal si te gustan los aromas dulces, suaves y elegantes, con carácter gourmand pero sin ser empalagosos. Su combinación de azúcar, vainilla y musk crea una sensación acogedora, casi hogareña. A diferencia de las típicas fragancias intensas, esta mist gana con la combinación: aplica tras la ducha y acompáñalo con la loción para mejorar su fijación.</p>', NULL),
(12796, 'Liz Claiborne Curve Crush 100ml EDT Mujer', '<p><strong>Notas de salida</strong>: kiwi, lavanda, mandarina, yuzu, menta, toronja, anís y bergamota</p><p><strong>Notas de corazón</strong>: sándalo, pachulí y geranio</p><p><strong>Notas de fondo</strong>: haba tonka, almizcle, vainilla, pimienta y ámbar gris</p>', 21500, 9, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886d5-c67a-721b-b791-cf268c0b4715.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886d5-c571-75ba-b650-7ee249f8b2dc.jpeg?storeId=1681', 'Mujer', 1, 0, '<p><strong>Liz Claiborne Curve Crush</strong> es una fragancia femenina floral-frutal que combina cítricos frescos, especias cálidas y matices lechosos. Su estela es suave y acogedora, ideal para uso diario, especialmente en épocas templadas o frías. Su encanto radica en transmitir comodidad y nostalgia, con una dulzura discreta y un toque especiado. Perfecta para quienes buscan una fragancia reconfortante pero sencilla de llevar.</p>', NULL),
(12797, 'Chanel Chance Eau Tendre 100ml EDT Mujer', '<p>Notas de salida: toronja (pomelo) y membrillo.</p><p>Notas de corazón: jazmín y jacinto.</p><p>Notas de fondo: almizcle blanco, iris, cedro de Virginia y ámbar.</p>', 98000, 0, 'Chanel', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-efa3-752b-88a2-516d139c87d6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998990-f0bb-72ca-bdd0-a3104420616b.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Chanel Chance Eau Tendre es una fragancia femenina lanzada en 2010, creada por el perfumista Jacques Polge. Pertenece a la familia olfativa floral frutal y se caracteriza por su suavidad, frescura y elegancia.</p>', NULL),
(12798, 'Lattafa AJWAD EDP 60ml Unisex', '<p>Notas de salida: Notas afrutadas</p><p>Notas de corazón: Rosa, jazmín</p><p>Notas de fondo: Vainilla, almizcle, ámbar, cedro</p>', 20500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998992-848d-716c-84f1-4b627fb7b6fe.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998992-82b4-7290-bf58-78b5d4a62f8b.jpeg?storeId=1681', 'Mujer|Hombre', 1, 0, '<p>Ajwad de Lattafa es una fragancia unisex que combina notas florales y amaderadas con un toque dulce y especiado. Su apertura afrutada da paso a un corazón floral de rosa y jazmín, mientras que en el fondo se perciben notas cálidas de vainilla, almizcle, ámbar y cedro. Es ideal para quienes buscan una fragancia sofisticada y envolvente.</p>', NULL),
(12799, 'Hugo Boss The Scent 100ml EDT Hombre', '<p>Salida: Jengibre, mandarina, bergamota — un arranque fresco y especiado.</p><p>Corazón: Fruta de maninka (fruta africana dulce/exótica) y lavanda — añade un toque aromático y frutal.</p><p>Fondo: Cuero y notas amaderadas — base cálida y masculina con un dejo elegante</p>', 46500, 2, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-e3bf-7238-bed6-133cd39d9894.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019b15aa-0756-74fe-a5ff-f4d3d43fd948.png?storeId=1681', 'Hombre', 1, 0, '<p>Boss The Scent (2015) es una fragancia masculina oriental‑especiada que evoca seducción y magnetismo. Mezcla fresca y cálida que destaca por su estilo masculino, ideal para usar en ocasiones especiales o en el día a día con elegancia</p>', NULL),
(12800, 'Hugo Boss Femme EDP 75ml Mujer', '<p>Notas de salida: Fresia, mandarina, grosella negra</p><p>Notas de corazón: Rosa de Bulgaria, azucena, jazmín</p><p>Notas de fondo: Limonero, albaricoque, ámbar</p>', 28500, 1, 'Hugo Boss', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-e453-729e-8d80-df4457a00bca.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198809e-bd17-7188-86b4-0e20d6f8079a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Hugo Boss Femme es una fragancia femenina que exuda una feminidad cautivadora y moderna. Su aroma radiante, suave y terso combina notas florales y frutales, creando una experiencia olfativa seductora y sofisticada. Ideal para el uso diario, especialmente en climas cálidos.</p>', NULL),
(12801, 'Set Elizabeth Arden White Tea PERFUME + CREMA', '<p>Notas de salida: Bergamota, mandarina y limón</p><p>Notas de corazón: Té blanco, jazmín y lirio de los valles.</p><p>Notas de fondo: Almizcle, cedro y ámbar.</p>', 32000, 0, 'Elizabeth Arden', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-dcd7-73f5-8499-3d770313cb9c.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set delicado y sereno que combina la fragancia fresca y elegante de White Tea con una crema corporal hidratante, ideal para quienes buscan una experiencia relajante y sofisticada con aromas limpios y suaves.</p>', NULL),
(12802, 'Lattafa Asad 100ml EDP Hombre', '<p>Notas de salida: Pimienta negra, tabaco, piña.</p><p>Notas de corazón: Pachulí, café, iris.</p><p>Notas de fondo: Vainilla, ámbar, madera seca, benjuí, ládano</p>', 22000, 5, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998436-e7ca-70ba-b72b-075faf8d7f7a.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998436-e9d8-75e8-aedf-48bff76d947e.png?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Asad es una fragancia masculina que ha ganado popularidad por su similitud con Dior Sauvage Elixir, ofreciendo una opción más accesible sin sacrificar calidad. Con una combinación de notas especiadas, amaderadas y dulces, es ideal para quienes buscan una esencia intensa y duradera.</p>', NULL),
(12803, 'Body Mist Victoria Secret Bare Vainilla Candied', '<p>Salida: malvavisco cremoso y chispas de fresa (fruity‑gourmand) </p><p>Corazón: flor de malvavisco (marshmallow flower) y remolino de ciruela o gelatina de durazno </p><p>Fondo: cálida vainilla azucarada, caramelo y un suave velo almizclado</p>', 12800, 0, 'Victoria Secret', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-d087-7048-822a-3768398163b2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f9-085b-727b-a9c8-43940dbd534d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-a105-71aa-91a9-555195ef14cf.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>Bare Vanilla Candied es una fragancia gourmand femenina que combina la calidez de la vainilla cremosa con un toque acogedor de malvavisco y una suave nota frutal (fresa/pastel). Dulce, nostálgico y festivo, ideal para quienes aman los aromas cálidos y reconfortantes en días frescos.</p>', NULL),
(12804, 'Reyane Tradition Acqua Di Parisis Magic EDP 100ml', '<p>Salida: Frambuesa, grosella negra, mandarina y pimienta rosa.</p><p>Corazón: Rosa, jazmín y flor de azahar.</p><p>Fondo: Pachulí, ámbar y vainilla</p>', 19800, 0, 'Reyane Tradition', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-ccfa-7069-889c-df62893701e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779f5-9edd-71e4-863d-cacb4fbc5412.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31a-2a7a-7506-aba7-e276a864808a.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia oriental floral que combina notas frutales y florales con un toque amaderado, creando una experiencia olfativa envolvente y seductora.</p>', NULL),
(12805, 'Carolina Herrera 212 Heroes EDP 80ml Mujer', '<p>Notas de salida: mandarina y frambuesa</p><p>Notas de corazón: jazmín y flor de azahar del naranjo</p><p>Notas de fondo: cedro y sándalo</p>', 58000, 0, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-c70f-74d1-99e5-ae90e582a783.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998451-d134-76bd-a2eb-b09d5e08238d.png?storeId=1681', 'Mujer', 1, 0, '<p>Carolina Herrera 212 Heroes for Her es una fragancia femenina lanzada en 2021 que celebra la juventud, la autenticidad y la libertad de ser uno mismo. Esta fragancia 100% vegana y de origen sostenible se presenta en un innovador frasco en forma de monopatín, simbolizando la creatividad y el estilo urbano</p>', NULL),
(12806, 'Set Moschino Toy 2 4pzas Mujer', '<p>Notas de salida: Bergamota, mandarina y pimienta rosa.</p><p>Notas de corazón: Jazmín, flor de azahar y pera.</p><p>Notas de fondo: Almizcle blanco, maderas claras y vainilla.</p>', 48800, 0, 'Moschino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-c2b5-7353-9eb4-5eb898f15fb8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fb-cc68-76b4-892e-26fdf1f90751.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-5393-7515-9223-83e8dcda188a.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set divertido y moderno que mezcla la frescura cítrica con un toque dulce y floral, ideal para mujeres que buscan un aroma vibrante, energético y único para cualquier ocasión.</p>', NULL),
(12807, 'Reebok Inspire Your Mind 100ml EDT Mujer', '<p>Notas de salida: Bergamota, pera y pistacho.</p><p>Notas de corazón: Rosa, magnolia y ylang-ylang.</p><p>Notas de fondo: Vainilla, almizcle y pachulí.</p>', 6800, 0, 'Reebok', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-bf28-743e-b024-fd07ca4243f4.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779fa-f9ba-7528-86e5-8ec30fb3680d.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c327-5791-7635-9cbb-49b63d16b478.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina de la familia olfativa oriental floral, lanzada en 2022, que combina notas dulces y florales con un toque gourmand, ideal para mujeres activas y modernas</p>', NULL),
(12808, 'Antonio Banderas King Of Seduction EDT 200ml Hombre', '<h3>Familia olfativa: Aromática - Cítrica</h3><p><br></p><p><strong>Notas de salida:</strong> Bergamota, limón, manzana verde</p><p><strong>Notas de corazón:</strong> Lavanda, jazmín, geranio</p><p><strong>Notas de fondo:</strong> Cedro, almizcle, madera de sándalo</p><p><br></p><p>Esta fragancia ofrece una combinación fresca, limpia y seductora, ideal para el día a día y para hombres que buscan un aroma moderno y fácil de llevar.</p>', 22500, 2, 'Antonio Banderas', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-bc5a-71d9-bab6-5daa78df036c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198d8f9-9fe3-751f-b73d-4a7d7614b969.png?storeId=1681', 'Hombre', 1, 0, '<p>Antonio Banderas King of Seduction es una fragancia masculina fresca y vibrante, pensada para hombres seguros y carismáticos. Combina notas cítricas y frutales con un corazón floral y un fondo amaderado, ofreciendo un aroma equilibrado, moderno y seductor. Perfecto para el uso diario y ocasiones casuales, evoca una sensación de frescura y magnetismo natural.</p>', NULL),
(12809, 'Disney Princess Ariel 100ml EDT Girls', '<p>Melón, durazno y piña — una combinación frutal jugosa y alegre.</p><p>Notas de corazón:</p><p>Jazmín, rosa y lirio de los valles — flores suaves y delicadas que aportan frescura.</p><p>Notas de fondo:</p><p>Almizcle, ámbar y sándalo — una base cálida y reconfortante que completa la fragancia.</p>', 8500, 0, NULL, 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31f-103b-738d-a802-f54a297a06c8.jpeg?storeId=1681', 'Niños', 1, 0, '<p>Una fragancia fresca y dulce inspirada en la princesa Ariel, perfecta para niñas a partir de 3 años. Su aroma combina notas frutales y florales con un toque dulce, evocando la magia del océano y la fantasía de Disney.</p>', NULL),
(12810, 'Lancome La Nuit Tresor 100ml EDP Mujer', '<p>Pera, naranja tangerina y bergamota.</p><p>Notas de corazón: Fresa, orquídea de vainilla, rosa negra y maracuyá.</p><p>Notas de fondo: Praliné, caramelo, lichi, vainilla, pachulí, incienso, café, regaliz, cumarina y papiro de Egipto.</p>', 73500, 0, 'Lancome', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-b46b-777b-873c-c98cb342650e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199871e-cc20-7608-9645-75762359a1b0.png?storeId=1681', 'Mujer', 1, 0, '<p>La Nuit Trésor de Lancôme es una fragancia oriental gourmand que combina notas frutales, florales y dulces, creando una experiencia sensorial envolvente y seductora. Ideal para ocasiones especiales, noches románticas o climas frescos</p>', NULL),
(12811, 'Armaf Odyssey Mega EDP 100ml Hombre', '<p>Notas de salida:</p><p>Naranja</p><p>Bergamota</p><p>Limón</p><p>Jengibre</p><p>Menta</p><p>Notas de corazón:</p><p>Piña</p><p>Geranio</p><p>Enebro de Virginia</p><p>Salvia</p><p>Notas de fondo:</p><p>Haba tonka</p><p>Cedro</p><p>Almizcle</p>', 24500, 1, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-aac7-773a-9544-aabe29635273.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998720-fc31-7119-858f-6d21f60c27c9.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Mega es una fragancia masculina lanzada en 2023, que pertenece a la familia olfativa amaderada aromática. Esta fragancia se caracteriza por su apertura fresca y especiada, combinando notas cítricas con un toque herbal. En su corazón, presenta un acorde afrutado y ligeramente floral, mientras que en su fondo, se despliega una base cálida y amaderada que le otorga profundidad y longevidad.</p>', NULL),
(12812, 'Nautica Voyage 100ml EDT Hombre', '<p>Salida: manzana verde, hojas verdes, pepino/cucumber water — crea frescura inicial intensa </p><p>Corazón: loto, mimosa, pepino acuático — mantiene el carácter limpio y acuático </p><p>besuitedaroma.com</p><p>Fondo: almizcle, cedro, ámbar, roble musgoso, musgo — para un secado suave y seco</p>', 13800, 0, 'Nautica', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e1-1de4-76ca-8e33-9ccd201f89f1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e1-1a57-75f2-b3f0-9757d53c5af9.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c319-07fa-71d3-87e3-e715796773ab.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Nautica Voyage es una fragancia masculina aromática–acuática clásica que evoca frescura marina, verde y ligeramente frutal. Con un perfil limpio y universal, es ideal para el uso diario, especialmente en clima cálido.</p>', NULL),
(12813, 'Paris Hilton Rose Rush 100ml EDT Mujer', '<p>Pétalos de rosa</p><p>Neroli</p><p>Lichi (lychee)</p>', 23500, 1, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886b5-8cdf-743d-9cb6-71c99d3bfb4c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019886b5-8a41-758e-9826-e949c6e3db94.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Rose Rush (2017) es una fragancia femenina dentro de la colección Gold Rush. Brilla por su mezcla sofisticada y divertida de rosas, frutas exóticas y un fondo cálido, diseñada para crear una impresión suave, romántica pero con carácter.</p>', NULL),
(12814, 'Armaf Tag Uomo Rosso EDP 100ml', '<p><strong>Salida :</strong></p><p>Cardamomo</p><p>Lavanda</p><p>Notas aromáticas</p><p><strong>Corazón :</strong></p><p>Pimienta negra</p><p>Notas especiadas</p><p><strong>Fondo :</strong></p><p>Vainilla</p><p>Haba tonka</p><p>Incienso</p><p>Pachulí</p>', 22500, 2, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-95b0-75fb-b513-e802d36a1cee.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998728-8634-71e8-b116-2832fcd077f3.png?storeId=1681', 'Hombre', 1, 0, '<p>ARMAF Tag Uomo Rosso Eau de Parfum es una fragancia masculina de estilo oriental y amaderado, con un perfil olfativo intenso, cálido y especiado.</p><p>Descripción olfativa:</p><p>Una salida vibrante y especiada con notas de pimienta rosa y bergamota da paso a un corazón aromático y sensual con lavanda, salvia y canela. En el fondo, se asienta una base cálida y masculina de ámbar, pachulí y maderas oscuras, que aporta profundidad y persistencia.</p><p>Sensación general:</p><p>Elegante, seductora y con un toque misterioso, ideal para climas frescos o salidas nocturnas.</p>', NULL),
(12815, 'Paco Rabanne Phantom 100ml EDT Hombre', '<p>Salida (Top): limón de Amalfi y lavanda vibrante—una apertura cítrica fresca combinada con un corazón aromático clásico.</p><p>Corazón (Middle): lavanda reafirmada, manzana jugosa, pachulí terroso y un sutil toque ahumado que aporta profundidad.</p><p>Fondo (Base): vainilla cremosa, vetiver ahumado y una base amaderada suave que deja una estela cálida y persistente.</p>', 58000, 0, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e2-577d-778c-9283-a3323f977a34.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790e2-58c0-7745-ac85-e6b3093b7942.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Lanzada en 2021, Phantom de Paco Rabanne es una fragancia masculina del grupo Woody Aromatic / Fougère que fusiona aromas cítricos modernos con una dulzura cremosa. Su envase robótico digital añade un toque futurista, dando vida a una experiencia olfativa energizante y confiada.</p>', NULL),
(12816, 'Britney Spears Midnight Fantasy 100ml EDP Mujer', '<p>Salida: cereza negra, frambuesa (framboise) y ciruela (plum) — jugosas y profundas </p><p>Corazón: orquídea nocturna, fresia y lirio aterciopelado (velvet iris) — añaden un toque floral sofisticado </p><p>Fondo: almizcle seductor, ámbar y vainilla cálida — crean una estela envolvente y duradera</p>', 20800, 1, 'Britney Spears', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-1dd1-716f-8946-40495146377b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993f7c-7803-73df-82f1-d21f3465bd1d.png?storeId=1681', 'Mujer', 1, 0, '<p>Lanzada en 2006 como una versión más intensa y nocturna de Fantasy, Midnight Fantasy es una fragancia gourmand-afrutada pensada para la noche, con un toque elegante y sensual que supera expectativas en perfumería de celebridades.</p>', NULL),
(12817, 'Lattafa Yara Candy 100ml EDP Mujer', '<p><strong>Salida:</strong> Grosella negra, mandarina verde </p><p><strong>Corazón:</strong> Strawberry Fizz Candy (gomita de fresa efervescente), gardenia </p><p><strong>Fondo:</strong> Vainilla, ámbar, sándalo, almizcle</p>', 22000, 7, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-1b65-7557-b579-6c9a6045a6b7.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0198e26b-1f75-77c9-b675-b02e9bb84e2e.png?storeId=1681', 'Mujer', 1, 0, '<p>Alegre y vibrante, una explosión juvenil de frutas golosinas con corazón floral y un cierre cremoso dulce.</p>', NULL),
(12818, 'Body Mist Paris Hilton Can Can 8.0 Mujer', '<p>Notas de salida: Clementina, nectarina, grosella negra (cassis) y frambuesa.</p><p>Notas de corazón: Orquídea salvaje y flor de azahar (orange blossom).</p><p>Notas de fondo: Ámbar, almizcle y notas amaderadas.</p>', 7800, 4, 'Paris Hilton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-15f3-7139-8607-d7a4c80d6a3c.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c320-a047-7268-a675-795ad7f103de.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Body Mist Paris Hilton Can Can 8.0 oz es una fragancia femenina que combina notas florales y afrutadas, diseñada para ofrecer una experiencia sensorial fresca y seductora.</p>', NULL),
(12819, 'Dolce&Gabbana Light Blue EDP INTENSE 100ml Mujer', '<p>Limón cítrico y manzana Granny Smith  apertura fresca y afrutada </p><p>Melodía central </p><p>Jazmín y caléndula  bouquet floral suave y luminoso </p><p>Ritmo fina</p><p>Almizcle blanco y amberwood  base cálida, sedosa y sensual</p>', 48500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-1125-778d-b362-4190d3859762.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199872d-99e5-73a0-a765-7d1e093f93a2.png?storeId=1681', 'Mujer', 1, 0, '<p>Una versión más profunda y envolvente del clásico Light Blue, lanzada en 2017. Conserva la frescura mediterránea del original, elevándola con un corazón floral más redondo y un fondo cálido y almizclado. Perfecta para quienes buscan una fragancia veraniega con más cuerpo y duración.</p>', NULL),
(12820, 'Lancome La Vie Est Belle 100ml EDP Mujer', '<p>Notas de salida: Grosella negra, pera</p><p>Notas de corazón: Iris, jazmín sambac, flor de azahar del naranjo</p><p>Notas de fondo: Praliné, vainilla, pachulí, haba tonka</p>', 62500, 1, 'Lancome', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-0d04-722d-afd1-a11060a97e06.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199872e-bf3f-71ec-886f-50de02242c57.png?storeId=1681', 'Mujer', 1, 0, '<p>La Vie Est Belle celebra la belleza de la vida y la alegría en las pequeñas cosas. Con una mezcla de notas dulces y florales, esta fragancia ofrece una experiencia olfativa envolvente y femenina, perfecta para el uso diario y ocasiones especiales</p>', NULL),
(12821, 'Body Spray Lattafa Fakhar Mujer', '<p>Salida: afrutada y brillante (pomelo, frutas variadas, aldehídos, lirio) </p><p>Corazón: bouquet floral blanco (tuberosa, jazmín, gardenia, peonía, rosa, madreselva) </p><p>Fondo: cálido y cremoso (vainilla, sándalo, almizcle blanco, ambroxan)</p>', 4000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-097e-751c-b409-c31a98065296.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-bff4-779a-8eab-40fd251e0f62.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c324-67b4-7210-b5bf-20b26cb10e88.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Fakhar Mujer es una fragancia floral-blanca con matices frutales y amaderados, inspirada en L’Interdit de Givenchy. Tiene una proyección inicial agradable y elegante, pero su duración es muy variable. Mejora tras macerarse y al aplicarla estratégicamente en capas. Suelen maravillar a quienes buscan un body spray femenino \"lujoso\" y económico, aunque puede decepcionar a quienes prefieran aromas consistentes y potentes.</p>', NULL);
INSERT INTO `product` (`idproduct`, `name`, `description`, `price`, `stock`, `brand`, `pathimg`, `category`, `active`, `decant`, `shortDescription`, `iddiscount`) VALUES
(12822, 'Paco Rabanne One Million EDT 100ml Hombre', '<p>Pomelo (toronja)</p><p>Mandarina roja</p><p>Menta</p>', 54000, 1, 'Paco Rabanne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-04c7-72fe-a673-64a9f91bfa0f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998731-e166-74db-bdab-eee0a36ff7fb.png?storeId=1681', 'Hombre', 1, 0, '<p>One Million (2008) es una fragancia masculina icónica con una esencia lujosa, audaz y seductora. Su diseño triangular en forma de lingote de oro refleja su carácter distintivo. Equilibra frescura cítrica con matices especiados, florales, ambarados, amaderados y de cuero. Es conocida por su personalidad carismática y su sillage inolvidable.</p>', NULL),
(12823, 'Elizabeth Arden 5th Avenida EDP 125ml Mujer', '<p>Notas de salida: Magnolia húmeda, lila, flor de tilo, lirio de los valles, mandarina exótica y bergamota.</p><p>Notas de corazón: Violeta, rosa búlgara, ylang-ylang, jazmín, nardo indio, melocotón, clavo de olor y nuez moscada.</p><p>Notas de fondo: Ámbar, almizcle tibetano, sándalo, iris y vainilla.</p>', 23800, 3, 'Elizabeth Arden', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976071-00eb-7009-8fcb-c55406e145e2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01998427-2fdb-73ac-97eb-1ff2da80cbad.png?storeId=1681', 'Mujer', 1, 0, '<p>5th Avenue de Elizabeth Arden es una fragancia femenina que captura la esencia del estilo y la sofisticación de la ciudad de Nueva York. Lanzada en 1996, esta fragancia floral fresca está inspirada en la famosa Quinta Avenida, conocida por su lujo y elegancia. Es ideal para mujeres que buscan una fragancia clásica y atemporal, adecuada para el uso diario y ocasiones especiales.</p>', NULL),
(12824, 'Jesus Del Pozo Halloween Blue Drop EDT 100ml Mujer', '<p><strong>Notas de salida</strong>: Cítricos, manzana verde, lavanda</p><p><strong>Notas de corazón</strong>: Flores blancas, violeta, jazmín</p><p><strong>Notas de fondo</strong>: Ámbar, canela, almizcle</p>', 23800, 2, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-fb8c-77af-90d5-79c057cd0a85.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199608c-cfc8-7048-9628-365b28e82915.png?storeId=1681', 'Mujer', 1, 0, '<p>Halloween Blue Drop de Jesús del Pozo, lanzado en 2012, es una fragancia femenina fresca y floral que combina notas cítricas, florales y especiadas. Ideal para el día y especialmente para climas cálidos, ofrece una experiencia olfativa ligera y envolvente. aroma inspirado en D&amp;G Light Blue.</p>', NULL),
(12825, 'Christian Dior Sauvage EDP 100ml Hombre', '<p>Notas de salida: Bergamota de Calabria, aportando una frescura cítrica y ligeramente especiada.</p><p>Notas de corazón: Pimienta de Sichuan, lavanda, anís estrellado y nuez moscada, que añaden complejidad y calidez a la fragancia.</p><p>Notas de fondo: Ambroxan y extracto de vainilla de Papúa Nueva Guinea, brindando una base amaderada, ambarina y sensual</p>', 79000, 0, 'Dior', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790dd-1fac-779b-8bd0-3166304c185c.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c31b-7a92-772e-a50a-8c8e88097183.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>El Sauvage Eau de Parfum de Christian Dior es una fragancia masculina intensa y sofisticada, lanzada en 2018. Esta versión potencia la esencia original con una estela más profunda y envolvente, ideal para quienes buscan una fragancia con carácter y elegancia.</p>', NULL),
(12826, 'Yvest Saint Laurent Y EDT 100ml Hombre', '<p>Notas de salida: Aldehídos, bergamota y jengibre.</p><p>Notas de corazón: Lavanda, esclarea y geranio.</p><p>Notas de fondo: Ámbar gris, cedro, vainilla e incienso de olíbano</p>', 61500, 2, 'Yvest Saint Laurent', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-f638-743c-beec-83e65a5f24d1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01996094-003c-714d-99cf-1ff62a3d6c7d.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia fresca y moderna que fusiona notas cítricas y especiadas con un fondo amaderado, ideal para el hombre contemporáneo que busca elegancia, frescura y energía.</p>', NULL),
(12827, 'Liz Claiborne Curve Connect 100ml EDT Mujer', '<p>Salida: Mandarina, melón blanco</p><p>Corazón: Flor de cactus, ciruela, azafrán, canela</p><p>Fondo: Sándalo, cedro, pachulí suave, vainilla</p>', 14500, 7, 'Liz Claiborne', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-ed29-70e0-851d-631e60771302.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019a4a9d-2b90-7709-b74f-38b026c8e6ab.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Liz Claiborne Curve Connect es una fragancia femenina lanzada en 2008, que combina notas frutales y especiadas con un fondo amaderado y dulce. Su aroma fresco y envolvente la convierte en una opción ideal para el uso diario y ocasiones especiales.</p>', NULL),
(12828, 'Lattafa Asad Bourbon EDP 100ml Hombre', '<p>Notas de salida: Lavanda, pimienta rosa, ciruela Mirabel</p><p>Notas de corazón: Cacao, davana, nuez moscada</p><p>Notas de fondo: Vainilla Bourbon, ámbar, vetiver</p>', 28000, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-edd1-7779-b58c-114868000fa8.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972fc-8cdf-748d-b306-63c1b28035b2.png?storeId=1681', 'Hombre', 1, 0, '<p>Lattafa Asad Bourbon es una fragancia envolvente y sofisticada que combina notas dulces y especiadas con un fondo amaderado y cálido. Su apertura fresca y afrutada da paso a un corazón cremoso y especiado, mientras que su base profunda y seductora deja una estela duradera. Ideal para ocasiones especiales y noches frescas.</p>', NULL),
(12829, 'Reyane Tradition Acqua Di Parisis Venezia 100ml EDP Mujer', '<p>Familia: Almizcle floral amaderado – dulce y seductor </p><p>Salida: acordes afrutados de grosella negra, pera y toques cítricos de piña y bergamota, creando una apertura jugosa y luminosa </p><p>Corazón: un bouquet floral cremoso con jazmín, rosa, osmanthus </p><p>Fondo: base cálida y envolvente de ámbar, almizcle, vainilla, caramelo y toques amaderados, que prolonga su estela</p>', 18500, 2, 'Reyane Tradition', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-e3ba-7161-97fe-943c5d1916bf.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019972fe-f0be-746d-92e3-f1546664e140.png?storeId=1681', 'Mujer', 1, 0, '<p>Una fragancia femenina y envolvente que combina frutalidad, floralidad y gourmand en una composición seductora y duradera. Perfecta si buscas una opción dulce, elegante y versátil con buena presencia, especialmente en ocasiones nocturnas o de clima templado. Inspirada en la famosa Vie Este Belle. </p>', NULL),
(12830, 'Givenchy Ange Ou Demon 100ml EDP Mujer', '<p>Notas de salida: Mandarina, comino blanco, azafrán</p><p>Notas de corazón: Lirio, orquídea, ylang-ylang</p><p>Notas de fondo: Vainilla, haba tonka, musgo de roble, palo de rosa</p>', 56500, 0, 'Givenchy', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-e080-7736-94ee-213a55c77c70.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997301-82d2-713e-b6f3-fbc1d5971153.png?storeId=1681', 'Mujer', 1, 0, '<p>Ange Ou Demon de Givenchy, lanzado en 2006, es una fragancia femenina que encarna la dualidad entre la inocencia y la seducción. Con una mezcla de notas florales, especiadas y amaderadas, esta fragancia crea una estela misteriosa y envolvente, ideal para mujeres que buscan un aroma sofisticado y cautivador.</p>', NULL),
(12831, 'Carolina Herrera Bad Boy Cobalt EDP 100ml Hombre', '<p>Notas de salida: lavanda y pimienta rosa</p><p>Notas de corazón: ciruela y geranio</p><p>Notas de fondo: vetiver, cedro, trufa y roble</p>', 63500, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-dfec-7329-ab70-46c8e345b34b.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997303-935e-7232-bbf8-b57d9e5298ae.png?storeId=1681', 'Hombre', 1, 0, '<p>Carolina Herrera Bad Boy Cobalt Eau de Parfum es una fragancia masculina lanzada en 2022, parte de la línea Bad Boy de la marca. Diseñada por la perfumista Domitille Michalon Bertier, esta fragancia busca capturar la dualidad del hombre moderno: fuerte y sensible, rebelde y sofisticado. Su presentación en un frasco con forma de rayo en tonos azules refleja esta dualidad y aporta un toque visual distintivo.</p>', NULL),
(12832, 'Valentino Born In Roma EDT 100ml Hombre', '<p>Salida: Sal marina, hojas de violeta, acorde mineral.</p><p>Corazón: Jengibre, salvia.</p><p>Fondo: Vetiver, maderas ambaradas.</p>', 71500, 1, 'Valentino', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-d68e-70ab-9769-ceb0ade94354.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997309-b084-708b-9589-da2f622ae737.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia elegante y moderna que combina frescura salina y herbal con un corazón especiado y un fondo amaderado. Ideal para hombres que buscan versatilidad, sofisticación y un toque distintivo en su día a día.</p>', NULL),
(12833, 'Calvin Klein Obssesion EDP 100ml Mujer', '<p>Notas de salida: mandarina, bergamota, limón, albahaca, notas verdes, melocotón, vainilla</p><p>Notas de corazón: especias, sándalo, cilantro, musgo de roble, cedro, flor de azahar del naranjo, jazmín, rosa</p><p>Notas de fondo: ámbar, incienso, almizcle, algalia (civet), vetiver</p>', 24800, 0, 'Calvin Klein', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-d36d-7760-85ce-ef39354909c2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01993ed2-48b1-74ef-b40f-6b4446a5f347.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Calvin Klein Obsession Eau de Parfum 100 ml para Mujer es una fragancia intensa y seductora, lanzada en 1985. Pertenece a la familia olfativa Oriental Especiada y está diseñada para mujeres que buscan una esencia profunda y envolvente</p>', NULL),
(12834, 'Body Mist Perry Ellis 18 Mujer', '<p>Salida: bergamota, mandarina y manzana — cítricas y jugosas.</p><p>Corazón: jazmín, lirio de los valles y rosa — florales y delicadas.</p><p>Fondo: almizcle, sándalo y ámbar — cálidos y reconfortantes.</p>', 8500, 1, 'Perry Ellis', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-cfa8-71ad-bfbb-4fb38755490b.jpeg?storeId=1681', 'Mujer>Body Mist', 1, 0, '<p>El Perry Ellis 18 Body Mist para Mujer es una opción encantadora y accesible para quienes buscan un aroma fresco, floral y afrutado en un formato práctico y ligero. Ideal para quienes prefieren fragancias suaves y fáciles de llevar.</p>', NULL),
(12835, 'Jean Paul Gaultier Le Beau EDT 125ml Hombre', '<p>Notas de salida: Bergamota</p><p>Notas de corazón: Coco</p><p>Notas de fondo: Haba tonka</p>', 61000, 1, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-c9b9-7675-ae51-c4f7f267e6e7.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199730c-e836-71d9-acd8-50e3cacb02e6.png?storeId=1681', 'Hombre', 1, 0, '<p>Jean Paul Gaultier Le Beau Eau de Toilette es una fragancia masculina lanzada en 2019 que pertenece a la familia olfativa amaderada aromática. Creada por los perfumistas Quentin Bisch y Sonia Constant, esta fragancia se caracteriza por su aroma fresco y seductor, ideal para el uso diario y ocasiones especiales.</p>', NULL),
(12836, 'Lattafa EMEER EDP 100ml Unisex', '<p>Notas de salida: Bergamota, limón (lima ácida), esclarea, bayas de enebro</p><p>Notas de corazón: Té blanco, sándalo, cardamomo, incienso de olíbano (franquincienso)</p><p>Notas de fondo: Ámbar gris, cedro, pachulí, cachemira</p>', 30500, 0, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-c73c-70dc-bc33-fb5b4b0a9b4f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199730e-0ab1-73a8-b8e5-a55781308eef.png?storeId=1681', 'Hombre|Mujer', 1, 0, '<p>Emeer es una fragancia fresca y especiada que combina notas cítricas y herbales en su apertura, seguidas de un corazón amaderado y especiado con té blanco y cardamomo. Su base cálida y terrosa de ámbar gris, pachulí y cachemira ofrece una estela duradera y elegante. Ideal para quienes buscan una fragancia versátil que se adapta tanto a climas cálidos como frescos</p>', NULL),
(12837, 'Benetton Cold EDT 100ml Hombre', '<p>Salida: cítricos como mandarina, bergamota y neroli, mezclados con una nota fresca especiada gracias al coriandro y al carvi </p><p>Corazón: un acorde herbal con geranio y lavanda que aporta un carácter suave y limpio .</p><p>Fondo: cálido y reconfortante, formado por ámbar, pachulí, vetiver, incienso y almizcle, que proporcionan profundidad y balance .</p>', 11000, 0, 'Benetton', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790de-14cc-738f-8c91-5181c01653f1.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c325-00b6-7584-aad0-804ea247b6ee.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Benetton Cold es una opción económica y fiable para quienes buscan un aroma fresco-herbal con un fondo cálido y limpio. Ideal para el día a día, este clásico de los 90 sigue siendo una buena propuesta para hombres jóvenes o de espíritu relajado que buscan colonia sin complicaciones pero con armonía olfativa.</p>', NULL),
(12838, 'Set Versace Pour Femme Dylan Turquoise 3.4 EDT 4PC Women', '<p>Notas de salida: Limón primofiore, mandarina y pimienta rosa.</p><p>Notas de corazón: Jazmín, fresia y grosella negra.</p><p>Notas de fondo: Almizcle, madera clara y cedro.</p>', 56800, 0, 'Versace', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-c1b7-711d-99c9-258447688150.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019779ff-dfe7-758a-8198-e5a89e1c9cac.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c321-e850-737c-8323-27060ada2c26.jpeg?storeId=1681', 'Sets Mujer', 1, 0, '<p>Un set refrescante y sofisticado que evoca la brisa del mar y la calidez del sol. Dylan Turquoise es una fragancia vibrante y femenina, perfecta para mujeres que aman la frescura, el estilo y la libertad.</p>', NULL),
(12839, 'New Brand COMMANDO EDT 100ml Hombre', '<p>Salida: yuzu, menta, bergamota y jengibre (también puede incluir manzana, limón, toronja y mandarina en algunas versiones)</p><p>Corazón: romero, lavanda, hojas de violeta, edelweiss, geranio (en algunas fórmulas también cardamomo y nuez moscada)</p><p>Fondo: ciprés, abeto balsámico, cedro, almizcle y ámbar (otras presentan también cuero y vetiver)</p>', 8500, 0, 'New Brand', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-bf73-77e5-8778-725ade5be0ce.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a02-059a-72c9-bcb2-593c8a37359f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-31ca-7769-9078-ba68d3d123a1.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Commando de New Brand es una fragancia masculina aromática–amaderada vibrante y fresca. Combina cítricos energizantes con un corazón herbal y una base cálida y masc olfativa. Ideal para uso diario o casual, con buen rendimiento para su precio accesible</p>', NULL),
(12840, 'Dumont Nitro Red EDP 100ml Hombre', '<p>Manzana crujiente, lavanda y bergamota apertura fresca y dulce </p><p>Melodía central  Sandía jugosa, cedro y cálamo aromático bouquet refrescante y amaderado </p><p>Ritmo fina Ámbar, sándalo y pachulí base cálida, ligeramente dulce y envolvente</p>', 29000, 1, 'Dumont', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-bb46-7188-9bee-c3279f33b8f2.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997312-e7c7-70cd-82d7-19d6c5f5fa9c.jpeg?storeId=1681', 'Hombre', 1, 0, '<p>Una fragancia cítrico‑afrendada con un toque gourmand y fondo amaderado, lanzada en 2020. Combina la frescura “jugosa” de la fruta con un trasfondo cálido y duradero, ideal para el día y la noche en primavera y verano, aunque su dulzura pronunciada puede sentirse más en ambientes cálidos.</p>', NULL),
(12841, 'Halloween Blossom 100ml EDT Mujer', '<p>Salida: Fresa salvaje, mandarina verde, pimienta rosa</p><p>Corazón: Flor de azahar del naranjo, flor de zarzamora, jazmín egipcio</p><p>Fondo: Cedro, almizcle, vainilla</p>', 22800, 0, 'Jesus Del Pozo', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-b848-717d-84c4-4cd59c60be4f.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997314-0438-75dc-a400-a4e75b7661f2.png?storeId=1681', 'Mujer', 1, 0, '<p>Halloween Blossom de Jesús del Pozo es una fragancia fresca, femenina y alegre lanzada en 2022. Combina notas florales y frutales con una base cálida y dulce, perfecta para el uso diario, especialmente en primavera y verano.</p>', NULL),
(12842, 'Dolce & Gabbana Devotion EDP 100ml Mujer', '<p>Limón confitado   chispeante y dulce. </p><p>Melodía principal </p><p>Flor de azahar del naranjo, panna cotta (nota gourmand cremosa) y ron – aportan sofisticación dulce y floral. </p><p>Ritmo final </p><p>Vainilla  cálida, envolvente y duradera.</p>', 50500, 0, 'Dolce&Gabbana', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988676-751e-70dd-8a44-d70794de41d9.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01988676-7180-71d7-9ae6-14cd74ca6337.png?storeId=1681', 'Mujer', 1, 0, '<p>Un gourmand cítrico-luminoso inspirado en el panettone navideño, que ofrece una apertura brillante y dulce, evolucionando hacia un corazón floral y un fondo cremoso y reconfortante. Ideal para quienes buscan una fragancia alegre, reconfortante y moderna.</p>', NULL),
(12843, 'Armaf Odyssey Aqua 100ml Hombre', '<p><strong>Familia olfativa:</strong> Amaderada aromática con carácter fresco y moderno. Lanzamiento: 2023 </p><p><strong>Notas principales:</strong></p><ul><li>Salida: naranja, toronja (pomelo), abrótano (ajenjo)</li><li>Corazón: lavanda y menta</li><li>Fondo: ambroxan, pachulí y ciprés</li></ul><p><strong>Perfil olfativo general:</strong> Apertura cítrica vibrante con un toque herbal por la nota de ajenjo; corazón limpio y mentolado que evoca brisa marina fresca; base ambarada, moderna y con buena profundidad gracias al ambroxan y las notas amaderadas.</p>', 24500, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-afb3-74b8-bbe7-26352db71d8e.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01997317-4458-73de-844c-12cbc218bba9.png?storeId=1681', 'Hombre', 1, 0, '<p>Armaf Odyssey Aqua es una fragancia masculina fresca y acuática que combina notas cítricas y marinas con un fondo amaderado y almizclado. Ideal para el uso diario y climas cálidos, ofrece un aroma ligero, revitalizante y moderno. Perfecta para hombres activos que buscan un perfume versátil y fácil de llevar.</p>', NULL),
(12844, 'Body Spray Club De Nuit Intense', '<p>Notas de salida (fresco y afrutadas): limón, bergamota, piña, manzana y grosella negra (blackcurrant) </p><p>Notas de corazón (florales y amaderadas): abedul, jazmín y rosa </p><p>Notas de fondo (cálidas y duraderas): almizcle, ámbar gris, pachulí y vainilla</p>', 6000, 0, 'Armaf', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-a113-7078-9678-9e31c58139d6.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01977a00-00d7-7639-9041-b6eb986c0dba.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c322-8e90-70e9-a12e-89bc65e16e5d.png?storeId=1681', 'Hombre', 1, 0, '<p>Un body spray amaderado, especiado y cítrico con un rendimiento sobresaliente, valorado por su similitud al Aventus. Sin embargo, su apertura intensa puede no ser del agrado de todos. Si te atrae más el corazón cálido y frutal, puede gustarte tras un ajuste en la aplicación o el tipo de fórmula.</p>', NULL),
(12845, 'Jean Paul Gaultier La Belle Paradise Garden 100ml EDP Mujer', '<p>Notas de salida: Loto azul</p><p>Notas de corazón: Iris</p><p>Notas de fondo: Vainilla</p>', 62500, 0, 'Jean Paul Gaultier', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-9512-7050-ab06-3341e683892e.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0199842c-42c9-72dd-b0d9-27a98d50824f.png?storeId=1681', 'Mujer', 1, 0, '<p>Jean Paul Gaultier La Belle Paradise Garden es una fragancia femenina lanzada en 2023, que forma parte de la colección La Belle. Esta edición se distingue por su perfil floral ambarino, ofreciendo una interpretación fresca y sofisticada del ADN característico de la línea La Belle.</p>', NULL),
(12846, 'Carolina Herrera CH 100ml EDT Hombre', '<p><strong>Salida</strong>Hierba fresca, bergamota, pomelo </p><p><strong>Corazón</strong>Notas amaderadas, nuez moscada, violeta, azafrán, jazmín </p><p><strong>Fondo</strong>Azúcar, cuero, vainilla, gamuza, ámbar, cashmeran, sándalo, musgo de roble, vetiver</p>', 58500, 1, 'Carolina Herrera', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-01976070-91a9-74fc-85e9-b94754519cbb.jpeg?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019885a9-632c-7602-8b36-858c0b7de1fa.png?storeId=1681', 'Hombre', 1, 0, '<p><em>CH Men</em> es una elegante fragancia masculina que combina frescura herbal y cítrica con la calidez del cuero y la vainilla. Ofrece buen rendimiento y una personalidad versátil que se adapta bien a múltiples ocasiones</p>', NULL),
(12847, 'Body Spray Lattafa Yara', '<p>Salida:</p><p>Mandarina/tangerina, orquídea, heliotropo — combinan un aire cítrico-floral dulce y suave </p><p>Corazón:</p><p>Frutas tropicales y un acorde gourmand — crean una mezcla jugosa, afrutada y ligeramente cremosa </p><p>Fondo:</p><p>Vainilla, sándalo y almizcle — aportan calidez, cremosidad y una estela dulce/amaderada que se percibe en proximidad</p>', 4500, 4, 'Lattafa', 'https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-019790de-f45a-712c-ae68-c06de8530505.png?storeId=1681|https://avenida-magento.s3.amazonaws.com/catalog/product/1/8/1803-0197c328-19d7-7528-b146-af2e42e2920d.jpeg?storeId=1681', 'Mujer', 1, 0, '<p>Lattafa Yara es un body spray frutal-gourmand con una apertura cítrico-floral y una estela dulce y cremosa gracias a la vainilla, sándalo y almizcle. Puede requerir un tiempo de maceración para alcanzar su mejor versión. La recepción varía según la piel: algunas personas aman su dulzura suave y longevidad, mientras que otras pueden encontrar la fase inicial demasiado artificial o sintética.</p>', NULL);
